INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('drillan/mixseek-plus/mixseek-skills', 'community', 'drillan', 'mixseek-plus', 'drillan/mixseek-plus', 'mixseek-skills', 0, 0, 38, '2026-03-08T01:57:15.273Z', '2026-03-08T02:00:28.687Z', '5b48d0944d8e8f3e541c11f9ef5591882d359673487792d83508c0b4549b1107', '{"id":"drillan/mixseek-plus/mixseek-skills","name":"mixseek-skills","description":{"en":"mixseek-skills is a collection of agent skills for MixSeek-Core, providing features like Python command detection and workspace initialization. It benefits AI agent developers and users.","zh":"MixSeek Skills是一套AI工具，提供Python命令判别、工作空间初始化和团队设置生成等功能，帮助开发者提高效率","ja":"MixSeek SkillsはAIエージェント用のスキルコレクションです。Pythonコマンド判別、ワークスペース初期化、チーム設定生成などを提供します","ko":"MixSeek Skills는 AI 에이전트 용도의 스킬 모음입니다. Python 명령어 판별, 작업 공간 초기화, 팀 설정 생성 등을 제공합니다","es":"Mixseek-skills es una colección de habilidades para Agentes de IA que incluye detección de comandos Python y configuración de equipos","fr":"Mixseek-skills est un ensemble de compétences pour Outils d''IA qui comprend la détection de commandes Python et la configuration d''équipes","de":"Mixseek-skills ist eine Sammlung von Fähigkeiten für KI-Agents, die die Erkennung von Python-Befehlen und die Teamkonfiguration umfasst","pt":"O MixSeek-Skills é uma coleção de habilidades para agentes de IA que visa melhorar a produtividade do desenvolvimento. Ele inclui recursos como detecção de comandos Python e inicialização de workspace.","ru":"MixSeek-Skills - коллекция навыков для агентов ИИ, предназначенная для повышения производительности разработки. Он включает в себя функции, такие как обнаружение команд Python и инициализация рабочего пространства.","ar":"MixSeek-Skills هو مجموعة من المهارات لوسائل الإي الأبتكار التي تهدف إلى تحسين إنتاجية التطوير. يتضمن ميزات مثل الكشف عن أوامر Python وإعداد مساحة العمل."},"seo":{"title":{"en":"mixseek-skills: Setup Guide for AI Agents","zh":"MixSeek Skills 安装指南 - AI工具配置与优化","ja":"MixSeek Skills セットアップガイド - AIエージェントの設定と最適化","ko":"MixSeek Skills 설치 가이드 - AI 에이전트 설정 및 최적화","es":"Guía de configuración de mixseek-skills para Agentes de IA","fr":"Guide d''installation de mixseek-skills pour Outils d''IA","de":"Einrichtungsleitfaden für mixseek-skills in KI-Agents","pt":"Guia de Configuração do MixSeek-Skills: Ferramentas de AI...","ru":"Настройка MixSeek-Skills: Инструменты ИИ для Разработчиков","ar":"دليل إعداد MixSeek-Skills: أدوات الإي الأبتكار للمطورين"},"description":{"en":"Unlock the full potential of mixseek-skills with our expert setup guide. Learn how to install and configure mixseek-skills for optimal performance.","zh":"了解MixSeek Skills的功能和特点，包括Python命令判别、工作空间初始化和团队设置生成等，提升您的AI工具配置效率","ja":"MixSeek Skillsの機能と特徴を紹介します。Pythonコマンド判別、ワークスペース初期化、チーム設定生成などを含みます","ko":"MixSeek Skills의 기능과 특징을 소개합니다. Python 명령어 판별, 작업 공간 초기화, 팀 설정 생성 등이 포함되어 있습니다","es":"Aprende a configurar mixseek-skills para mejorar tus Agentes de IA con funcionalidades de detección de comandos Python y configuración de equipos","fr":"Découvrez comment installer mixseek-skills pour améliorer vos Outils d''IA avec des fonctionnalités de détection de commandes Python et de configuration d''équ...","de":"Erfahren Sie, wie Sie mixseek-skills einrichten, um Ihre KI-Agents mit Funktionen zur Erkennung von Python-Befehlen und Teamkonfiguration zu verbessern","pt":"Aprenda a configurar o MixSeek-Skills, uma coleção de habilidades para agentes de IA, e descubra como melhorar a produtividade do seu time de desenvolvimento","ru":"Узнайте, как настроить MixSeek-Skills, коллекцию навыков для агентов ИИ, и узнайте, как повысить производительность своей команды разработчиков","ar":"تعلم كيفية إعداد MixSeek-Skills، مجموعة من المهارات لوسائل الإي الأبتكار، واكتشف كيف تحسن إنتاجية فريق التطوير الخاص بك"},"definition":{"en":"mixseek-skills is a set of agent skills designed for MixSeek-Core, offering various functionalities such as configuration validation and model listing.","zh":"MixSeek Skills是一套用于AI工具配置和优化的技能集","ja":"MixSeek SkillsはAIエージェント用のスキルコレクションです","ko":"MixSeek Skills는 AI 에이전트 용도의 스킬 모음입니다","es":"Mixseek-skills es un conjunto de habilidades para mejorar la funcionalidad de Agentes de IA","fr":"Mixseek-skills est un ensemble de compétences pour améliorer la fonctionnalité des Outils d''IA","de":"Mixseek-skills ist eine Sammlung von Fähigkeiten zur Verbesserung der Funktionalität von KI-Agents","pt":"O que é MixSeek-Skills? É uma coleção de habilidades para agentes de IA que fornece recursos para melhorar a produtividade do desenvolvimento","ru":"Что такое MixSeek-Skills? Это коллекция навыков для агентов ИИ, предоставляющая функции для повышения производительности разработки","ar":"ما هو MixSeek-Skills؟ هو مجموعة من المهارات لوسائل الإي الأبتكار التي توفر ميزات لتحسين إنتاجية التطوير"},"features":{"en":["Detects and executes Python commands using `detect-python-command`","Initializes workspace with `mixseek-workspace-init`","Generates team configurations via `mixseek-team-config`","Validates settings with `mixseek-config-validate`","Provides model listings through `mixseek-model-list`"],"zh":["Python命令判别和执行","工作空间初始化","团队设置生成","设置验证","模型列表获取","调试功能和日志控制"],"ja":["Pythonコマンド判別と実行","ワークスペース初期化","チーム設定生成","設定検証","モデル一覧取得","デバッグ機能とログ制御"],"ko":["Python 명령어 판별과 실행","작업 공간 초기화","팀 설정 생성","설정 검증","모델 목록 가져오기","디버깅 기능과 로그 제어"],"es":["Detección de comandos Python","Configuración de equipos","Inicialización de espacio de trabajo","Configuración de orquestador","Generación de configuración de evaluador","Validación de configuración"],"fr":["Détection de commandes Python","Configuration d''équipes","Initialisation de l''espace de travail","Configuration de l''orchestrateur","Génération de la configuration de l''évaluateur","Validation de la configuration"],"de":["Erkennung von Python-Befehlen","Teamkonfiguration","Initialisierung des Arbeitsbereichs","Konfiguration des Orchesters","Generierung der Konfiguration des Evaluators","Validierung der Konfiguration"],"pt":["Detecção de comandos Python","Inicialização de workspace","Geração de configuração de equipe","Configuração de orquestrador","Geração de configuração de avaliador","Validação de configuração"],"ru":["Обнаружение команд Python","Инициализация рабочего пространства","Генерация конфигурации команды","Настройка оркестратора","Генерация конфигурации оценщика","Валидация конфигурации"],"ar":["كشف عن أوامر Python","إعداد مساحة العمل","توليد تكوين الفريق","ضبط المنسق","توليد تكوين التقييم","التحقق من التكوين"]},"keywords":{"en":["how to use mixseek-skills","mixseek-skills setup guide","mixseek-skills alternative","mixseek-skills vs MixSeek-Core","install mixseek-skills","mixseek-skills configuration"],"zh":["MixSeek Skills","AI工具配置","Python命令判别","工作空间初始化","团队设置生成","AIエージェント","设置验证","模型列表获取"],"ja":["MixSeek Skills","AIエージェント","Pythonコマンド判別","ワークスペース初期化","チーム設定生成","設定検証","モデル一覧取得","デバッグ機能"],"ko":["MixSeek Skills","AI 에이전트","Python 명령어 판별","작업 공간 초기화","팀 설정 생성","설정 검증","모델 목록 가져오기","디버깅 기능"],"es":["Agentes de IA","Herramientas de IA","Configuración de mixseek-skills","Detección de comandos Python","Configuración de equipos","Inicialización de espacio de trabajo","Orquestador de IA","Evaluación de IA"],"fr":["Outils d''IA","Agents d''IA","Installation de mixseek-skills","Détection de commandes Python","Configuration d''équipes","Initialisation de l''espace de travail","Orchestrateur d''IA","Évaluation d''IA"],"de":["KI-Agents","KI-Tools","Einrichtung von mixseek-skills","Erkennung von Python-Befehlen","Teamkonfiguration","Initialisierung des Arbeitsbereichs","KI-Orchester","KI-Evaluierung"],"pt":["MixSeek-Skills","Agentes de IA","Desenvolvimento de software","Produtividade","Comandos Python","Iniciativa de workspace","Configuração de equipe","Orquestrador","Avaliador"],"ru":["MixSeek-Skills","ИИ Агенты","Разработка программного обеспечения","Производительность","Команды Python","Инициализация рабочего пространства","Конфигурация команды","Оркестратор","Оценщик"],"ar":["MixSeek-Skills","وسائل الإي الأبتكار","تطوير البرمجيات","الإنتاجية","أوامر Python","إعداد مساحة العمل","تكوين الفريق","المنسق","التقييم"]}},"owner":"drillan","repo":"mixseek-plus","repoPath":"drillan/mixseek-plus","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.273Z","topics":[],"category":"community","skillMd":{"name":"mixseek-skills","description":"MixSeek Agent Skills collection for AI coding assistants. Provides workspace management, team configuration, evaluation setup, and debugging tools for MixSeek-Core.","version":"1.0.0","bodyPreview":"# MixSeek Agent Skills\n\nMixSeek-Core用のAgent Skillsコレクションです。\n\n## 含まれるスキル\n\n| スキル | 説明 |\n|--------|------|\n| `detect-python-command` | Pythonコマンド判別・実行 |\n| `mixseek-workspace-init` | ワークスペース初期化 |\n| `mixseek-team-config` | チーム設定生成 |\n| `mixseek-orchestrator-config` | オーケストレーター設定 |\n| `mixseek-evaluator-config` | 評価設定生成 |\n| `mixseek-config-validate` | 設定検証 |\n| `mixseek-model-list` | モデル一覧取得 |\n| `mixseek-prompt-builder` | プロンプトビルダー設定 |\n| `mixseek-debug` | デバッグ機能・ログ制御 |\n\n## インストール\n\n```bash\nnpx skills add","body":"# MixSeek Agent Skills\n\nMixSeek-Core用のAgent Skillsコレクションです。\n\n## 含まれるスキル\n\n| スキル | 説明 |\n|--------|------|\n| `detect-python-command` | Pythonコマンド判別・実行 |\n| `mixseek-workspace-init` | ワークスペース初期化 |\n| `mixseek-team-config` | チーム設定生成 |\n| `mixseek-orchestrator-config` | オーケストレーター設定 |\n| `mixseek-evaluator-config` | 評価設定生成 |\n| `mixseek-config-validate` | 設定検証 |\n| `mixseek-model-list` | モデル一覧取得 |\n| `mixseek-prompt-builder` | プロンプトビルダー設定 |\n| `mixseek-debug` | デバッグ機能・ログ制御 |\n\n## インストール\n\n```bash\nnpx skills add drillan/mixseek-plus\n```\n\n## 詳細\n\n各スキルの詳細は、サブディレクトリ内の `SKILL.md` を参照してください。\n"},"lastSynced":"2026-03-08T02:00:28.687Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced Python command detection and workspace initialization capabilities.","zh":"适用于需要高级Python命令检测和工作空间初始化功能的AI代理。","ja":"高度なPythonコマンド検出とワークスペース初期化機能を必要とするAIエージェントに最適です。","ko":"고급 Python 명령어 감지 및 작업 공간 초기화 기능이 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan detección de comandos avanzados de Python y capacidades de inicialización del espacio de trabajo.","fr":"Parfait pour les agents IA nécessitant une détection de commandes Python avancée et des capacités d''initialisation de l''espace de travail.","de":"Perfekt für KI-Agents, die eine erweiterte Python-Befehlsdetektion und Arbeitsbereichsinitialisierungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de IA que necessitam de detecção avançada de comandos Python e capacidades de inicialização de espaço de trabalho.","ru":"Идеально для агентов ИИ, которым необходима продвинутая детекция команд Python и возможности инициализации рабочего пространства.","ar":"مثالي لعمليات الوكلاء الذكية التي تحتاج إلى اكتشاف متقدم لأوامر Python وقدرات 초기 化 مساحة العمل."},"recommendation":{"en":"Empowers agents to detect and execute Python commands, initialize workspaces, and configure teams and orchestrators, all while validating settings and managing models, using features like `detect-python-command` and `mixseek-workspace-init`.","zh":"赋予代理检测和执行Python命令、初始化工作空间、配置团队和协调器的能力，同时验证设置和管理模型，使用诸如`detect-python-command`和`mixseek-workspace-init`的功能。","ja":"エージェントにPythonコマンドの検出と実行、ワークスペースの初期化、チームとオーケストレーターの構成を行う機能を与え、設定の検証とモデル管理を行うことができる機能、たとえば`detect-python-command`および`mixseek-workspace-init`です。","ko":"에이전트가 Python 명령어를 감지하고 실행하며, 작업 공간을 초기화하고, 팀과 오케스트레이터를 구성하며, 설정을 검증하고 모델을 관리할 수 있는 기능을 제공하며, `detect-python-command` 및 `mixseek-workspace-init`와 같은 기능을 사용합니다.","es":"Habilita a los agentes a detectar y ejecutar comandos de Python, inicializar espacios de trabajo y configurar equipos y orquestadores, todo mientras se validan la configuración y se gestionan los modelos, utilizando características como `detect-python-command` y `mixseek-workspace-init`.","fr":"Permet aux agents de détecter et d''exécuter des commandes Python, d''initialiser des espaces de travail et de configurer des équipes et des orchestrateurs, le tout en validant les paramètres et en gérant les modèles, en utilisant des fonctionnalités comme `detect-python-command` et `mixseek-workspace-init`.","de":"Ermöglicht es Agenten, Python-Befehle zu erkennen und auszuführen, Arbeitsbereiche zu initialisieren und Teams und Orchestrierer zu konfigurieren, während die Einstellungen überprüft und die Modelle verwaltet werden, unter Verwendung von Funktionen wie `detect-python-command` und `mixseek-workspace-init`.","pt":"Habilita agentes a detectar e executar comandos Python, inicializar espaços de trabalho, configurar equipes e orquestradores, tudo isso enquanto valida configurações e gerencia modelos, usando recursos como `detect-python-command` e `mixseek-workspace-init`.","ru":"Наделяет агентов возможностью обнаруживать и выполнять команды Python, инициализировать рабочие пространства, настраивать команды и оркестраторы, все это при проверке настроек и управлении моделями, используя функции как `detect-python-command` и `mixseek-workspace-init`.","ar":"تمكّن الوكلاء من اكتشاف وتشغيل أوامر Python، وتحديد مساحات العمل، وتكوين الفريق والمنسق، كل ذلك مع التحقق من الإعدادات وإدارة النماذج، باستخدام ميزات مثل `detect-python-command` و `mixseek-workspace-init`."},"useCases":{"en":["Automating Python command execution","Initializing workspaces for collaborative projects","Debugging MixSeek configurations with `mixseek-debug`"],"zh":["自动化Python命令执行","为协作项目初始化工作空间","使用`mixseek-debug`调试MixSeek配置"],"ja":["Pythonコマンドの実行を自動化する","共同プロジェクト用のワークスペースを初期化する","`mixseek-debug`を使用してMixSeekの設定をデバッグする"],"ko":["Python 명령어 실행 자동화","협업 프로젝트를 위한 작업 공간 초기화","`mixseek-debug`를 사용하여 MixSeek 구성 디버깅"],"es":["Automatización de la ejecución de comandos de Python","Inicialización de espacios de trabajo para proyectos colaborativos","Depuración de configuraciones de MixSeek con `mixseek-debug`"],"fr":["Automatisation de l''exécution de commandes Python","Initialisation d''espaces de travail pour des projets collaboratifs","Débogage des configurations MixSeek avec `mixseek-debug`"],"de":["Automatisierung der Ausführung von Python-Befehlen","Initialisierung von Arbeitsbereichen für kollaborative Projekte","Fehlerbehebung bei MixSeek-Konfigurationen mit `mixseek-debug`"],"pt":["Automatizar a execução de comandos Python","Inicializar espaços de trabalho para projetos colaborativos","Depurar configurações do MixSeek com `mixseek-debug`"],"ru":["Автоматизировать выполнение команд Python","Инициализировать рабочие пространства для совместных проектов","Отладить конфигурации MixSeek с помощью `mixseek-debug`"],"ar":["أتمتة تشغيل أوامر Python","تثبيت مساحات العمل لمشاريع تعاونية","تصحيح أخطاء تكوين MixSeek باستخدام `mixseek-debug`"]},"limitations":{"en":["Requires MixSeek-Core compatibility","Limited to Python command detection and execution"],"zh":["需要MixSeek-Core兼容性","仅限Python命令检测和执行"],"ja":["MixSeek-Coreの互換性が必要","Pythonコマンドの検出と実行に限定される"],"ko":["MixSeek-Core 호환성이 필요","Python 명령어 감지 및 실행에만 제한"],"es":["Requiere compatibilidad con MixSeek-Core","Limitado a la detección y ejecución de comandos de Python"],"fr":["Nécessite la compatibilité avec MixSeek-Core","Limité à la détection et à l''exécution de commandes Python"],"de":["Benötigt Kompatibilität mit MixSeek-Core","Begrenzt auf die Erkennung und Ausführung von Python-Befehlen"],"pt":["Requer compatibilidade com o MixSeek-Core","Limitado à detecção e execução de comandos Python"],"ru":["Требует совместимости с MixSeek-Core","Ограничен детекцией и выполнением команд Python"],"ar":["يتطلب توافقًا مع MixSeek-Core","محدود بالكشف عن أوامر Python والتشغيل"]},"version":4},"contentHash":"5b48d0944d8e8f3e541c11f9ef5591882d359673487792d83508c0b4549b1107","qualityScore":38}');
