INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('eng-cc/agent-world/monetization-systems', 'monetization-systems', 'eng-cc', 'agent-world', 'community', 'monetization-systems eng-cc agent-world community The monetization-systems skill helps developers choose the right revenue model for their game type, including premium, free-to-play, and subscription-based models. 本文介绍了盈利系统的设置方法，包括选择合适的盈利模式，例如Premium、F2P、订阅等 収益化システムの設定方法を紹介します。収益化モデルを選択する方法、例えばPremium、F2P、サブスクリプションなど 수익화 시스템의 구축 방법을 소개합니다. 수익화 모델을 선택하는 방법, 예를 들어 Premium, F2P, 구독 등 Los sistemas de monetización permiten a los desarrolladores generar ingresos a través de modelos como premium, free-to-play y suscripciones. Elige el modelo adecuado para tu juego o aplicación. Les systèmes de monétisation permettent aux développeurs de générer des revenus via des modèles tels que premium, free-to-play et abonnements. Choisissez le modèle adapté à votre jeu ou application. Monetisierungssysteme ermöglichen es Entwicklern, durch Modelle wie Premium, Free-to-Play und Abonnements Einnahmen zu generieren. Wählen Sie das richtige Modell für Ihr Spiel oder Ihre Anwendung. Os sistemas de monetização permitem que os desenvolvedores gerem receita a partir de seus jogos e aplicativos. Escolha o modelo certo para o seu produto. Системы монетизации позволяют разработчикам генерировать доход от своих игр и приложений. Выберите правильную модель для вашего продукта. أنظمة التمويل تسمح للمطورين بتوليد الإيرادات من ألعابهم وتطبيقاتهم. اختر النموذج الصحيح لمنتجك. how to use monetization-systems monetization-systems setup guide monetization-systems alternative monetization-systems vs revenue models what is monetization-systems monetization-systems install monetization-systems for game developers free-to-play monetization-systems premium game monetization-systems subscription-based monetization-systems AI工具 盈利系统 游戏开发 Premium F2P 订阅 Battle Pass 广告 轻度IAP Supports premium models with pricing ranges from $10-60 Offers free-to-play models with battle pass and in-app purchases Provides subscription-based models for MMO and live service games Includes recommendations for story-driven, competitive multiplayer, and mobile casual games Features a choice of monetization models based on game type Monetization-systems is a set of revenue models and strategies for game developers to generate income from their products.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rohitg00/manim-video-generator/math-visualizer', 'community', 'rohitg00', 'manim-video-generator', 'rohitg00/manim-video-generator', 'math-visualizer', 0, 0, 38, '2026-03-08T01:57:15.284Z', '2026-03-08T02:00:56.197Z', '064fc7a01b13bee0ed3780c36fad7d737031908107a1c1d60427177492f95021', '{"id":"rohitg00/manim-video-generator/math-visualizer","name":"math-visualizer","description":{"en":"The math-visualizer skill generates mathematical animations using natural language descriptions, benefiting developers and educators who need to visualize complex concepts.","zh":"Math Visualizer 是一个使用 OpenAI GPT 模型将自然语言描述转换为 Manim 代码的应用程序，用于生成数学动画","ja":"Math Visualizer は、OpenAI の GPT モデルを使用して自然言語の説明を Manim コードに変換し、数学アニメーションを生成するアプリケーションです","ko":"Math Visualizer는 OpenAI의 GPT 모델을 사용하여 자연어 설명을 Manim 코드로 변환하여 수학 애니메이션을 생성하는 애플리케이션입니다","es":"Math Visualizer es una aplicación que permite generar animaciones matemáticas utilizando descripciones en lenguaje natural, utilizando OpenAI''s GPT para convertir descripciones en código Manim","fr":"Math Visualizer est une application qui permet de générer des animations mathématiques à l''aide de descriptions en langage naturel, en utilisant OpenAI''s GPT pour convertir les descriptions en code Manim","de":"Math Visualizer ist eine Anwendung, die die Erstellung von mathematischen Animationen mithilfe von natürlichen Sprachbeschreibungen ermöglicht, indem OpenAI''s GPT verwendet wird, um Beschreibungen in Manim-Code umzuwandeln","pt":"O Math Visualizer é uma aplicação que gera animações matemáticas usando descrições em linguagem natural, convertendo-as em código Manim com o modelo GPT da OpenAI.","ru":"ИИ Агент Math Visualizer - это приложение, которое генерирует математические анимации на основе описаний в естественном языке, преобразуя их в код Manim с помощью модели GPT от OpenAI.","ar":"Math Visualizer هو تطبيق يولد حركات رياضية باستخدام وصفات اللغة الطبيعية، ويحولها إلى كود Manim باستخدام نموذج GPT من OpenAI."},"seo":{"title":{"en":"math-visualizer: Generate Mathematical Animations | AI Ag...","zh":"Math Visualizer 应用程序设置指南 - 使用 OpenAI GPT","ja":"Math Visualizer AIエージェントのベストプラクティス - Manimコード生成","ko":"Math Visualizer 설정 가이드 - 자연어 설명을 사용한 수학 애니메이션 생성","es":"Guía de configuración de Math Visualizer para animaciones...","fr":"Guide d''installation de Math Visualizer pour les animatio...","de":"Math Visualizer-Setup-Anleitung für mathematische Animati...","pt":"Guia de Configuração do Math Visualizer: Crie Animações M...","ru":"ИИ Агент Math Visualizer: Руководство по Созданию Математ...","ar":"دليل إعداد Math Visualizer: إنشاء حركات رياضية باستخدام O..."},"description":{"en":"Discover how math-visualizer uses OpenAI''s GPT model to create stunning mathematical animations from natural language descriptions - get started now!","zh":"使用 Math Visualizer 应用程序，通过自然语言描述生成精美的数学动画。支持代数、微积分、几何、三角学和线性代数等多个数学领域","ja":"Math Visualizer AIエージェントを使用して、自然言語の説明から美しい数学アニメーションを生成します。代数、微積分、幾何、三角法、線形代数などをサポート","ko":"Math Visualizer를 사용하여 자연어 설명을 통해 아름다운 수학 애니메이션을 생성합니다. 대수, 미적분, 기하, 삼각, 선형대수 등 다양한 수학 분야를 지원","es":"Crea animaciones matemáticas hermosas con Math Visualizer, utilizando OpenAI''s GPT para convertir descripciones en código Manim","fr":"Créez des animations mathématiques beautés avec Math Visualizer, en utilisant OpenAI''s GPT pour convertir les descriptions en code Manim","de":"Erstellen Sie schöne mathematische Animationen mit Math Visualizer, indem Sie OpenAI''s GPT verwenden, um Beschreibungen in Manim-Code umzuwandeln","pt":"Aprenda a criar animações matemáticas precisas com o Math Visualizer, utilizando o modelo GPT da OpenAI para converter descrições em código Manim.","ru":"Создавайте математические анимации с помощью ИИ Агента Math Visualizer, который использует модель GPT от OpenAI для преобразования описаний в код Manim.","ar":"تعلم كيفية إنشاء حركات رياضية دقيقة باستخدام Math Visualizer، الذي يستخدم نموذج GPT من OpenAI لتحويل الوصف إلى كود Manim."},"definition":{"en":"math-visualizer is a skill that converts natural language descriptions into Manim code to create precise mathematical animations","zh":"Math Visualizer 是一个使用自然语言描述生成数学动画的应用程序","ja":"Math Visualizer は、自然言語の説明から数学アニメーションを生成するアプリケーションです","ko":"Math Visualizer는 자연어 설명을 통해 수학 애니메이션을 생성하는 애플리케이션입니다","es":"Math Visualizer es una herramienta de visualización matemática que convierte descripciones en lenguaje natural en código Manim para crear animaciones","fr":"Math Visualizer est un outil de visualisation mathématique qui convertit les descriptions en langage naturel en code Manim pour créer des animations","de":"Math Visualizer ist ein mathematisches Visualisierungstool, das Beschreibungen in natürlicher Sprache in Manim-Code umwandelt, um Animationen zu erstellen","pt":"O Math Visualizer é um agente de IA que cria animações matemáticas precisas a partir de descrições em linguagem natural.","ru":"ИИ Агент Math Visualizer - это агент искусственного интеллекта, создающий точные математические анимации на основе описаний в естественном языке.","ar":"Math Visualizer هو عامل ذكاء اصطناعي ي tạo حركات رياضية دقيقة من وصفات اللغة الطبيعية."},"features":{"en":["Supports Algebra, Calculus, Geometry, Trigonometry, and Linear Algebra domains","Uses OpenAI''s GPT model to convert descriptions into Manim code","Generates animations for equations, inequalities, polynomials, derivatives, and more","Includes support for vectors, matrices, and transformations in Linear Algebra","Creates beautiful animations to reveal mathematical structure and relationships"],"zh":["支持代数、微积分、几何、三角学和线性代数等多个数学领域","使用 OpenAI GPT 模型将自然语言描述转换为 Manim 代码","生成精美的数学动画","支持多种数学概念，包括方程、不等式、多项式、导数、积分、极限和级数","使用 Manim 代码创建动画"],"ja":["代数、微積分、幾何、三角法、線形代数などをサポート","OpenAI の GPT モデルを使用して自然言語の説明を Manim コードに変換","美しい数学アニメーションを生成","方程式、不等式、多項式、導関数、積分、極限、級数などをサポート","Manim コードを使用してアニメーションを作成"],"ko":["대수, 미적분, 기하, 삼각, 선형대수 등 다양한 수학 분야를 지원","OpenAI의 GPT 모델을 사용하여 자연어 설명을 Manim 코드로 변환","아름다운 수학 애니메이션을 생성","방정식, 부등식, 다항식, 도함수, 적분, 극한, 급수 등 다양한 수학 개념을 지원","Manim 코드를 사용하여 애니메이션을 생성"],"es":["Soporte para álgebra, cálculo, geometría, trigonometría y álgebra lineal","Uso de OpenAI''s GPT para convertir descripciones en código Manim","Creación de animaciones matemáticas precisas y hermosas","Compatibilidad con descripciones en lenguaje natural","Generación de código Manim para animaciones personalizadas"],"fr":["Prise en charge de l''algèbre, du calcul, de la géométrie, de la trigonométrie et de l''algèbre linéaire","Utilisation d''OpenAI''s GPT pour convertir les descriptions en code Manim","Création d''animations mathématiques précises et beautés","Compatibilité avec les descriptions en langage naturel","Génération de code Manim pour des animations personnalisées"],"de":["Unterstützung für Algebra, Analysis, Geometrie, Trigonometrie und Lineare Algebra","Verwendung von OpenAI''s GPT, um Beschreibungen in Manim-Code umzuwandeln","Erstellung von präzisen und schönen mathematischen Animationen","Kompatibilität mit Beschreibungen in natürlicher Sprache","Generierung von Manim-Code für personalisierte Animationen"],"pt":["Geração de animações matemáticas com OpenAI","Suporte a equações, desigualdades e polinômios em Álgebra","Suporte a derivadas, integrais e limites em Cálculo","Suporte a formas, transformações e provas em Geometria","Suporte a funções, identidades e círculo unitário em Trigonometria","Suporte a vetores, matrizes e transformações em Álgebra Linear"],"ru":["Создание математических анимаций с помощью ИИ Агента OpenAI","Поддержка уравнений, неравенств и полиномов в Алгебре","Поддержка производных, интегралов и пределов в Исчислении","Поддержка форм, преобразований и доказательств в Геометрии","Поддержка функций, тождеств и единичного круга в Тригонометрии","Поддержка векторов, матриц и преобразований в Линейной Алгебре"],"ar":["إنشاء حركات رياضية باستخدام عامل الذكاء الاصطناعي OpenAI","دعم للمعادلات، والأشكال، والدوال في الجبر","دعم للمشتقات، والمكاملات، والحدود في التفاضل والتكامل","دعم للأشكال، والتحويلات، والبراهين في الهندسة","دعم للدوال، والهويات، والدائرة الواحدة في المثلثات","دعم للمتجهات، والматريات، والتحويلات في الجبر الخطي"]},"keywords":{"en":["how to use math-visualizer","math-visualizer alternative","math-visualizer setup guide","what is math-visualizer","math-visualizer vs Manim","math-visualizer install","mathematical animation generation","OpenAI GPT model applications","Manim code generation"],"zh":["Math Visualizer","OpenAI GPT","Manim 代码","数学动画","自然语言描述","代数","微积分","几何","三角学","线性代数"],"ja":["Math Visualizer","OpenAI GPT","Manim コード","数学アニメーション","自然言語の説明","代数","微積分","幾何","三角法","線形代数"],"ko":["Math Visualizer","OpenAI GPT","Manim 코드","수학 애니메이션","자연어 설명","대수","미적분","기하","삼각","선형대수"],"es":["herramientas de visualización matemática","animaciones matemáticas","OpenAI GPT","código Manim","descripciones en lenguaje natural","matemáticas avanzadas","visualización de ecuaciones","educación matemática","herramientas de aprendizaje"],"fr":["outils de visualisation mathématique","animations mathématiques","OpenAI GPT","code Manim","descriptions en langage naturel","mathématiques avancées","visualisation d''équations","éducation mathématique","outils d''apprentissage"],"de":["mathematische Visualisierungstools","mathematische Animationen","OpenAI GPT","Manim-Code","Beschreibungen in natürlicher Sprache","fortgeschrittene Mathematik","Gleichungsvisualisierung","mathematische Bildung","Lernwerkzeuge"],"pt":["math visualizer","animações matemáticas","OpenAI","GPT","Manim","Álgebra","Cálculo","Geometria","Trigonometria","Álgebra Linear"],"ru":["ИИ Агент Math Visualizer","математические анимации","OpenAI","GPT","Manim","Алгебра","Исчисление","Геометрия","Тригонометрия","Линейная Алгебра"],"ar":["عامل الذكاء الاصطناعي Math Visualizer","حركات رياضية","OpenAI","GPT","Manim","الجبر","التفاضل والتكامل","الهندسة","المثلثات","الجبر الخطي"]}},"owner":"rohitg00","repo":"manim-video-generator","repoPath":"rohitg00/manim-video-generator","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.284Z","topics":[],"category":"community","skillMd":{"name":"math-visualizer","description":"|","version":"1.0.0","bodyPreview":"# Math Visualizer Skill\n\nThe Math Visualizer brings mathematical concepts to life through precise, beautiful animations that reveal the structure and relationships within mathematics.\n\n## Mathematical Domains\n\n### Supported Areas\n- **Algebra**: Equations, inequalities, polynomials\n- **Calculus**: Derivatives, integrals, limits, series\n- **Geometry**: Shapes, transformations, proofs\n- **Trigonometry**: Functions, identities, unit circle\n- **Linear Algebra**: Vectors, matrices, transformations\n- *","body":"# Math Visualizer Skill\n\nThe Math Visualizer brings mathematical concepts to life through precise, beautiful animations that reveal the structure and relationships within mathematics.\n\n## Mathematical Domains\n\n### Supported Areas\n- **Algebra**: Equations, inequalities, polynomials\n- **Calculus**: Derivatives, integrals, limits, series\n- **Geometry**: Shapes, transformations, proofs\n- **Trigonometry**: Functions, identities, unit circle\n- **Linear Algebra**: Vectors, matrices, transformations\n- **Complex Analysis**: Complex numbers, transformations\n- **Number Theory**: Primes, sequences, patterns\n\n## Rules\n\n### [rules/equation-presentation.md](rules/equation-presentation.md)\nHow to present equations with proper pacing and emphasis.\n\n### [rules/color-coding-math.md](rules/color-coding-math.md)\nConsistent color schemes for mathematical elements.\n\n### [rules/graphing-best-practices.md](rules/graphing-best-practices.md)\nCreating clear, informative function graphs.\n\n### [rules/proof-visualization.md](rules/proof-visualization.md)\nStep-by-step proof animations that build understanding.\n\n## Color Coding Standard\n\n| Element | Color | Hex |\n|---------|-------|-----|\n| Variables (x, y) | BLUE | #58C4DD |\n| Constants | YELLOW | #FFFF00 |\n| Operators | WHITE | #FFFFFF |\n| Key Terms | GREEN | #83C167 |\n| Equals/Results | GOLD | #FFD700 |\n| Negative/Subtract | RED | #FC6255 |\n\n## Templates\n\n### Equation Derivation\n```python\nfrom manim import *\n\nclass EquationDerivation(Scene):\n    def construct(self):\n        # Initial equation\n        eq1 = MathTex(r\"x^2 + 2x + 1 = 0\")\n        self.play(Write(eq1))\n        self.wait()\n\n        # Transform step by step\n        eq2 = MathTex(r\"(x + 1)^2 = 0\")\n        eq3 = MathTex(r\"x + 1 = 0\")\n        eq4 = MathTex(r\"x = -1\")\n\n        # Show each transformation\n        for new_eq in [eq2, eq3, eq4]:\n            self.play(TransformMatchingTex(eq1, new_eq))\n            self.wait()\n            eq1 = new_eq\n\n        # Highlight final answer\n        box = SurroundingRectangle(eq4, color=GREEN, buff=0.2)\n        self.play(Create(box))\n```\n\n### Color-Coded Equation\n```python\nfrom manim import *\n\nclass ColorCodedEquation(Scene):\n    def construct(self):\n        # Equation with color-coded parts\n        equation = MathTex(\n            r\"f(\", r\"x\", r\") = \", r\"a\", r\"x^2\", r\" + \", r\"b\", r\"x\", r\" + \", r\"c\"\n        )\n\n        # Color code\n        equation[1].set_color(BLUE)   # x\n        equation[3].set_color(YELLOW) # a\n        equation[4].set_color(BLUE)   # x^2\n        equation[6].set_color(YELLOW) # b\n        equation[7].set_color(BLUE)   # x\n        equation[9].set_color(YELLOW) # c\n\n        self.play(Write(equation))\n\n        # Explain each part\n        labels = [\n            (equation[3], \"coefficient\"),\n            (equation[1], \"variable\"),\n            (equation[9], \"constant\")\n        ]\n\n        for part, label_text in labels:\n            self.play(Indicate(part))\n            label = Text(label_text, font_size=24).next_to(part, DOWN)\n            self.play(Write(label))\n            self.wait()\n            self.play(FadeOut(label))\n```\n\n### Function Graph with Animation\n```python\nfrom manim import *\n\nclass FunctionGraph(Scene):\n    def construct(self):\n        # Create axes\n        axes = Axes(\n            x_range=[-4, 4, 1],\n            y_range=[-2, 8, 1],\n            x_length=8,\n            y_length=5,\n            axis_config={\"include_tip\": True}\n        )\n        labels = axes.get_axis_labels(x_label=\"x\", y_label=\"y\")\n\n        self.play(Create(axes), Write(labels))\n\n        # Function\n        func = axes.plot(lambda x: x**2, color=BLUE)\n        func_label = MathTex(r\"f(x) = x^2\", color=BLUE).to_corner(UR)\n\n        self.play(Create(func), Write(func_label))\n\n        # Show derivative\n        deriv = axes.plot(lambda x: 2*x, color=GREEN)\n        deriv_label = MathTex(r\"f''(x) = 2x\", color=GREEN).next_to(func_label, DOWN)\n\n        self.play(Create(deriv), Write(deriv_label))\n\n        # Tangent line demonstration\n        x_tracker = ValueTracker(-2)\n\n        tangent = always_redraw(lambda: axes.get_secant_slope_group(\n            x=x_tracker.get_value(),\n            graph=func,\n            dx=0.01,\n            secant_line_color=YELLOW,\n            secant_line_length=4\n        ))\n\n        dot = always_redraw(lambda: Dot(\n            axes.c2p(x_tracker.get_value(), x_tracker.get_value()**2),\n            color=RED\n        ))\n\n        self.play(Create(tangent), Create(dot))\n        self.play(x_tracker.animate.set_value(2), run_time=4)\n```\n\n### 3D Mathematical Surface\n```python\nfrom manim import *\n\nclass Surface3D(ThreeDScene):\n    def construct(self):\n        # Set up camera\n        self.set_camera_orientation(phi=75 * DEGREES, theta=-45 * DEGREES)\n\n        # Create axes\n        axes = ThreeDAxes(\n            x_range=[-3, 3, 1],\n            y_range=[-3, 3, 1],\n            z_range=[-2, 2, 1]\n        )\n\n        # Create surface\n        surface = Surface(\n            lambda u, v: axes.c2p(u, v, np.sin(u) * np.cos(v)),\n            u_range=[-PI, PI],\n            v_range=[-PI, PI],\n            resolution=(30, 30),\n            fill_opacity=0.7\n        )\n        surface.set_fill_by_value(\n            axes=axes,\n            colorscale=[(RED, -1), (YELLOW, 0), (GREEN, 1)]\n        )\n\n        # Animate\n        self.play(Create(axes))\n        self.play(Create(surface), run_time=3)\n        self.begin_ambient_camera_rotation(rate=0.2)\n        self.wait(5)\n```\n\n### Geometric Proof\n```python\nfrom manim import *\n\nclass PythagoreanProof(Scene):\n    def construct(self):\n        # Create right triangle\n        triangle = Polygon(\n            ORIGIN, RIGHT * 3, RIGHT * 3 + UP * 4,\n            color=WHITE, fill_opacity=0.3\n        )\n\n        # Labels\n        a_label = MathTex(\"a\").next_to(triangle, DOWN)\n        b_label = MathTex(\"b\").next_to(triangle, RIGHT)\n        c_label = MathTex(\"c\").move_to(\n            (ORIGIN + RIGHT * 3 + UP * 4) / 2 + LEFT * 0.5 + UP * 0.3\n        )\n\n        self.play(Create(triangle))\n        self.play(Write(a_label), Write(b_label), Write(c_label))\n\n        # Show squares on each side\n        sq_a = Square(side_length=3, color=BLUE, fill_opacity=0.5)\n        sq_a.next_to(triangle, DOWN, buff=0)\n\n        sq_b = Square(side_length=4, color=GREEN, fill_opacity=0.5)\n        sq_b.next_to(triangle, RIGHT, buff=0)\n\n        self.play(Create(sq_a), Create(sq_b))\n\n        # Area labels\n        area_a = MathTex(r\"a^2\", color=BLUE).move_to(sq_a)\n        area_b = MathTex(r\"b^2\", color=GREEN).move_to(sq_b)\n\n        self.play(Write(area_a), Write(area_b))\n\n        # Conclusion\n        theorem = MathTex(r\"a^2 + b^2 = c^2\").to_edge(UP)\n        box = SurroundingRectangle(theorem, color=GOLD)\n\n        self.play(Write(theorem), Create(box))\n```\n\n## LaTeX Quick Reference\n\n### Common Expressions\n```latex\n% Fractions\n\\frac{a}{b}\n\n% Square root\n\\sqrt{x}  \\sqrt[n]{x}\n\n% Summation\n\\sum_{i=1}^{n} x_i\n\n% Integral\n\\int_{a}^{b} f(x) \\, dx\n\n% Limit\n\\lim_{x \\to \\infty} f(x)\n\n% Matrix\n\\begin{pmatrix} a & b \\\\ c & d \\end{pmatrix}\n\n% Partial derivative\n\\frac{\\partial f}{\\partial x}\n```\n\n### Greek Letters\n```latex\n\\alpha \\beta \\gamma \\delta \\epsilon\n\\theta \\lambda \\mu \\pi \\sigma \\omega\n\\Gamma \\Delta \\Theta \\Lambda \\Sigma \\Omega\n```\n\n## Best Practices\n\n1. **Reveal equations gradually** - Build up complex equations piece by piece\n2. **Use consistent notation** - Same symbol = same meaning throughout\n3. **Annotate meaningfully** - Labels should clarify, not clutter\n4. **Show, don''t just state** - Animate the mathematical relationships\n5. **Connect to intuition** - Bridge abstract math to visual understanding\n"},"lastSynced":"2026-03-08T02:00:56.197Z","agentAnalysis":{"suitability":{"en":"Perfect for Educational Agents needing interactive mathematical visualizations and animations.","zh":"非常适合需要交互式数学可视化和动画的教育代理。","ja":"教育エージェントがインタラクティブな数学のビジュアライゼーションとアニメーションを必要とする場合に最適です。","ko":"교육 에이전트가 상호작용형 수학 시각화 및 애니메이션을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes Educativos que necesitan visualizaciones y animaciones matemáticas interactivas.","fr":"Parfait pour les Agents Éducatifs ayant besoin de visualisations et d''animations mathématiques interactives.","de":"Perfekt für Bildungsagenten, die interaktive mathematische Visualisierungen und Animationen benötigen.","pt":"Perfeito para Agentes Educacionais que necessitam de visualizações e animações matemáticas interativas.","ru":"Идеально подходит для образовательных агентов, которым необходимы интерактивные математические визуализации и анимации.","ar":"مثالي لعمليات एजنت التعليمية التي تحتاج إلى تصورات ورسوم متحركة رياضية تفاعلية."},"recommendation":{"en":"Empowers agents to generate precise mathematical animations using natural language descriptions, supporting various mathematical domains such as Algebra, Calculus, Geometry, Trigonometry, and Linear Algebra, utilizing libraries like p5.js and outputting animations in formats like SVG.","zh":"赋予代理生成精确的数学动画的能力，使用自然语言描述，支持多个数学领域，例如代数、微积分、几何、三角学和线性代数，利用像 p5.js 的库，并以 SVG 等格式输出动画。","ja":"エージェントが自然言語の説明を使用して正確な数学アニメーションを生成することを可能にします。代数、微積分、幾何学、 тригонометрия、線形代数などのさまざまな数学ドメインをサポートし、p5.js などのライブラリを利用し、SVG などの形式でアニメーションを出力します。","ko":"에이전트가 자연어 설명을 사용하여 정확한 수학 애니메이션을 생성할 수 있도록 합니다. 대수, 미적분, 기하학, 삼각법, 선형대수와 같은 다양한 수학 영역을 지원하며 p5.js와 같은 라이브러리를 사용하고 SVG와 같은 형식으로 애니메이션을 출력합니다.","es":"Habilita a los agentes a generar animaciones matemáticas precisas utilizando descripciones de lenguaje natural, que admiten varios dominios matemáticos como Álgebra, Cálculo, Geometría, Trigonometría y Álgebra Lineal, utilizando bibliotecas como p5.js y generando animaciones en formatos como SVG.","fr":"Permet aux agents de générer des animations mathématiques précises en utilisant des descriptions de langage naturel, en prenant en charge divers domaines mathématiques tels que l''Algèbre, le Calcul, la Géométrie, la Trigonométrie et l''Algèbre Linéaire, en utilisant des bibliothèques comme p5.js et en produisant des animations au format SVG.","de":"Ermöglicht es Agenten, präzise mathematische Animationen mithilfe von natürlichen Sprachbeschreibungen zu erzeugen, die verschiedene mathematische Bereiche wie Algebra, Analysis, Geometrie, Trigonometrie und lineare Algebra unterstützen, unter Verwendung von Bibliotheken wie p5.js und Ausgabe von Animationen in Formaten wie SVG.","pt":"Habilita os agentes a gerar animações matemáticas precisas usando descrições em linguagem natural, suportando vários domínios matemáticos como Álgebra, Cálculo, Geometria, Trigonometria e Álgebra Linear, utilizando bibliotecas como p5.js e produzindo animações em formatos como SVG.","ru":"Наделяет агентов возможностью генерировать точные математические анимации с использованием описаний на естественном языке, поддерживая различные математические области, такие как Алгебра, Исчисление, Геометрия, Тригонометрия и Линейная Алгебра, используя библиотеки типа p5.js и выводя анимации в форматах типа SVG.","ar":"تمكين الوكلاء من توليد رسوم متحركة رياضية دقيقة باستخداموصف لغة طبيعية ، ودعم مجالات رياضية مختلفة مثل الجبر ، والتفاضل والتكامل ، والهندسة ، ومثلثات ، والجبر الخطي ، باستخدام مكتبات مثل p5.js وانتاج الرسوم المتحركة في صيغ مثل SVG."},"useCases":{"en":["Generating interactive animations for calculus concepts like derivatives and integrals","Visualizing algebraic equations and inequalities for educational purposes","Creating geometric shape transformations and proofs for math lessons","Animating trigonometric functions and identities for unit circle explanations","Illustrating linear algebra concepts like vector and matrix transformations"],"zh":["为微积分概念（如导数和积分）生成交互式动画","可视化代数方程和不等式，用于教育目的","创建几何形状转换和证明，用于数学课程","动画三角函数和恒等式，用于单位圆解释","说明线性代数概念，如向量和矩阵转换"],"ja":["導関数や積分などの微積分の概念のインタラクティブなアニメーションを生成する","教育目的のための代数方程式と不等式の視覚化","数学の授業のための幾何学的形状の変換と証明の作成","単位円の説明のための三角関数と恒等式のアニメーション","ベクトルと行列の変換などの線形代数の概念の説明"],"ko":["도함수와 적분과 같은 미적분 개념에 대한 상호작용 애니메이션 생성","교육 목적을 위한 대수 방정식 및 부등식의 시각화","수학 수업을 위한 기하학적 도형 변환 및 증명의 생성","단위 원의 설명을 위한 三角함수 및 등식의 애니메이션","벡터 및 행렬 변환과 같은 선형대수 개념 설명"],"es":["Generar animaciones interactivas para conceptos de cálculo como derivadas e integrales","Visualizar ecuaciones e inecuaciones algebraicas para fines educativos","Crear transformaciones de formas geométricas y pruebas para lecciones de matemáticas","Animar funciones trigonométricas e identidades para explicaciones del círculo unitario","Ilustrar conceptos de álgebra lineal como transformaciones de vectores y matrices"],"fr":["Générer des animations interactives pour des concepts de calcul tels que les dérivées et les intégrales","Visualiser des équations et des inégalités algébriques à des fins éducatives","Créer des transformations de formes géométriques et des preuves pour des leçons de mathématiques","Animer des fonctions trigonométriques et des identités pour des explications du cercle unitaire","Illustre des concepts d''algèbre linéaire tels que les transformations de vecteurs et de matrices"],"de":["Interaktive Animationen für Analysis-Konzepte wie Ableitungen und Integrale erzeugen","Algebraische Gleichungen und Ungleichungen für Bildungszwecke visualisieren","Geometrische Formen-Transformationen und Beweise für Mathematik-Lektionen erstellen","Trigonometrische Funktionen und Identitäten für Erklärungen des Einheitskreises animieren","Konzepte der linearen Algebra wie Vektor- und Matrix-Transformationen veranschaulichen"],"pt":["Gerar animações interativas para conceitos de cálculo como derivadas e integrais","Visualizar equações e desigualdades algébricas para fins educacionais","Criar transformações de formas geométricas e provas para lições de matemática","Animar funções trigonométricas e identidades para explicações do círculo unitário","Ilustrar conceitos de álgebra linear como transformações de vetores e matrizes"],"ru":["Генерировать интерактивные анимации для концепций исчисления, таких как производные и интегралы","Визуализировать алгебраические уравнения и неравенства для образовательных целей","Создавать геометрические преобразования фигур и доказательства для уроков математики","Анимировать тригонометрические функции и тождества для объяснений единичного круга","Иллюстрировать концепции линейной алгебры, такие как преобразования векторов и матриц"],"ar":["توليد الرسوم المتحركة التفاعلية لمفاهيم التفاضل والتكامل مثل المشتقات والمكامل","تجسير المعادلات واللامعادلات الجبرية للأغراض التعليمية","إنشاء تحويلات أشكال هندسية وبراهين لدروس الرياضيات","توليد الرسوم المتحركة للدوال المثلثية والهويات لشرح الدائرة الواحدة","توضيح مفاهيم الجبر الخطي مثل تحويلات المتجهات والمصفوفات"]},"limitations":{"en":["Limited to supported mathematical domains","Requires precise natural language descriptions for accurate animations","Dependent on libraries like p5.js for animation rendering"],"zh":["仅限支持的数学领域","需要精确的自然语言描述才能生成准确的动画","依赖于像 p5.js 的库来渲染动画"],"ja":["サポートされている数学ドメインのみ","正確なアニメーションを生成するには、正確な自然言語の説明が必要","p5.js などのライブラリに依存してアニメーションをレンダリングする"],"ko":["지원되는 수학 영역만","정확한 애니메이션을 생성하려면 정확한 자연어 설명이 필요","애니메이션 렌더링을 위해 p5.js와 같은 라이브러리에 의존"],"es":["Limitado a los dominios matemáticos admitidos","Requiere descripciones de lenguaje natural precisas para animaciones precisas","Dependiente de bibliotecas como p5.js para la representación de animaciones"],"fr":["Limité aux domaines mathématiques pris en charge","Nécessite des descriptions de langage naturel précises pour des animations précises","Dépendant de bibliothèques comme p5.js pour le rendu d''animations"],"de":["Begrenzt auf unterstützte mathematische Bereiche","Benötigt präzise natürliche Sprachbeschreibungen für genaue Animationen","Abhängig von Bibliotheken wie p5.js für die Animationendarstellung"],"pt":["Limitado aos domínios matemáticos suportados","Exige descrições em linguagem natural precisas para animações precisas","Dependente de bibliotecas como p5.js para renderização de animações"],"ru":["Ограничен поддерживаемыми математическими областями","Требует точных описаний на естественном языке для точных анимаций","Зависит от библиотек типа p5.js для рендеринга анимаций"],"ar":["محدود بالمجالات الرياضية المدعومة","يتطلب وصفًا دقيقًا بلغة طبيعية لرسوم متحركة دقيقة","يعتمد على مكتبات مثل p5.js لتصيير الرسوم المتحركة"]},"version":4},"contentHash":"064fc7a01b13bee0ed3780c36fad7d737031908107a1c1d60427177492f95021","qualityScore":38}');
