INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vargHQ/sdk/varg-video-generation', 'varg-video-generation', 'vargHQ', 'sdk', 'community', 'varg-video-generation vargHQ sdk community varg-video-generation is an AI-native SDK for video tooling, allowing developers to generate AI videos using declarative JSX syntax. It benefits developers seeking automated video generation with caching and parallel processing. varg-video-generation是一个AI-native SDK，支持declarative JSX语法，用于生成AI视频 varg-video-generationはAI-native SDKで、declarative JSX構文をサポートしてAIビデオを生成します varg-video-generation은 AI-native SDK로 선언적 JSX 구문을 지원하여 AI 비디오를 생성합니다 varg-video-generation es un SDK nativo de IA para herramientas de vídeo que permite generar vídeos AI con sintaxis JSX declarativa varg-video-generation est un SDK natif d''IA pour les outils de vidéo qui permet de générer des vidéos AI avec une syntaxe JSX déclarative varg-video-generation ist ein natives IA-SDK für Videotools, das die Erstellung von AI-Videos mit deklarativer JSX-Syntax ermöglicht O varg-video-generation é um SDK de IA para ferramentas de vídeo que permite geração de vídeos com JSX e React varg-video-generation - это AI-родной SDK для видеоинструментов, который позволяет генерировать видео с помощью JSX и React varg-video-generation هو SDK ذكي لادوات الفيديو الذي يسمح بإنشاء مقاطع فيديو باستخدام JSX و React how to use varg-video-generation varg-video-generation setup guide varg-video-generation alternative varg-video-generation vs competing SDKs varg-video-generation install what is varg-video-generation varg-video-generation JSX syntax AI-native video generation automatic video caching varg-video-generation AI-native SDK declarative JSX 自动缓存 并行生成 bunx vargai FAL_KEY ELEVENLABS_API_KEY Generates AI videos using declarative JSX syntax Supports automatic caching for efficient video generation Enables parallel generation for faster video processing Initializes new projects with bunx vargai init command Creates hello.tsx starters with bunx vargai hello command varg-video-generation is an AI-native SDK for video tooling that enables developers to generate videos using JSX syntax with automatic caching and parallel generation capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nexus-labs-automation/mobile-observability/session-replay', 'community', 'nexus-labs-automation', 'mobile-observability', 'nexus-labs-automation/mobile-observability', 'session-replay', 0, 0, 38, '2026-03-08T01:57:15.286Z', '2026-03-08T02:00:58.063Z', '044e03c3c8cfdb2f4f5e5062fbb302ab78ce60692bd13c276a0399547e172f43', '{"id":"nexus-labs-automation/mobile-observability/session-replay","name":"session-replay","description":{"en":"Session-replay is a Claude Code plugin for mobile app observability, providing crash reporting, performance monitoring, and instrumentation for iOS, Android, and React Native. It benefits developers and QA teams.","zh":"会话回放插件为移动应用提供可观测性，包括崩溃报告、性能监控和仪表化，支持iOS、Android和React Native","ja":"セッションリプレイプラグインは、モバイルアプリの可観測性を提供し、クラッシュレポート、パフォーマンスモニタリング、計装化をサポートします","ko":"세션 리플레이 플러그인은 모바일 앱의 관측성을 제공하며, 충돌 보고, 성능 모니터링, 기기화 등을 지원합니다","es":"Session-replay es un plugin de Claude Code para la observabilidad móvil que permite capturar grabaciones visuales de sesiones de usuario para la depuración y el monitoreo de rendimiento","fr":"Session-replay est un plugin Claude Code pour l''observabilité mobile qui permet de capturer des enregistrements visuels de sessions utilisateur pour le débogage et le suivi des performances","de":"Session-replay ist ein Plugin von Claude Code für die mobile Observabilität, das die Erfassung visueller Aufzeichnungen von Benutzersitzungen für die Fehlersuche und Leistungsüberwachung ermöglicht","pt":"O Session Replay é um plugin para observabilidade de aplicativos móveis, permitindo capturar gravações visuais de sessões de usuário para depuração","ru":"Сессия Replay - это плагин для наблюдения за мобильными приложениями, который позволяет записывать визуальные сессии пользователей для отладки","ar":"Session Replay هو مكون إضافي لمراقبة التطبيقات النقالة، يسمح بتسجيل جلسات المستخدمين لتصحيح الأخطاء"},"seo":{"title":{"en":"Session-Replay: Crash Reporting and Performance Monitorin...","zh":"会话回放设置指南：移动应用可观测性最佳实践","ja":"セッションリプレイの設定方法：モバイルアプリの可観測性向上","ko":"세션 리플레이 설정 가이드: 모바일 앱 관측성 최적화","es":"Guía de Configuración de session-replay para Observabilid...","fr":"Configurer session-replay pour l''Observabilité Mobile","de":"Einrichtungsanleitung für session-replay zur mobilen Obse...","pt":"Guia de Configuração do Session Replay para Desenvolvedores","ru":"ИИ Агенты: Руководство по Настройке Session Replay","ar":"دليل إعداد Session Replay للأجهزة الذكية"},"description":{"en":"Unlock mobile app observability with session-replay. Learn how to capture user sessions, debug issues, and optimize performance. Get started now!","zh":"了解如何使用会话回放插件提高移动应用的可观测性，包括崩溃报告、性能监控和仪表化","ja":"セッションリプレイプラグインを使用してモバイルアプリの可観測性を向上させる方法について説明します","ko":"세션 리플레이 플러그인을 사용하여 모바일 앱의 관측성을 향상시키는 방법에 대해 알아보세요","es":"Aprende a configurar session-replay para capturar grabaciones visuales de sesiones de usuario y mejorar la depuración en iOS, Android y React Native","fr":"Découvrez comment configurer session-replay pour capturer des enregistrements visuels de sessions utilisateur et améliorer le débogage sur iOS, Android et Re...","de":"Erfahren Sie, wie Sie session-replay konfigurieren, um visuelle Aufzeichnungen von Benutzersitzungen zu erfassen und die Fehlersuche in iOS, Android und Reac...","pt":"Aprenda a configurar o Session Replay para capturar gravações visuais de sessões de usuário para depuração em iOS, Android e React Native","ru":"Используйте ИИ Агенты для сбора данных о сессиях пользователей и улучшения производительности мобильных приложений","ar":"استخدم Session Replay لتسجيل جلسات المستخدمين وتصحيح الأخطاء في التطبيقات النقالة"},"definition":{"en":"Session-replay is a technique for capturing visual recordings of user sessions to aid in debugging and understanding user behavior.","zh":"会话回放是一种可观测性技术，用于捕获用户会话的视觉记录以进行调试","ja":"セッションリプレイは、ユーザーセッションの視覚的な記録をキャプチャしてデバッグを行う可観測性技術です","ko":"세션 리플레이는 사용자 세션의 시각적 기록을 캡처하여 디버깅을 수행하는 관측성 기술입니다","es":"Session-replay es una técnica de depuración que permite capturar grabaciones visuales de sesiones de usuario para reproducir y analizar problemas","fr":"Session-replay est une technique de débogage qui permet de capturer des enregistrements visuels de sessions utilisateur pour reproduire et analyser des problèmes","de":"Session-replay ist eine Fehlersuchtechnik, die die Erfassung visueller Aufzeichnungen von Benutzersitzungen ermöglicht, um Probleme zu reproduzieren und zu analysieren","pt":"Session Replay é uma tecnologia que captura gravações visuais de sessões de usuário para depuração e análise","ru":"Сессия Replay - это технология, которая записывает визуальные сессии пользователей для отладки и анализа","ar":"Session Replay هو تقنية لتسجيل جلسات المستخدمين لتصحيح الأخطاء والتحليل"},"features":{"en":["Captures visual recordings of user sessions for debugging","Provides crash reporting and performance monitoring for iOS, Android, and React Native","Masks sensitive data, including text input fields, passwords, and financial information","Operates within a performance budget of <5% additional CPU and <20MB additional memory","Supports QA and support investigations"],"zh":["崩溃报告","性能监控","仪表化","支持iOS、Android和React Native","遮蔽默认的文本输入字段和敏感数据","CPU使用率小于5%，内存使用率小于20MB"],"ja":["クラッシュレポート","パフォーマンスモニタリング","計装化","iOS、Android、React Nativeをサポート","テキスト入力フィールドと機密データのマスキング","CPU使用率5%未満、メモリ使用率20MB未満"],"ko":["충돌 보고","성능 모니터링","기기화","iOS, Android, React Native 지원","텍스트 입력 필드와 민감한 데이터 마스킹","CPU 사용량 5% 미만, 메모리 사용량 20MB 미만"],"es":["Captura de grabaciones visuales de sesiones de usuario","Depuración de errores difíciles de reproducir","Monitoreo de rendimiento para iOS, Android y React Native","Instrumentación para la recopilación de datos de rendimiento","Privacidad integrada con enmascaramiento de datos sensibles"],"fr":["Capture d''enregistrements visuels de sessions utilisateur","Débogage d''erreurs difficiles à reproduire","Suivi des performances pour iOS, Android et React Native","Instrumentation pour la collecte de données de performances","Confidentialité intégrée avec masquage de données sensibles"],"de":["Erfassung visueller Aufzeichnungen von Benutzersitzungen","Fehlersuche bei schwer reproduzierbaren Fehlern","Leistungsüberwachung für iOS, Android und React Native","Instrumentierung für die Erfassung von Leistungsdaten","Integrierte Datenschutzfunktionen mit Maskierung sensibler Daten"],"pt":["Captura de gravações visuais de sessões de usuário","Depuração de problemas difíceis de reproduzir","Monitoramento de desempenho em iOS, Android e React Native","Instrumentação para análise de dados","Proteção de privacidade com mascaramento de dados sensíveis"],"ru":["Запись визуальных сессий пользователей","Отладка трудно воспроизводимых проблем","Мониторинг производительности в iOS, Android и React Native","Инструментирование для анализа данных","Защита конфиденциальности с помощью маскирования чувствительных данных"],"ar":["تسجيل جلسات المستخدمين","تصحيح الأخطاء الصعبة","مراقبة الأداء في iOS و Android و React Native","أدوات لتحليل البيانات","حماية البيانات الحساسة بمasking"]},"keywords":{"en":["how to use session-replay","session-replay plugin","mobile app observability","crash reporting tools","session-replay vs bugsnag","session-replay install guide","what is session-replay","session-replay alternative","session-replay setup for react native"],"zh":["会话回放","移动应用可观测性","崩溃报告","性能监控","仪表化","React Native","iOS","Android","AIエージェント","可观测性技术"],"ja":["セッションリプレイ","モバイルアプリの可観測性","クラッシュレポート","パフォーマンスモニタリング","計装化","React Native","iOS","Android","AIエージェント","可観測性技術"],"ko":["세션 리플레이","모바일 앱 관측성","충돌 보고","성능 모니터링","기기화","React Native","iOS","Android","AI 에이전트","관측성 기술"],"es":["session-replay","observabilidad móvil","depuración de errores","monitoreo de rendimiento","instrumentación de aplicaciones","privacidad de datos","iOS","Android","React Native"],"fr":["session-replay","observabilité mobile","débogage d''erreurs","suivi des performances","instrumentation d''applications","confidentialité des données","iOS","Android","React Native"],"de":["session-replay","mobile Observabilität","Fehlersuche","Leistungsüberwachung","Instrumentierung von Anwendungen","Datenschutz","iOS","Android","React Native"],"pt":["session replay","observabilidade de aplicativos móveis","depuração de aplicativos","monitoramento de desempenho","React Native","iOS","Android","desenvolvimento de aplicativos móveis"],"ru":["сессия replay","наблюдение за мобильными приложениями","отладка приложений","мониторинг производительности","React Native","iOS","Android","разработка мобильных приложений"],"ar":["session replay","مراقبة التطبيقات النقالة","تصحيح الأخطاء","مراقبة الأداء","React Native","iOS","Android","تطوير التطبيقات النقالة"]}},"owner":"nexus-labs-automation","repo":"mobile-observability","repoPath":"nexus-labs-automation/mobile-observability","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.286Z","topics":[],"category":"community","skillMd":{"name":"session-replay","description":"Set up session replay for visual debugging. Use when implementing screen recording, replay features, or visual debugging tools.","bodyPreview":"# Session Replay\n\nCapture visual recordings of user sessions for debugging.\n\n## When to Use\n\n- Reproducing hard-to-debug issues\n- Understanding user confusion\n- QA and support investigations\n\n## Privacy Requirements (Must Do)\n\nMask by default:\n- All text input fields\n- Passwords and sensitive data\n- User-generated content\n- Financial information\n- User photos/documents\n\n## Performance Budget\n\n| Resource | Limit |\n|----------|-------|\n| CPU | <5% additional |\n| Memory | <20MB additional |\n| Netwo","body":"# Session Replay\n\nCapture visual recordings of user sessions for debugging.\n\n## When to Use\n\n- Reproducing hard-to-debug issues\n- Understanding user confusion\n- QA and support investigations\n\n## Privacy Requirements (Must Do)\n\nMask by default:\n- All text input fields\n- Passwords and sensitive data\n- User-generated content\n- Financial information\n- User photos/documents\n\n## Performance Budget\n\n| Resource | Limit |\n|----------|-------|\n| CPU | <5% additional |\n| Memory | <20MB additional |\n| Network | Batch on WiFi |\n| Battery | Pause when low |\n\n## Capture Strategies\n\n| Strategy | Fidelity | Overhead |\n|----------|----------|----------|\n| Screenshots (1-2 fps) | Lower | Lower |\n| View hierarchy recording | Higher | Moderate |\n| Hybrid (screenshots + events) | Best | Moderate |\n\n## Best Practice\n\nDon''t record everything. Target:\n- Error sessions only (rolling buffer)\n- Key user journeys\n- 1-10% sampling for general insights\n\n## Implementation\n\nSee `references/session-replay.md` for:\n- Platform-specific setup\n- Privacy masking patterns\n- Vendor configurations (Sentry, Datadog)\n"},"lastSynced":"2026-03-08T02:00:58.063Z","agentAnalysis":{"suitability":{"en":"Perfect for Mobile App Analysis Agents needing advanced crash reporting and performance monitoring capabilities.","zh":"适合需要高级崩溃报告和性能监控能力的移动应用分析代理。","ja":"高度なクラッシュレポートとパフォーマンスモニタリング機能を必要とするモバイルアプリ分析エージェントに最適です。","ko":"고급 크래시 보고 및 성능 모니터링 기능이 필요한 모바일 앱 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Aplicaciones Móviles que necesitan capacidades de informes de errores y monitoreo de rendimiento avanzados.","fr":"Parfait pour les Agents d''Analyse d''Applications Mobiles ayant besoin de fonctionnalités de rapport d''erreurs et de surveillance de performances avancées.","de":"Perfekt für Mobile App Analyse-Agents, die erweiterte Absturzberichterstattungs- und Leistungsüberwachungsfunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Aplicativos Móveis que precisam de recursos avançados de relatórios de falhas e monitoramento de desempenho.","ru":"Идеально подходит для Агентов анализа мобильных приложений, которым необходимы продвинутые функции отчетов о сбоях и мониторинга производительности.","ar":"مثالي لعميل تحليل تطبيقات الجوال الذين يحتاجون إلى تقارير متقدمة عن الأعطال ومراقبة الأداء."},"recommendation":{"en":"Empowers agents to capture visual recordings of user sessions for debugging, utilizing crash reporting, performance monitoring, and instrumentation for iOS, Android, and React Native, while ensuring privacy through default masking of sensitive data such as text input fields and passwords.","zh":"赋予代理捕获用户会话的视觉录制用于调试，利用崩溃报告、性能监控和仪表化，支持iOS、Android和React Native，同时通过默认屏蔽敏感数据（如文本输入字段和密码）来确保隐私。","ja":"エージェントにユーザーセッションの視覚的なレコーディングをキャプチャし、クラッシュレポート、パフォーマンスモニタリング、およびインストルメンテーションを使用してデバッグを行うことを可能にします。iOS、Android、React Nativeをサポートし、テキスト入力フィールドやパスワードなどの機密データをデフォルトでマスクしてプライバシーを確保します。","ko":"에이전트가 사용자 세션의 시각적 녹화를 캡처하여 디버깅에 사용하고, 크래시 보고, 성능 모니터링 및 계측을 사용하여 iOS, Android 및 React Native를 지원하며, 텍스트 입력 필드 및 비밀번호와 같은 민감한 데이터를 기본적으로 마스킹하여 개인 정보를 보장합니다.","es":"Habilita a los agentes a capturar grabaciones visuales de sesiones de usuario para depuración, utilizando informes de errores, monitoreo de rendimiento e instrumentación para iOS, Android y React Native, garantizando la privacidad a través de la mascarada predeterminada de datos sensibles como campos de entrada de texto y contraseñas.","fr":"Permet aux agents de capturer des enregistrements visuels de sessions utilisateur pour le débogage, en utilisant les rapports d''erreurs, la surveillance des performances et l''instrumentation pour iOS, Android et React Native, tout en assurant la confidentialité grâce au masquage par défaut des données sensibles telles que les champs de saisie de texte et les mots de passe.","de":"Ermächtigt Agenten, visuelle Aufzeichnungen von Benutzersitzungen für die Fehlerbehebung zu erfassen, indem sie Fehlerberichte, Leistungsüberwachung und Instrumentierung für iOS, Android und React Native nutzen, während die Privatsphäre durch die standardmäßige Maskierung sensibler Daten wie Texteingabefelder und Passwörter gewährleistet wird.","pt":"Permite que os agentes capturem gravações visuais de sessões de usuário para depuração, utilizando relatórios de falhas, monitoramento de desempenho e instrumentação para iOS, Android e React Native, garantindo a privacidade por meio do mascaramento padrão de dados sensíveis, como campos de entrada de texto e senhas.","ru":"Позволяет агентам захватывать визуальные записи сессий пользователей для отладки, используя отчеты о сбоях, мониторинг производительности и инструментирование для iOS, Android и React Native, обеспечивая конфиденциальность за счет маскирования конфиденциальных данных, таких как поля ввода текста и пароли.","ar":"يمكن للعميل من التقاط التسجيلات المرئية للجلسات الخاصة بالمستخدمين من أجل التصحيح، واستخدام تقارير الأعطال ومراقبة الأداء والآلات لiOS وAndroid وReact Native، مع ضمان الخصوصية من خلال التماسك الافتراضي للبيانات الحساسة مثل حقول إدخال النص وكلمات المرور."},"useCases":{"en":["Reproducing hard-to-debug issues","Understanding user confusion through session replay","Conducting QA and support investigations"],"zh":["重现难以调试的问题","通过会话回放理解用户困惑","进行QA和支持调查"],"ja":["デバッグが難しい問題の再現","セッションリプレイを使用したユーザーの混乱の理解","QAおよびサポートの調査の実施"],"ko":["어려운 디버깅 문제 재현","세션 재생을 통한 사용자 혼란 이해","QA 및 지원 조사 수행"],"es":["Reproducir problemas difíciles de depurar","Comprender la confusión del usuario a través de la repetición de la sesión","Realizar investigaciones de garantía de calidad y soporte"],"fr":["Reproduire des problèmes difficiles à déboguer","Comprendre la confusion de l''utilisateur à travers la répétition de la session","Effectuer des enquêtes de garantie de qualité et de support"],"de":["Schwierig zu debuggende Probleme reproduzieren","Benutzerverwirrung durch Sitzungswiederholung verstehen","Qualitäts- und Supportuntersuchungen durchführen"],"pt":["Reproduzir problemas difíceis de depurar","Entender a confusão do usuário por meio da reprodução de sessão","Realizar investigações de QA e suporte"],"ru":["Воспроизводить трудно диагностируемые проблемы","Понимать путаницу пользователя через воспроизведение сессии","Проводить расследования QA и поддержки"],"ar":["إعادة إنتاج المشكلات الصعبة في التصحيح","فهم ارتباك المستخدم من خلال إعادة تشغيل الجلسة","إجراء تحقيقات دعم وضمان الجودة"]},"limitations":{"en":["Requires Claude Code plugin integration","CPU usage limited to <5% additional","Memory usage limited to <20MB additional"],"zh":["需要Claude Code插件集成","CPU使用量限制为<5%增加","内存使用量限制为<20MB增加"],"ja":["Claude Codeプラグインの統合が必要","CPU使用量は<5%増加に制限","メモリ使用量は<20MB増加に制限"],"ko":["Claude Code 플러그인 통합 필요","CPU 사용량은 <5% 증가로 제한","메모리 사용량은 <20MB 증가로 제한"],"es":["Requiere integración del plugin Claude Code","Uso de CPU limitado a <5% adicional","Uso de memoria limitado a <20MB adicional"],"fr":["Nécessite l''intégration du plugin Claude Code","Utilisation de l''UC limitée à <5% supplémentaire","Utilisation de la mémoire limitée à <20MO supplémentaire"],"de":["Erfordert Claude Code-Plugin-Integration","CPU-Auslastung auf <5% zusätzlich begrenzt","Speicherauslastung auf <20MB zusätzlich begrenzt"],"pt":["Requer integração do plug-in Claude Code","Uso de CPU limitado a <5% adicional","Uso de memória limitado a <20MB adicional"],"ru":["Требуется интеграция с плагином Claude Code","Использование CPU ограничено <5% дополнительно","Использование памяти ограничено <20MB дополнительно"],"ar":["يتطلب تكامل مع إضافة Claude Code","استخدام وحدة المعالجة المركزية محدود بـ <5% إضافي","استخدام الذاكرة محدود بـ <20MB إضافي"]},"version":4},"contentHash":"044e03c3c8cfdb2f4f5e5062fbb302ab78ce60692bd13c276a0399547e172f43","qualityScore":38}');
