INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nexus-labs-automation/mobile-observability/session-replay', 'session-replay', 'nexus-labs-automation', 'mobile-observability', 'community', 'session-replay nexus-labs-automation mobile-observability community Session-replay is a Claude Code plugin for mobile app observability, providing crash reporting, performance monitoring, and instrumentation for iOS, Android, and React Native. It benefits developers and QA teams. 会话回放插件为移动应用提供可观测性，包括崩溃报告、性能监控和仪表化，支持iOS、Android和React Native セッションリプレイプラグインは、モバイルアプリの可観測性を提供し、クラッシュレポート、パフォーマンスモニタリング、計装化をサポートします 세션 리플레이 플러그인은 모바일 앱의 관측성을 제공하며, 충돌 보고, 성능 모니터링, 기기화 등을 지원합니다 Session-replay es un plugin de Claude Code para la observabilidad móvil que permite capturar grabaciones visuales de sesiones de usuario para la depuración y el monitoreo de rendimiento Session-replay est un plugin Claude Code pour l''observabilité mobile qui permet de capturer des enregistrements visuels de sessions utilisateur pour le débogage et le suivi des performances Session-replay ist ein Plugin von Claude Code für die mobile Observabilität, das die Erfassung visueller Aufzeichnungen von Benutzersitzungen für die Fehlersuche und Leistungsüberwachung ermöglicht O Session Replay é um plugin para observabilidade de aplicativos móveis, permitindo capturar gravações visuais de sessões de usuário para depuração Сессия Replay - это плагин для наблюдения за мобильными приложениями, который позволяет записывать визуальные сессии пользователей для отладки Session Replay هو مكون إضافي لمراقبة التطبيقات النقالة، يسمح بتسجيل جلسات المستخدمين لتصحيح الأخطاء how to use session-replay session-replay plugin mobile app observability crash reporting tools session-replay vs bugsnag session-replay install guide what is session-replay session-replay alternative session-replay setup for react native 会话回放 移动应用可观测性 崩溃报告 性能监控 仪表化 React Native iOS Android AIエージェント 可观测性技术 Captures visual recordings of user sessions for debugging Provides crash reporting and performance monitoring for iOS, Android, and React Native Masks sensitive data, including text input fields, passwords, and financial information Operates within a performance budget of <5% additional CPU and <20MB additional memory Supports QA and support investigations Session-replay is a technique for capturing visual recordings of user sessions to aid in debugging and understanding user behavior.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jaypaulb/CanvusAPI-LLMDemo/Global Security', 'community', 'jaypaulb', 'CanvusAPI-LLMDemo', 'jaypaulb/CanvusAPI-LLMDemo', 'Global Security', 0, 0, 38, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:19.500Z', 'b9fcc3e25b78211d72960646c261078e9ef51edfd7a9bbabd33a934a9cc52480', '{"id":"jaypaulb/CanvusAPI-LLMDemo/Global Security","name":"Global Security","description":{"en":"Global Security is a script that monitors a Canvas on a specified Canvas Server, passing content to ChatGPT and posting responses. This skill benefits developers working with AI agents and Canvas integration.","zh":"全局安全脚本监控Canvas服务器，检测{{ }}内容并将其传递给ChatGPT，实现安全响应","ja":"グローバルセキュリティスクリプトはCanvasサーバーを監視し、{{ }}コンテンツを検知してChatGPTに伝達し、セキュアなレスポンスを実現","ko":"글로벌 보안 스크립트는 Canvas 서버를 모니터링하고 {{ }} 내용을 감지하여 ChatGPT로 전송하여 보안 응답을 구현합니다","es":"La seguridad global es un conjunto de scripts que monitorean un Canvas en un servidor especificado y pasan contenido a ChatGPT para obtener respuestas.","fr":"La sécurité globale est un ensemble de scripts qui surveillent un Canvas sur un serveur spécifié et passent le contenu à ChatGPT pour obtenir des réponses.","de":"Die globale Sicherheit ist ein Satz von Skripten, die ein Canvas auf einem bestimmten Server überwachen und Inhalt an ChatGPT weiterleiten, um Antworten zu erhalten.","pt":"O Skill de Segurança Global fornece orientação sobre como lidar com padrões de codificação relacionados à segurança global, incluindo monitoramento de canvas e integração com ChatGPT.","ru":"Навык Глобальной Безопасности предоставляет рекомендации по обработке стандартов кодирования, связанных с глобальной безопасностью, включая мониторинг холста и интеграцию с ChatGPT.","ar":"مهارة الأمان العالمي توفر إرشادات حول كيفية التعامل مع معايير الترميز المتعلقة بالأمان العالمي، بما في ذلك مراقبة Canvas والدمج مع ChatGPT."},"seo":{"title":{"en":"Global Security: Setup Guide for AI Agents | AI Agent Skill","zh":"全局安全设置指南 - AI工具集成","ja":"グローバルセキュリティ設定ガイド - AIエージェントのベストプラクティス","ko":"글로벌 보안 설정 가이드 - AI 도구 통합","es":"Configuración de Seguridad Global: Guía de Implementación","fr":"Mise en Place de la Sécurité Globale: Meilleures Pratiques","de":"Globaler Sicherheitseinstellung: Einrichtungsleitfaden","pt":"Guia de Configuração de Segurança Global para Ferramentas...","ru":"Настройка Глобальной Безопасности для ИИ Агентов","ar":"دليل إعداد أمان عالمي لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to implement Global Security for your AI agents and learn how to monitor Canvas content with ChatGPT integration - get started now!","zh":"了解全局安全的脚本运行和ChatGPT集成，提高AI工具的安全性","ja":"グローバルセキュリティのスクリプト実行とChatGPTの統合について学び、AIエージェントのセキュリティを高める","ko":"글로벌 보안의 스크립트 실행과 ChatGPT 통합에 대해 알아보고 AI 도구의 보안을 강화하세요","es":"Aprende a configurar la seguridad global en tu proyecto con nuestra guía detallada sobre el uso de ChatGPT y Canvas Server para una seguridad óptima.","fr":"Découvrez comment mettre en place la sécurité globale dans votre projet avec notre guide détaillé sur l''utilisation de ChatGPT et Canvas Server pour une sécu...","de":"Erfahren Sie, wie Sie die globale Sicherheit in Ihrem Projekt mit unserer detaillierten Anleitung zur Verwendung von ChatGPT und Canvas Server für optimale S...","pt":"Aprenda a configurar a segurança global para ferramentas de IA, incluindo monitoramento de canvas e integração com ChatGPT","ru":"Узнайте, как настроить глобальную безопасность для ИИ агентов, включая мониторинг холста и интеграцию с ChatGPT","ar":"تعرف على كيفية إعداد أمان عالمي لأدوات الذكاء الاصطناعي، بما في ذلك مراقبة Canvas والدمج مع ChatGPT"},"definition":{"en":"Global Security is a technical standard guiding Claude Code to handle global security, adhering to specific coding standards for AI agents.","zh":"全局安全是一种脚本运行机制，用于监控Canvas服务器并与ChatGPT集成以确保安全","ja":"グローバルセキュリティは、Canvasサーバーを監視しChatGPTと統合してセキュリティを確保するスクリプト実行メカニ