INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tcole333/python-learning-module/start-session', 'start-session', 'tcole333', 'python-learning-module', 'community', 'start-session tcole333 python-learning-module community The start-session skill is a Python learning module designed for R users, featuring a Jeopardy game project and Claude Code integration for AI tutoring. It benefits developers seeking interactive learning experiences. 启动会话是Python学习模块，为R用户提供Jeopardy游戏项目和Claude Code集成的AI辅导 セッション開始は、Rユーザー向けのPython学習モジュールであり、JeopardyゲームプロジェクトとClaude Codeの統合によるAIチュートリアルを提供する 세션 시작은 Python 학습 모듈로, R 사용자를 위한 Jeopardy 게임 프로젝트와 Claude Code 통합을 통해 AI 튜터링을 제공합니다 Módulo de aprendizaje de Python para usuarios de R que automatiza sesiones de estudio. Incluye un proyecto Jeopardy, integración con Claude Code para tutoría de IA y gestión del estado de aprendizaje mediante archivos JSON y Markdown. Module d''apprentissage Python pour utilisateurs de R automatisant les sessions d''étude. Inclut un projet Jeopardy, une intégration Claude Code pour tutorat IA et une gestion d''état d''apprentissage via fichiers JSON et Markdown. Python-Lernmodul für R-Nutzer, das Lernsessionen automatisiert. Enthält ein Jeopardy-Projekt, Claude Code-Integration für KI-Tutoring und Verwaltung des Lernstatus über JSON- und Markdown-Dateien. O start-session é um módulo de aprendizado de Python para usuários de R, com integração do Claude Code e projeto de jogo Jeopardy Start-session - это модуль обучения Python для пользователей R, с интеграцией Claude Code и проектом игры Jeopardy جلسة التعلم هي وحدة تعليمية لبرمجة Python لمستخدمي R، مع دمج Claude Code ومشروع لعبة Jeopardy how to use start-session start-session alternative start-session setup guide what is start-session start-session vs other learning modules installing start-session Claude Code AI tutoring integration Jeopardy game project for Python learning Python学习模块 R用户 Jeopardy游戏项目 Claude Code集成 AI辅导 启动会话 progress.json session_log.md quiz_bank.md Reads progress.json to determine current learning state Utilizes session_log.md to track learning progress Checks for concepts due for review based on last_practiced timestamp Displays quick review questions from quiz_bank.md Suggests next learning modules based on meta.current_module Updates meta.last_session timestamp in progress.json start-session is a Python learning module that utilizes AI tutoring and game-based projects to enhance learning outcomes for R users.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MQFacultyOfArts/PromptGrimoireTool/code-review', 'community', 'MQFacultyOfArts', 'PromptGrimoireTool', 'MQFacultyOfArts/PromptGrimoireTool', 'code-review', 0, 0, 38, '2026-03-08T01:57:15.312Z', '2026-03-08T02:02:37.748Z', 'f2908e9cdae18948213d3f7976b17b8a9673e4d7f7958baf3ff57f761dfc86ae', '{"id":"MQFacultyOfArts/PromptGrimoireTool/code-review","name":"code-review","description":{"en":"The code-review skill performs professional code audits following standards in prompts/CODE_REVIEW.md, benefiting developers and teams by ensuring high-quality code.","zh":"代码审查工具帮助开发者进行专业的代码审查，确保代码质量和可维护性","ja":"コードレビューツールは、開発者がプロフェッショナルなコードレビューを実施することを支援し、コードの品質とメンテナンス性を確保します","ko":"코드 리뷰 도구는 개발자가 전문적인 코드 리뷰를 수행하도록 지원하여 코드 품질과 유지 보수성을 보장합니다","es":"La revisión de código es un proceso crucial para garantizar la calidad y seguridad del código. Nuestra guía te muestra cómo hacerlo de manera profesional.","fr":"La revue de code est un processus crucial pour garantir la qualité et la sécurité du code. Notre guide vous montre comment le faire de manière professionnelle.","de":"Die Code-Review ist ein entscheidender Prozess, um die Qualität und Sicherheit des Codes zu gewährleisten. Unser Leitfaden zeigt Ihnen, wie Sie dies auf professionelle Weise tun können.","pt":"Realize revisões de código seguindo os padrões em prompts/CODE_REVIEW.md, antes de commitar alterações significantes","ru":"Выполняйте код-ревью, следуя стандартам в prompts/CODE_REVIEW.md, перед коммитом значительных изменений","ar":"اجري مراجعات الكود متبعًا المعايير في prompts/CODE_REVIEW.md، قبل الإلتزام بالتغييرات المهمة"},"seo":{"title":{"en":"Code-Review: Professional Code Audit Setup Guide | AI Age...","zh":"代码审查工具：专业代码审查设置指南","ja":"コードレビューツール：プロフェッショナルコードレビューのベストプラクティス","ko":"코드 리뷰 도구: 전문가 코드 리뷰 설정 가이드","es":"Guía de configuración para revisión de código con herrami...","fr":"Guide de mise en place de la revue de code avec les outil...","de":"Einrichtungsleitfaden für Code-Review mit KI-Tools","pt":"Guia de Configuração de Revisão de Código com Ferramentas...","ru":"Настройка код-ревью с помощью ИИ Агентов","ar":"دليل إعداد مراجعة الكود باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to perform thorough code reviews with git status, git diff, and git log. Learn to identify scope and follow standards with this AI agent skill.","zh":"使用代码审查工具提高代码质量，自动化代码审查流程，优化开发效率","ja":"コードレビューツールを使用してコード品質を向上させ、コードレビューの自動化を実現し、開発効率を最適化します","ko":"코드 리뷰 도구를 사용하여 코드 품질을 향상시키고 코드 리뷰 프로세스를 자동화하여 개발 효율성을 최적화합니다","es":"Aprende a realizar una revisión de código profesional con nuestra guía paso a paso y mejora la calidad de tu código con herramientas de AI","fr":"Découvrez comment effectuer une revue de code professionnelle avec notre guide étape par étape et améliorez la qualité de votre code avec les outils d''IA","de":"Erfahren Sie, wie Sie eine professionelle Code-Review durchführen können, mit unserer Schritt-für-Schritt-Anleitung und verbessern Sie die Qualität Ihres Cod...","pt":"Aprenda a realizar revisões de código profissionais com as ferramentas de IA, seguindo os padrões de revisão de código","ru":"Узнайте, как выполнять профессиональные код-ревью с помощью ИИ Агентов, следуя стандартам код-ревью","ar":"تعلم كيفية إجراء مراجعات الكود احترافية باستخدام أدوات الذكاء الاصطناعي، متبعًا معايير مراجعة الكود"},"definition":{"en":"Code-review is a systematic examination of code changes using git commands to identify scope and ensure adherence to coding standards.","zh":"代码审查工具是一种自动化工具，用于检查和评估代码质量和可维护性","ja":"コードレビューツールは、コードの品質とメンテナンス性をチェックおよび評価する自動化ツールです","ko":"코드 리뷰 도구는 코드 품질과 유지 보수성을 확인 및 평가하는 자동화 도구입니다","es":"La revisión de código es el proceso de examinar el código fuente para detectar errores y mejorar la calidad del software","fr":"La revue de code est le processus d''examen du code source pour détecter les erreurs et améliorer la qualité du logiciel","de":"Die Code-Review ist der Prozess der Überprüfung des Quellcodes, um Fehler zu erkennen und die Qualität der Software zu verbessern","pt":"Revisão de código é o processo de avaliar código para garantir que atenda aos padrões de qualidade e segurança","ru":"Код-ревью - это процесс оценки кода, чтобы гарантировать, что он соответствует стандартам качества и безопасности","ar":"مراجعة الكود هي عملية تقييم الكود لضمان امتثاله لمعايير الجودة والأمان"},"features":{"en":["Identifies scope using git status and git diff for uncommitted changes","Analyzes commits since last review with git log","Follows standards outlined in prompts/CODE_REVIEW.md","Determines code review needs based on Stop hook reminders or user requests","Supports code review after completing spikes or features"],"zh":["支持Git代码管理","自动化代码审查流程","检查代码规范和可维护性","优化开发效率","集成CI/CD流程"],"ja":["Gitコード管理をサポート","コードレビューの自動化","コードの規範とメンテナンス性をチェック","開発効率を最適化","CI/CDフローとの統合"],"ko":["Git 코드 관리 지원","코드 리뷰 프로세스 자동화","코드 표준 및 유지 보수성을 확인","개발 효율성을 최적화","CI/CD 프로세스 통합"],"es":["Identificación del alcance de la revisión de código con git status y git diff","Análisis de commits con git log para detectar cambios","Revisión de código para detectar errores y mejorar la calidad","Integración con herramientas de AI para una revisión de código más eficiente","Mejora de la calidad del código con un proceso de revisión estructurado"],"fr":["Identification de la portée de la revue de code avec git status et git diff","Analyse des commits avec git log pour détecter les modifications","Revue de code pour détecter les erreurs et améliorer la qualité","Intégration avec les outils d''IA pour une revue de code plus efficace","Amélioration de la qualité du code avec un processus de revue structuré"],"de":["Identifizierung des Umfangs der Code-Review mit git status und git diff","Analyse der Commits mit git log, um Änderungen zu erkennen","Überprüfung des Codes, um Fehler zu erkennen und die Qualität zu verbessern","Integration mit KI-Tools für eine effizientere Code-Review","Verbesserung der Code-Qualität mit einem strukturierten Überprüfungsprozess"],"pt":["Identificação do escopo da revisão de código com git status e git diff","Verificação de commits desde a última revisão com git log","Análise de código para garantir a qualidade e segurança","Integração com prompts/CODE_REVIEW.md para padrões de revisão de código","Suporte para revisão de código antes de commitar alterações significantes"],"ru":["Определение объема код-ревью с помощью git status и git diff","Проверка коммитов с момента последнего код-ревью с помощью git log","Анализ кода для обеспечения качества и безопасности","Интеграция с prompts/CODE_REVIEW.md для стандартов код-ревью","Поддержка код-ревью перед коммитом значительных изменений"],"ar":["تحديد نطاق مراجعة الكود باستخدام git status و git diff","فحص الإلتزامات منذ المراجعة الأخيرة باستخدام git log","تحليل الكود لضمان الجودة والأمان","التكامل مع prompts/CODE_REVIEW.md لمعايير مراجعة الكود","دعم مراجعة الكود قبل الإلتزام بالتغييرات المهمة"]},"keywords":{"en":["how to use code-review","code-review setup guide","what is code-review","code-review vs manual review","code-review install for AI agents","git status for code review","code-review best practices for developers"],"zh":["代码审查工具","代码质量","代码可维护性","自动化代码审查","Git代码管理","CI/CD流程","代码开发效率","代码审查设置指南"],"ja":["コードレビューツール","コード品質","コードメンテナンス性","コードレビューの自動化","Gitコード管理","CI/CDフロー","コード開発効率","コードレビューのベストプラクティス"],"ko":["코드 리뷰 도구","코드 품질","코드 유지 보수성","코드 리뷰 프로세스 자동화","Git 코드 관리","CI/CD 프로세스","코드 개발 효율성","코드 리뷰 설정 가이드"],"es":["revisión de código","herramientas de AI","git status","git diff","git log","calidad del código","seguridad del código","desarrollo de software","ingeniería de software"],"fr":["revue de code","outils d''IA","git status","git diff","git log","qualité du code","sécurité du code","développement de logiciels","ingénierie de logiciels"],"de":["Code-Review","KI-Tools","git status","git diff","git log","Code-Qualität","Code-Sicherheit","Software-Entwicklung","Software-Ingenieurwesen"],"pt":["revisão de código","ferramentas de IA","git status","git diff","git log","padrões de revisão de código","qualidade de código","segurança de código"],"ru":["код-ревью","ИИ Агенты","git status","git diff","git log","стандарты код-ревью","качество кода","безопасность кода"],"ar":["مراجعة الكود","أدوات الذكاء الاصطناعي","git status","git diff","git log","معايير مراجعة الكود","جودة الكود","أمان الكود"]}},"owner":"MQFacultyOfArts","repo":"PromptGrimoireTool","repoPath":"MQFacultyOfArts/PromptGrimoireTool","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.312Z","topics":[],"category":"community","skillMd":{"name":"code-review","description":"Perform a maximally picky and professional code review of recent changes. Reviews all code added since the last review, checking for thread safety, async safety, security vulnerabilities, data integrity, test quality, and code smells. Use before committing significant changes.","bodyPreview":"# Code Review Skill\n\nPerform a professional code review following the standards in `prompts/CODE_REVIEW.md`.\n\n## When to Use\n\n- Before committing significant code changes\n- After completing a spike or feature\n- When the Stop hook reminds you\n- When explicitly requested by user\n\n## Process\n\n1. **Identify scope** - Determine what code needs review:\n   - Check `git status` and `git diff` for uncommitted changes\n   - Check `git log` to find commits since last review\n   - Look for any existing code r","body":"# Code Review Skill\n\nPerform a professional code review following the standards in `prompts/CODE_REVIEW.md`.\n\n## When to Use\n\n- Before committing significant code changes\n- After completing a spike or feature\n- When the Stop hook reminds you\n- When explicitly requested by user\n\n## Process\n\n1. **Identify scope** - Determine what code needs review:\n   - Check `git status` and `git diff` for uncommitted changes\n   - Check `git log` to find commits since last review\n   - Look for any existing code review documents to find the last review point\n\n2. **Read the review template** - Load `prompts/CODE_REVIEW.md` for the full criteria\n\n3. **Perform the review** - Apply all criteria from the template:\n   - MANDATORY: No Quick Hacks policy\n   - Race Condition Audit Checklist\n   - Critical issues (thread safety, async safety, security, data integrity)\n   - High priority (type hints, input validation, logging, test coverage)\n   - Medium priority (magic numbers, hard-coded config, duplication)\n   - Test quality (primary use cases tested, no anti-patterns)\n\n4. **Write the review document** - Save to `.claude/plans/` with:\n   - Executive summary\n   - Issues grouped by severity with file:line references\n   - Specific code fixes (before/after)\n   - Checklist of items to fix\n   - Verification steps\n   - Notes for future work\n\n5. **Report the path** - Tell the user where to find the review document\n\n## Key Principles\n\n- Be specific and critical\n- Every issue needs a file:line reference\n- Provide concrete fixes, not just descriptions\n- Consider whether code enables future architectural goals\n- Quick hacks are absolutely forbidden\n"},"lastSynced":"2026-03-08T02:02:37.748Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing comprehensive code audits and professional review following standards in prompts/CODE_REVIEW.md","zh":"适合需要全面代码审计和专业审查的开发代理，按照prompts/CODE_REVIEW.md中的标准","ja":"開発エージェントが包括的なコード監査とプロフェッショナルなレビューを行う必要がある場合に適しています。prompts/CODE_REVIEW.mdに記載された規格に従ったレビューが可能です","ko":"개발 에이전트가 종합적인 코드 감시 및 전문가 리뷰를 수행하는 데 적합하며 prompts/CODE_REVIEW.md의 표준을 따릅니다","es":"Perfecto para Agentes de Desarrollo que necesitan auditorías de código comprehensivas y revisión profesional siguiendo los estándares en prompts/CODE_REVIEW.md","fr":"Parfait pour les Agents de Développement ayant besoin d''audits de code complets et de révision professionnelle suivant les normes dans prompts/CODE_REVIEW.md","de":"Perfekt für Entwicklungsmittel, die umfassende Code-Audits und professionelle Überprüfung nach den Standards in prompts/CODE_REVIEW.md benötigen","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de auditorias de código abrangentes e revisão profissional seguindo os padrões em prompts/CODE_REVIEW.md","ru":"Идеально подходит для агентов разработки, которым требуются комплексные аудиты кода и профессиональный обзор, следующий стандартам в prompts/CODE_REVIEW.md","ar":"مثالي لعميل التطوير الذين يحتاجون إلى تدقيق شامل للرمز والمراجعة المهنية التالية للمعايير في prompts/CODE_REVIEW.md"},"recommendation":{"en":"Empowers agents to perform professional code audits, ensuring high-quality code through standards like git status, git diff, and git log, while benefiting developers and teams with comprehensive review processes","zh":"赋予代理执行专业代码审计的能力，通过git status、git diff和git log等标准，确保高质量的代码，同时为开发人员和团队提供全面审查流程","ja":"エージェントがプロフェッショナルなコード監査を実行できるようにし、git status、git diff、git logなどの規格を通じて、高品質のコードを保証し、開発者やチームに徹底的なレビュー・プロセスを提供します","ko":"에이전트가 전문적인 코드 감사를 수행할 수 있도록 하여 git status, git diff, git log 등의 표준을 통해 높은 품질의 코드를 보장하고 개발자 및 팀에 대한 종합적인 검토 프로세스를 제공합니다","es":"Permite a los agentes realizar auditorías de código profesionales, garantizando un código de alta calidad a través de estándares como git status, git diff y git log, mientras que beneficia a los desarrolladores y equipos con procesos de revisión comprehensivos","fr":"Permet aux agents d''effectuer des audits de code professionnels, assurant un code de haute qualité grâce à des normes comme git status, git diff et git log, tout en bénéficiant aux développeurs et équipes de processus de révision complets","de":"Ermöglicht es Agenten, professionelle Code-Audits durchzuführen, um hochwertigen Code durch Standards wie git status, git diff und git log sicherzustellen, während Entwickler und Teams von umfassenden Überprüfungsprozessen profitieren","pt":"Habilita os agentes a realizar auditorias de código profissionais, garantindo um código de alta qualidade por meio de padrões como git status, git diff e git log, enquanto beneficia os desenvolvedores e as equipes com processos de revisão abrangentes","ru":"Наделяет агентов возможностью проводить профессиональные аудиты кода, гарантируя высококачественный код посредством стандартов như git status, git diff и git log, а также принося пользу разработчикам и командам с помощью всесторонних процессов обзора","ar":"يمنح الوكيل القدرة على أداء تدقيق رمز محترف، مما يضمن رمزًا عالي الجودة من خلال معايير مثل git status و git diff و git log، بينما يستفيد المطورون والفرق من عمليات مراجعة شاملة"},"useCases":{"en":["Performing audits before committing significant code changes","Reviewing code after completing spikes or features","Validating code quality when explicitly requested by users"],"zh":["在提交重大代码更改之前进行审计","完成spikes或功能后审查代码","在用户明确请求时验证代码质量"],"ja":["重大なコード変更をコミットする前に監査を実行する","スパイクや機能を完了した後、コードをレビューする","ユーザーが明示的に要求した場合、コードの品質を検証する"],"ko":["중요한 코드 변경을 커밋하기 전에 감사를 수행한다","스파이크 또는 기능을 완료한 후 코드를 검토한다","사용자가 명시적으로 요청한 경우 코드 품질을 검증한다"],"es":["Realizar auditorías antes de realizar cambios de código significativos","Revisar el código después de completar spikes o características","Validar la calidad del código cuando se solicita explícitamente por los usuarios"],"fr":["Réalisant des audits avant d''apporter des modifications de code importantes","Réviser le code après avoir terminé les spikes ou les fonctionnalités","Valider la qualité du code lorsqu''elle est explicitement demandée par les utilisateurs"],"de":["Durchführen von Audits vor der Durchführung signifikanter Code-Änderungen","Überprüfen des Codes nach dem Abschließen von spikes oder Funktionen","Überprüfen der Code-Qualität, wenn diese explizit von den Benutzern angefordert wird"],"pt":["Realizar auditorias antes de fazer alterações significativas no código","Revisar código após concluir spikes ou recursos","Validar a qualidade do código quando solicitado explicitamente pelos usuários"],"ru":["Проведение аудитов перед внесением значительных изменений в код","Обзор кода после завершения спайков или функций","Проверка качества кода, когда это явно запрошено пользователями"],"ar":["إجراء التدقيق قبل إجراء تغييرات كبيرة على الرمز","مراجعة الرمز بعد إكمال السبايك أو الميزات","التحقق من جودة الرمز عند الطلب صراحة من قبل المستخدمين"]},"limitations":{"en":["Requires access to git repository","Follows specific standards outlined in prompts/CODE_REVIEW.md"],"zh":["需要访问git仓库","遵循prompts/CODE_REVIEW.md中概述的具体标准"],"ja":["gitリポジトリへのアクセスが必要","prompts/CODE_REVIEW.mdに概説されている特定の規格に従う"],"ko":["git 저장소에 액세스해야 함","prompts/CODE_REVIEW.md에概説된 특정 표준을 따름"],"es":["Requiere acceso al repositorio git","Sigue estándares específicos descritos en prompts/CODE_REVIEW.md"],"fr":["Nécessite l''accès au référentiel git","Suit des normes spécifiques décrites dans prompts/CODE_REVIEW.md"],"de":["Benötigt Zugriff auf das Git-Repository","Folgt bestimmten Standards, die in prompts/CODE_REVIEW.md beschrieben sind"],"pt":["Requer acesso ao repositório git","Segue padrões específicos descritos em prompts/CODE_REVIEW.md"],"ru":["Требует доступа к репозиторию git","Следует конкретным стандартам, изложенным в prompts/CODE_REVIEW.md"],"ar":["يتطلب الوصول إلى مستودع git","يتبع معايير محددة موضحة في prompts/CODE_REVIEW.md"]},"version":4},"contentHash":"f2908e9cdae18948213d3f7976b17b8a9673e4d7f7958baf3ff57f761dfc86ae","qualityScore":38}');
