INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MQFacultyOfArts/PromptGrimoireTool/code-review', 'code-review', 'MQFacultyOfArts', 'PromptGrimoireTool', 'community', 'code-review MQFacultyOfArts PromptGrimoireTool community The code-review skill performs professional code audits following standards in prompts/CODE_REVIEW.md, benefiting developers and teams by ensuring high-quality code. 代码审查工具帮助开发者进行专业的代码审查，确保代码质量和可维护性 コードレビューツールは、開発者がプロフェッショナルなコードレビューを実施することを支援し、コードの品質とメンテナンス性を確保します 코드 리뷰 도구는 개발자가 전문적인 코드 리뷰를 수행하도록 지원하여 코드 품질과 유지 보수성을 보장합니다 La revisión de código es un proceso crucial para garantizar la calidad y seguridad del código. Nuestra guía te muestra cómo hacerlo de manera profesional. La revue de code est un processus crucial pour garantir la qualité et la sécurité du code. Notre guide vous montre comment le faire de manière professionnelle. Die Code-Review ist ein entscheidender Prozess, um die Qualität und Sicherheit des Codes zu gewährleisten. Unser Leitfaden zeigt Ihnen, wie Sie dies auf professionelle Weise tun können. Realize revisões de código seguindo os padrões em prompts/CODE_REVIEW.md, antes de commitar alterações significantes Выполняйте код-ревью, следуя стандартам в prompts/CODE_REVIEW.md, перед коммитом значительных изменений اجري مراجعات الكود متبعًا المعايير في prompts/CODE_REVIEW.md، قبل الإلتزام بالتغييرات المهمة how to use code-review code-review setup guide what is code-review code-review vs manual review code-review install for AI agents git status for code review code-review best practices for developers 代码审查工具 代码质量 代码可维护性 自动化代码审查 Git代码管理 CI/CD流程 代码开发效率 代码审查设置指南 Identifies scope using git status and git diff for uncommitted changes Analyzes commits since last review with git log Follows standards outlined in prompts/CODE_REVIEW.md Determines code review needs based on Stop hook reminders or user requests Supports code review after completing spikes or features Code-review is a systematic examination of code changes using git commands to identify scope and ensure adherence to coding standards.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('u9401066/template-is-all-you-need/feature-development', 'community', 'u9401066', 'template-is-all-you-need', 'u9401066/template-is-all-you-need', 'feature-development', 0, 0, 38, '2026-03-08T01:57:15.314Z', '2026-03-08T02:02:43.496Z', 'e227f1dd4e3a0e6e8e0c08d9dcc169b9c1997f30542e19acba4f111a048f342c', '{"id":"u9401066/template-is-all-you-need/feature-development","name":"feature-development","description":{"en":"The feature-development skill provides an AI-assisted development project template, enabling developers to coordinate multiple Skills and manage workflows from planning to deployment.","zh":"功能開發工作流是一個完整的功能開發流程，從規劃到部署，編排多個Skills協同工作","ja":"AIエージェントによる機能開発ワークフローは、計画からデプロイまでの機能開発プロセスをサポートします","ko":"기능 개발 프로세스 구축은 계획에서 배포까지의 기능 개발 프로세스를 지원합니다","es":"El desarrollo de características con AI Agent es un proceso que abarca desde la planificación hasta la implementación y el despliegue de nuevas funcionalidades","fr":"Le développement de fonctionnalités avec Outil IA est un processus qui va de la planification à la mise en œuvre et au déploiement de nouvelles fonctionnalités","de":"Die Entwicklung von Funktionen mit KI-Tool ist ein Prozess, der von der Planung bis zur Implementierung und zum Einsatz neuer Funktionen reicht","pt":"O desenvolvimento de recursos é um processo completo que envolve planejamento, implementação e deploy, utilizando várias habilidades em conjunto","ru":"Разработка функций - это полный процесс, включающий планирование, реализацию и развертывание, используя несколько навыков в совокупности","ar":"تطوير الميزات هو عملية شاملة تشمل التخطيط والتنفيذ والتوزيع، باستخدام العديد من المهارات بشكل مشترك"},"seo":{"title":{"en":"Feature-Development: AI-Assisted Project Template Setup G...","zh":"功能開發工作流 Setup Guide","ja":"AIエージェントによる機能開発ワークフロー Best Practices","ko":"기능 개발 프로세스 구축 가이드","es":"Guía de configuración para el desarrollo de característic...","fr":"Guide de mise en place pour le développement de fonctionn...","de":"Einrichtungsleitfaden für die Entwicklung von Funktionen ...","pt":"Guia de Configuração de Desenvolvimento de Recursos com F...","ru":"Руководство по настройке разработки функций с помощью ИИ ...","ar":"دليل إعداد وتطوير الميزات باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient feature development with Claude Skills, Memory Bank, and Constitution-Bylaw system. Discover how to streamline your workflow today!","zh":"了解功能開發工作流的技術細節，包括規劃、需求分析和部署","ja":"AIエージェントを使用した機能開発ワークフローの詳細を確認する","ko":"기능 개발 프로세스 구축을 위한 기술 정보를 확인하십시오","es":"Aprende a configurar y utilizar el desarrollo de características con AI Agent para mejorar tus proyectos de desarrollo de software","fr":"Découvrez comment configurer et utiliser le développement de fonctionnalités avec Outil IA pour améliorer vos projets de développement de logiciels","de":"Erfahren Sie, wie Sie die Entwicklung von Funktionen mit KI-Tool konfigurieren und nutzen können, um Ihre Software-Entwicklungsprojekte zu verbessern","pt":"Aprenda a configurar o desenvolvimento de recursos com o modelo de projeto de desenvolvimento assistido por IA, incluindo Claude Skills, Memory Bank e sistem...","ru":"Узнайте, как настроить разработку функций с помощью модели проекта разработки, поддерживаемой ИИ Агентами, включая Claude Skills, Memory Bank и систему Конст...","ar":"تعرف على كيفية إعداد وتطوير الميزات باستخدام نموذج مشروع التطوير المدعوم بالذكاء الاصطناعي، بما في ذلك مهارات كلود، بنك الذاكرة ونظام الدستور واللوائح"},"definition":{"en":"feature-development is an AI-assisted development project template with a Constitution-Bylaw system, streamlining the development workflow","zh":"功能開發工作流是指使用AI Skills、Memory Bank和Constitution-Bylaw系统进行功能开发的流程","ja":"AIエージェントによる機能開発ワークフローは、AI Skills、Memory Bank、Constitution-Bylawシステムを使用した機能開発プロセスです","ko":"기능 개발 프로세스 구축은 AI Skills, Memory Bank, Constitution-Bylaw 시스템을 사용하여 기능을 개발하는 프로세스입니다","es":"El desarrollo de características con AI Agent es un conjunto de herramientas y técnicas que permiten la creación y implementación de nuevas funcionalidades de software","fr":"Le développement de fonctionnalités avec Outil IA est un ensemble d''outils et de techniques qui permettent la création et la mise en œuvre de nouvelles fonctionnalités de logiciel","de":"Die Entwicklung von Funktionen mit KI-Tool ist eine Sammlung von Werkzeugen und Techniken, die die Erstellung und Implementierung neuer Softwarefunktionen ermöglichen","pt":"Desenvolvimento de recursos é um processo de criação de novas funcionalidades em um projeto de software, utilizando tecnologias de IA","ru":"Разработка функций - это процесс создания новых функциональных возможностей в проекте программного обеспечения, используя технологии ИИ","ar":"تطوير الميزات هو عملية إنشاء ميزات جديدة في مشروع برمجي، باستخدام تقنيات الذكاء الاصطناعي"},"features":{"en":["Utilizes Claude Skills for collaborative workflow management","Integrates Memory Bank for efficient data storage and retrieval","Employs a Constitution-Bylaw system for structured development processes","Supports phased development workflows, including planning and deployment","Triggers workflows with specific commands, such as ''新功能開發'' or ''FD: [功能名稱]''","Manages multiple Skills to coordinate development tasks"],"zh":["規劃和需求分析","多個Skills協同工作","Memory Bank和Constitution-Bylaw系统集成","從規劃到部署的完整功能開發流程","支援新功能開發和現有功能更新"],"ja":["計画と要件分析","複数のSkillsの共同作業","Memory BankとConstitution-Bylawシステムの統合","計画からデプロイまでの機能開発プロセス","新機能開発と既存機能更新のサポート"],"ko":["계획과 요구사항 분석","다중 Skills의 협업","Memory Bank와 Constitution-Bylaw 시스템 통합","계획에서 배포까지의 기능 개발 프로세스","새 기능 개발과 기존 기능 업데이트 지원"],"es":["Planificación y análisis de requisitos","Identificación de alcance y afectación","Implementación y despliegue de nuevas funcionalidades","Integración con Claude Skills y Memory Bank","Sistema de Constitution-Bylaw para la gestión de funcionalidades"],"fr":["Planification et analyse des exigences","Identification de la portée et de l''impact","Mise en œuvre et déploiement de nouvelles fonctionnalités","Intégration avec Outil IA et Memory Bank","Système de Constitution-Bylaw pour la gestion des fonctionnalités"],"de":["Planung und Anforderungsanalyse","Ermittlung des Umfangs und der Auswirkungen","Implementierung und Einsatz neuer Funktionen","Integration mit KI-Tool und Memory Bank","Constitution-Bylaw-System für die Funktionsverwaltung"],"pt":["Integração com Claude Skills para automação de tarefas","Utilização de Memory Bank para armazenamento de dados","Implementação do sistema de Constituição-Regulamento para governança","Desenvolvimento de recursos personalizados com tecnologias de IA","Integração com outras habilidades para fluxos de trabalho complexos"],"ru":["Интеграция с Claude Skills для автоматизации задач","Использование Memory Bank для хранения данных","Реализация системы Конституции-Устава для управления","Разработка индивидуальных функций с помощью технологий ИИ","Интеграция с другими навыками для сложных рабочих процессов"],"ar":["التكامل مع مهارات كلود لتوفير الوقت","استخدام بنك الذاكرة لتخزين البيانات","تنفيذ نظام الدستور واللوائح للحوكمة","تطوير ميزات مخصصة باستخدام تقنيات الذكاء الاصطناعي","التكامل مع مهارات أخرى لتحقيق تدفقات عمل معقدة"]},"keywords":{"en":["how to use feature-development","feature-development setup guide","what is feature-development","feature-development alternative","feature-development vs competitors","install feature-development","Claude Skills workflow management","Memory Bank integration"],"zh":["功能開發工作流","AI Skills","Memory Bank","Constitution-Bylaw系统","功能开发流程","需求分析","規劃和部署"],"ja":["AIエージェント","機能開発ワークフロー","AI Skills","Memory Bank","Constitution-Bylawシステム","機能開発プロセス","要件分析","計画とデプロイ"],"ko":["AI 에이전트","기능 개발 프로세스","AI Skills","Memory Bank","Constitution-Bylaw 시스템","기능 개발 프로세스","요구사항 분석","계획과 배포"],"es":["desarrollo de características","AI Agent","herramientas de desarrollo de software","planificación de funcionalidades","implementación de funcionalidades","despliegue de funcionalidades","integración con Claude Skills","integración con Memory Bank","sistema de Constitution-Bylaw"],"fr":["développement de fonctionnalités","Outil IA","outils de développement de logiciels","planification de fonctionnalités","mise en œuvre de fonctionnalités","déploiement de fonctionnalités","intégration avec Outil IA","intégration avec Memory Bank","système de Constitution-Bylaw"],"de":["Entwicklung von Funktionen","KI-Tool","Werkzeuge für die Software-Entwicklung","Planung von Funktionen","Implementierung von Funktionen","Einsatz von Funktionen","Integration mit KI-Tool","Integration mit Memory Bank","Constitution-Bylaw-System"],"pt":["desenvolvimento de recursos","ferramentas de ia","claude skills","memory bank","constituição-regulamento","ia no desenvolvimento de software","tecnologias de ia","automatização de tarefas","armazenamento de dados"],"ru":["разработка функций","ии агенты","claude skills","memory bank","конституция-устав","ии в разработке программного обеспечения","технологии ии","автоматизация задач","хранение данных"],"ar":["تطوير الميزات","أدوات الذكاء الاصطناعي","مهارات كلود","بنك الذاكرة","نظام الدستور واللوائح","الذكاء الاصطناعي في تطوير البرمجيات","تقنيات الذكاء الاصطناعي","توفير الوقت","تخزين البيانات"]}},"owner":"u9401066","repo":"template-is-all-you-need","repoPath":"u9401066/template-is-all-you-need","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.314Z","topics":[],"category":"community","skillMd":{"name":"feature-development","description":"Complete feature development workflow orchestrating multiple skills from planning to deployment. Triggers: FD, 新功能, 開發功能, feature, implement, 實作, 實現, 建立功能, create feature, develop, 開發新, add feature, 加功能, 功能開發.","version":"1.0.0","bodyPreview":"# 功能開發工作流\n\n## 描述\n\n完整的功能開發流程，從規劃到部署，編排多個 Skills 協同工作。\n\n## 觸發條件\n\n- 「新功能開發」「implement feature」「建立新功能」\n- 「FD: [功能名稱]」\n\n---\n\n## 📋 工作流程\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│              Feature Development Workflow                    │\n├─────────────────────────────────────────────────────────────┤\n│  Phase 1: 📐 規劃 (Planning)                                 │\n│  ├─ 需求分析與確認                                           │\n│  ├─ 識別影響範圍","body":"# 功能開發工作流\n\n## 描述\n\n完整的功能開發流程，從規劃到部署，編排多個 Skills 協同工作。\n\n## 觸發條件\n\n- 「新功能開發」「implement feature」「建立新功能」\n- 「FD: [功能名稱]」\n\n---\n\n## 📋 工作流程\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│              Feature Development Workflow                    │\n├─────────────────────────────────────────────────────────────┤\n│  Phase 1: 📐 規劃 (Planning)                                 │\n│  ├─ 需求分析與確認                                           │\n│  ├─ 識別影響範圍                                             │\n│  └─ 更新 Memory Bank (activeContext)                        │\n├─────────────────────────────────────────────────────────────┤\n│  Phase 2: 🏗️ 架構 (Architecture)                            │\n│  ├─ [ddd-architect] 生成 DDD 結構                           │\n│  ├─ 建立介面定義                                             │\n│  └─ 更新架構文檔                                             │\n├─────────────────────────────────────────────────────────────┤\n│  Phase 3: 🧪 測試先行 (TDD)                                  │\n│  ├─ [test-generator] 生成測試框架                            │\n│  ├─ 撰寫失敗的測試案例                                       │\n│  └─ 定義驗收標準                                             │\n├─────────────────────────────────────────────────────────────┤\n│  Phase 4: 💻 實作 (Implementation)                          │\n│  ├─ 實作 Domain 層                                          │\n│  ├─ 實作 Application 層                                     │\n│  ├─ 實作 Infrastructure 層                                  │\n│  └─ 實作 Presentation 層                                    │\n├─────────────────────────────────────────────────────────────┤\n│  Phase 5: ✅ 驗證 (Verification)                            │\n│  ├─ 執行測試套件                                             │\n│  ├─ [code-reviewer] 程式碼審查                              │\n│  ├─ [security-reviewer] 安全檢查                            │\n│  └─ 靜態分析 (mypy, ruff, vulture)                          │\n├─────────────────────────────────────────────────────────────┤\n│  Phase 6: 📦 提交 (Commit)                                  │\n│  ├─ [memory-updater] 更新 Memory Bank                       │\n│  ├─ [git-precommit] 執行提交前檢查                          │\n│  └─ 提交變更                                                │\n└─────────────────────────────────────────────────────────────┘\n```\n\n---\n\n## 🚀 使用範例\n\n### 基本用法\n\n```\n「新功能：用戶認證模組」\n\nAI 執行：\n1. 📐 確認需求：登入、註冊、密碼重設\n2. 🏗️ 生成 DDD 結構 (Domain/Application/Infrastructure)\n3. 🧪 生成測試框架\n4. 💻 引導逐步實作\n5. ✅ 執行驗證\n6. 📦 準備提交\n```\n\n### 帶參數用法\n\n```\n「FD: Order 管理 --frontend React --backend Python」\n\nAI 執行：\n1. 生成後端 Python DDD 結構\n2. 生成前端 React DDD 結構\n3. 建立 API 契約\n4. 生成前後端測試\n```\n\n---\n\n## 📊 輸出格式\n\n```markdown\n## 🚀 功能開發報告\n\n### 功能: 用戶認證模組\n\n#### Phase 1: 規劃 ✅\n- 需求: 登入、註冊、密碼重設\n- 影響範圍: 5 個新檔案\n\n#### Phase 2: 架構 ✅\n- 建立 Domain/Entities/User.py\n- 建立 Application/UseCases/AuthenticateUser.py\n- 建立 Infrastructure/Repositories/UserRepository.py\n\n#### Phase 3: 測試 ✅\n- 單元測試: 12 個\n- 整合測試: 5 個\n\n#### Phase 4: 實作 🚧\n- [x] Domain 層\n- [x] Application 層\n- [ ] Infrastructure 層\n- [ ] Presentation 層\n\n#### Phase 5: 驗證 ⏳\n- 等待實作完成\n\n#### Phase 6: 提交 ⏳\n- 等待驗證通過\n\n### 下一步\n實作 Infrastructure 層的 UserRepository\n```\n\n---\n\n## ⚙️ 配置選項\n\n| 參數 | 說明 | 預設值 |\n|------|------|--------|\n| `--frontend` | 前端框架 (React/Vue/none) | none |\n| `--backend` | 後端語言 (Python/Go/Rust) | Python |\n| `--skip-tests` | 跳過測試生成 | false |\n| `--quick` | 快速模式（跳過審查） | false |\n"},"lastSynced":"2026-03-08T02:02:43.496Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring streamlined project management and workflow coordination from planning to deployment.","zh":"适合需要从规划到部署的项目管理和工作流协调的开发代理。","ja":"計画からデプロイまでのプロジェクト管理とワークフロー調整が必要な開発エージェントに適しています。","ko":"계획에서 배포까지 프로젝트 관리와 워크플로 조정이 필요한 개발 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren una gestión de proyectos y coordinación de flujo de trabajo optimizadas desde la planificación hasta la implementación.","fr":"Idéal pour les Agents de Développement nécessitant une gestion de projets et une coordination de flux de travail rationalisées de la planification à la mise en production.","de":"Ideal für Entwicklungsmittel benötigende Entwicklungsagenten, die eine optimierte Projektverwaltung und Arbeitsablaufkoordination von der Planung bis zur Bereitstellung benötigen.","pt":"Ideal para Agentes de Desenvolvimento que exigem gestão de projetos e coordenação de fluxo de trabalho simplificadas, desde o planejamento até a implantação.","ru":"Идеально подходит для агентов разработки, требующих упрощенного управления проектами и координации рабочих процессов от планирования до развертывания.","ar":"مثالي لعمليات وكيل التطوير التي تتطلب إدارة مشاريع وتنسيق تدفق العمل المبسّط من التخطيط إلى النشر."},"recommendation":{"en":"Empowers agents to orchestrate multiple skills, manage complex workflows, and ensure seamless feature development using protocols like FD, implementing features with precision and speed, and coordinating skills for efficient project execution.","zh":"赋予代理人编排多个技能、管理复杂的工作流、确保使用协议如FD实现特性开发的精确和速度，并协调技能以实现高效的项目执行。","ja":"エージェントに複数のスキルをオーケストレートし、複雑なワークフローを管理し、FDなどのプロトコルを使用して機能開発を精密かつ迅速に実行し、スキルを調整して効率的なプロジェクト実行を確実にする。","ko":"에이전트가 여러 가지 기능을 오케스트레이션하고, 복잡한 워크플로를 관리하고, FD와 같은 프로토콜을 사용하여 기능 개발을 정밀하고 신속하게 수행하며, 기능을 조정하여 효율적인 프로젝트 실행을 보장합니다.","es":"Permite a los agentes orquestar múltiples habilidades, gestionar flujos de trabajo complejos y garantizar un desarrollo de funciones sin problemas utilizando protocolos como FD, implementando funciones con precisión y velocidad, y coordinando habilidades para una ejecución de proyectos eficiente.","fr":"Permet aux agents d''orchestrer plusieurs compétences, de gérer des flux de travail complexes et d''assurer un développement de fonctionnalités sans heurts en utilisant des protocoles comme FD, en mettant en œuvre des fonctionnalités avec précision et rapidité, et en coordonnant les compétences pour une exécution de projet efficiente.","de":"Ermöglicht es den Agenten, mehrere Fähigkeiten zu orchestrieren, komplexe Arbeitsabläufe zu verwalten und eine reibungslose Funktionsentwicklung unter Verwendung von Protokollen wie FD sicherzustellen, Funktionen mit Präzision und Geschwindigkeit umzusetzen und Fähigkeiten für eine effiziente Projektausführung zu koordinieren.","pt":"Habilita os agentes a orquestrar várias habilidades, gerenciar fluxos de trabalho complexos e garantir o desenvolvimento de recursos sem interrupções usando protocolos como FD, implementando recursos com precisão e velocidade, e coordenando habilidades para uma execução de projeto eficiente.","ru":"Предоставляет агентам возможность оркестрировать несколько навыков, управлять сложными рабочими процессами и обеспечивать бесперебойное развитие функций с использованием протоколов, таких как FD, реализацию функций с точностью и скоростью, а также координацию навыков для эффективного выполнения проекта.","ar":"تمكّن الوكيل من تنسيق مهارات متعدّدة وإدارة تدفقات العمل المعقّدة وضمان تنمية الميزات دون انقطاع باستخدام بروتوكولات مثل FD وتنفيذ الميزات بدقّة وسرعة وتنسيق المهارات من أجل تنفيذ مشروع فعال."},"useCases":{"en":["Automating feature development workflows","Coordinating multiple skills for project execution","Managing workflows from planning to deployment"],"zh":["自动化特性开发工作流","协调多个技能以进行项目执行","从规划到部署的工作流管理"],"ja":["機能開発ワークフローの自動化","プロジェクト実行のための複数のスキルの調整","計画からデプロイまでのワークフローの管理"],"ko":["기능 개발 워크플로 자동화","프로젝트 실행을 위한 여러 가지 기능의 조정","계획에서 배포까지의 워크플로 관리"],"es":["Automatizar flujos de trabajo de desarrollo de funciones","Coordinar múltiples habilidades para la ejecución de proyectos","Gestionar flujos de trabajo desde la planificación hasta la implementación"],"fr":["Automatiser les flux de travail de développement de fonctionnalités","Coordonner plusieurs compétences pour l''exécution de projets","Gérer les flux de travail de la planification à la mise en production"],"de":["Automatisierung von Funktionsentwicklungs-Arbeitsabläufen","Koordinierung mehrerer Fähigkeiten für die Projektausführung","Verwaltung von Arbeitsabläufen von der Planung bis zur Bereitstellung"],"pt":["Automatizar fluxos de trabalho de desenvolvimento de recursos","Coordenar várias habilidades para execução de projeto","Gerenciar fluxos de trabalho desde o planejamento até a implantação"],"ru":["Автоматизировать рабочие процессы разработки функций","Координировать несколько навыков для выполнения проекта","Управлять рабочими процессами от планирования до развертывания"],"ar":["تأتمة تدفقات العمل لتطوير الميزات","تنسيق مهارات متعدّدة لتنفيذ المشروع","إدارة تدفقات العمل من التخطيط إلى النشر"]},"limitations":{"en":["Requires specific trigger conditions like ''新功能開發'' or ''FD: [功能名稱]''"],"zh":["需要特定的触发条件，如 ''新功能開發'' 或 ''FD: [功能名稱]''"],"ja":["特定のトリガー条件 seperti ''新機能開発'' または ''FD: [機能名]'' が必要"],"ko":["특정 트리거 조건이 필요합니다. 예를 들어 ''새 기능 개발'' 또는 ''FD: [기능 이름]''"],"es":["Requiere condiciones de activación específicas como ''新功能開發'' o ''FD: [nombre de la función]''"],"fr":["Nécessite des conditions de déclenchement spécifiques comme ''新功能開發'' ou ''FD: [nom de la fonction]''"],"de":["Erfordert spezifische Triggerbedingungen wie ''新功能開發'' oder ''FD: [Funktionsname]''"],"pt":["Exige condições de disparo específicas como ''نوفا funcionalidade de desenvolvimento'' ou ''FD: [nome da funcionalidade]''"],"ru":["Требует специальных условий триггера, таких как ''新功能開發'' или ''FD: [название функции]''"],"ar":["يتطلّب شروط انطلاق محدّدة مثل ''新功能開發'' أو ''FD: [اسم الوظيفة]''"]},"version":4},"contentHash":"e227f1dd4e3a0e6e8e0c08d9dcc169b9c1997f30542e19acba4f111a048f342c","qualityScore":38}');
