INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('u9401066/template-is-all-you-need/feature-development', 'feature-development', 'u9401066', 'template-is-all-you-need', 'community', 'feature-development u9401066 template-is-all-you-need community The feature-development skill provides an AI-assisted development project template, enabling developers to coordinate multiple Skills and manage workflows from planning to deployment. 功能開發工作流是一個完整的功能開發流程，從規劃到部署，編排多個Skills協同工作 AIエージェントによる機能開発ワークフローは、計画からデプロイまでの機能開発プロセスをサポートします 기능 개발 프로세스 구축은 계획에서 배포까지의 기능 개발 프로세스를 지원합니다 El desarrollo de características con AI Agent es un proceso que abarca desde la planificación hasta la implementación y el despliegue de nuevas funcionalidades Le développement de fonctionnalités avec Outil IA est un processus qui va de la planification à la mise en œuvre et au déploiement de nouvelles fonctionnalités Die Entwicklung von Funktionen mit KI-Tool ist ein Prozess, der von der Planung bis zur Implementierung und zum Einsatz neuer Funktionen reicht O desenvolvimento de recursos é um processo completo que envolve planejamento, implementação e deploy, utilizando várias habilidades em conjunto Разработка функций - это полный процесс, включающий планирование, реализацию и развертывание, используя несколько навыков в совокупности تطوير الميزات هو عملية شاملة تشمل التخطيط والتنفيذ والتوزيع، باستخدام العديد من المهارات بشكل مشترك how to use feature-development feature-development setup guide what is feature-development feature-development alternative feature-development vs competitors install feature-development Claude Skills workflow management Memory Bank integration 功能開發工作流 AI Skills Memory Bank Constitution-Bylaw系统 功能开发流程 需求分析 規劃和部署 Utilizes Claude Skills for collaborative workflow management Integrates Memory Bank for efficient data storage and retrieval Employs a Constitution-Bylaw system for structured development processes Supports phased development workflows, including planning and deployment Triggers workflows with specific commands, such as ''新功能開發'' or ''FD: [功能名稱]'' Manages multiple Skills to coordinate development tasks feature-development is an AI-assisted development project template with a Constitution-Bylaw system, streamlining the development workflow');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('longbridge/gpui-component/generate-component-story', 'community', 'longbridge', 'gpui-component', 'longbridge/gpui-component', 'generate-component-story', 0, 0, 38, '2026-03-08T01:57:15.295Z', '2026-03-08T02:02:48.582Z', 'e2f3b32391855612eb6c3f58671f0a539f5568ed0af9283e9d03bcef88a9d7aa', '{"id":"longbridge/gpui-component/generate-component-story","name":"generate-component-story","description":{"en":"The generate-component-story skill helps developers build fantastic cross-platform desktop applications using Rust GUI components and GPUI. It provides a structured approach to creating component stories.","zh":"generate-component-story是一个Rust GUI组件生成工具，用于创建跨平台桌面应用。它提供了组件故事的创建和管理功能","ja":"generate-component-storyはRust GUIコンポーネントを生成するツールで、クロスプラットフォームデスクトップアプリケーションを作成するために使用されます。コンポーネントストーリーの作成と管理機能を提供します","ko":"generate-component-story는 Rust GUI 컴포넌트를 생성하는 도구로, 크로스 플랫폼 데스크톱 애플리케이션을 생성하는 데 사용됩니다. 컴포넌트 스토리의 생성과 관리 기능을 제공합니다","es":"La herramienta AI generate-component-story automatiza la creación de historias de componentes para interfaces GUI en Rust usando el framework GPUI. Genera ejemplos estructurados que muestran el uso básico, variantes y estados interactivos siguiendo los patrones del código base.","fr":"L''outil IA generate-component-story automatise la création d''histoires de composants pour les interfaces GUI en Rust en utilisant le framework GPUI. Il génère des exemples structurés montrant l''usage de base, les variantes et les états interactifs en suivant les modèles du code source.","de":"Das KI-Tool generate-component-story automatisiert die Erstellung von Component Stories für GUI-Schnittstellen in Rust mit dem GPUI-Framework. Es generiert strukturierte Beispiele, die die Grundnutzung, Varianten und interaktive Zustände zeigen, basierend auf den Mustern des Quellcodes.","pt":"O generate-component-story é uma habilidade que permite criar histórias de componentes para aplicativos de desktop cross-plataforma com GPUI e Rust","ru":"generate-component-story - это навык, который позволяет создавать истории компонентов для кроссплатформенных настольных приложений с помощью GPUI и Rust","ar":"generate-component-story هو مهارة يسمح بإنشاء قصص المكونات للتطبيقات المكتبية متعددة المنصات باستخدام GPUI و Rust"},"seo":{"title":{"en":"generate-component-story: Rust GUI Component Setup Guide ...","zh":"generate-component-story入门指南 - Rust GUI组件最佳实践","ja":"generate-component-storyセットアップガイド - AIエージェントによるRust GUIコン...","ko":"generate-component-story 설정 가이드 - Rust GUI 컴포넌트를 위한 AI 도구","es":"generate-component-story: Guía para Crear Historias de Co...","fr":"generate-component-story : Guide des Bonnes Pratiques pou...","de":"generate-component-story: Anleitung für GPUI Component St...","pt":"Guia de Configuração do generate-component-story para Fer...","ru":"Руководство по настройке generate-component-story для ИИ ...","ar":"دليل إعداد generate-component-story لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock cross-platform desktop app development with generate-component-story. Learn how to create stunning GUI components using GPUI and get started with our ...","zh":"使用generate-component-story创建Rust GUI组件，实现跨平台桌面应用开发。了解如何使用GPUI构建精彩的组件故事","ja":"generate-component-storyを使用してRust GUIコンポーネントを作成し、クロスプラットフォームデスクトップアプリケーションを開発します。GPUIによるコンポーネントストーリーの構築方法を学習します","ko":"generate-component-story를 사용하여 Rust GUI 컴포넌트를 생성하고 크로스 플랫폼 데스크톱 애플리케이션을 개발합니다. GPUI를 사용한 컴포넌트 스토리의 구축 방법을 학습합니다","es":"Aprende a usar la herramienta AI generate-component-story para crear historias de componentes Rust GPUI. Sigue patrones existentes, usa secciones y cubre tod...","fr":"Apprenez à utiliser l''outil IA generate-component-story pour créer des histoires de composants Rust GPUI. Suivez les modèles existants, utilisez des sections...","de":"Lernen Sie, das KI-Tool generate-component-story zu verwenden, um Rust GPUI Component Stories zu erstellen. Folgen Sie bestehenden Mustern, nutzen Sie Abschn...","pt":"Aprenda a criar histórias de componentes para aplicativos de desktop cross-plataforma com GPUI e Rust","ru":"Узнайте, как создавать истории компонентов для кроссплатформенных настольных приложений с помощью GPUI и Rust","ar":"تعلم كيفية إنشاء قصص المكونات للتطبيقات المكتبية متعددة المنصات باستخدام GPUI و Rust"},"definition":{"en":"generate-component-story is a skill for creating Rust GUI components for cross-platform desktop applications using GPUI, following existing patterns and including comprehensive coverage of options and variants.","zh":"generate-component-story是一个用于创建Rust GUI组件的工具，用于生成跨平台桌面应用的组件故事","ja":"generate-component-storyはRust GUIコンポーネントを作成するためのツールで、クロスプラットフォームデスクトップアプリケーションのコンポーネントストーリーを生成するために使用されます","ko":"generate-component-story는 Rust GUI 컴포넌트를 생성하는 도구로, 크로스 플랫폼 데스크톱 애플리케이션의 컴포넌트 스토리를 생성하는 데 사용됩니다","es":"generate-component-story es una herramienta de IA que genera código para historias de componentes en el framework GPUI de Rust. Su propósito es crear documentación de UI automatizada que muestre todas las opciones, variantes y ejemplos de uso de un componente, organizada en secciones.","fr":"generate-component-story est un outil IA qui génère du code pour des histoires de composants dans le framework GPUI de Rust. Son but est de créer une documentation UI automatisée montrant toutes les options, variantes et exemples d''usage d''un composant, organisée en sections.","de":"generate-component-story ist ein KI-Tool, das Code für Component Stories im Rust GPUI-Framework generiert. Es dient dazu, automatisierte UI-Dokumentation zu erstellen, die alle Optionen, Varianten und Nutzungsbeispiele einer Komponente in Abschnitten organisiert zeigt.","pt":"O generate-component-story é uma habilidade que cria histórias de componentes para aplicativos de desktop","ru":"generate-component-story - это навык, создающий истории компонентов для настольных приложений","ar":"generate-component-story هو مهارة ي createContext histórias المكونات للتطبيقات المكتبية"},"features":{"en":["Follows existing patterns in crates/story/src/stories","Organizes stories with section! calls for each major part","Includes comprehensive coverage of all options, variants, and usage examples","Supports basic usage examples and different variants and states","Utilizes GPUI for building cross-platform desktop applications","Creates stories with interactive examples"],"zh":["基于GPUI的Rust GUI组件生成","组件故事的创建和管理","支持跨平台桌面应用开发","提供基本用法示例和不同变体","支持交互式组件示例"],"ja":["GPUIを使用したRust GUIコンポーネントの生成","コンポーネントストーリーの作成と管理","クロスプラットフォームデスクトップアプリケーションの開発をサポート","基本的な使用方法の例とさまざまなバリアントを提供","インタラクティブなコンポーネントの例をサポート"],"ko":["GPUI를 사용한 Rust GUI 컴포넌트 생성","컴포넌트 스토리의 생성과 관리","크로스 플랫폼 데스크톱 애플리케이션 개발을 지원","기본적인 사용 방법의 예와 다양한 변형을 제공","인터랙티브 컴포넌트의 예를 지원"],"es":["Sigue patrones existentes de crates/story/src/stories como tabs_story.rs","Organiza el código con llamadas section! para cada parte principal","Cubre todas las opciones, variantes y ejemplos de uso del componente","Genera ejemplos de uso básico y diferentes estados del componente","Incluye demostraciones interactivas para los componentes","Específico para el ecosistema de GUI en Rust con GPUI"],"fr":["Suit les modèles existants de crates/story/src/stories comme tabs_story.rs","Organise le code avec des appels section! pour chaque partie principale","Couvre toutes les options, variantes et exemples d''usage du composant","Génère des exemples d''usage de base et différents états du composant","Inclut des démonstrations interactives pour les composants","Spécifique à l''écosystème GUI en Rust avec GPUI"],"de":["Folgt bestehenden Mustern aus crates/story/src/stories wie tabs_story.rs","Organisiert Code mit section!-Aufrufen für jeden Hauptteil","Deckt alle Optionen, Varianten und Nutzungsbeispiele der Komponente ab","Generiert grundlegende Nutzungsbeispiele und verschiedene Komponentenzustände","Beinhaltet interaktive Demonstrationen für Komponenten","Spezifisch für das GUI-Ökosystem in Rust mit GPUI"],"pt":["Criação de histórias de componentes com GPUI","Suporte a aplicativos de desktop cross-plataforma","Uso de Rust como linguagem de programação","Organização de histórias com section!","Cobertura abrangente de opções e variantes de componentes"],"ru":["Создание историй компонентов с помощью GPUI","Поддержка кроссплатформенных настольных приложений","Использование Rust в качестве языка программирования","Организация историй с помощью section!","Полное покрытие опций и вариантов компонентов"],"ar":["إنشاء قصص المكونات باستخدام GPUI","دعم التطبيقات المكتبية متعددة المنصات","استخدام Rust كภาษة برمجة","تنظيم القصص باستخدام section!","التغطية الشاملة للخيارات ومتغيرات المكونات"]},"keywords":{"en":["how to use generate-component-story","generate-component-story alternative","generate-component-story setup guide","what is generate-component-story","generate-component-story vs GPUI","generate-component-story install","Rust GUI component development","cross-platform desktop application development","GPUI tutorial"],"zh":["Rust GUI组件","generate-component-story","GPUI","跨平台桌面应用","组件故事","Rust开发","GUI组件生成","AI工具","组件开发"],"ja":["Rust GUIコンポーネント","generate-component-story","GPUI","クロスプラットフォームデスクトップアプリケーション","コンポーネントストーリー","Rust開発","GUIコンポーネント生成","AIエージェント","コンポーネント開発"],"ko":["Rust GUI 컴포넌트","generate-component-story","GPUI","크로스 플랫폼 데스크톱 애플리케이션","컴포넌트 스토리","Rust 개발","GUI 컴포넌트 생성","AI 도구","컴포넌트 개발"],"es":["rust gpui componentes","historias de componentes gpui","generate-component-story ai","herramientas ai para desarrolladores","rust gui desarrollo","ejemplos de componentes interactivos","tabs_story.rs referencia","automatizar documentación ui"],"fr":["rust gpui composants","histoires de composants gpui","generate-component-story ia","outils ia pour développeurs","développement gui rust","exemples de composants interactifs","tabs_story.rs référence","automatiser documentation ui"],"de":["rust gpui komponenten","component stories gpui","generate-component-story ki","ki tools für entwickler","rust gui entwicklung","interaktive komponenten beispiele","tabs_story.rs referenz","ui dokumentation automatisieren"],"pt":["generate-component-story","GPUI","Rust","aplicativos de desktop","histórias de componentes","desenvolvimento de software","ferramentas de IA","programação de computador"],"ru":["generate-component-story","GPUI","Rust","настольные приложения","истории компонентов","разработка программного обеспечения","ИИ Агенты","программирование компьютеров"],"ar":["generate-component-story","GPUI","Rust","التطبيقات المكتبية","قصص المكونات","تطوير البرمجيات","أدوات الذكاء الاصطناعي","برمجة الحاسوب"]}},"owner":"longbridge","repo":"gpui-component","repoPath":"longbridge/gpui-component","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.295Z","topics":[],"category":"community","skillMd":{"name":"generate-component-story","description":"Create story examples for components. Use when writing stories, creating examples, or demonstrating component usage.","bodyPreview":"## Instructions\n\nWhen creating component stories:\n\n1. **Follow existing patterns**: Base stories on the styles found in `crates/story/src/stories` (examples: `tabs_story.rs`, `group_box_story.rs`, etc.)\n2. **Use sections**: Organize the story with `section!` calls for each major part\n3. **Comprehensive coverage**: Include all options, variants, and usage examples of the component\n\n## Examples\n\nA typical story structure includes:\n- Basic usage examples\n- Different variants and states\n- Interactiv","body":"## Instructions\n\nWhen creating component stories:\n\n1. **Follow existing patterns**: Base stories on the styles found in `crates/story/src/stories` (examples: `tabs_story.rs`, `group_box_story.rs`, etc.)\n2. **Use sections**: Organize the story with `section!` calls for each major part\n3. **Comprehensive coverage**: Include all options, variants, and usage examples of the component\n\n## Examples\n\nA typical story structure includes:\n- Basic usage examples\n- Different variants and states\n- Interactive examples\n- Edge cases and error states\n"},"lastSynced":"2026-03-08T02:02:48.582Z","agentAnalysis":{"suitability":{"en":"Perfect for GUI-focused Agents needing structured component story generation in Rust GUI components and GPUI.","zh":"非常适合专注于 GUI 的 Agent，需要在 Rust GUI 组件和 GPUI 中进行结构化组件故事生成。","ja":"Rust GUI コンポーネントと GPUI における構造化されたコンポーネントストーリー生成を必要とする GUI 中心のエージェントに最適です。","ko":"Rust GUI 컴포넌트와 GPUI에서 구조화된 컴포넌트 스토리 생성이 필요한 GUI 중심 에이전트에 완벽합니다.","es":"Perfecto para agentes enfocados en GUI que necesitan generación de historias de componentes estructuradas en componentes GUI de Rust y GPUI.","fr":"Parfait pour les agents axés sur GUI nécessitant une génération de récits de composants structurés dans les composants GUI Rust et GPUI.","de":"Perfekt für GUI-fokussierte Agents, die eine strukturierte Komponentenstory-Generierung in Rust-GUI-Komponenten und GPUI benötigen.","pt":"Perfeito para Agentes focados em GUI que necessitam de geração de histórias de componentes estruturadas em componentes GUI Rust e GPUI.","ru":"Идеально подходит для агентов, ориентированных на GUI, которым необходима структурированная генерация историй компонентов в компонентах GUI Rust и GPUI.","ar":" مثالي لعميل ذكاء اصطناعي يركز على واجهة المستخدم الرسومية التي تحتاج إلى إنشاء قصة مكونات منظمة في مكونات واجهة المستخدم الرسومية روست و GPUI."},"recommendation":{"en":"Empowers agents to create comprehensive cross-platform desktop applications using Rust GUI components, providing a structured approach to component stories with sections and comprehensive coverage, utilizing GPUI for optimized performance.","zh":"赋能 Agent 使用 Rust GUI 组件创建全面的跨平台桌面应用程序，通过 section! 调用提供带有章节和全面覆盖的结构化组件故事方法，并利用 GPUI 实现优化性能。","ja":"Rust GUI コンポーネントを使用して包括的なクロスプラットフォームデスクトップアプリケーションを作成するエージェントを強化し、section! 呼び出しによるセクションと包括的なカバレッジを備えた構造化されたコンポーネントストーリー手法を提供し、最適化されたパフォーマンスのために GPUI を利用します。","ko":"Rust GUI 컴포넌트를 사용하여 포괄적인 크로스 플랫폼 데스크톱 애플리케이션을 생성하는 에이전트의 능력을 강화하며, section! 호출을 통해 섹션과 포괄적인 커버리지를 갖춘 구조화된 컴포넌트 스토리 접근법을 제공하고 최적화된 성능을 위해 GPUI를 활용합니다.","es":"Habilita a los agentes a crear aplicaciones de escritorio integrales de varias plataformas utilizando componentes GUI de Rust, proporcionando un enfoque estructurado para las historias de los componentes con secciones y cobertura integral, utilizando GPUI para un rendimiento optimizado.","fr":"Permet aux agents de créer des applications de bureau complètes multi-plateformes en utilisant les composants GUI Rust, en fournissant une approche structurée pour les récits de composants avec des sections et une couverture globale, en utilisant GPUI pour des performances optimisées.","de":"Ermächtigt Agents, umfassende Cross-Plattform-Desktop-Anwendungen mit Rust-GUI-Komponenten zu erstellen, indem sie einen strukturierten Ansatz für Komponentenstorys mit Abschnitten und umfassender Abdeckung bieten, wobei GPUI für optimierte Leistung verwendet wird.","pt":"Permite que os agentes criem aplicações de área de trabalho cross-platform abrangentes usando componentes GUI Rust, fornecendo uma abordagem estruturada para histórias de componentes com seções e cobertura abrangente, utilizando GPUI para desempenho otimizado.","ru":"Предоставляет агентам возможность создавать всесторонние кроссплатформенные настольные приложения, используя компоненты GUI Rust, обеспечивая структурированный подход к историям компонентов с разделами и полным покрытием, используя GPUI для оптимизированной производительности.","ar":"يمكّن العميل من إنشاء تطبيقات سطح المكتب شاملة متعددة المنصات باستخدام مكونات واجهة المستخدم الرسومية روست، مما يوفر نهجًا منظمًا لروايات المكونات مع أقسام وتغطية شاملة، وذلك باستخدام GPUI لأداء محسّن."},"useCases":{"en":["Generating component stories for tabs and group boxes","Creating interactive stories with different variants and states","Organizing story structures with section! calls"],"zh":["为选项卡和分组框生成组件故事","创建具有不同变体和状态的交互式故事","使用 section! 调用来组织故事结构"],"ja":["タブとグループボックスのコンポーネントストーリーの生成","異なるバリアントと状態を持つインタラクティブなストーリーの作成","section! 呼び出しを使用したストーリー構造の整理"],"ko":["탭과 그룹 박스에 대한 컴포넌트 스토리 생성","다른 변형과 상태를 가진 인터랙티브 스토리 생성","section! 호출을 사용한 스토리 구조 구성"],"es":["Generar historias de componentes para pestañas y cuadros de grupo","Crear historias interactivas con diferentes variantes y estados","Organizar estructuras de historia con llamadas a sección"],"fr":["Générer des récits de composants pour les onglets et les boîtes de groupe","Créer des histoires interactives avec différentes variantes et états","Organiser les structures de récit avec des appels de section"],"de":["Generieren von Komponentenstorys für Registerkarten und Gruppenfelder","Erstellen interaktiver Storys mit unterschiedlichen Varianten und Zuständen","Organisieren von Story-Strukturen mit Section-Aufrufen"],"pt":["Gerar histórias de componentes para guias e caixas de grupo","Criar histórias interativas com variantes e estados diferentes","Organizar estruturas de histórias com chamadas de seção"],"ru":["Генерировать истории компонентов для вкладок и групповых ящиков","Создавать интерактивные истории с различными вариантами и состояниями","Организовывать структуры историй с помощью вызовов секций"],"ar":["إنشاء قصة مكونات للفواصل والصناديق المجمعة","إنشاء قصص تفاعلية بمتغيرات وحالات مختلفة","تنظيم هيكل القصة باستخدام استدعاءات القسم"]},"limitations":{"en":["Requires Rust GUI components and GPUI setup","Follows specific patterns found in crates/story/src/stories"],"zh":["需要 Rust GUI 组件和 GPUI 设置","遵循 crates/story/src/stories 中发现的具体模式"],"ja":["Rust GUI コンポーネントと GPUI のセットアップが必要","crates/story/src/stories で見られる特定のパターンに従う"],"ko":["Rust GUI 컴포넌트 및 GPUI 설정 필요","crates/story/src/stories에서 발견되는 특정 패턴 준수"],"es":["Requiere configuración de componentes GUI de Rust y GPUI","Sigue patrones específicos encontrados en crates/story/src/stories"],"fr":["Nécessite une configuration de composants GUI Rust et GPUI","Suit des modèles spécifiques trouvés dans crates/story/src/stories"],"de":["Benötigt Rust-GUI-Komponenten und GPUI-Setup","Befolgt spezifische Muster, die in crates/story/src/stories gefunden werden"],"pt":["Exige configuração de componentes GUI Rust e GPUI","Sigue padrões específicos encontrados em crates/story/src/stories"],"ru":["Требует настройки компонентов GUI Rust и GPUI","Следует конкретным шаблонам, найденным в crates/story/src/stories"],"ar":["يتطلب إعداد مكونات واجهة المستخدم الرسومية روست و GPUI","يتبع أنماطًا محددة وجدت في crates/story/src/stories"]},"version":4},"contentHash":"e2f3b32391855612eb6c3f58671f0a539f5568ed0af9283e9d03bcef88a9d7aa","qualityScore":38}');
