INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('longbridge/gpui-component/generate-component-story', 'generate-component-story', 'longbridge', 'gpui-component', 'community', 'generate-component-story longbridge gpui-component community The generate-component-story skill helps developers build fantastic cross-platform desktop applications using Rust GUI components and GPUI. It provides a structured approach to creating component stories. generate-component-story是一个Rust GUI组件生成工具，用于创建跨平台桌面应用。它提供了组件故事的创建和管理功能 generate-component-storyはRust GUIコンポーネントを生成するツールで、クロスプラットフォームデスクトップアプリケーションを作成するために使用されます。コンポーネントストーリーの作成と管理機能を提供します generate-component-story는 Rust GUI 컴포넌트를 생성하는 도구로, 크로스 플랫폼 데스크톱 애플리케이션을 생성하는 데 사용됩니다. 컴포넌트 스토리의 생성과 관리 기능을 제공합니다 La herramienta AI generate-component-story automatiza la creación de historias de componentes para interfaces GUI en Rust usando el framework GPUI. Genera ejemplos estructurados que muestran el uso básico, variantes y estados interactivos siguiendo los patrones del código base. L''outil IA generate-component-story automatise la création d''histoires de composants pour les interfaces GUI en Rust en utilisant le framework GPUI. Il génère des exemples structurés montrant l''usage de base, les variantes et les états interactifs en suivant les modèles du code source. Das KI-Tool generate-component-story automatisiert die Erstellung von Component Stories für GUI-Schnittstellen in Rust mit dem GPUI-Framework. Es generiert strukturierte Beispiele, die die Grundnutzung, Varianten und interaktive Zustände zeigen, basierend auf den Mustern des Quellcodes. O generate-component-story é uma habilidade que permite criar histórias de componentes para aplicativos de desktop cross-plataforma com GPUI e Rust generate-component-story - это навык, который позволяет создавать истории компонентов для кроссплатформенных настольных приложений с помощью GPUI и Rust generate-component-story هو مهارة يسمح بإنشاء قصص المكونات للتطبيقات المكتبية متعددة المنصات باستخدام GPUI و Rust how to use generate-component-story generate-component-story alternative generate-component-story setup guide what is generate-component-story generate-component-story vs GPUI generate-component-story install Rust GUI component development cross-platform desktop application development GPUI tutorial Rust GUI组件 generate-component-story GPUI 跨平台桌面应用 组件故事 Rust开发 GUI组件生成 AI工具 组件开发 Follows existing patterns in crates/story/src/stories Organizes stories with section! calls for each major part Includes comprehensive coverage of all options, variants, and usage examples Supports basic usage examples and different variants and states Utilizes GPUI for building cross-platform desktop applications Creates stories with interactive examples generate-component-story is a skill for creating Rust GUI components for cross-platform desktop applications using GPUI, following existing patterns and including comprehensive coverage of options and variants.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alexandru/social-publish/arrow-resource', 'community', 'alexandru', 'social-publish', 'alexandru/social-publish', 'arrow-resource', 0, 0, 38, '2026-03-08T01:57:15.326Z', '2026-03-08T02:03:02.176Z', '95d2230c912e181d9558b6c5fb9e4a4466eebc22949a615e4fb08ad5d95c8ad9', '{"id":"alexandru/social-publish/arrow-resource","name":"arrow-resource","description":{"en":"arrow-resource is a self-hosted service that enables sharing to multiple social media platforms simultaneously, benefiting developers who need to manage complex social media workflows.","zh":"Arrow Resource 是一个 Kotlin 库，提供了并行资源管理的功能，通过 `resourceScope` 和 `resource` 实现资源的定义和组合","ja":"Arrow Resource は Kotlin ライブラリで、並列リソース管理機能を提供します。`resourceScope` と `resource` を使用してリソースを定義して組み合わせます","ko":"Arrow Resource는 Kotlin 라이브러리로서 병렬 리소스 관리 기능을 제공합니다. `resourceScope`와 `resource`를 사용하여 리소스를 정의하고 조합합니다","es":"Arrow Resource es un servicio de alojamiento propio que permite compartir contenido en múltiples plataformas sociales al mismo tiempo con Kotlin.","fr":"Arrow Resource est un service d''hébergement autonome qui permet de partager du contenu sur plusieurs plateformes sociales en même temps avec Kotlin.","de":"Arrow Resource ist ein selbst gehosteter Service, der es ermöglicht, Inhalte auf mehreren sozialen Plattformen gleichzeitig mit Kotlin zu teilen.","pt":"O Arrow Resource é um serviço de autopublicação que permite compartilhar conteúdo em várias plataformas de mídia social ao mesmo tempo, utilizando Kotlin","ru":"Arrow Resource - это само-хостинговый сервис, помогающий публиковать контент на нескольких социальных платформах одновременно, написанный на Kotlin","ar":"Arrow Resource هو خدمة لنشر المحتوى على منصات متعددة، يستخدم Kotlin لتنفيذ هذه المهمة"},"seo":{"title":{"en":"arrow-resource: Setup Guide for AI Agents | AI Agent Skill","zh":"Arrow Resource 设置指南：Kotlin 并行资源管理","ja":"Arrow Resource のベストプラクティス：並列リソース管理 with Kotlin","ko":"Arrow Resource 사용 가이드: Kotlin을 이용한 병렬 리소스 관리","es":"Arrow Resource: Guía de configuración para desarrolladores","fr":"Arrow Resource: Guide d''installation pour les développeurs","de":"Arrow Resource: Einrichtungsanleitung für Entwickler","pt":"Guia de Configuração do Arrow Resource para Desenvolvedores","ru":"ИИ Агенты: Настройка Arrow Resource для Мультиплатформенн...","ar":"دليل تنصيب Arrow Resource لأتمتة النشر على منصات متعددة"},"description":{"en":"Discover how to use arrow-resource to streamline social media sharing. Learn to compose resources with .bind() and parZip for parallel acquisition.","zh":"了解 Arrow Resource 的技术细节，实现 Kotlin 并行资源管理，提升开发效率","ja":"Arrow Resource を使用して Kotlin での並列リソース管理を実現し、開発効率を向上させる","ko":"Arrow Resource를 사용하여 Kotlin의 병렬 리소스 관리를 구현하고 개발 효율성을 높여보세요","es":"Aprende a configurar Arrow Resource para compartir contenido en múltiples plataformas sociales con Kotlin","fr":"Découvrez comment configurer Arrow Resource pour partager du contenu sur plusieurs plateformes sociales avec Kotlin","de":"Erfahren Sie, wie Sie Arrow Resource für die Veröffentlichung von Inhalten auf mehreren sozialen Plattformen mit Kotlin einrichten","pt":"Aprenda a configurar o Arrow Resource para compartilhar conteúdo em múltiplas plataformas de mídia social com facilidade","ru":"Откройте для себя, как настроить Arrow Resource для публикации контента на нескольких социальных платформах одновременно","ar":"اكتشف كيفية تنصيب Arrow Resource لنشر المحتوى بسهولة على منصات متعددة"},"definition":{"en":"arrow-resource is a Kotlin-based service that helps share content across multiple social media platforms at once, using resourceScope and resource definitions.","zh":"Arrow Resource 是一个 Kotlin 库，用于并行资源管理和组合","ja":"Arrow Resource は Kotlin ライブラリで、並列リソース管理と組み合わせを実現する","ko":"Arrow Resource는 Kotlin 라이브러리로서 병렬 리소스 관리와 조합을 구현하는 라이브러리입니다","es":"Arrow Resource es un servicio que permite compartir contenido en varias plataformas sociales utilizando Kotlin","fr":"Arrow Resource est un outil d''agent IA qui permet de partager du contenu sur plusieurs plateformes sociales en utilisant Kotlin","de":"Arrow Resource ist ein Tool für künstliche Intelligenz, das die Veröffentlichung von Inhalten auf mehreren sozialen Plattformen mit Kotlin ermöglicht","pt":"O que é Arrow Resource? Um serviço de autopublicação para compartilhar conteúdo em múltiplas plataformas de mídia social","ru":"Что такое Arrow Resource? Сервис для мультиплатформенной публикации контента","ar":"ما هو Arrow Resource? خدمة لنشر المحتوى على منصات متعددة"},"features":{"en":["Uses `resourceScope { ... }` for lifecycle boundary management","Defines resources with `resource { install(acquire) { a, exitCase -> release } }`","Composes resources with `.bind()` for dependent acquisition","Supports parallel acquisition using `parZip`","Provides reusable constructors on `ResourceScope` for customized workflows","Follows patterns and examples outlined in `references/resource.md`"],"zh":["使用 `resourceScope` 实现资源定义和组合","通过 `resource` 定义资源并实现并行管理","支持 `parZip` 实现独立的并行资源获取","提供 `install` 和 `acquire` 方法实现资源的定义和获取","支持 Kotlin 语言开发"],"ja":["『resourceScope』を使用してリソースを定義して組み合わせる","『resource』を使用してリソースを定義して並列管理する","『parZip』をサポートして独立した並列リソース取得を実現する","『install』と『acquire』メソッドを提供してリソースを定義して取得する","Kotlin 言語開発をサポートする"],"ko":["『resourceScope』를 사용하여 리소스를 정의하고 조합한다","『resource』를 사용하여 리소스를 정의하고 병렬 관리한다","『parZip』를 지원하여 독립적인 병렬 리소스 获取을 구현한다","『install』와 『acquire』 메서드를 제공하여 리소스를 정의하고 가져온다","Kotlin 언어 개발을 지원한다"],"es":["Uso de `resourceScope` para definir límites de ciclo de vida","Definición de recursos con `resource` y `install`","Composición de recursos con `.bind()`","Uso de `parZip` para adquisición paralela independiente","Implementación de un `Resource<A>` con `install`"],"fr":["Utilisation de `resourceScope` pour définir les limites du cycle de vie","Définition de ressources avec `resource` et `install`","Composition de ressources avec `.bind()`","Utilisation de `parZip` pour acquisition parallèle indépendante","Implémentation d''un `Resource<A>` avec `install`"],"de":["Verwendung von `resourceScope` für die Definition von Lebenszyklusgrenzen","Definition von Ressourcen mit `resource` und `install`","Zusammensetzung von Ressourcen mit `.bind()`","Verwendung von `parZip` für unabhängige parallele Beschaffung","Implementierung eines `Resource<A>` mit `install`"],"pt":["Utiliza `resourceScope { ... }` para definir limites de ciclo de vida","Define recursos com `resource { install(acquire) { a, exitCase -> release } }`","Composição com `.bind()` e `parZip` para aquisição paralela independente","Padrões e exemplos concretos em `references/resource.md`","Implementação de `Resource<A>` usando `install`"],"ru":["Использует `resourceScope { ... }` для определения границ жизненного цикла","Определяет ресурсы с `resource { install(acquire) { a, exitCase -> release } }`","Композиция с `.bind()` и `parZip` для независимой параллельной аquisição","Шаблоны и конкретные примеры в `references/resource.md`","Реализация `Resource<A>` с помощью `install`"],"ar":["يستخدم `resourceScope { ... }` لتحديد حدود دورة الحياة","يحدد الموارد باستخدام `resource { install(acquire) { a, exitCase -> release } }`","التأليف مع `.bind()` و `parZip` للأستحواذ الموازي المستقل","أنماط وأمثلة محددة في `references/resource.md`","تنفيذ `Resource<A>` باستخدام `install`"]},"keywords":{"en":["how to use arrow-resource","what is arrow-resource","arrow-resource alternative","arrow-resource vs buffer","arrow-resource install","arrow-resource setup guide","kotlin resource management","social media sharing api","parallel acquisition in kotlin"],"zh":["Arrow Resource","Kotlin 并行资源管理","资源定义和组合","并行资源管理","Kotlin 开发","AIエージェント","资源管理库"],"ja":["Arrow Resource","Kotlin 並列リソース管理","リソース定義と組み合わせ","並列リソース管理","Kotlin 開発","AIエージェント","リソース管理ライブラリ"],"ko":["Arrow Resource","Kotlin 병렬 리소스 관리","리소스 정의와 조합","병렬 리소스 관리","Kotlin 개발","AI 에이전트","리소스 관리 라이브러리"],"es":["Arrow Resource","Kotlin","compartir contenido en redes sociales","servicio de alojamiento propio","programación funcional","ciclo de vida de recursos","agentes de inteligencia artificial","herramientas de desarrollo de software"],"fr":["Arrow Resource","Kotlin","partager du contenu sur les réseaux sociaux","service d''hébergement autonome","programmation fonctionnelle","cycle de vie des ressources","agents d''intelligence artificielle","outils de développement de logiciels"],"de":["Arrow Resource","Kotlin","Inhalte in sozialen Netzwerken teilen","selbst gehosteter Service","funktionale Programmierung","Lebenszyklus von Ressourcen","künstliche Intelligenz-Tools","Software-Entwicklungstools"],"pt":["Arrow Resource","Kotlin","autopublicação","mídia social","desenvolvedores","programação","tecnologia","compartilhamento de conteúdo","plataformas de mídia social"],"ru":["ИИ Агенты","Arrow Resource","Kotlin","мультиплатформенная публикация","социальные платформы","публикация контента","программирование","технологии","настройка Arrow Resource"],"ar":["Arrow Resource","Kotlin","نشر المحتوى","منصات متعددة","مطورون","برمجة","تكنولوجيا","مشاركة المحتوى","منصات التواصل الاجتماعي"]}},"owner":"alexandru","repo":"social-publish","repoPath":"alexandru/social-publish","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.326Z","topics":[],"category":"community","skillMd":{"name":"arrow-resource","description":"Kotlin + Arrow Resource lifecycle management with `Resource`, `ResourceScope`, and `resourceScope`. Use for designing safe acquisition/release of files, streams, DB pools/connections, HTTP clients, or multipart parts; composing resources (including parallel acquisition); or integrating Resource with typed errors and cancellation.","bodyPreview":"# Arrow Resource (Kotlin)\n\n## Quick start\n- Use `resourceScope { ... }` at lifecycle boundaries.\n- Define each resource with `resource { install(acquire) { a, exitCase -> release } }`.\n- Compose with `.bind()`; use `parZip` for independent parallel acquisition.\n- Read `references/resource.md` for patterns and concrete examples.\n\n## Workflow\n1. Identify the acquire step and the release step.\n2. Implement a `Resource<A>` using `install`.\n3. Create reusable constructors on `ResourceScope` when need","body":"# Arrow Resource (Kotlin)\n\n## Quick start\n- Use `resourceScope { ... }` at lifecycle boundaries.\n- Define each resource with `resource { install(acquire) { a, exitCase -> release } }`.\n- Compose with `.bind()`; use `parZip` for independent parallel acquisition.\n- Read `references/resource.md` for patterns and concrete examples.\n\n## Workflow\n1. Identify the acquire step and the release step.\n2. Implement a `Resource<A>` using `install`.\n3. Create reusable constructors on `ResourceScope` when needed.\n4. Compose resources into higher-level resources with `.bind()`.\n5. Execute in `resourceScope` and keep finalizers idempotent.\n\n## Usage guidance\n- Prefer Resource over `use`/`try/finally` when you need suspend finalizers or MPP support.\n- Use `ExitCase` to handle rollback/cleanup differences.\n- When mixing with typed errors, pick nesting order deliberately to control `ExitCase` seen by finalizers.\n\n## References\n- Load `references/resource.md` for API details and end-to-end examples.\n"},"lastSynced":"2026-03-08T02:03:02.176Z","agentAnalysis":{"suitability":{"en":"Perfect for Kotlin-based AI Agents needing efficient resource management and parallel acquisition capabilities.","zh":"非常适合需要高效资源管理和并行获取能力的基于Kotlin的AI代理。","ja":"KotlinベースのAIエージェントが効率的なリソース管理と並列取得機能を必要とする場合に最適です。","ko":"효율적인 리소스 관리와 병렬 처리 기능이 필요한 Kotlin 기반의 AI 에이전트에 적합합니다.","es":"Perfecto para Agentes de IA basados en Kotlin que necesitan un manejo eficiente de recursos y capacidades de adquisición paralela.","fr":"Parfait pour les agents d''IA basés sur Kotlin nécessitant une gestion efficace des ressources et des capacités d''acquisition parallèle.","de":"Perfekt für auf Kotlin basierende KI-Agents, die ein effizientes Ressourcenmanagement und parallele Akquise-Fähigkeiten benötigen.","pt":"Perfeito para Agentes de IA baseados em Kotlin que necessitam de gerenciamento eficiente de recursos e capacidades de aquisição paralela.","ru":"Идеально подходит для агентов ИИ на основе Kotlin, требующих эффективного управления ресурсами и возможностей параллельного приобретения.","ar":"مثالي للوكلاء الذكيين القائمين على Kotlin الذين يحتاجون إلى إدارة موارد فعالة وقدرات اكتساب متوازي."},"recommendation":{"en":"Empowers agents to manage complex social media workflows by composing resources with `.bind()` and utilizing `parZip` for independent parallel acquisition, all while ensuring safe resource release using `resourceScope` and `install` with `acquire` and `release` steps.","zh":"使代理能够通过组合资源使用`.bind()`和利用`parZip`进行独立的并行获取来管理复杂的社交媒体工作流，同时使用`resourceScope`和`install`以及`acquire`和`release`步骤来确保安全的资源释放。","ja":"エージェントが`.bind()`でリソースを組み合わせて使用し、`parZip`で独立した並列取得を行い、`resourceScope`と`install`および`acquire`と`release`ステップを使用して安全なリソースの解放を保証することで、複雑なソーシャルメディアのワークフローを管理できるようにします。","ko":"`.bind()`를 사용하여 리소스를 구성하고, `parZip`를 사용하여 독립적인 병렬処리를 수행함으로써 복잡한 소셜 미디어 워크플로우를 관리할 수 있도록 에이전트를 강화하고, `resourceScope`와 `install` 및 `acquire` 및 `release` 단계를 사용하여 안전한 리소스 해제를 보장합니다.","es":"Habilita a los agentes a gestionar flujos de trabajo de medios sociales complejos mediante la composición de recursos con `.bind()` y la utilización de `parZip` para la adquisición paralela independiente, todo mientras se garantiza la liberación segura de recursos utilizando `resourceScope` y `install` con los pasos `acquire` y `release`.","fr":"Permet aux agents de gérer des flux de travail de médias sociaux complexes en composant des ressources avec `.bind()` et en utilisant `parZip` pour l''acquisition parallèle indépendante, le tout en garantissant une libération sécurisée des ressources en utilisant `resourceScope` et `install` avec les étapes `acquire` et `release`.","de":"Ermöglicht es Agenten, komplexe Social-Media-Workflows zu verwalten, indem sie Ressourcen mit `.bind()` komponieren und `parZip` für unabhängige parallele Akquise verwenden, während gleichzeitig eine sichere Ressourcenfreigabe unter Verwendung von `resourceScope` und `install` mit den Schritten `acquire` und `release` sichergestellt wird.","pt":"Habilita os agentes a gerenciar fluxos de trabalho de mídia social complexos, compondo recursos com `.bind()` e utilizando `parZip` para aquisição paralela independente, garantindo a liberação segura de recursos usando `resourceScope` e `install` com as etapas `acquire` e `release`.","ru":"Позволяет агентам управлять сложными рабочими процессами социальных сетей, составляя ресурсы с помощью `.bind()` и используя `parZip` для независимого параллельного приобретения, обеспечивая безопасное освобождение ресурсов с помощью `resourceScope` и `install` с шагами `acquire` и `release`.","ar":"تمكين الوكلاء من إدارة سلاسل عمل متعددة الوسائط الاجتماعية المعقدة من خلال تكوين الموارد باستخدام `.bind()` واستخدام `parZip` للاكتساب المتوازي المستقل، مع ضمان الإطلاق الآمن للموارد باستخدام `resourceScope` و `install` بخطوات `acquire` و `release`."},"useCases":{"en":["Automating social media posting across multiple platforms","Implementing reusable resource constructors for streamlined workflows","Debugging resource acquisition and release issues with `resource { install(acquire) { a, exitCase -> release } }`"],"zh":["跨多个平台自动化社交媒体帖子","实现可重用的资源构造器以简化工作流程","使用`resource { install(acquire) { a, exitCase -> release } }`调试资源获取和释放问题"],"ja":["複数のプラットフォームにわたるソーシャルメディア投稿の自動化","再利用可能なリソースコンストラクターを実装してワークフローを簡素化する","`resource { install(acquire) { a, exitCase -> release } }`を使用してリソースの取得と解放の問題をデバッグする"],"ko":["여러 플랫폼에 걸쳐 소셜 미디어 포스팅을 자동화하는 것","재사용 가능한 리소스 생성자를 구현하여 워크플로우를 간소화하는 것","`resource { install(acquire) { a, exitCase -> release } }`를 사용하여 리소스 취득 및 해제 문제를 디버깅하는 것"],"es":["Automatizar publicaciones en redes sociales en varias plataformas","Implementar constructores de recursos reutilizables para flujos de trabajo optimizados","Depurar problemas de adquisición y liberación de recursos con `resource { install(acquire) { a, exitCase -> release } }`"],"fr":["Automatiser les publications sur les médias sociaux sur plusieurs plateformes","Implémenter des constructeurs de ressources réutilisables pour des flux de travail optimisés","Déboguer les problèmes d''acquisition et de libération de ressources avec `resource { install(acquire) { a, exitCase -> release } }`"],"de":["Automatisieren von Social-Media-Beiträgen auf mehreren Plattformen","Implementieren von wiederverwendbaren Ressourcenkonstruktoren für optimierte Workflows","Fehlerbehebung bei Problemen mit der Ressourcenakquise und -freigabe mit `resource { install(acquire) { a, exitCase -> release } }`"],"pt":["Automatizar postagens em mídia social em várias plataformas","Implementar construtores de recursos reutilizáveis para fluxos de trabalho otimizados","Depurar problemas de aquisição e liberação de recursos com `resource { install(acquire) { a, exitCase -> release } }`"],"ru":["Автоматизировать публикацию в социальных сетях на нескольких платформах","Реализовывать многократно используемые конструкторы ресурсов для оптимизированных рабочих процессов","Отлаживать проблемы приобретения и освобождения ресурсов с помощью `resource { install(acquire) { a, exitCase -> release } }`"],"ar":["التحكم الآلي في نشر المحتوى على منصات متعددة من الوسائط الاجتماعية","تنفيذ معماريين موارد لإعادة الاستخدام من أجل سلاسل عمل مبسطة","تصحيح أخطاء اكتساب وإطلاق الموارد باستخدام `resource { install(acquire) { a, exitCase -> release } }`"]},"limitations":{"en":["Requires Kotlin programming language","Self-hosted service needed","Manual implementation of acquire and release steps required"],"zh":["需要Kotlin编程语言","需要自托管服务","需要手动实现获取和释放步骤"],"ja":["Kotlinプログラミング言語が必要","セルフホスティングサービスが必要","取得と解放のステップの手動実装が必要"],"ko":["Kotlin 프로그래밍 언어가 필요함","셀프 호스팅 서비스가 필요함","취득 및 해제 단계의 수동 구현이 필요함"],"es":["Requiere el lenguaje de programación Kotlin","Se necesita un servicio de alojamiento propio","Se requiere una implementación manual de los pasos de adquisición y liberación"],"fr":["Nécessite le langage de programmation Kotlin","Un service d''hébergement autonome est nécessaire","Une mise en œuvre manuelle des étapes d''acquisition et de libération est requise"],"de":["Erfordert die Programmiersprache Kotlin","Ein selbstgehosteter Dienst ist erforderlich","Eine manuelle Implementierung der Akquise- und Freigabeschritte ist erforderlich"],"pt":["Requer a linguagem de programação Kotlin","Necessário serviço hospedado","Requer implementação manual das etapas de aquisição e liberação"],"ru":["Требует языка программирования Kotlin","Требуется самохостящий сервис","Требуется ручная реализация шагов приобретения и освобождения"],"ar":["يتطلب لغة برمجة Kotlin","يتم الحاجة إلى خدمة ذاتية الاستضافة","يتطلب تنفيذ يدوي لخطوات الحصول والإطلاق"]},"version":4},"contentHash":"95d2230c912e181d9558b6c5fb9e4a4466eebc22949a615e4fb08ad5d95c8ad9","qualityScore":38}');
