INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('alexandru/social-publish/arrow-resource', 'arrow-resource', 'alexandru', 'social-publish', 'community', 'arrow-resource alexandru social-publish community arrow-resource is a self-hosted service that enables sharing to multiple social media platforms simultaneously, benefiting developers who need to manage complex social media workflows. Arrow Resource 是一个 Kotlin 库，提供了并行资源管理的功能，通过 `resourceScope` 和 `resource` 实现资源的定义和组合 Arrow Resource は Kotlin ライブラリで、並列リソース管理機能を提供します。`resourceScope` と `resource` を使用してリソースを定義して組み合わせます Arrow Resource는 Kotlin 라이브러리로서 병렬 리소스 관리 기능을 제공합니다. `resourceScope`와 `resource`를 사용하여 리소스를 정의하고 조합합니다 Arrow Resource es un servicio de alojamiento propio que permite compartir contenido en múltiples plataformas sociales al mismo tiempo con Kotlin. Arrow Resource est un service d''hébergement autonome qui permet de partager du contenu sur plusieurs plateformes sociales en même temps avec Kotlin. Arrow Resource ist ein selbst gehosteter Service, der es ermöglicht, Inhalte auf mehreren sozialen Plattformen gleichzeitig mit Kotlin zu teilen. O Arrow Resource é um serviço de autopublicação que permite compartilhar conteúdo em várias plataformas de mídia social ao mesmo tempo, utilizando Kotlin Arrow Resource - это само-хостинговый сервис, помогающий публиковать контент на нескольких социальных платформах одновременно, написанный на Kotlin Arrow Resource هو خدمة لنشر المحتوى على منصات متعددة، يستخدم Kotlin لتنفيذ هذه المهمة how to use arrow-resource what is arrow-resource arrow-resource alternative arrow-resource vs buffer arrow-resource install arrow-resource setup guide kotlin resource management social media sharing api parallel acquisition in kotlin Arrow Resource Kotlin 并行资源管理 资源定义和组合 并行资源管理 Kotlin 开发 AIエージェント 资源管理库 Uses `resourceScope { ... }` for lifecycle boundary management Defines resources with `resource { install(acquire) { a, exitCase -> release } }` Composes resources with `.bind()` for dependent acquisition Supports parallel acquisition using `parZip` Provides reusable constructors on `ResourceScope` for customized workflows Follows patterns and examples outlined in `references/resource.md` arrow-resource is a Kotlin-based service that helps share content across multiple social media platforms at once, using resourceScope and resource definitions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AndreaCadonna/serverless_function_runtime/code-quality', 'community', 'AndreaCadonna', 'serverless_function_runtime', 'AndreaCadonna/serverless_function_runtime', 'code-quality', 0, 0, 38, '2026-03-08T01:57:15.330Z', '2026-03-08T02:03:10.440Z', '99780de266bc7374930a433f0b9557627129a6f0a70b4d10f2228be04815a976', '{"id":"AndreaCadonna/serverless_function_runtime/code-quality","name":"code-quality","description":{"en":"Code-quality maintains consistent, spec-compliant code throughout serverless function runtime implementation, benefiting developers writing new source files or reviewing existing code.","zh":"代码质量是Serverless函数运行时实现的关键，使用现代JavaScript或TypeScript和Web标准的Request/Response合同","ja":"コード品質はServerless関数の実装において重要です。现代JavaScriptやTypeScriptとWeb標準のRequest/Response契約を使用しましょう","ko":"코드 품질은 Serverless 함수 런타임 구현에서 중요한 역할을 합니다. 최신 JavaScript 또는 TypeScript와 Web 표준의 Request/Response 계약을 사용하세요","es":"La habilidad de calidad de código mantiene la consistencia y el cumplimiento de especificaciones en el runtime de funciones serverless, utilizando Node.js con JavaScript moderno o TypeScript","fr":"La compétence de qualité de code maintient la cohérence et le respect des spécifications dans le runtime de fonctions serverless, en utilisant Node.js avec JavaScript moderne ou TypeScript","de":"Die Code-Qualitätsfunktion gewährleistet Konsistenz und Spezifikationskonformität im serverless-Funktionsruntime, mit Node.js und modernem JavaScript oder TypeScript","pt":"O skill Code-Quality ajuda a manter um código consistente e de alta qualidade para servidores sem estado, utilizando Node.js e JavaScript moderno","ru":"ИИ Агент Code-Quality помогает поддерживать качество кода для серверных приложений, используя Node.js и современный JavaScript","ar":"تساعد مهارة Code-Quality في الحفاظ على جودة عالية للرمز البرمجي لخوادم بدون حالة، باستخدام Node.js وJavaScript الحديث"},"seo":{"title":{"en":"Code-Quality: Setup Guide for Serverless Runtime | AI Age...","zh":"代码质量设置指南 - 优化Serverless函数运行时","ja":"コード品質ベストプラクティス - AIエージェントを使用したServerless関数の実装","ko":"코드 품질 최적화 가이드 - Serverless 함수 런타임 구현을 위한 AI 도구","es":"Guía de Configuración de Calidad de Código para Agentes d...","fr":"Guide de Configuration de la Qualité de Code pour les Out...","de":"Einrichtungsleitfaden für Code-Qualität in KI-Agents","pt":"Guia de Configuração de Code-Quality para Desenvolvedores","ru":"ИИ Агенты: Настройка Code-Quality для Разработчиков","ar":"دليل إعداد Code-Quality للبرمجة"},"description":{"en":"Discover how to implement code-quality for consistent, spec-compliant code in serverless functions. Learn more and get started with our expert guide.","zh":"了解代码质量的重要性和实现方法，优化Serverless函数运行时和API端点","ja":"コード品質を高めるためのベストプラクティスとAIエージェントの活用方法を紹介","ko":"코드 품질을 향상시키고 Serverless 함수 런타임을 최적화하는 방법을 알아보세요","es":"Aprenda a mantener un código consistente y cumplir con las especificaciones en su runtime de función serverless con la habilidad de calidad de código","fr":"Découvrez comment maintenir un code cohérent et respecter les spécifications dans votre runtime de fonction serverless avec la compétence de qualité de code","de":"Erfahren Sie, wie Sie konsistenten Code und spezifikationskonforme Implementierungen in Ihrem serverless-Funktionsruntime mit der Code-Qualitätsfunktion erre...","pt":"Aprenda a manter um código consistente e de alta qualidade com o skill Code-Quality, ideal para desenvolvedores de servidores sem estado","ru":"Получите информацию о том, как поддерживать качество кода с помощью ИИ Агента Code-Quality, предназначенного для разработчиков серверных приложений","ar":"تعرف على كيفية الحفاظ على جودة عالية للرمز البرمجي باستخدام مهارة Code-Quality المخصصة لمطوري الخوادم بدون حالة"},"definition":{"en":"Code-quality is a local serverless runtime that maps files to HTTP endpoints using a strict Web Request -> Response contract.","zh":"代码质量是指代码的可维护性、可扩展性和可靠性，使用代码质量工具可以提高代码的质量","ja":"コード品質とは、コードの保守性、拡張性、信頼性のことです。コード品質ツールを使用することでコードの品質を向上させることができます","ko":"코드 품질이란 코드의 유지 보수성, 확장성, 신뢰성을 의미하며, 코드 품질 도구를 사용하면 코드의 품질을 향상시킬 수 있습니다","es":"La calidad de código se refiere a la capacidad de mantener un código consistente y cumplir con las especificaciones en el desarrollo de software","fr":"La qualité de code fait référence à la capacité de maintenir un code cohérent et de respecter les spécifications dans le développement de logiciels","de":"Code-Qualität bezeichnet die Fähigkeit, konsistenten Code und spezifikationskonforme Implementierungen im Software-Entwicklungprozess zu gewährleisten","pt":"Code-Quality é uma habilidade que ajuda a manter um código consistente e de alta qualidade para servidores sem estado","ru":"Code-Quality - это навык, который помогает поддерживать качество кода для серверных приложений","ar":"Code-Quality هي مهارة تساعد في الحفاظ على جودة عالية للرمز البرمجي لخوادم بدون حالة"},"features":{"en":["Maps files in api/ to HTTP endpoints","Dispatches requests using a strict Web Request -> Response contract","Supports Node.js with modern JavaScript or TypeScript","Utilizes ES modules (import/export) for module management","Implements web-standard Request/Response for handler contract"],"zh":["使用现代JavaScript或TypeScript","支持Web标准的Request/Response合同","优化Serverless函数运行时","提高代码的可维护性和可扩展性","支持ES模块（import/export）","使用全局Request对象"],"ja":["现代JavaScriptやTypeScriptの使用","Web標準のRequest/Response契約のサポート","Serverless関数の実行時間の最適化","コードの保守性と拡張性の向上","ESモジュール（import/export）のサポート","グローバルRequestオブジェクトの使用"],"ko":["최신 JavaScript 또는 TypeScript 사용","Web 표준의 Request/Response 계약 지원","Serverless 함수 런타임 최적화","코드의 유지 보수성과 확장성 향상","ES 모듈（import/export）지원","전역 Request 객체 사용"],"es":["Uso de Node.js con JavaScript moderno o TypeScript","Implementación de módulos ES (import/export)","Contrato de solicitud / respuesta web estándar","Uso de la solicitud global y respuesta","Compatibilidad con la función serverless","Cumplimiento de las especificaciones de código"],"fr":["Utilisation de Node.js avec JavaScript moderne ou TypeScript","Implémentation de modules ES (import/export)","Contrat de requête / réponse web standard","Utilisation de la requête et de la réponse globales","Compatibilité avec la fonction serverless","Respect des spécifications de code"],"de":["Verwendung von Node.js mit modernem JavaScript oder TypeScript","Implementierung von ES-Modulen (import/export)","Standard-Webanfrage-/Antwortvertrag","Verwendung der globalen Anfrage und Antwort","Kompatibilität mit serverless-Funktionen","Einhaltung von Code-Spezifikationen"],"pt":["Utiliza Node.js com JavaScript moderno ou TypeScript","Segue o contrato de solicitação e resposta da Web","Utiliza módulos ES para importação e exportação","Segue as convenções de tempo de execução do Node.js","Utiliza o contrato de manipulador de solicitação e resposta"],"ru":["Использует Node.js с современным JavaScript или TypeScript","Следует контракту запроса и ответа веб-стандарта","Использует модули ES для импорта и экспорта","Следует конвенциям времени выполнения Node.js","Использует контракт обработчика запроса и ответа"],"ar":["استخدام Node.js مع JavaScript الحديث أو TypeScript","التزام بمعايير الويب لبروتوكول الطلب والاستجابة","استخدام الوحدات ES لأغراض الاستيراد والتصدير","التزام بمعايير تشغيل Node.js","استخدام بروتوكول معالج الطلب والاستجابة"]},"keywords":{"en":["how to use code-quality","code-quality setup guide","what is code-quality","code-quality alternative","code-quality vs serverless framework","code-quality install for Node.js"],"zh":["代码质量","Serverless函数运行时","现代JavaScript","TypeScript","Web标准","Request/Response合同","ES模块","代码优化","代码可维护性"],"ja":["コード品質","Serverless関数の実行時間","现代JavaScript","TypeScript","Web標準","Request/Response契約","ESモジュール","コード最適化","コードの保守性"],"ko":["코드 품질","Serverless 함수 런타임","최신 JavaScript","TypeScript","Web 표준","Request/Response 계약","ES 모듈","코드 최적화","코드의 유지 보수성"],"es":["calidad de código","desarrollo de software","Node.js","JavaScript moderno","TypeScript","módulos ES","contrato de solicitud / respuesta web","función serverless","cumplimiento de especificaciones"],"fr":["qualité de code","développement de logiciels","Node.js","JavaScript moderne","TypeScript","modules ES","contrat de requête / réponse web","fonction serverless","respect des spécifications"],"de":["Code-Qualität","Software-Entwicklung","Node.js","modernes JavaScript","TypeScript","ES-Module","Webanfrage-/Antwortvertrag","serverless-Funktionen","Einhaltung von Spezifikationen"],"pt":["code quality","desenvolvimento de servidores sem estado","Node.js","JavaScript moderno","TypeScript","ES modules","contrato de solicitação e resposta","desenvolvedores de servidores sem estado"],"ru":["качество кода","разработка серверных приложений","ИИ Агенты","Node.js","современный JavaScript","TypeScript","ES модули","контракт запроса и ответа","разработчики серверных приложений"],"ar":["جودة الرمز البرمجي","برمجة خوادم بدون حالة","ادوات الذكاء الاصطناعي","Node.js","JavaScript الحديث","TypeScript","وحدات ES","بروتوكول الطلب والاستجابة","مطورو خوادم بدون حالة"]}},"owner":"AndreaCadonna","repo":"serverless_function_runtime","repoPath":"AndreaCadonna/serverless_function_runtime","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.330Z","topics":[],"category":"community","skillMd":{"name":"code-quality","description":"Node.js code quality standards for the serverless function runtime. Use when writing, reviewing, or refactoring JavaScript/TypeScript code.","bodyPreview":"# Code Quality — Skill\n\n## Purpose\n\nMaintain consistent, spec-compliant code throughout the serverless function runtime implementation.\n\n## When to Use\n\n- Writing new source files\n- Reviewing or refactoring existing code\n- Making implementation decisions about structure or patterns\n\n## Language and Runtime Conventions\n\n1. **Node.js with modern JavaScript or TypeScript.** Use ES modules (`import`/`export`).\n2. **Web-standard `Request`/`Response`** for the handler contract. Use the global `Request","body":"# Code Quality — Skill\n\n## Purpose\n\nMaintain consistent, spec-compliant code throughout the serverless function runtime implementation.\n\n## When to Use\n\n- Writing new source files\n- Reviewing or refactoring existing code\n- Making implementation decisions about structure or patterns\n\n## Language and Runtime Conventions\n\n1. **Node.js with modern JavaScript or TypeScript.** Use ES modules (`import`/`export`).\n2. **Web-standard `Request`/`Response`** for the handler contract. Use the global `Request` and `Response` objects (Node.js 18+ built-in) or a minimal polyfill.\n3. **Minimal dependencies.** Do not add frameworks or libraries unless strictly required by the spec. Prefer Node.js built-ins.\n4. **No TypeScript compilation complexity.** If using TypeScript, keep the build step simple. Plain JavaScript is acceptable.\n\n## Code Structure Conventions\n\n1. **One module, one responsibility.** Each file should have a clear, single purpose.\n2. **Named exports for public API.** Default exports only for handler method functions.\n3. **Handler functions are named by HTTP method**: `export function GET(request) {}`, `export function POST(request) {}`.\n4. **No global mutable state** except where explicitly required by the spec (warm module reuse via module-level variables is allowed per REQ-RTG-006).\n\n## Error Handling Conventions\n\n1. **Runtime errors use the spec''s JSON format**: `{\"errorCode\": \"<CODE>\", \"message\": \"<detail>\"}`.\n2. **Error codes are exactly**: `ROUTE_NOT_FOUND`, `METHOD_NOT_ALLOWED`, `HANDLER_EXCEPTION`, `INVALID_HANDLER_RESPONSE`, `INVOCATION_TIMEOUT`.\n3. **HTTP status mapping is fixed**: 404, 405, 500, 500, 504 respectively.\n4. **Handler exceptions must be caught** and mapped to `HANDLER_EXCEPTION` with the original error message.\n5. **Timeout enforcement uses AbortController or equivalent** — do not rely on unref''d timers alone.\n\n## Testing Conventions\n\n1. **E2E tests run via `npm test`** (REQ-RCV-006).\n2. **Tests start the runtime, send HTTP requests, and assert responses.** No mocking of the runtime itself.\n3. **Each spec scenario (Section 6) maps to at least one test case.**\n4. **Test exit code 0 on success** (REQ-RCV-007).\n\n## Quality Checklist\n\n- [ ] All source files use ES modules\n- [ ] Handler contract uses Web-standard Request/Response\n- [ ] No unnecessary dependencies added\n- [ ] Error responses match spec JSON format exactly\n- [ ] Timeout enforcement is 3000ms per invocation\n- [ ] No debug prints or commented-out code in committed files\n- [ ] Each file has a single, clear responsibility\n"},"lastSynced":"2026-03-08T02:03:10.440Z","agentAnalysis":{"suitability":{"en":"Perfect for Serverless Agents needing consistent, spec-compliant code maintenance across Node.js and TypeScript implementations.","zh":"非常适合需要跨 Node.js 和 TypeScript 实现保持一致、符合规范代码维护的无服务器代理。","ja":"Node.js と TypeScript の実装にわたって、仕様に準拠したコードメンテナンスを一貫して行う必要があるサーバーレスエージェントに最適です。","ko":"Node.js와 TypeScript 구현 전반에 걸쳐 일관적이고 사양을 준수하는 코드 유지 관리가 필요한 Serverless Agent에 완벽합니다.","es":"Perfecto para agentes sin servidor que necesitan un mantenimiento de código coherente y conforme a las especificaciones en implementaciones de Node.js y TypeScript.","fr":"Parfait pour les agents sans serveur nécessitant une maintenance de code cohérente et conforme aux spécifications sur les implémentations Node.js et TypeScript.","de":"Perfekt für Serverless-Agents, die ein konsistentes, spezifikationskonformes Code-Maintenance über Node.js- und TypeScript-Implementierungen benötigen.","pt":"Perfeito para Agentes Serverless que necessitam de manutenção de código consistente e conforme ao padrão em implementações Node.js e TypeScript.","ru":"Идеально подходит для агентов Serverless, которым требуется постоянное поддержание кода в соответствии со стандартом в реализациях Node.js и TypeScript.","ar":"مثالي لعميل الخادم بدون خادم الذي يحتاج إلى صيانة شفرة متسقة ومتوافقة مع المواصفات عبر تنفيذات Node.js وTypeScript."},"recommendation":{"en":"Empowers agents to enforce ES module standards, utilize web-standard Request/Response handlers, and maintain consistent code quality throughout serverless function runtime implementations using modern JavaScript or TypeScript.","zh":"使代理能够强制执行 ES 模块标准，利用 Web 标准的 Request/Response 处理程序，并在使用现代 JavaScript 或 TypeScript 的无服务器函数运行时实现中保持一致的代码质量。","ja":"エージェントが ES モジュール標準を強制し、Web 標準の Request/Response ハンドラーを利用し、現代的な JavaScript または TypeScript を使用したサーバーレス関数ランタイム実装全体で一貫したコード品質を維持することを可能にします。","ko":"에이전트가 ES 모듈 표준을 적용하고, 웹 표준 Request/Response 핸들러를 활용하며, 현대적인 JavaScript 또는 TypeScript를 사용하는 서버리스 함수 런타임 구현 전반에 걸쳐 일관된 코드 품질을 유지할 수 있도록 합니다.","es":"Habilita a los agentes a aplicar los estándares de módulos ES, utilizar controladores de solicitudes y respuestas de estándares web y mantener una calidad de código coherente en todo el tiempo de ejecución de funciones sin servidor utilizando JavaScript moderno o TypeScript.","fr":"Permet aux agents d''appliquer les normes de modules ES, d''utiliser des gestionnaires de requêtes/réponses de normes web et de maintenir une qualité de code cohérente dans toutes les implémentations de runtime de fonctions sans serveur en utilisant JavaScript moderne ou TypeScript.","de":"Ermächtigt Agenten, ES-Modul-Standards durchzusetzen, webstandardmäßige Request-/Response-Handler zu nutzen und eine konsistente Code-Qualität während der gesamten Laufzeit von serverlosen Funktionen mit modernem JavaScript oder TypeScript beizubehalten.","pt":"Habilita os agentes a impor padrões de módulo ES, utilizar manipuladores de solicitação/resposta de padrão da web e manter a qualidade do código consistente em todo o tempo de execução das funções sem servidor usando JavaScript moderno ou TypeScript.","ru":"Предоставляет агентам возможность устанавливать стандарты модулей ES, использовать обработчики запросов/ответов веб-стандарта и поддерживать постоянное качество кода на протяжении всего времени выполнения функций без сервера с использованием современного JavaScript или TypeScript.","ar":"يمنح الوكلاء القدرة على فرض معايير موديل ES، واستخدام معالجات الطلب/الاستجابة لمعيار الويب، والحفاظ على جودة الشفرة المتسقة في جميع أنحاء وقت تشغيل الدوال بدون خادم باستخدام جافاسكريبت الحديثة أو TypeScript."},"useCases":{"en":["Writing new source files with compliant code structure","Reviewing existing code for spec compliance and refactoring","Making informed implementation decisions about code structure and patterns"],"zh":["使用合规的代码结构编写新的源文件","审查现有代码是否符合规范并进行重构","就代码结构和模式做出明智的实现决策"],"ja":["準拠したコード構造で新しいソースファイルを記述する","仕様準拠のための既存コードのレビューとリファクタリング","コード構造とパターンに関する情報に基づいた実装決定を行う"],"ko":["준수하는 코드 구조로 새로운 소스 파일 작성","사양 준수를 위한 기존 코드 검토 및 리팩토링","코드 구조와 패턴에 관한 정보에 기반한 구현 결정 내리기"],"es":["Escribir nuevos archivos fuente con estructura de código conforme","Revisar el código existente para la conformidad con las especificaciones y refactorizar","Tomar decisiones informadas sobre la estructura y los patrones de código"],"fr":["Écrire de nouveaux fichiers source avec une structure de code conforme","Réviser le code existant pour la conformité aux spécifications et refactoriser","Prendre des décisions éclairées concernant la structure et les modèles de code"],"de":["Neue Quelldateien mit konformer Code-Struktur schreiben","Bestehenden Code auf Spezifikationskonformität überprüfen und refaktorisieren","Informierte Entscheidungen über Code-Struktur und -Muster treffen"],"pt":["Escrever novos arquivos de origem com estrutura de código conforme o padrão","Revisar o código existente para conformidade com o padrão e reestruturá-lo","Tomar decisões informadas sobre a estrutura e os padrões de código"],"ru":["Создание новых исходных файлов со структурой кода, соответствующей стандарту","Проверка существующего кода на соответствие стандарту и его рефакторинг","Принятие обоснованных решений о структуре и шаблонах кода"],"ar":["كتابة ملفات مصدر جديدة ذات هيكل شفرة متوافق مع المعايير","مراجعة الشفرة الحالية للامتثال للمعايير وإعادة هيكلتها","اتخاذ قرارات مستنيرة بشأن هيكل الشفرة وأنماطها"]},"limitations":{"en":["Requires Node.js environment with modern JavaScript or TypeScript support","Limited to serverless function runtime implementations"],"zh":["需要支持现代 JavaScript 或 TypeScript 的 Node.js 环境","仅限于无服务器函数运行时实现"],"ja":["現代的な JavaScript または TypeScript をサポートする Node.js 環境が必要","サーバーレス関数ランタイムの実装に限定される"],"ko":["현대적인 JavaScript 또는 TypeScript를 지원하는 Node.js 환경 필요","서버리스 함수 런타임 구현으로만 제한됨"],"es":["Requiere un entorno Node.js con soporte para JavaScript moderno o TypeScript","Limitado a implementaciones de tiempo de ejecución de funciones sin servidor"],"fr":["Nécessite un environnement Node.js avec un support pour JavaScript moderne ou TypeScript","Limité aux implémentations de runtime de fonctions sans serveur"],"de":["Benötigt eine Node.js-Umgebung mit Unterstützung für modernes JavaScript oder TypeScript","Begrenzt auf Implementierungen von serverlosen Funktionen-Lauffzeiten"],"pt":["Requer ambiente Node.js com suporte a JavaScript moderno ou TypeScript","Limitado a implementações de tempo de execução de funções sem servidor"],"ru":["Требуется среда Node.js с поддержкой современного JavaScript или TypeScript","Ограничен реализациями времени выполнения функций без сервера"],"ar":["يتطلب بيئة Node.js بدعم لجافاسكريبت الحديثة أو TypeScript","محدود بتطبيقات وقت تشغيل الدوال بدون خادم"]},"version":4},"contentHash":"99780de266bc7374930a433f0b9557627129a6f0a70b4d10f2228be04815a976","qualityScore":38}');
