INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AndreaCadonna/serverless_function_runtime/code-quality', 'code-quality', 'AndreaCadonna', 'serverless_function_runtime', 'community', 'code-quality AndreaCadonna serverless_function_runtime community Code-quality maintains consistent, spec-compliant code throughout serverless function runtime implementation, benefiting developers writing new source files or reviewing existing code. 代码质量是Serverless函数运行时实现的关键，使用现代JavaScript或TypeScript和Web标准的Request/Response合同 コード品質はServerless関数の実装において重要です。现代JavaScriptやTypeScriptとWeb標準のRequest/Response契約を使用しましょう 코드 품질은 Serverless 함수 런타임 구현에서 중요한 역할을 합니다. 최신 JavaScript 또는 TypeScript와 Web 표준의 Request/Response 계약을 사용하세요 La habilidad de calidad de código mantiene la consistencia y el cumplimiento de especificaciones en el runtime de funciones serverless, utilizando Node.js con JavaScript moderno o TypeScript La compétence de qualité de code maintient la cohérence et le respect des spécifications dans le runtime de fonctions serverless, en utilisant Node.js avec JavaScript moderne ou TypeScript Die Code-Qualitätsfunktion gewährleistet Konsistenz und Spezifikationskonformität im serverless-Funktionsruntime, mit Node.js und modernem JavaScript oder TypeScript O skill Code-Quality ajuda a manter um código consistente e de alta qualidade para servidores sem estado, utilizando Node.js e JavaScript moderno ИИ Агент Code-Quality помогает поддерживать качество кода для серверных приложений, используя Node.js и современный JavaScript تساعد مهارة Code-Quality في الحفاظ على جودة عالية للرمز البرمجي لخوادم بدون حالة، باستخدام Node.js وJavaScript الحديث how to use code-quality code-quality setup guide what is code-quality code-quality alternative code-quality vs serverless framework code-quality install for Node.js 代码质量 Serverless函数运行时 现代JavaScript TypeScript Web标准 Request/Response合同 ES模块 代码优化 代码可维护性 Maps files in api/ to HTTP endpoints Dispatches requests using a strict Web Request -> Response contract Supports Node.js with modern JavaScript or TypeScript Utilizes ES modules (import/export) for module management Implements web-standard Request/Response for handler contract Code-quality is a local serverless runtime that maps files to HTTP endpoints using a strict Web Request -> Response contract.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zerx-lab/zTerm/generate-component-story', 'community', 'zerx-lab', 'zTerm', 'zerx-lab/zTerm', 'generate-component-story', 0, 0, 38, '2026-03-08T01:57:15.304Z', '2026-03-08T02:03:19.574Z', 'e2f3b32391855612eb6c3f58671f0a539f5568ed0af9283e9d03bcef88a9d7aa', '{"id":"zerx-lab/zTerm/generate-component-story","name":"generate-component-story","description":{"en":"The generate-component-story skill helps developers create comprehensive component stories by following existing patterns and using sections. It benefits developers who need to document and demonstrate component usage.","zh":"生成组件故事是一种高效的终端体验，通过遵循现有的模式和使用sections来组织故事","ja":"コンポーネントストーリー生成は、パターンに従い、セクションを使用してストーリーを組織することで実現されます","ko":"컴포넌트 스토리 생성은 기존 패턴을 따르고 section을 사용하여 스토리를 구성하는 것을 의미합니다","es":"generate-component-story es una habilidad para crear historias de componentes siguiendo patrones existentes y utilizando secciones para una cobertura integral","fr":"generate-component-story est une compétence pour créer des histoires de composants en suivant des modèles existants et en utilisant des sections pour une couverture complète","de":"generate-component-story ist eine Fähigkeit, um Komponenten-Geschichten zu erstellen, indem bestehende Muster befolgt und Abschnitte für eine umfassende Abdeckung verwendet werden","pt":"O generate-component-story é uma ferramenta para criar histórias de componentes, seguindo padrões existentes e incluindo todas as opções e variantes","ru":"ИИ Агент generate-component-story предназначен для создания историй компонентов, основанных на существующих шаблонах и включающих все опции и варианты","ar":"أداة generate-component-story هي أداة لإنشاء قصص المكونات، تتبع الأنماط الحالية وتشمل جميع خيارات ومتغيرات المكونات"},"seo":{"title":{"en":"generate-component-story: Best Practices for AI Agents | ...","zh":"生成组件故事的最佳实践","ja":"コンポーネントストーリー生成のセットアップガイド - AIエージェント","ko":"컴포넌트 스토리 생성을 위한 개발자 가이드","es":"Guía de configuración para generate-component-story","fr":"Meilleures pratiques pour generate-component-story","de":"Einrichtungsleitfaden für generate-component-story","pt":"Guia de Configuração do generate-component-story para Des...","ru":"Настройка ИИ Агентов: generate-component-story для Разраб...","ar":"دليل إعداد generate-component-story لأدوات الذكاء الاصطنا..."},"description":{"en":"Discover how to create efficient component stories with generate-component-story. Learn how to follow existing patterns, use sections, and achieve comprehens...","zh":"了解如何创建高效的组件故事，并发现生成组件故事的技巧和最佳实践","ja":"コンポーネントストーリー生成のために、パターンに従い、セクションを使用し、包括的なカバレッジを実現する方法を学びます - AIエージェント","ko":"컴포넌트 스토리를 생성하는 방법에 대한 가이드와 컴포넌트 개발의 최선의 방법을 확인하세요","es":"Aprende a crear historias de componentes con generate-component-story y mejora tus habilidades de desarrollo","fr":"Découvrez comment utiliser generate-component-story pour créer des histoires de composants et améliorer vos compétences de développement","de":"Erfahren Sie, wie Sie mit generate-component-story Komponenten-Geschichten erstellen und Ihre Entwicklungsfähigkeiten verbessern","pt":"Aprenda a criar histórias de componentes com o generate-component-story, incluindo padrões existentes e cobertura abrangente de opções e variantes","ru":"Изучите, как создавать истории компонентов с помощью generate-component-story, включая существующие шаблоны и полное покрытие опций и вариантов","ar":"تعلم كيفية إنشاء قصص المكونات باستخدام generate-component-story، بما في ذلك الأنماط الحالية والتغطية الشاملة لخيارات ومتغيرات المكونات"},"definition":{"en":"generate-component-story is a skill that enables developers to create detailed stories for components, including basic usage examples, different variants, and states.","zh":"生成组件故事是一种创建组件的方法，通过遵循现有的模式和使用sections来组织故事","ja":"コンポーネントストーリー生成とは、パターンに従い、セクションを使用してストーリーを組織することでコンポーネントを作成する方法です","ko":"컴포넌트 스토리 생성은 컴포넌트를 생성하는 방법으로 기존 패턴을 따르고 section을 사용하여 스토리를 구성합니다","es":"generate-component-story es una herramienta de desarrollo que permite crear historias de componentes para una mejor documentación y reutilización","fr":"generate-component-story est un outil de développement qui permet de créer des histoires de composants pour une meilleure documentation et réutilisation","de":"generate-component-story ist ein Entwicklungstool, das die Erstellung von Komponenten-Geschichten für eine bessere Dokumentation und Wiederverwendung ermöglicht","pt":"O generate-component-story é uma ferramenta de desenvolvimento que cria histórias de componentes","ru":"ИИ Агент generate-component-story - это инструмент для разработчиков, создающий истории компонентов","ar":"أداة generate-component-story هي أداة تطوير لإنشاء قصص المكونات"},"features":{"en":["Follows existing patterns found in crates/story/src/stories","Organizes stories with section! calls for each major part","Includes comprehensive coverage of all options, variants, and usage examples","Supports creation of basic usage examples and different variants","Enables interactive storytelling with comprehensive coverage"],"zh":["遵循现有的模式","使用sections来组织故事","包括所有选项、变体和使用示例","支持基本使用示例","支持不同变体和状态","支持交互式示例"],"ja":["パターンに従う","セクションを使用してストーリーを組織する","すべてのオプション、バリアント、使用例を含む","基本的な使用例をサポートする","異なるバリアントと状態をサポートする","インタラクティブな例をサポートする"],"ko":["기존 패턴을 따르기","section을 사용하여 스토리를 구성하기","모든 옵션, 변형, 사용 예를 포함하기","기본 사용 예를 지원하기","다른 변형과 상태를 지원하기","인터랙티브한 예를 지원하기"],"es":["Seguir patrones existentes en crates/story/src/stories","Utilizar secciones con llamadas a section! para cada parte principal","Cobertura integral de todas las opciones, variantes y ejemplos de uso del componente","Incluir ejemplos de uso básico, variantes y estados diferentes","Crear historias interactivas para una mejor experiencia del usuario"],"fr":["Suivre des modèles existants dans crates/story/src/stories","Utiliser des sections avec des appels à section! pour chaque partie principale","Couverture complète de toutes les options, variantes et exemples d''utilisation du composant","Inclure des exemples d''utilisation de base, des variantes et des états différents","Créer des histoires interactives pour une meilleure expérience utilisateur"],"de":["Bestehende Muster in crates/story/src/stories befolgen","Abschnitte mit Aufrufen von section! für jeden Hauptteil verwenden","Umfassende Abdeckung aller Optionen, Varianten und Verwendungsexamples des Komponenten","Beispiele für die grundlegende Verwendung, Varianten und verschiedene Zustände einschließen","Interaktive Geschichten erstellen, um eine bessere Benutzererfahrung zu ermöglichen"],"pt":["Segue padrões existentes em crates/story/src/stories","Organiza a história com seções utilizando section!","Cobertura abrangente de opções e variantes de componentes","Inclui exemplos básicos de uso e diferentes variantes e estados","Permite interação com o componente"],"ru":["Следует существующим шаблонам в crates/story/src/stories","Организует историю с помощью секций, используя section!","Полное покрытие опций и вариантов компонентов","Включает базовые примеры использования и разные варианты и состояния","Позволяет взаимодействовать с компонентом"],"ar":["يتبع الأنماط الحالية في crates/story/src/stories","ينظم القصة مع أقسام باستخدام section!","التغطية الشاملة لخيارات ومتغيرات المكونات","يشمل الأمثلة الأساسية للاستخدام والمتغيرات المختلفة والحالات","يمكّن التفاعل مع المكون"]},"keywords":{"en":["how to use generate-component-story","generate-component-story setup guide","what is generate-component-story","generate-component-story alternative","generate-component-story vs storybook","generate-component-story install","create component stories with section!","comprehensive component story coverage"],"zh":["生成组件故事","组件开发","终端体验","AI工具","组件故事生成","开发者指南","技术文档"],"ja":["コンポーネントストーリー生成","コンポーネント開発","ターミナル体験","AIエージェント","コンポーネントストーリー","開発者ガイド","テクニカルドキュメント"],"ko":["컴포넌트 스토리 생성","컴포넌트 개발","터미널 경험","AI도구","컴포넌트 스토리","개발자 가이드","техническая документация"],"es":["generate-component-story","desarrollo de componentes","historias de componentes","patrones de diseño","secciones en componentes","cobertura integral de componentes","ejemplos de uso de componentes","herramientas de desarrollo de AI","agentes de AI para desarrollo"],"fr":["generate-component-story","développement de composants","histoires de composants","modèles de conception","sections dans les composants","couverture complète des composants","exemples d''utilisation des composants","outils de développement d''IA","agents d''IA pour le développement"],"de":["generate-component-story","Komponenten-Entwicklung","Komponenten-Geschichten","Entwurfsmuster","Abschnitte in Komponenten","umfassende Abdeckung von Komponenten","Verwendungsexamples von Komponenten","Entwicklungstools von KI","KI-Agents für die Entwicklung"],"pt":["generate-component-story","criar histórias de componentes","padrões existentes","cobertura abrangente","opções e variantes de componentes","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["generate-component-story","создание историй компонентов","существующие шаблоны","полное покрытие","опции и варианты компонентов","разработка программного обеспечения","инструменты для разработчиков"],"ar":["generate-component-story","إنشاء قصص المكونات","الأنماط الحالية","التغطية الشاملة","خيارات ومتغيرات المكونات","تطوير البرمجيات","أدوات المطورين"]}},"owner":"zerx-lab","repo":"zTerm","repoPath":"zerx-lab/zTerm","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.304Z","topics":[],"category":"community","skillMd":{"name":"generate-component-story","description":"Create story examples for components. Use when writing stories, creating examples, or demonstrating component usage.","bodyPreview":"## Instructions\n\nWhen creating component stories:\n\n1. **Follow existing patterns**: Base stories on the styles found in `crates/story/src/stories` (examples: `tabs_story.rs`, `group_box_story.rs`, etc.)\n2. **Use sections**: Organize the story with `section!` calls for each major part\n3. **Comprehensive coverage**: Include all options, variants, and usage examples of the component\n\n## Examples\n\nA typical story structure includes:\n- Basic usage examples\n- Different variants and states\n- Interactiv","body":"## Instructions\n\nWhen creating component stories:\n\n1. **Follow existing patterns**: Base stories on the styles found in `crates/story/src/stories` (examples: `tabs_story.rs`, `group_box_story.rs`, etc.)\n2. **Use sections**: Organize the story with `section!` calls for each major part\n3. **Comprehensive coverage**: Include all options, variants, and usage examples of the component\n\n## Examples\n\nA typical story structure includes:\n- Basic usage examples\n- Different variants and states\n- Interactive examples\n- Edge cases and error states\n"},"lastSynced":"2026-03-08T02:03:19.574Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing comprehensive component documentation and demonstration capabilities.","zh":"适用于需要全面组件文档和演示功能的前端代理。","ja":"フロントエンドエージェントが包括的なコンポーネントのドキュメントとデモ機能を必要とする場合に適しています。","ko":"전면 에이전트가 포괄적인 구성 요소 문서 및 데모 기능을 필요로 하는 경우 완벽합니다.","es":"Perfecto para agentes Frontend que necesitan documentación de componentes completa y capacidades de demostración.","fr":"Parfait pour les agents Frontend ayant besoin d''une documentation de composants complète et de capacités de démonstration.","de":"Perfekt für Frontend-Agenten, die umfassende Komponentendokumentation und Demonstrationsmöglichkeiten benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de documentação de componentes abrangente e capacidades de demonstração.","ru":"Идеально для агентов Frontend, которым необходима всесторонняя документация компонентов и возможности демонстрации.","ar":"مثالي لعميل واجهة المستخدم الذين يحتاجون إلى توثيق شامل للمكونات وقدرات العرض."},"recommendation":{"en":"Empowers agents to generate detailed component stories using existing patterns and sections, providing comprehensive coverage of all options, variants, and usage examples, while utilizing `section!` calls and following styles from `crates/story/src/stories`.","zh":"赋予代理生成详细组件故事的能力，使用现有的模式和部分，提供对所有选项、变体和用法示例的全面覆盖，同时利用 `section!` 调用并遵循 `crates/story/src/stories` 中的样式。","ja":"エージェントに、既存のパターンとセクションを使用して詳細なコンポーネントのストーリーを生成する能力を付与し、すべてのオプション、バリアント、および使用例の包括的なカバーを提供し、同時に `section!` 呼び出しを利用し、`crates/story/src/stories` のスタイルに従います。","ko":"에이전트가 기존 패턴 및 섹션을 사용하여 세부 구성 요소 이야기를 생성할 수 있도록 하는 동시에 모든 옵션, 변형 및 사용 예의 철저한 범위를 제공하며 `section!` 호출을 활용하고 `crates/story/src/stories`의 스타일을 따릅니다.","es":"Permite a los agentes generar historias de componentes detalladas utilizando patrones y secciones existentes, proporcionando una cobertura completa de todas las opciones, variantes y ejemplos de uso, mientras utiliza llamadas `section!` y sigue estilos de `crates/story/src/stories`.","fr":"Permet aux agents de générer des histoires de composants détaillées en utilisant des modèles et des sections existants, offrant une couverture complète de toutes les options, variantes et exemples d''utilisation, tout en utilisant des appels `section!` et en suivant les styles de `crates/story/src/stories`.","de":"Ermöglicht es Agenten, detaillierte Komponentengeschichten unter Verwendung bestehender Muster und Abschnitte zu generieren, wodurch eine umfassende Abdeckung aller Optionen, Varianten und Nutzungbeispiele bereitgestellt wird, während `section!`-Aufrufe verwendet und Stile von `crates/story/src/stories` befolgt werden.","pt":"Habilita os agentes a gerar histórias de componentes detalhadas usando padrões e seções existentes, fornecendo cobertura abrangente de todas as opções, variantes e exemplos de uso, ao mesmo tempo em que utilizam chamadas `section!` e seguem estilos de `crates/story/src/stories`.","ru":"Позволяет агентам генерировать подробные истории компонентов, используя существующие шаблоны и разделы, обеспечивая всестороннее покрытие всех опций, вариантов и примеров использования, а также используя вызовы `section!` и следуя стилям из `crates/story/src/stories`.","ar":"تمكّن الوكيل من توليد قصص مفصلة للمكونات باستخدام الأنماط والفقرات الحالية، وتوفير تغطية شاملة لجميع الخيارات والمرادفات وأمثلة الاستخدام، مع استخدام呼 `section!` ومتابعة الأساليب من `crates/story/src/stories`."},"useCases":{"en":["Automating component documentation with basic usage examples and different variants","Generating interactive stories for component demonstration","Creating comprehensive coverage of component options and states"],"zh":["使用基本用法示例和不同变体自动化组件文档","生成交互式故事用于组件演示","创建组件选项和状态的全面覆盖"],"ja":["基本的な使用方法の例とさまざまなバリアントを使用してコンポーネントのドキュメントを自動化する","コンポーネントのデモのためにインタラクティブなストーリーを生成する","コンポーネントのオプションと状態の包括的なカバーを作成する"],"ko":["기본 사용법 예제 및 다양한 변형으로 구성 요소 문서를 자동화하는 것","구성 요소 데모를 위한 상호 작용 스토리 생성","구성 요소 옵션 및 상태에 대한 포괄적인 범위를 만드는 것"],"es":["Automatizar la documentación de componentes con ejemplos de uso básico y diferentes variantes","Generar historias interactivas para la demostración de componentes","Crear una cobertura completa de las opciones y estados de los componentes"],"fr":["Automatiser la documentation de composants avec des exemples d''utilisation de base et différentes variantes","Générer des histoires interactives pour la démonstration de composants","Créer une couverture complète des options et états des composants"],"de":["Automatisierung der Komponentendokumentation mit grundlegenden Nutzungbeispielen und verschiedenen Varianten","Generierung interaktiver Geschichten für die Demonstration von Komponenten","Erstellung einer umfassenden Abdeckung der Komponentenoptionen und -zustände"],"pt":["Automatizar a documentação de componentes com exemplos básicos de uso e variantes diferentes","Gerar histórias interativas para demonstração de componentes","Criar cobertura abrangente das opções e estados de componentes"],"ru":["Автоматизация документации компонентов с базовыми примерами использования и различными вариантами","Генерация интерактивных историй для демонстрации компонентов","Создание всестороннего покрытия опций и состояний компонентов"],"ar":["توسيع توثيق المكونات مع أمثلة أساسية للاستخدام والمرادفات المختلفة","توليد قصص تفاعلية لعرض المكونات","إنشاء تغطية شاملة للخيارات والحالات للمكونات"]},"limitations":{"en":["Requires access to `crates/story/src/stories` for pattern reference","Limited to component story generation, not general-purpose documentation"],"zh":["需要访问 `crates/story/src/stories` 以获取模式引用","仅限于组件故事生成，不是通用文档"],"ja":["パターン参照のために `crates/story/src/stories` へのアクセスが必要","コンポーネントストーリーの生成に限定され、一般的なドキュメントではありません"],"ko":["패턴 참조를 위해 `crates/story/src/stories`에 액세스해야 함","구성 요소 스토리 생성에만 제한되어おり, 일반적인 문서에는 해당되지 않음"],"es":["Requiere acceso a `crates/story/src/stories` para referencia de patrones","Limitado a la generación de historias de componentes, no a documentación de propósito general"],"fr":["Nécessite un accès à `crates/story/src/stories` pour référence de modèles","Limité à la génération d''histoires de composants, et non à la documentation à usage général"],"de":["Erfordert Zugriff auf `crates/story/src/stories` für Musterreferenz","Begrenzt auf die Generierung von Komponentengeschichten, nicht auf allgemeine Dokumentation"],"pt":["Requer acesso a `crates/story/src/stories` para referência de padrão","Limitado à geração de histórias de componentes, não documentação de propósito geral"],"ru":["Требует доступа к `crates/story/src/stories` для справки по шаблонам","Ограничен генерацией историй компонентов, не общей документацией"],"ar":["يتطلب الوصول إلى `crates/story/src/stories` لمرجع الأنماط","محدود بتوليد قصص المكونات، وليس توثيق عام"]},"version":4},"contentHash":"e2f3b32391855612eb6c3f58671f0a539f5568ed0af9283e9d03bcef88a9d7aa","qualityScore":38}');
