INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zerx-lab/zTerm/generate-component-story', 'generate-component-story', 'zerx-lab', 'zTerm', 'community', 'generate-component-story zerx-lab zTerm community The generate-component-story skill helps developers create comprehensive component stories by following existing patterns and using sections. It benefits developers who need to document and demonstrate component usage. 生成组件故事是一种高效的终端体验，通过遵循现有的模式和使用sections来组织故事 コンポーネントストーリー生成は、パターンに従い、セクションを使用してストーリーを組織することで実現されます 컴포넌트 스토리 생성은 기존 패턴을 따르고 section을 사용하여 스토리를 구성하는 것을 의미합니다 generate-component-story es una habilidad para crear historias de componentes siguiendo patrones existentes y utilizando secciones para una cobertura integral generate-component-story est une compétence pour créer des histoires de composants en suivant des modèles existants et en utilisant des sections pour une couverture complète generate-component-story ist eine Fähigkeit, um Komponenten-Geschichten zu erstellen, indem bestehende Muster befolgt und Abschnitte für eine umfassende Abdeckung verwendet werden O generate-component-story é uma ferramenta para criar histórias de componentes, seguindo padrões existentes e incluindo todas as opções e variantes ИИ Агент generate-component-story предназначен для создания историй компонентов, основанных на существующих шаблонах и включающих все опции и варианты أداة generate-component-story هي أداة لإنشاء قصص المكونات، تتبع الأنماط الحالية وتشمل جميع خيارات ومتغيرات المكونات how to use generate-component-story generate-component-story setup guide what is generate-component-story generate-component-story alternative generate-component-story vs storybook generate-component-story install create component stories with section! comprehensive component story coverage 生成组件故事 组件开发 终端体验 AI工具 组件故事生成 开发者指南 技术文档 Follows existing patterns found in crates/story/src/stories Organizes stories with section! calls for each major part Includes comprehensive coverage of all options, variants, and usage examples Supports creation of basic usage examples and different variants Enables interactive storytelling with comprehensive coverage generate-component-story is a skill that enables developers to create detailed stories for components, including basic usage examples, different variants, and states.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Chai-Un/wedding/extract-errors', 'community', 'Chai-Un', 'wedding', 'Chai-Un/wedding', 'extract-errors', 0, 0, 38, '2026-03-08T01:57:15.340Z', '2026-03-08T02:03:26.235Z', '70d61d42e5b5806e1eeb0ef2380b2f3d4d87237e848128e7da35929f78813e5f', '{"id":"Chai-Un/wedding/extract-errors","name":"extract-errors","description":{"en":"The extract-errors skill automates error code extraction, benefiting developers by streamlining error reporting. It checks for new errors and ensures error codes are up to date.","zh":"Extract Errors是一个用于提取和管理错误代码的工具，通过运行Yarn命令即可使用","ja":"エラーコード抽出ツールは、Yarnコマンドを実行することでエラーコードを抽出し、管理することができます","ko":"Extract Errors는 Yarn 명령을 실행하여 오류 코드를 추출하고 관리하는 도구입니다","es":"La habilidad de extracción de errores permite ejecutar yarn extract-errors para reportar nuevos errores y verificar la actualización de los códigos de error","fr":"L''outil d''extraction d''erreurs permet d''exécuter yarn extract-errors pour signaler de nouvelles erreurs et vérifier la mise à jour des codes d''erreur","de":"Die Fähigkeit zur Fehlerextraktion ermöglicht die Ausführung von yarn extract-errors, um neue Fehler zu melden und die Aktualisierung der Fehlercodes zu überprüfen","pt":"O extract-errors é uma ferramenta que ajuda a extrair códigos de erro e manter atualizados com facilidade. Execute `yarn extract-errors` para começar.","ru":"Extract-errors - это инструмент, который помогает извлекать коды ошибок и поддерживать их в актуальном состоянии. Запустите `yarn extract-errors`, чтобы начать.","ar":"extract-errors هو أداة تساعد في استخراج رموز الأخطاء والحفاظ عليها محدثة بسهولة. تشغيل `yarn extract-errors` لبدء العمل."},"seo":{"title":{"en":"extract-errors: Automated Error Code Extraction Setup Gui...","zh":"Extract Errors Setup Guide: 使用Yarn提取错误代码","ja":"エラーコード抽出ツール: AIエージェントによるextract-errors","ko":"extract-errors 설정 가이드: Yarn을 사용한 오류 코드 추출","es":"Herramientas de extracción de errores: Guía de configuración","fr":"Outil d''extraction d''erreurs: Meilleures pratiques","de":"Fehlerextraktions-Tool: Einrichtungsanleitung","pt":"Guia de Configuração do Extract-Errors: Ferramentas de IA...","ru":"ИИ Агенты: Руководство по Настройке Extract-Errors для Ра...","ar":"دليل إعداد extract-errors: أدوات الذكاء الاصطناعي للمطورين"},"description":{"en":"Discover how to automate error code extraction with extract-errors. Learn how to run yarn extract-errors and optimize your workflow today!","zh":"学习如何使用Yarn运行extract-errors命令，报告新错误并保持错误代码更新","ja":"AIエージェントのextract-errorsを使用してエラーコードを抽出し、最新の状態を保持する方法を学ぶ","ko":"Yarn을 사용하여 extract-errors 명령을 실행하고 새로운 오류를 보고 오류 코드를 최신 상태로 유지하는 방법을 배우세요","es":"Aprende a utilizar la habilidad de extracción de errores con yarn extract-errors y mejora la gestión de errores en tu proyecto","fr":"Découvrez comment utiliser l''outil d''extraction d''erreurs avec yarn extract-errors pour améliorer la gestion des erreurs","de":"Erfahren Sie, wie Sie die Fähigkeit zur Fehlerextraktion mit yarn extract-errors verwenden und die Fehlerverwaltung in Ihrem Projekt verbessern","pt":"Aprenda a configurar o extract-errors para melhorar a eficiência do seu desenvolvimento com ferramentas de IA","ru":"Узнайте, как настроить extract-errors для повышения эффективности разработки с помощью ИИ Агентов","ar":"تعلم كيفية إعداد extract-errors لتحسين كفاءة تطويرك مع أدوات الذكاء الاصطناعي"},"definition":{"en":"extract-errors is a skill that automates the extraction of error codes, utilizing commands like yarn extract-errors to report and update error codes efficiently.","zh":"Extract Errors是一种自动化工具，用于提取和管理错误代码","ja":"エラーコード抽出ツールは、エラーコードを自動的に抽出し、管理するためのツールです","ko":"Extract Errors는 오류 코드를 자동으로 추출하고 관리하기 위한 도구입니다","es":"La extracción de errores es una habilidad que utiliza yarn extract-errors para identificar y reportar errores en proyectos de desarrollo","fr":"L''extraction d''erreurs est un outil qui utilise yarn extract-errors pour identifier et signaler des erreurs dans les projets de développement","de":"Die Fehlerextraktion ist eine Fähigkeit, die yarn extract-errors verwendet, um Fehler in Entwicklungsprojekten zu identifizieren und zu melden","pt":"O que é extract-errors? É uma ferramenta de linha de comando que extrai códigos de erro e os mantém organizados.","ru":"Что такое extract-errors? Это команда CLI, которая извлекает коды ошибок и поддерживает их в порядке.","ar":"ما هو extract-errors؟ هو أداة سطر الأوامر التي تستخرج رموز الأخطاء وتحافظ عليها منظمّة."},"features":{"en":["Runs yarn extract-errors command to extract error codes","Reports new errors that require code assignment","Checks if error codes are up to date for optimal error handling","Utilizes Yarn package manager for efficient dependency management","Streamlines error reporting and code assignment process"],"zh":["使用Yarn运行extract-errors命令","报告新错误并分配错误代码","检查错误代码是否最新","自动化错误代码管理","提高代码质量和可靠性"],"ja":["Yarnコマンドを使用してエラーコードを抽出","新しいエラーを報告し、エラーコードを割り当て","エラーコードが最新かどうかを確認","エラーコード管理の自動化","コード品質と信頼性の向上"],"ko":["Yarn을 사용하여 extract-errors 명령을 실행","새로운 오류를 보고 오류 코드를 할당","오류 코드가 최신인지 확인","오류 코드 관리 자동화","코드 품질과 신뢰성 향상"],"es":["Ejecución de yarn extract-errors para reportar nuevos errores","Verificación de la actualización de los códigos de error","Integración con proyectos de desarrollo","Uso de la línea de comandos (CLI) para la ejecución","Compatibilidad con yarn para la gestión de dependencias"],"fr":["Exécution de yarn extract-errors pour signaler de nouvelles erreurs","Vérification de la mise à jour des codes d''erreur","Intégration avec les projets de développement","Utilisation de la ligne de commande (CLI) pour l''exécution","Compatibilité avec yarn pour la gestion des dépendances"],"de":["Ausführung von yarn extract-errors, um neue Fehler zu melden","Überprüfung der Aktualisierung der Fehlercodes","Integration mit Entwicklungsprojekten","Verwendung der Kommandozeile (CLI) für die Ausführung","Kompatibilität mit yarn für die Abhängigkeitsverwaltung"],"pt":["Execução de `yarn extract-errors` para iniciar o processo","Relatório de novos erros que precisam de códigos atribuídos","Verificação se os códigos de erro estão atualizados","Integração com ferramentas de desenvolvimento","Suporte à linha de comando"],"ru":["Запуск `yarn extract-errors` для начала процесса","Отчет о новых ошибках, которым необходимо присвоить коды","Проверка актуальности кодов ошибок","Интеграция с инструментами разработки","Поддержка командной строки"],"ar":["تشغيل `yarn extract-errors` لبدء العملية","تقارير الأخطاء الجديدة التي تحتاج إلى رموز معينة","التحقق من是否 رموز الأخطاء محدثة","التكامل مع أدوات التطوير","دعم سطر الأوامر"]},"keywords":{"en":["how to use extract-errors","extract-errors setup guide","yarn extract-errors command","automated error code extraction","extract-errors alternative","error code management best practices","extract-errors install","what is extract-errors"],"zh":["extract-errors","Yarn","错误代码","自动化","代码质量","AI工具","错误管理"],"ja":["エラーコード抽出","Yarn","エラーコード","自動化","コード品質","AIエージェント","エラーマネジメント"],"ko":["extract-errors","Yarn","오류 코드","자동화","코드 품질","AI 도구","오류 관리"],"es":["herramientas de extracción de errores","yarn extract-errors","gestión de errores","proyectos de desarrollo","línea de comandos","CLI","yarn","dependencias","desarrollo de software"],"fr":["outils d''extraction d''erreurs","yarn extract-errors","gestion des erreurs","projets de développement","ligne de commande","CLI","yarn","dépendances","développement de logiciels"],"de":["Fehlerextraktions-Tools","yarn extract-errors","Fehlerverwaltung","Entwicklungsprojekte","Kommandozeile","CLI","yarn","Abhängigkeiten","Software-Entwicklung"],"pt":["extract-errors","ferramentas de IA","desenvolvimento de software","códigos de erro","yarn","CLI","desenvolvedores","otimização de desenvolvimento"],"ru":["extract-errors","ИИ Агенты","разработка программного обеспечения","коды ошибок","yarn","CLI","разработчики","оптимизация разработки"],"ar":["extract-errors","أدوات الذكاء الاصطناعي","تطوير البرمجيات","رموز الأخطاء","yarn","سطر الأوامر","المطورين","تحسين التطوير"]}},"owner":"Chai-Un","repo":"wedding","repoPath":"Chai-Un/wedding","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.340Z","topics":[],"category":"community","skillMd":{"name":"extract-errors","description":"Use when adding new error messages to React, or seeing unknown error code warnings.","bodyPreview":"# Extract Error Codes\n\n## Instructions\n\n1. Run `yarn extract-errors`\n2. Report if any new errors need codes assigned\n3. Check if error codes are up to date","body":"# Extract Error Codes\n\n## Instructions\n\n1. Run `yarn extract-errors`\n2. Report if any new errors need codes assigned\n3. Check if error codes are up to date\n"},"lastSynced":"2026-03-08T02:03:26.235Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring automated error reporting and code extraction capabilities.","zh":"适合需要自动错误报告和代码提取功能的开发代理。","ja":"自動エラーレポートおよびコード抽出機能を必要とする開発エージェントに適しています。","ko":"자동 오류 보고 및 코드 추출 기능이 필요한 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo que requieren informes de errores automatizados y capacidades de extracción de código.","fr":"Idéal pour les agents de développement nécessitant des rapports d''erreurs automatisés et des capacités d''extraction de code.","de":"Ideal für Entwicklungssagenten, die automatisierte Fehlerberichte und Code-Extraktionsfunktionen benötigen.","pt":"Ideal para Agentes de Desenvolvimento que necessitam de relatórios de erros automatizados e capacidades de extração de código.","ru":"Идеально подходит для агентов разработки, требующих автоматизированного отчета об ошибках и возможностей извлечения кода.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى تقارير الأخطاء التلقائية وقدرات استخراج الشفرة."},"recommendation":{"en":"Empowers agents to streamline error reporting by automatically extracting error codes, checking for new errors, and ensuring error codes are up to date using yarn commands like `yarn extract-errors`.","zh":"使代理能够通过自动提取错误代码、检查新错误并使用yarn命令（如`yarn extract-errors`）确保错误代码是最新的，从而简化错误报告。","ja":"エージェントがエラーコードを自動的に抽出して新しいエラーを確認し、yarnコマンド（例：`yarn extract-errors`）を使用してエラーコードが最新であることを確認することで、エラーレポートを簡素化できるようにします。","ko":"에이전트가 에러 코드를 자동으로 추출하여 새로운 에러를 확인하고, yarn 명령어(예: `yarn extract-errors`)를 사용하여 에러 코드가 최신인지 확인함으로써 에러 보고를 간소화할 수 있도록 합니다.","es":"Permite a los agentes simplificar los informes de errores al extraer automáticamente los códigos de error, comprobar nuevos errores y asegurarse de que los códigos de error estén actualizados utilizando comandos de yarn como `yarn extract-errors`.","fr":"Permet aux agents de rationaliser les rapports d''erreurs en extrayant automatiquement les codes d''erreur, en vérifiant les nouvelles erreurs et en s''assurant que les codes d''erreur sont à jour en utilisant des commandes yarn comme `yarn extract-errors`.","de":"Ermöglicht es Agenten, Fehlerberichte zu rationalisieren, indem Fehlercodes automatisch extrahiert, neue Fehler überprüft und sichergestellt wird, dass Fehlercodes auf dem neuesten Stand sind, indem yarn-Befehle wie `yarn extract-errors` verwendet werden.","pt":"Permite que os agentes otimizem os relatórios de erros, extraíndo automaticamente códigos de erros, verificando novos erros e garantindo que os códigos de erros estejam atualizados usando comandos do yarn como `yarn extract-errors`.","ru":"Наделяет агентов возможностью оптимизировать отчеты об ошибках, автоматически извлекая коды ошибок, проверяя новые ошибки и обеспечивая актуальность кодов ошибок с помощью команд yarn, таких как `yarn extract-errors`.","ar":"يمكن للوكلاء بفضلها تحسين تقارير الأخطاء عن طريق استخراج رموز الأخطاء تلقائيا، وفحص أخطاء جديدة، وضمان تحديث رموز الأخطاء باستخدام أوامر yarn مثل `yarn extract-errors`."},"useCases":{"en":["Automating error code extraction","Reporting new errors for code assignment","Validating error code updates"],"zh":["自动化错误代码提取","报告新的错误以进行代码分配","验证错误代码更新"],"ja":["エラーコードの自動抽出","コード割り当てのための新しいエラーの報告","エラーコード更新の検証"],"ko":["에러 코드 자동 추출","코드 할당을 위한 새로운 에러 보고","에러 코드 업데이트 검증"],"es":["Automatización de la extracción de códigos de error","Informe de nuevos errores para la asignación de código","Validación de actualizaciones de códigos de error"],"fr":["Automatisation de l''extraction des codes d''erreur","Rapport de nouvelles erreurs pour l''affectation de code","Validation des mises à jour des codes d''erreur"],"de":["Automatisierung der Extraktion von Fehlercodes","Meldung neuer Fehler für die Codezuweisung","Überprüfung von Fehlercode-Aktualisierungen"],"pt":["Automatizar a extração de códigos de erros","Relatar novos erros para atribuição de código","Validar atualizações de códigos de erros"],"ru":["Автоматизировать извлечение кодов ошибок","Сообщать о новых ошибках для назначения кода","Проверять обновления кодов ошибок"],"ar":["تأشير استخراج رموز الأخطاء تلقائيا","إبلاغ أخطاء جديدة لتعيين الشفرة","التحقق من تحديثات رموز الأخطاء"]},"limitations":{"en":["Requires yarn installation","Dependent on error code assignment process"],"zh":["需要yarn安装","依赖于错误代码分配过程"],"ja":["yarnのインストールが必要","エラーコード割り当てプロセスに依存"],"ko":["yarn 설치가 필요","에러 코드 할당 프로세스에 의존"],"es":["Requiere instalación de yarn","Dependiente del proceso de asignación de códigos de error"],"fr":["Nécessite l''installation de yarn","Dépendant du processus d''affectation de codes d''erreur"],"de":["Benötigt yarn-Installation","Abhängig vom Fehlercode-Zuweisungsprozess"],"pt":["Requer instalação do yarn","Dependente do processo de atribuição de códigos de erros"],"ru":["Требует установки yarn","Зависит от процесса назначения кодов ошибок"],"ar":["يتطلب تثبيت yarn","يعتمد على عملية تعيين رموز الأخطاء"]},"version":4},"contentHash":"70d61d42e5b5806e1eeb0ef2380b2f3d4d87237e848128e7da35929f78813e5f","qualityScore":38}');
