INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Chai-Un/wedding/extract-errors', 'extract-errors', 'Chai-Un', 'wedding', 'community', 'extract-errors Chai-Un wedding community The extract-errors skill automates error code extraction, benefiting developers by streamlining error reporting. It checks for new errors and ensures error codes are up to date. Extract Errors是一个用于提取和管理错误代码的工具，通过运行Yarn命令即可使用 エラーコード抽出ツールは、Yarnコマンドを実行することでエラーコードを抽出し、管理することができます Extract Errors는 Yarn 명령을 실행하여 오류 코드를 추출하고 관리하는 도구입니다 La habilidad de extracción de errores permite ejecutar yarn extract-errors para reportar nuevos errores y verificar la actualización de los códigos de error L''outil d''extraction d''erreurs permet d''exécuter yarn extract-errors pour signaler de nouvelles erreurs et vérifier la mise à jour des codes d''erreur Die Fähigkeit zur Fehlerextraktion ermöglicht die Ausführung von yarn extract-errors, um neue Fehler zu melden und die Aktualisierung der Fehlercodes zu überprüfen O extract-errors é uma ferramenta que ajuda a extrair códigos de erro e manter atualizados com facilidade. Execute `yarn extract-errors` para começar. Extract-errors - это инструмент, который помогает извлекать коды ошибок и поддерживать их в актуальном состоянии. Запустите `yarn extract-errors`, чтобы начать. extract-errors هو أداة تساعد في استخراج رموز الأخطاء والحفاظ عليها محدثة بسهولة. تشغيل `yarn extract-errors` لبدء العمل. how to use extract-errors extract-errors setup guide yarn extract-errors command automated error code extraction extract-errors alternative error code management best practices extract-errors install what is extract-errors extract-errors Yarn 错误代码 自动化 代码质量 AI工具 错误管理 Runs yarn extract-errors command to extract error codes Reports new errors that require code assignment Checks if error codes are up to date for optimal error handling Utilizes Yarn package manager for efficient dependency management Streamlines error reporting and code assignment process extract-errors is a skill that automates the extraction of error codes, utilizing commands like yarn extract-errors to report and update error codes efficiently.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OpenAEC-Foundation/conventions/interview', 'community', 'OpenAEC-Foundation', 'conventions', 'OpenAEC-Foundation/conventions', 'interview', 0, 0, 38, '2026-03-08T01:57:15.347Z', '2026-03-08T02:03:38.537Z', '4021ac132d76007704d189abce6046557ecc32a25c9f79495df3552bcb23547f', '{"id":"OpenAEC-Foundation/conventions/interview","name":"interview","description":{"en":"The interview skill enables in-depth technical discussions about implementation, concerns, and tradeoffs, benefiting developers working on complex projects. It utilizes the AskUserQuestionTool for thorough questioning.","zh":"面试技能允许您使用AskUserQuestionTool进行深入的技术讨论，涵盖代码实现、担忧、权衡等方面。","ja":"インタビュースキルを使用すると、AskUserQuestionToolを使用してコード実装、懸念、トレードオフなどについて詳細な技術的ディスカッションを行うことができます。","ko":"면접 기술을 사용하면 AskUserQuestionTool을 사용하여 코드 구현, 우려, 트레이드 오프 등에 대한 심층 기술 논의를 수행할 수 있습니다.","es":"La habilidad de entrevista utiliza AskUserQuestionTool para hacer preguntas detalladas sobre implementaciones técnicas y resolver dudas","fr":"La fonction d''entretien utilise AskUserQuestionTool pour poser des questions détaillées sur les mises en œuvre techniques et résoudre les préoccupations","de":"Die Befragungsfunktion verwendet AskUserQuestionTool, um detaillierte Fragen zu technischen Implementierungen zu stellen und Bedenken zu klären","pt":"A habilidade de entrevista permite uma entrevista detalhada sobre implementação técnica, preocupações e tradeoffs, utilizando a ferramenta AskUserQuestionTool.","ru":"ХабилIDADE Entrevista позволяет провести подробное интервью о технической реализации, проблемах и компромиссах, используя инструмент AskUserQuestionTool.","ar":"تسمح مهارة المقابلة بإجراء مقابلة مفصلة حول التنفيذ الفني والاهتمامات والتنازلات، باستخدام أداة AskUserQuestionTool."},"seo":{"title":{"en":"Interview: In-Depth Technical Discussion Guide | AI Agent...","zh":"面试设置指南：使用AskUserQuestionTool进行深入技术讨论","ja":"インタビューセットアップガイド：AskUserQuestionToolを使用した詳細な技術的ディスカッション","ko":"면접 설정 가이드: AskUserQuestionTool을 사용한 심층 기술 논의","es":"Guía de configuración de la habilidad de entrevista con A...","fr":"Guide de configuration de l''entretien avec AskUserQuestio...","de":"Einrichtungsleitfaden für die Befragungsfunktion mit AskU...","pt":"Guia de Configuração da Habilidade de Entrevista com Ferr...","ru":"Настройка ИИ Агентов: Руководство по habilidade Entrevista","ar":"دليل إعداد مهارة المقابلة باستخدام أدوات الإي آي"},"description":{"en":"Unlock the full potential of complex projects with the interview skill, guiding you through detailed discussions to spec file creation - learn how to use it ...","zh":"了解如何使用面试技能进行深入的技术讨论，包括代码实现、担忧、权衡等，AIエージェント","ja":"面试スキルを使用して、コード実装、懸念、トレードオフなどについて詳細な技術的ディスカッションを行う方法を学びます。AIエージェント","ko":"면접 기술을 사용하여 코드 구현, 우려, 트레이드 오프 등에 대한 심층 기술 논의를 수행하는 방법을 알아보세요. AI 에이전트","es":"Aprende a utilizar la habilidad de entrevista para desarrollar soluciones personalizadas con AskUserQuestionTool y mejora tus habilidades de codificación","fr":"Découvrez comment utiliser la fonction d''entretien pour développer des solutions sur mesure avec AskUserQuestionTool et améliorez vos compétences en codage","de":"Erfahren Sie, wie Sie die Befragungsfunktion verwenden, um maßgeschneiderte Lösungen mit AskUserQuestionTool zu entwickeln und Ihre Codierfähigkeiten zu verb...","pt":"Aprenda a configurar a habilidade de entrevista com ferramentas de AI para desenvolvedores, incluindo dicas de implementação e boas práticas","ru":"Узнайте, как настроить habilidade Entrevista с помощью ИИ Агентов, включая советы по реализации и лучшие практики","ar":"تعرف على كيفية إعداد مهارة المقابلة باستخدام أدوات الإي آي للمطورين، بما في ذلك نصائح التنفيذ وأفضل الممارسات"},"definition":{"en":"Interview is a technical discussion skill that uses the AskUserQuestionTool to delve into detailed inquiries about any topic, ensuring no concerns are left unaddressed.","zh":"面试技能是一种使用AskUserQuestionTool进行深入技术讨论的方法，涵盖代码实现、担忧、权衡等方面。","ja":"インタビュースキルは、AskUserQuestionToolを使用してコード実装、懸念、トレードオフなどについて詳細な技術的ディスカッションを行う方法です。","ko":"면접 기술은 AskUserQuestionTool을 사용하여 코드 구현, 우려, 트레이드 오프 등에 대한 심층 기술 논의를 수행하는 방법입니다.","es":"La habilidad de entrevista es una función que utiliza AskUserQuestionTool para hacer preguntas detalladas y resolver dudas técnicas","fr":"La fonction d''entretien est une fonctionnalité qui utilise AskUserQuestionTool pour poser des questions détaillées et résoudre des problèmes techniques","de":"Die Befragungsfunktion ist eine Funktion, die AskUserQuestionTool verwendet, um detaillierte Fragen zu stellen und technische Bedenken zu klären","pt":"A habilidade de entrevista é uma habilidade de AI que permite uma entrevista detalhada sobre implementação técnica e preocupações","ru":"ХабилIDADE Entrevista - это habilidade ИИ Агентов, которая позволяет провести подробное интервью о технической реализации и проблемах","ar":"مهارة المقابلة هي مهارة الإي آي التي تسمح بإجراء مقابلة مفصلة حول التنفيذ الفني والاهتمامات"},"features":{"en":["Utilizes the AskUserQuestionTool for in-depth questioning","Covers technical implementation, concerns, and tradeoffs","Ensures thorough understanding of code not following CONVENTIONS.md","Continues discussion until all concerns are addressed","Writes the spec to a file upon completion"],"zh":["使用AskUserQuestionTool进行深入技术讨论","涵盖代码实现、担忧、权衡等方面","支持CONVENTIONS.md规范","能够生成详细的技术规范文档"],"ja":["AskUserQuestionToolを使用した詳細な技術的ディスカッション","コード実装、懸念、トレードオフなどについてのディスカッション","CONVENTIONS.md規約のサポート","詳細な技術仕様書の生成"],"ko":["AskUserQuestionTool을 사용한 심층 기술 논의","코드 구현, 우려, 트레이드 오프 등에 대한 논의","CONVENTIONS.md 규약 지원","상세한 기술 사양서 생성"],"es":["Utiliza AskUserQuestionTool para hacer preguntas detalladas sobre implementaciones técnicas","Resuelve dudas y preocupaciones técnicas de manera exhaustiva","Permite la creación de soluciones personalizadas","Seguimiento de convenciones de codificación","Generación de especificaciones técnicas"],"fr":["Utilise AskUserQuestionTool pour poser des questions détaillées sur les mises en œuvre techniques","Résout les préoccupations et les problèmes techniques de manière exhaustive","Permet la création de solutions sur mesure","Suivi des conventions de codage","Génération de spécifications techniques"],"de":["Verwendet AskUserQuestionTool, um detaillierte Fragen zu technischen Implementierungen zu stellen","Klärt technische Bedenken und Probleme umfassend","Ermöglicht die Erstellung maßgeschneiderter Lösungen","Überwachung von Codierkonventionen","Erzeugung technischer Spezifikationen"],"pt":["Entrevista detalhada sobre implementação técnica","Utilização da ferramenta AskUserQuestionTool","Análise de preocupações e tradeoffs","Geração de especificações técnicas","Integração com CONVENTIONS.md"],"ru":["Подробное интервью о технической реализации","Использование инструмента AskUserQuestionTool","Анализ проблем и компромиссов","Генерация технических спецификаций","Интеграция с CONVENTIONS.md"],"ar":["مقابلة مفصلة حول التنفيذ الفني","استخدام أداة AskUserQuestionTool","تحليل الاهتمامات والتنازلات","توليد مواصفات فنية","التكامل مع CONVENTIONS.md"]},"keywords":{"en":["how to use interview skill","what is interview skill","interview skill alternative","interview skill vs technical discussion tools","interview skill setup guide","interview skill install for AI agents","in-depth technical discussion techniques","AskUserQuestionTool integration","CONVENTIONS.md compliance"],"zh":["面试技能","AskUserQuestionTool","代码实现","技术讨论","AIエージェント","CONVENTIONS.md","技术规范"],"ja":["インタビュースキル","AskUserQuestionTool","コード実装","技術的ディスカッション","AIエージェント","CONVENTIONS.md","技術仕様"],"ko":["면접 기술","AskUserQuestionTool","코드 구현","기술 논의","AI 에이전트","CONVENTIONS.md","기술 사양"],"es":["entrevista técnica","AskUserQuestionTool","desarrollo de software","codificación","convenciones de codificación","especificaciones técnicas","soluciones personalizadas"],"fr":["entretien technique","AskUserQuestionTool","développement de logiciels","codage","conventions de codage","spécifications techniques","solutions sur mesure"],"de":["technisches Interview","AskUserQuestionTool","Softwareentwicklung","Codierung","Codierkonventionen","technische Spezifikationen","maßgeschneiderte Lösungen"],"pt":["habilidade de entrevista","ferramentas de AI","entrevista técnica","AskUserQuestionTool","CONVENTIONS.md","desenvolvimento de software","implementação técnica"],"ru":["ХабилIDADE Entrevista","ИИ Агенты","техническое интервью","AskUserQuestionTool","CONVENTIONS.md","разработка программного обеспечения","техническая реализация"],"ar":["مهارة المقابلة","أدوات الإي آي","مقابلة فنية","AskUserQuestionTool","CONVENTIONS.md","تطوير البرمجيات","التنفيذ الفني"]}},"owner":"OpenAEC-Foundation","repo":"conventions","repoPath":"OpenAEC-Foundation/conventions","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.347Z","topics":[],"category":"community","skillMd":{"name":"interview","description":"Figure out specs before you start with something complex.","bodyPreview":"# Coding Skill\n\nInterview me in detail using the AskUserQuestionTool about literally anything: technical implementation, concerns, tradeoffs, etc. make sure the questions aren''t obvious.\n\nbe very in-depth and keep interviewing me until there are NO concerns anymore. then, write the spec to a file.\n\n## When to Use\n\n- When the user requests something complex or rare\n- When the user asks you to interview them\n- When you run into code which isn''t following CONVENTIONS.md and requires understanding o","body":"# Coding Skill\n\nInterview me in detail using the AskUserQuestionTool about literally anything: technical implementation, concerns, tradeoffs, etc. make sure the questions aren''t obvious.\n\nbe very in-depth and keep interviewing me until there are NO concerns anymore. then, write the spec to a file.\n\n## When to Use\n\n- When the user requests something complex or rare\n- When the user asks you to interview them\n- When you run into code which isn''t following CONVENTIONS.md and requires understanding of the underlying problem\n"},"lastSynced":"2026-03-08T02:03:38.537Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced Conversational Agents like Claude Code and AutoGPT requiring in-depth discussion capabilities for complex project implementation and tradeoff analysis.","zh":"适用于高级对话式Agent，如Claude Code和AutoGPT，需要深入讨论复杂项目实施和权衡分析的能力。","ja":"Claude CodeやAutoGPTのような高度な会話エージェントに適しており、複雑なプロジェクトの実装とトレードオフ分析のための深い議論能力が必要です。","ko":"클라우드 코드와 오토지피티 같은 고급 대화 에이전트에 적합하며, 복잡한 프로젝트 구현 및 트레이드 오프 분석을 위한 심도 있는 논의 능력이 필요합니다.","es":"Ideal para agentes de conversación avanzados como Claude Code y AutoGPT que requieren capacidades de discusión en profundidad para la implementación de proyectos complejos y análisis de compensaciones.","fr":"Idéal pour les agents de conversation avancés comme Claude Code et AutoGPT nécessitant des capacités de discussion approfondies pour la mise en œuvre de projets complexes et l''analyse des compromis.","de":"Ideal für fortschrittliche Conversationsagenten wie Claude Code und AutoGPT, die umfassende Diskussionsfähigkeiten für die Implementierung komplexer Projekte und die Analyse von Kompromissen erfordern.","pt":"Ideal para Agentes de Conversação Avançados como Claude Code e AutoGPT que requerem capacidades de discussão aprofundada para implementação de projetos complexos e análise de tradeoffs.","ru":"Идеально подходит для продвинутых агентов разговора, таких как Claude Code и AutoGPT, требующих глубоких обсуждений для реализации сложных проектов и анализа компромиссов.","ar":"مثالي للوكلاء المحادثين المتقدمين مثل Claude Code و AutoGPT الذين يحتاجون إلى قدرات مناقشة متعمقة لتنفيذ مشاريع معقدة وتحليل التبادل."},"recommendation":{"en":"Empowers agents to conduct thorough technical discussions utilizing the AskUserQuestionTool, enabling the exploration of implementation concerns, tradeoffs, and technical intricacies through meticulous questioning, ultimately ensuring comprehensive project understanding and specification documentation in formats like CONVENTIONS.md.","zh":"赋予代理进行彻底的技术讨论的能力，利用AskUserQuestionTool，通过严密的提问探索实施的关注点、权衡和技术细节，从而确保对项目的全面理解和规格文档的编制，如CONVENTIONS.md格式。","ja":"AskUserQuestionToolを利用して、実装の懸念、トレードオフ、技術的な細部について慎重な質問を通じて探究することで、包括的なプロジェクト理解と規格文書の作成（CONVENTIONS.md形式など）を可能にします。","ko":"에이전트가 AskUserQuestionTool을 사용하여 구현의 우려, 트레이드 오프, 기술적 세부 사항에 대해 주의 깊게 질문을 통해 탐구할 수 있도록 해주어, 포괄적인 프로젝트 이해와 규격 문서의 작성(CONVENTIONS.md 형식 등)을 가능하게 합니다.","es":"Permite a los agentes realizar discusiones técnicas exhaustivas utilizando la herramienta AskUserQuestionTool, lo que permite explorar las preocupaciones de implementación, los compromisos y las complejidades técnicas a través de un cuestionamiento meticuloso, garantizando en última instancia una comprensión y documentación de especificaciones de proyecto comprehensivas en formatos como CONVENTIONS.md.","fr":"Permet aux agents de mener des discussions techniques approfondies en utilisant l''outil AskUserQuestionTool, ce qui permet d''explorer les préoccupations de mise en œuvre, les compromis et les complexités techniques à travers un questionnement méticuleux, assurant en fin de compte une compréhension et une documentation de spécifications de projet complètes dans des formats tels que CONVENTIONS.md.","de":"Ermöglicht es den Agenten, gründliche technische Diskussionen mit Hilfe des AskUserQuestionTool zu führen, wodurch die Erforschung von Implementierungsbedenken, Kompromissen und technischen Feinheiten durch sorgfältiges Fragen ermöglicht wird, was letztendlich eine umfassende Projektverständnis und Spezifikationsdokumentation in Formaten wie CONVENTIONS.md gewährleistet.","pt":"Habilita os agentes a realizar discussões técnicas aprofundadas utilizando a AskUserQuestionTool, permitindo a exploração de preocupações de implementação, compromissos e complexidades técnicas por meio de questionamento minucioso, garantindo assim uma compreensão abrangente do projeto e documentação de especificações em formatos como CONVENTIONS.md.","ru":"Наделяет агентов возможностью вести тщательные технические обсуждения с использованием AskUserQuestionTool, позволяя исследовать проблемы реализации, компромиссы и технические детали посредством тщательного вопросирования, в конечном итоге обеспечивая всестороннее понимание проекта и документацию спецификаций в форматах, таких как CONVENTIONS.md.","ar":"تمكين الوكلاء من إجراء مناقشات تقنية شاملة باستخدام AskUserQuestionTool، مما يسمح استكشاف مشاكل التنفيذ والتبادلات وال细يات الفنية من خلال الاستفسار الدقيق، مما يضمن في النهاية فهمًا شاملاً للمشروع وتوثيق مواصفات في صيغ مثل CONVENTIONS.md."},"useCases":{"en":["Conducting in-depth interviews for complex project specifications","Debugging non-conventional code implementations","Generating detailed technical documentation for rare or complex user requests"],"zh":["进行复杂项目规格的深入访谈","调试非传统代码实现","为罕见或复杂的用户请求生成详细的技术文档"],"ja":["複雑なプロジェクトの仕様についての深いインタビューの実施","非伝統的なコード実装のデバッグ","希少または複雑なユーザー要求についての詳細な技術文書の生成"],"ko":["복잡한 프로젝트의 사양에 대한 심층 인터뷰 수행","비전통적인 코드 구현의 디버깅","희귀 또는 복잡한 사용자 요청에 대한詳細한 기술 문서 생성"],"es":["Realizar entrevistas en profundidad para especificaciones de proyectos complejos","Depurar implementaciones de código no convencionales","Generar documentación técnica detallada para solicitudes de usuarios raros o complejos"],"fr":["Mener des entrevues en profondeur pour des spécifications de projet complexes","Déboguer des mises en œuvre de code non conventionnelles","Générer une documentation technique détaillée pour des demandes d''utilisateurs rares ou complexes"],"de":["Durchführen von Interviews in die Tiefe für komplexe Projektspezifikationen","Fehlerbehebung bei nicht konventionellen Codeimplementierungen","Erstellen von detaillierter technischer Dokumentation für seltene oder komplexe Benutzeranfragen"],"pt":["Realizar entrevistas aprofundadas para especificações de projetos complexos","Depurar implementações de código não convencionais","Gerar documentação técnica detalhada para solicitações de usuário raras ou complexas"],"ru":["Проведение глубоких интервью для спецификаций сложных проектов","Отладка нестандартных реализаций кода","Генерация подробной технической документации для редких или сложных запросов пользователей"],"ar":["إجراء مقابلات متعمقة لمواصفات مشاريع معقدة","تصحيح مشاكل في تنفيذ رموز غير تقليدية","توليد توثيق تقني مفصل لطلبات المستخدمين النادرة أو المعقدة"]},"limitations":{"en":["Requires AskUserQuestionTool integration","Dependent on user engagement for thorough questioning","Best suited for scenarios where CONVENTIONS.md or similar guidelines are applicable"],"zh":["需要AskUserQuestionTool集成","依赖于用户参与以进行彻底的提问","最适合CONVENTIONS.md或类似指南适用的场景"],"ja":["AskUserQuestionToolの統合が必要","徹底的な質問を行うためにユーザーの参加に依存","CONVENTIONS.mdまたは同様のガイドラインが適用可能なシナリオに最適"],"ko":["AskUserQuestionTool 통합이 필요","彻底한 질문을 위해 사용자의 참여에 의존","CONVENTIONS.md 또는 유사한 가이드라인이 적용 가능한 시나리오에 최적"],"es":["Requiere la integración de AskUserQuestionTool","Depende del compromiso del usuario para un cuestionamiento exhaustivo","Es más adecuado para escenarios en los que se aplican pautas como CONVENTIONS.md o similares"],"fr":["Nécessite l''intégration de AskUserQuestionTool","Dépend de l''engagement de l''utilisateur pour un questionnement approfondi","Est mieux adapté pour les scénarios dans lesquels des lignes directrices comme CONVENTIONS.md ou similaires sont applicables"],"de":["Benötigt die Integration von AskUserQuestionTool","Ist abhängig von der Nutzerbeteiligung für gründliches Fragen","Eignet sich am besten für Szenarien, in denen Richtlinien wie CONVENTIONS.md oder ähnliche Anleitungen anwendbar sind"],"pt":["Requer integração com AskUserQuestionTool","Depende do envolvimento do usuário para questionamento aprofundado","Melhor adaptado para cenários onde se aplicam diretrizes como CONVENTIONS.md ou similares"],"ru":["Требует интеграции с AskUserQuestionTool","Зависит от участия пользователя для тщательного вопросирования","Лучше всего подходит для сценариев, в которых применяются руководства, такие как CONVENTIONS.md или аналогичные"],"ar":["يتطلب دمجًا مع AskUserQuestionTool","يعتمد على مشاركة المستخدم للاستفسار المتعمق","أفضل ما يناسب السيناريوهات التي يتم تطبيق إرشادات مثل CONVENTIONS.md أو مماثلة لها"]},"version":4},"contentHash":"4021ac132d76007704d189abce6046557ecc32a25c9f79495df3552bcb23547f","qualityScore":38}');
