INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('OpenAEC-Foundation/conventions/interview', 'interview', 'OpenAEC-Foundation', 'conventions', 'community', 'interview OpenAEC-Foundation conventions community The interview skill enables in-depth technical discussions about implementation, concerns, and tradeoffs, benefiting developers working on complex projects. It utilizes the AskUserQuestionTool for thorough questioning. 面试技能允许您使用AskUserQuestionTool进行深入的技术讨论，涵盖代码实现、担忧、权衡等方面。 インタビュースキルを使用すると、AskUserQuestionToolを使用してコード実装、懸念、トレードオフなどについて詳細な技術的ディスカッションを行うことができます。 면접 기술을 사용하면 AskUserQuestionTool을 사용하여 코드 구현, 우려, 트레이드 오프 등에 대한 심층 기술 논의를 수행할 수 있습니다. La habilidad de entrevista utiliza AskUserQuestionTool para hacer preguntas detalladas sobre implementaciones técnicas y resolver dudas La fonction d''entretien utilise AskUserQuestionTool pour poser des questions détaillées sur les mises en œuvre techniques et résoudre les préoccupations Die Befragungsfunktion verwendet AskUserQuestionTool, um detaillierte Fragen zu technischen Implementierungen zu stellen und Bedenken zu klären A habilidade de entrevista permite uma entrevista detalhada sobre implementação técnica, preocupações e tradeoffs, utilizando a ferramenta AskUserQuestionTool. ХабилIDADE Entrevista позволяет провести подробное интервью о технической реализации, проблемах и компромиссах, используя инструмент AskUserQuestionTool. تسمح مهارة المقابلة بإجراء مقابلة مفصلة حول التنفيذ الفني والاهتمامات والتنازلات، باستخدام أداة AskUserQuestionTool. how to use interview skill what is interview skill interview skill alternative interview skill vs technical discussion tools interview skill setup guide interview skill install for AI agents in-depth technical discussion techniques AskUserQuestionTool integration CONVENTIONS.md compliance 面试技能 AskUserQuestionTool 代码实现 技术讨论 AIエージェント CONVENTIONS.md 技术规范 Utilizes the AskUserQuestionTool for in-depth questioning Covers technical implementation, concerns, and tradeoffs Ensures thorough understanding of code not following CONVENTIONS.md Continues discussion until all concerns are addressed Writes the spec to a file upon completion Interview is a technical discussion skill that uses the AskUserQuestionTool to delve into detailed inquiries about any topic, ensuring no concerns are left unaddressed.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MAF2414/kyco/chat', 'community', 'MAF2414', 'kyco', 'MAF2414/kyco', 'chat', 0, 0, 38, '2026-03-08T01:57:15.349Z', '2026-03-08T02:03:43.887Z', 'bec79db94b33ddd971754f28629f5b1c6c9615b7e6e35e52e7f9d99d269de828', '{"id":"MAF2414/kyco/chat","name":"chat","description":{"en":"Chat is an AI-powered code task solution that provides transparency and accuracy. It benefits developers by providing a reliable response to code-related queries.","zh":"AI聊天工具提供透明的代码任务解决方案，帮助开发者了解代码库","ja":"AIエージェントチャットはコードタスクの透明性を提供し、開発者の生産性を向上させる","ko":"AI 채팅 도구는 코드베이스의 투명성을 제공하여 개발자의 생산성을 향상시킵니다","es":"La función de chat ofrece tareas de código con transparencia y es la solución a la programación basada en la intuición","fr":"La fonctionnalité de chat propose des tâches de code avec transparence et est l''antidote à la programmation basée sur l''intuition","de":"Die Chat-Funktion bietet Code-Aufgaben mit Transparenz und ist das Gegenmittel zur Intuition-basierten Programmierung","pt":"O chat é uma ferramenta de código AI que fornece tarefas de código com transparência, permitindo que os desenvolvedores trabalhem de forma mais eficiente","ru":"Чат - это инструмент кодирования ИИ, который обеспечивает задачи кодирования с прозрачностью, позволяя разработчикам работать более эффективно","ar":"الدردشة هي أداة كود ذكية توفر مهام الكود مع الشفافية، مما يسمح للمطورين بالعمل بطريقة أكثر كفاءة"},"seo":{"title":{"en":"Chat: AI-Powered Code Transparency Setup Guide | AI Agent...","zh":"AI聊天工具设置指南 - 了解代码库透明度","ja":"AIエージェントチャットのベストプラクティス - コードタスクの透明性","ko":"AI 채팅 도구 설치 가이드 - 코드베이스의 투명성","es":"Guía de configuración de chat: Tareas de código con trans...","fr":"Guide de mise en place de chat: Tâches de code avec trans...","de":"Einrichtungsleitfaden für Chat: Code-Aufgaben mit Transpa...","pt":"Guia de Configuração do Chat - Ferramentas de Código AI