INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mshafei721/Turbocat/Frontend Components', 'Frontend Components', 'mshafei721', 'Turbocat', 'community', 'Frontend Components mshafei721 Turbocat community Frontend Components is a skill for AI agents that facilitates the creation and modification of UI components using React, Vue, and Svelte. It benefits developers working on component files and directories. 前端组件技能提供了高效的React、Vue、Svelte组件开发和管理能力 フロントエンドコンポーネントスキルは、React、Vue、Svelteコンポーネントの開発と管理を効率化します 프론트엔드 컴포넌트 기능은 React, Vue, Svelte 컴포넌트 개발 및 관리를 효율화합니다 El componente frontend de nuestra plataforma de codificación de IA permite a los desarrolladores crear y personalizar componentes de interfaz de usuario de manera eficiente. Le composant frontend de notre plateforme de codage IA permet aux développeurs de créer et de personnaliser des composants d''interface utilisateur de manière efficace. Die Frontend-Komponente unserer KI-Coding-Plattform ermöglicht es Entwicklern, Benutzeroberflächenkomponenten effizient zu erstellen und anzupassen. Nossa plataforma de codificação de IA para componentes frontend oferece suporte a React, Vue e Svelte, permitindo a criação de UI personalizadas Наша платформа ИИ для фронтенд компонентов поддерживает React, Vue и Svelte, позволяя создавать индивидуальные интерфейсы منصتنا للتعليم الآلي لمكونات الواجهة الأمامية تدعم React و Vue و Svelte، مما يسمح بإنشاء واجهات مستخدم مخصصة how to use Frontend Components Frontend Components setup guide React and Vue component development Svelte UI component creation Frontend Components vs other UI tools installing Frontend Components for AI agents Frontend Components for multi-agent AI coding what is Frontend Components Frontend Components alternative for UI development 前端组件 AIエージェント React Vue Svelte 组件开发 组件管理 状态管理 组件设计 Generates new UI components using React, Vue, and Svelte Modifies existing component files in directories like components/ and ui/ Composes smaller components into larger UI structures Refactors large components into smaller, manageable pieces Manages state in components, deciding between local and lifted state Frontend Components is a multi-agent AI coding platform skill for building and managing UI components with technologies like React, Vue, and Svelte.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('leaderiop/hex-di/Testing Vitest', 'community', 'leaderiop', 'hex-di', 'leaderiop/hex-di', 'Testing Vitest', 0, 0, 38, '2026-03-08T01:57:15.358Z', '2026-03-08T02:04:06.891Z', 'fecb1933fe2bcb82927b7a020421e3e71cd2d405c0b92d7232dac9ddae450230', '{"id":"leaderiop/hex-di/Testing Vitest","name":"Testing Vitest","description":{"en":"Testing Vitest provides Claude Code with guidance on handling testing standards. It offers specific instructions for adherence to coding standards.","zh":"本文介绍如何使用 Vitest 进行测试，提供具体的指导和最佳实践。","ja":"Vitest を使用してテストを実行する方法について説明します。具体的なガイダンスとベストプラクティスを提供します。","ko":"Vitest를 사용하여 테스트를 수행하는 방법에 대해 설명합니다. 구체적인 가이드와 모범 사례를 제공합니다.","es":"Testing Vitest es una habilidad que proporciona orientación específica sobre cómo adherirse a los estándares de codificación para testing vitest. Esta guía te ayudará a configurar Testing Vitest para agentes de inteligencia artificial.","fr":"Testing Vitest est une compétence qui fournit des conseils spécifiques sur la façon de respecter les normes de codage pour testing vitest. Ce guide vous aidera à configurer Testing Vitest pour les outils d''intelligence artificielle.","de":"Testing Vitest ist eine Fähigkeit, die spezifische Anleitung zur Einhaltung von Codierungsstandards für testing vitest bietet. Diese Anleitung hilft Ihnen, Testing Vitest für künstliche Intelligenz einzurichten.","pt":"O Testing Vitest é uma habilidade que fornece orientação específica sobre como seguir padrões de codificação para testes Vitest","ru":"Testing Vitest - это навык, который предоставляет конкретные рекомендации по соблюдению стандартов кодирования для тестирования Vitest","ar":"Testing Vitest هو مهارة توفر إرشادات محددة حول كيفية اتباع معايير التدوين لاختبارات Vitest"},"seo":{"title":{"en":"Testing Vitest: Setup Guide for AI Agents | AI Agent Skill","zh":"Vitest 测试设置指南","ja":"Vitest テストベストプラクティス","ko":"Vitest 테스팅 가이드","es":"Guía de configuración de Testing Vitest para agentes de i...","fr":"Guide de mise en place de Testing Vitest pour les outils ...","de":"Einrichtungsleitfaden für Testing Vitest in künstlicher I...","pt":"Guia de Configuração do Testing Vitest para Ferramentas d...","ru":"Настройка Testing Vitest: Руководство для ИИ Агентов","ar":"دليل إعداد Testing Vitest لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient testing with Testing Vitest. Learn how to integrate it into your workflow and improve your AI agent''s performance. Get started now!","zh":"了解如何使用 Vitest 进行测试，提高代码质量和效率。","ja":"Vitest を使用してテストを実行し、コードの品質と効率を向上させる方法について学びます。","ko":"Vitest를 사용하여 테스트를 수행하고 코드 품질 및 효율성을 향상시키는 방법에 대해 알아보세요.","es":"Aprende a configurar Testing Vitest para agentes de inteligencia artificial y mejora tus habilidades de desarrollo con nuestras mejores prácticas","fr":"Découvrez comment configurer Testing Vitest pour les outils d''intelligence artificielle et améliorez vos compétences de développement avec nos meilleures pra...","de":"Erfahren Sie, wie Sie Testing Vitest für künstliche Intelligenz einrichten und verbessern Sie Ihre Entwicklungsfähigkeiten mit unseren Best Practices","pt":"Aprenda a configurar o Testing Vitest para garantir a qualidade do seu código com as melhores práticas e diretrizes de codificação","ru":"Узнайте, как настроить Testing Vitest для обеспечения качества вашего кода с помощью лучших практик и руководств по кодированию для ИИ Агентов","ar":"تعرف على كيفية إعداد Testing Vitest لضمان جودة кодك باستخدام أفضل الممارسات وإرشادات التدوين لآدوات الذكاء الاصطناعي"},"definition":{"en":"Testing Vitest is a skill that provides guidance on testing standards for AI agents, ensuring adherence to coding standards.","zh":"Vitest 测试是指使用 Vitest 框架进行的代码测试。","ja":"Vitest テストとは、Vitest フレームワークを使用して行われるコードのテストです。","ko":"Vitest 테스팅은 Vitest 프레임워크를 사용하여 수행되는 코드 테스트를 말합니다.","es":"Testing Vitest es una habilidad que proporciona orientación para testing vitest en agentes de inteligencia artificial","fr":"Testing Vitest est une compétence qui fournit des conseils pour testing vitest dans les outils d''intelligence artificielle","de":"Testing Vitest ist eine Fähigkeit, die Anleitung für testing vitest in künstlicher Intelligenz bietet","pt":"Testing Vitest é uma habilidade de codificação que ajuda a garantir a qualidade do código","ru":"Testing Vitest - это навык кодирования, который помогает обеспечить качество кода","ar":"Testing Vitest هو مهارة برمجة تساعد على ضمان جودة الكود"},"features":{"en":["Provides specific guidance on handling testing vitest","References the testing vitest file for detailed information","Ensures adherence to coding standards for AI agents","Offers instructions for integrating testing vitest into workflows","Supports Claude Code development with testing standards","Includes documentation for testing vitest setup and usage"],"zh":["使用 Vitest 框架进行代码测试","遵循特定的编码标准","提高代码质量和效率","提供具体的指导和最佳实践","支持多种测试场景"],"ja":["Vitest フレームワークを使用してコードをテストする","特定のコーディング標準に準拠する","コードの品質と効率を向上させる","具体的なガイダンスとベストプラクティスを提供する","複数のテストシナリオをサポートする"],"ko":["Vitest 프레임워크를 사용하여 코드를 테스트한다","특정한 코딩 표준을 준수한다","코드 품질과 효율성을 향상시킨다","구체적인 가이드와 모범 사례를 제공한다","다양한 테스트 시나리오를 지원한다"],"es":["Adherirse a los estándares de codificación para testing vitest","Configuración de Testing Vitest para agentes de inteligencia artificial","Mejora de las habilidades de desarrollo con Testing Vitest","Integración con Vitest para pruebas de código","Seguimiento de las mejores prácticas para testing vitest"],"fr":["Respecter les normes de codage pour testing vitest","Configuration de Testing Vitest pour les outils d''intelligence artificielle","Amélioration des compétences de développement avec Testing Vitest","Intégration avec Vitest pour les tests de code","Suivi des meilleures pratiques pour testing vitest"],"de":["Einhaltung von Codierungsstandards für testing vitest","Einrichtung von Testing Vitest für künstliche Inte