INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('toanpv-0639/claudekit-engineer/sequential-thinking', 'sequential-thinking', 'toanpv-0639', 'claudekit-engineer', 'community', 'sequential-thinking toanpv-0639 claudekit-engineer community Sequential thinking enables developers to tackle complex problems through structured, reflective thought sequences. It benefits developers working on multi-step solutions and hypothesis-driven investigations. 顺序思考是一种结构化的解决问题方法，通过可管理的反思性思考序列实现动态调整 シーケンシャル思考は、動的な調整を可能にする反省的な思考シーケンスを通じて構造化された問題解決方法です 순차적 사고는 다이나믹한 조정을 가능하게 하는 반성적인思考 시퀀스를 통해 구조화된 문제 해결 방법입니다 El pensamiento secuencial es una técnica de resolución de problemas que implica descomponer problemas complejos en secuencias manejables de pensamiento. Mejora la planificación y el análisis La pensée séquentielle est une technique de résolution de problèmes qui consiste à décomposer des problèmes complexes en séquences de pensée gérables. Améliorez la planification et l''analyse Das sequenzielle Denken ist eine Problemlösungstechnik, die komplexe Probleme in handhabbare Gedankenfolgen zerlegt. Verbessert die Planung und Analyse O pensamento sequencial é uma abordagem estruturada para resolver problemas complexos via sequências de pensamento refletidas e ajustes dinâmicos Последовательное мышление - это структурированный подход к решению сложных проблем посредством отраженных последовательностей мысли и динамических корректировок التفكير التتابعي هو نهج منظم ل حل المشكلات المعقدة من خلال تسلسلات من التفكير المنعكس والتعديلات الديناميكية how to use sequential thinking what is sequential thinking sequential thinking alternative sequential thinking vs critical thinking sequential thinking install sequential thinking setup guide sequential thinking for complex problem solving sequential thinking for adaptive planning sequential thinking for developers 顺序思考 AI工具 问题解决 复杂问题分解 适应性规划 假设驱动的调查 动态调整 多步骤解决方案 Enables complex problem decomposition via manageable thought sequences Supports adaptive planning with revision capability for unclear or emerging scope problems Facilitates multi-step solutions requiring context maintenance and dynamic adjustment Allows for hypothesis-driven investigation and debugging with course correction Starts with loose estimates and adjusts dynamically for reflective thought sequences Sequential-thinking is a problem-solving approach that involves manageable, reflective thought sequences with dynamic adjustment for complex problem decomposition and adaptive planning.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('doraemonkeys/sloc-guard/requirement-change', 'community', 'doraemonkeys', 'sloc-guard', 'doraemonkeys/sloc-guard', 'requirement-change', 0, 0, 38, '2026-03-08T01:57:15.364Z', '2026-03-08T02:04:20.315Z', '1c2d4ac81a79ff6e5002507304639b5a5df044a1e6e23b872ff2184dc839e542', '{"id":"doraemonkeys/sloc-guard/requirement-change","name":"requirement-change","description":{"en":"The requirement-change skill enforces SLOC limits and directory structure rules to prevent code bloat, benefiting developers working with Rust CLI. It ensures each task is independently completable and testable.","zh":"Requirement Change是一种高性能的Rust CLI工具，用于强制执行SLOC限制和目录结构规则，防止代码臃肿","ja":"Requirement Changeは、高パフォーマンスのRust CLIツールで、SLOC制限とディレクトリ構造ルールを強制実行してコードの肥大化を防ぎます","ko":"요구사항 변경은 코드 낭비를 방지하기 위해 SLOC 제한과 디렉토리 구조 규칙을 강제로 적용하는 고성능 Rust CLI 도구입니다","es":"Requirement Change es una herramienta de línea de comandos de Rust que aplica límites SLOC y reglas de estructura de directorios para prevenir la inflación de código","fr":"Requirement Change est un outil de ligne de commande Rust qui impose des limites SLOC et des règles de structure de répertoire pour prévenir l''inflation de code","de":"Requirement Change ist ein Rust-CLI-Tool, das SLOC-Grenzen und Verzeichnisstruktur-Regeln durchsetzt, um Code-Inflation zu verhindern","pt":"O Requirement Change é uma ferramenta de linha de comando em Rust que ajuda a prevenir a inflação de código, aplicando limites de linhas de código e estruturas de diretório","ru":"Requirement Change - это инструмент командной строки на Rust, предназначенный для предотвращения разрастания кода путем применения ограничений на количество строк кода и структуры каталогов","ar":"Requirement Change هي أداة سطر أوامر بلغة روست تساعد على منع التضخم البرمجي بتطبيق حدود للأسطر البرمجية وهيكل المجلدات"},"seo":{"title":{"en":"requir