INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('doraemonkeys/sloc-guard/requirement-change', 'requirement-change', 'doraemonkeys', 'sloc-guard', 'community', 'requirement-change doraemonkeys sloc-guard community The requirement-change skill enforces SLOC limits and directory structure rules to prevent code bloat, benefiting developers working with Rust CLI. It ensures each task is independently completable and testable. Requirement Change是一种高性能的Rust CLI工具，用于强制执行SLOC限制和目录结构规则，防止代码臃肿 Requirement Changeは、高パフォーマンスのRust CLIツールで、SLOC制限とディレクトリ構造ルールを強制実行してコードの肥大化を防ぎます 요구사항 변경은 코드 낭비를 방지하기 위해 SLOC 제한과 디렉토리 구조 규칙을 강제로 적용하는 고성능 Rust CLI 도구입니다 Requirement Change es una herramienta de línea de comandos de Rust que aplica límites SLOC y reglas de estructura de directorios para prevenir la inflación de código Requirement Change est un outil de ligne de commande Rust qui impose des limites SLOC et des règles de structure de répertoire pour prévenir l''inflation de code Requirement Change ist ein Rust-CLI-Tool, das SLOC-Grenzen und Verzeichnisstruktur-Regeln durchsetzt, um Code-Inflation zu verhindern O Requirement Change é uma ferramenta de linha de comando em Rust que ajuda a prevenir a inflação de código, aplicando limites de linhas de código e estruturas de diretório Requirement Change - это инструмент командной строки на Rust, предназначенный для предотвращения разрастания кода путем применения ограничений на количество строк кода и структуры каталогов Requirement Change هي أداة سطر أوامر بلغة روست تساعد على منع التضخم البرمجي بتطبيق حدود للأسطر البرمجية وهيكل المجلدات how to use requirement-change what is requirement-change requirement-change alternative requirement-change vs sloc-guard requirement-change install requirement-change setup guide Rust CLI for SLOC limits directory structure rules for code organization preventing code bloat with requirement-change Rust CLI SLOC限制 代码优化 代码臃肿防止 AI工具 代码结构优化 开发效率提高 Enforces SLOC limits to prevent code bloat Implements directory structure rules for organized code Reviews docs/PROJECT_OVERVIEW.md for task structure understanding Creates/modify tasks following independent completable and testable principles Delivers complete functionality that can be verified Avoids partial implementations that are untestable requirement-change is a high-performance Rust CLI that enforces SLOC limits and directory structure rules to prevent code bloat');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shunta-sato/agent-instructions-playbook/modularity', 'community', 'shunta-sato', 'agent-instructions-playbook', 'shunta-sato/agent-instructions-playbook', 'modularity', 0, 0, 38, '2026-03-08T01:57:15.370Z', '2026-03-08T02:04:26.521Z', 'ab3fc780f2e7ef57138eaf75c6b02ddd4e92f7a1e22898c294a4177739a5cd87', '{"id":"shunta-sato/agent-instructions-playbook/modularity","name":"modularity","description":{"en":"The modularity skill helps developers evaluate and improve code organization by keeping responsibilities cohesive and dependencies stable. This benefits developers seeking to refine their code structure.","zh":"模块化是保持代码的内聚性和低耦合性的关键，使用AI工具可以帮助您评估和改进代码的模块化","ja":"モジュラー設計はコードの内聚性と低結合性を保つ鍵です。AIエージェントを使用してコードのモジュラー性を評価し、改善することができます","ko":"모듈화는 코드의 응집도와 낮은 결합도를 유지하는 데 중요한 역할을 합니다. AI 도구를 사용하여 코드의 모듈화를 평가하고 개선할 수 있습니다","es":"La modularidad es crucial para mantener un código organizado y escalable. Nuestra guía te ayudará a evaluar y mejorar la modularidad en tus proyectos.","fr":"La modularité est essentielle pour maintenir un code organisé et évolutif. Notre guide vous aidera à évaluer et améliorer la modularité dans vos projets.","de":"Modularität ist entscheidend für die Wartung von organisiertem und skalierbarem Code. Unser Leitfaden hilft Ihnen, die Modularität in Ihren Projekten zu bewerten und zu verbessern.","pt":"A modularidade é fundamental para manter o código organizado e escalável. Aprenda a avaliar e melhorar a modularidade do seu código.","ru":"Модульность является фундаментальной для поддержания организованного и масштабируемого кода. Узнайте, как оценить и улучшить модульность вашего кода.","ar":"قابلية التحكم هي أساسية للحفاظ على رمز منظم وموسع. تعلم كيف تقييم وتحسين قابلية التحكم في رمزك."},"seo":{"title":{"en":"Modularity: Best Practices for AI Agents | Setup Guide","zh":"模块化Setup Guide：提高代码质量","ja":"モジュラー設計Best Practices：AIエージェントを使用して","ko":"모듈화 개선 가이드: 함수 및 클래스 최적화","es":"Guía de configuración de modularidad para agentes de IA","fr":"Meilleures pratiques de modularité pour les outils d''IA","de":"Modularitäts-Setup-Leitfaden für KI-Agents","pt":"Guia de Configuração de Modularidade: Melhorando Cohesão ...","ru":"ИИ Агенты: Руководство по Настройке Модульности для Разра...","ar":"دليل إعداد قابلية التحكم: تحسين التماسك والارتباط"},"description":{"en":"Discover how to evaluate and improve modularity in your code. Learn to keep responsibilities tightly grouped and dependencies small with our expert guide.","zh":"了解模块化的重要性和实现方法，使用AI工具提高代码质量和可维护性","ja":"モジュラー設計の重要性と実装方法を学び、AIエージェントを使用してコードの品質と保守性を向上させる","ko":"모듈화의 중요성과 구현 방법을 알아보고, AI 도구를 사용하여 코드 품질과 유지 보수성을 향상시키는 방법","es":"Aprende a evaluar y mejorar la modularidad en tus proyectos con nuestra guía de mejores prácticas para agentes de IA","fr":"Découvrez comment améliorer la modularité de vos projets avec nos meilleures pratiques pour les outils d''IA","de":"Erfahren Sie, wie Sie die Modularität in Ihren Projekten mit unserem Setup-Leitfaden für KI-Agents verbessern können","pt":"Aprenda a avaliar e melhorar a modularidade do seu código, mantendo responsabilidades agrupadas e dependências pequenas e estáveis.","ru":"Узнайте, как оценить и улучшить модульность вашего кода, сохраняя ответственность и зависимости стабильными.","ar":"تعلم كيف تقييم وتحسين قابلية التحكم في رمزك، مع الحفاظ على المسؤوليات المجموعة والاعتماد الصغير والثابت."},"definition":{"en":"Modularity is a design principle that keeps responsibilities tightly grouped and dependencies small and stable, ensuring explicit boundaries and maintainable code.","zh":"模块化是指将代码组织成小的、独立的单元，以提高代码的可维护性和可复用性","ja":"モジュラー設計とは、コードを小さく独立した単位に組織化することで、コードの保守性と再利用性を向上させること","ko":"모듈화란 코드를 작은 독립된 단위로 οργ化하여 코드의 유지 보수성과 재사용성을 향상시키는 것","es":"La modularidad se refiere a la capacidad de mantener responsabilidades agrupadas y dependencias pequeñas y estables en un proyecto","fr":"La modularité fait référence à la capacité de maintenir des responsabilités regroupées et des dépendances petites et stables dans un projet","de":"Modularität bezieht sich auf die Fähigkeit, Verantwortlichkeiten gruppiert und Abhängigkeiten klein und stabil in einem Projekt zu halten","pt":"Modularidade refere-se à capacidade de manter responsabilidades agrupadas e dependências pequenas e estáveis no código.","ru":"Модульность означает способность поддерживать ответственность и зависимости стабильными в коде.","ar":"قابلية التحكم تعني القدرة على الحفاظ على المسؤوليات المجموعة والاعتماد الصغير والثابت في الرمز."},"features":{"en":["Evaluates code modularity at the lowest meaningful unit (function, class, or small module)","Uses the worst rating as the truth to ensure accurate assessment","Helps keep responsibilities tightly grouped (cohesion) for better code organization","Minimizes dependencies and keeps them stable (coupling) for reduced complexity","Ensures explicit boundaries for clearer code structure"],"zh":["评估代码的内聚性和低耦合性","使用AI工具改进代码的模块化","保持代码的最小有意义单元（函数/类/小模块）","使用最坏的评级作为真实的评估结果","提高代码的可维护性和可复用性"],"ja":["コードの内聚性と低結合性を評価する","AIエージェントを使用してコードのモジュラー性を改善する","コードの最小有意义単位（関数/クラス/小モジュール）を保持する","最悪の評価を真実の評価結果として使用する","コードの保守性と再利用性を向上させる"],"ko":["코드의 응집도와 낮은 결합도를 평가한다","AI 도구를 사용하여 코드의 모듈화를 개선한다","코드의 최소 의미 있는 단위（함수/클래스/소모듈）를 유지한다","최악의 평점을 실제 평점 결과로 사용한다","코드의 유지 보수성과 재사용성을 향상시킨다"],"es":["Evaluación de la cohesión y el acoplamiento en módulos pequeños","Uso de la unidad más pequeña significativa para evaluar la modularidad","Identificación de dependencias pequeñas y estables","Establecimiento de límites explícitos en el código","Mejora de la escalabilidad y el mantenimiento del código"],"fr":["Évaluation de la cohésion et du couplage dans de petits modules","Utilisation de l''unité la plus petite significative pour évaluer la modularité","Identification de dépendances petites et stables","Établissement de limites explicites dans le code","Amélioration de la scalabilité et de la maintenance du code"],"de":["Bewertung der Kohäsion und des Couplings in kleinen Modulen","Verwendung der kleinsten bedeutungsvollen Einheit zur Bewertung der Modularität","Identifizierung kleiner und stabiler Abhängigkeiten","Festlegung expliziter Grenzen im Code","Verbesserung der Skalierbarkeit und Wartung des Codes"],"pt":["Avaliação de modularidade no nível de função ou classe","Manutenção de responsabilidades agrupadas e dependências pequenas","Definição de limites explícitos para módulos","Uso da pior avaliação como verdade para garantir a qualidade","Melhoria da coesão e redução do acoplamento"],"ru":["Оценка модульности на уровне функции или класса","Поддержание ответственности и зависимостей стабильными","Определение явных границ для модулей","Использование худшей оценки как истинной для обеспечения качества","Улучшение связности и снижение связывания"],"ar":["تقييم قابلية التحكم على مستوى الدالة أو الفئة","الحفاظ على المسؤوليات المجموعة والاعتماد الصغير","تعريف حدود واضحة للمكونات","استخدام التقييم الأسوأ كحقيقة لضمان الجودة","تحسين التماسك وتقليل الارتباط"]},"keywords":{"en":["how to use modularity in coding","what is modularity in software design","modularity vs encapsulation","modularity setup guide for developers","modularity best practices for AI agents","improving code modularity with cohesion and coupling"],"zh":["模块化","代码质量","AI工具","内聚性","低耦合性","代码可维护性","代码可复用性","模块化设计","代码评估"],"ja":["モジュラー設計","コード品質","AIエージェント","内聚性","低結合性","コード保守性","コード再利用性","モジュラー設計パターン","コード評価"],"ko":["모듈화","코드 품질","AI 도구","응집도","낮은 결합도","코드 유지 보수성","코드 재사용성","모듈화 패턴","코드 평가"],"es":["modularidad en proyectos de software","mejores prácticas de modularidad","evaluación de la modularidad","cohesión y acoplamiento en programación","agentes de IA y modularidad","desarrollo de software escalable","mantenimiento de código organizado"],"fr":["modularité dans les projets de logiciel","meilleures pratiques de modularité","évaluation de la modularité","cohésion et couplage en programmation","outils d''IA et modularité","développement de logiciel évolutif","maintenance de code organisé"],"de":["Modularität in Software-Projekten","Best Practices für Modularität","Bewertung der Modularität","Kohäsion und Coupling in der Programmierung","KI-Agents und Modularität","Entwicklung von skalierbarer Software","Wartung von organisiertem Code"],"pt":["modularidade","desenvolvimento de software","código organizado","escalabilidade","cohesion","acoplamento","melhoria de código","guias de desenvolvimento","ferramentas de desenvolvimento"],"ru":["модульность","разработка программного обеспечения","организованный код","масштабируемость","связность","связывание","улучшение кода","руководства по разработке","инструменты разработки","ИИ Агенты"],"ar":["قابلية التحكم","تطوير البرمجيات","رمز منظم","توسيع","تماسك","ارتباط","تحسين الرمز","دلائل التطوير","أدوات التطوير","وكلاء الذكاء الاصطناعي"]}},"owner":"shunta-sato","repo":"agent-instructions-playbook","repoPath":"shunta-sato/agent-instructions-playbook","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.370Z","topics":[],"category":"community","skillMd":{"name":"modularity","description":"Modularity handbook (cohesion/coupling/boundaries). Evaluate design at the lowest unit, judge by the worst level, and propose fixes that reduce change ripple. Always open references/modularity.md and cite headings.","bodyPreview":"## Purpose\n\nUse this skill to evaluate and improve **modularity**: keep responsibilities tightly grouped (cohesion), keep dependencies small and stable (coupling), and keep boundaries explicit.\n\nThis skill fixes one common failure mode: judging “module quality” only at a high level. Here, you always evaluate at the **lowest meaningful unit** (function / class / small module) and use the **worst** rating as the truth.\n\n## When to use\n\nUse this skill when:\n\n- You are unsure whether a change made a","body":"## Purpose\n\nUse this skill to evaluate and improve **modularity**: keep responsibilities tightly grouped (cohesion), keep dependencies small and stable (coupling), and keep boundaries explicit.\n\nThis skill fixes one common failure mode: judging “module quality” only at a high level. Here, you always evaluate at the **lowest meaningful unit** (function / class / small module) and use the **worst** rating as the truth.\n\n## When to use\n\nUse this skill when:\n\n- You are unsure whether a change made a module “too mixed” or “too entangled”.\n- You want to refactor to reduce change ripple, without rewriting everything.\n- You are reviewing an AI-written change and need an objective explanation and a concrete fix plan.\n\n## How to use\n\n0) Open `references/modularity.md`. Select **1–3 relevant headings** and cite them by heading name in your reasoning.\n\n1) Decide the evaluation unit (usually a single function, a class, or a small file section). List the units you will judge.\n\n2) For each unit:\n   - Rate cohesion at the **worst** level present.\n   - Rate coupling at the **worst** level present.\n   - Identify boundary leaks (external types, vendor exceptions, “framework objects” flowing inward).\n\n3) Propose the smallest fix that improves the worst rating:\n   split time/procedural cohesion into smaller functional units, isolate “translation glue” at boundaries, introduce a thin wrapper, or restructure data flow.\n\n4) Re-check: does the change reduce reader confusion and reduce future change ripple?\n\n## Output expectation\n\n- Provide a short rating summary (worst level + reason) and a fix plan with minimal diffs.\n- If you propose a larger change, justify it with: reduced ripple, simpler tests, and clearer boundaries.\n"},"lastSynced":"2026-03-08T02:04:26.521Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced modularity evaluation and improvement capabilities.","zh":"非常适合需要高级模块性评估和改进能力的代码审查代理。","ja":"コードレビューエージェントが高度なモジュラリティ評価と改善能力を必要とする場合に最適です。","ko":"코드 리뷰 에이전트가 고급 모듈성 평가 및 개선 기능을 필요로 하는 경우에 적합합니다.","es":"Ideal para Agentes de Revisión de Código que necesitan capacidades de evaluación e mejora de modularidad avanzadas.","fr":"Parfait pour les agents de revue de code nécessitant une évaluation et une amélioration de la modularité avancées.","de":"Perfekt für Code-Review-Agents, die erweiterte Modularitätsevaluierungs- und -verbesserungsfunktionen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que precisam de capacidades avançadas de avaliação e melhoria de modularidade.","ru":"Идеально подходит для агентов код-ревью, которым необходимы продвинутые возможности оценки и улучшения модульности.","ar":"مثالي لعميل المراجعة الكودية الذي يحتاج إلى قدرات متقدمة لتقييم وتحسين الوحداتية."},"recommendation":{"en":"Empowers agents to evaluate and refine code structure by enforcing cohesion, reducing coupling, and establishing explicit boundaries, utilizing metrics such as worst-case ratings for module quality assessment.","zh":"赋予代理评估和完善代码结构的能力，通过强制内聚、减少耦合和建立明确的边界，利用模块质量评估的指标，如最坏情况评级。","ja":"エージェントがコード構造を評価して改良する能力を付与し、凝集を強制し、結合を減らし、明示的な境界を確立することで、モジュール品質評価の指標である最悪の評価を使用します。","ko":"에이전트가 코드 구조를 평가하고 개선하는 기능을 부여하여 응집력을 강화하고 결합도를 줄이고 명시적인 경계를 설정하며 모듈 품질 평가의 지표인 최악의 경우 평가를 사용합니다.","es":"Habilita a los agentes a evaluar y perfeccionar la estructura del código al hacer cumplir la cohesión, reducir el acoplamiento y establecer límites explícitos, utilizando métricas como calificaciones de peor caso para la evaluación de la calidad del módulo.","fr":"Permet aux agents d''évaluer et d''affiner la structure du code en faisant respecter la cohésion, en réduisant le couplage et en établissant des limites explicites, en utilisant des métriques telles que les notes de pire cas pour l''évaluation de la qualité du module.","de":"Ermächtigt die Agenten, die Code-Struktur zu bewerten und zu verfeinern, indem sie die Kohäsion durchsetzen, die Kopplung reduzieren und explizite Grenzen festlegen, unter Verwendung von Metriken wie Worst-Case-Bewertungen für die Modulqualitätsbewertung.","pt":"Habilita os agentes a avaliar e refinar a estrutura de código, aplicando coesão, reduzindo acoplamento e estabelecendo limites explícitos, utilizando métricas como avaliações de pior caso para avaliação da qualidade do módulo.","ru":"Наделяет агентов возможностью оценивать и совершенствовать структуру кода, обеспечивая связность, снижая связанность и устанавливая явные границы, используя метрики, такие как рейтинги худшего случая для оценки качества модуля.","ar":"يمنح الوكيل khảية تقييم وتحسين هيكل الكود عن طريق تطبيق التماسك وتقليل الارتباط وتحديد الحدود الصريحة، باستخدام مقاييس مثل تقييمات الحالة الأسوأ لتقييم جودة الوحدة."},"useCases":{"en":["Evaluating module quality at the lowest meaningful unit","Improving code organization by reducing dependencies","Refining class and function responsibilities for better cohesion"],"zh":["在最低有意义的单位评估模块质量","通过减少依赖关系改善代码组织","通过完善类和函数的职责来提高凝集力"],"ja":["最も意味のある単位でモジュール品質を評価する","依存関係を減らしてコードの組織を改善する","クラスと関数の責任を改善して凝集力を高める"],"ko":["가장 의미 있는 단위에서 모듈 품질을 평가한다","의존성을 줄여 코드 조직을 개선한다","클래스와 함수의 책임을 개선하여 응집력을 높인다"],"es":["Evaluar la calidad del módulo en la unidad más baja con sentido","Mejorar la organización del código reduciendo las dependencias","Perfeccionar las responsabilidades de las clases y las funciones para una mejor cohesión"],"fr":["Évaluer la qualité du module à l''unité la plus basse significative","Améliorer l''organisation du code en réduisant les dépendances","Affiner les responsabilités des classes et des fonctions pour une meilleure cohésion"],"de":["Bewerten der Modulqualität in der niedrigsten sinnvollen Einheit","Verbesserung der Codeorganisation durch Reduzierung der Abhängigkeiten","Verfeinern der Klassen- und Funktionsverantwortlichkeiten für eine bessere Kohäsion"],"pt":["Avaliar a qualidade do módulo na unidade mais baixa e significativa","Melhorar a organização do código, reduzindo dependências","Refinar responsabilidades de classe e função para melhor coesão"],"ru":["Оценка качества модуля на самом низком и значимом уровне","Улучшение организации кода за счет снижения зависимостей","Совершенствование ответственности класса и функции для лучшей связности"],"ar":["تقييم جودة الوحدة على أدنى وحدة واضحة","تحسين تنظيم الكود من خلال تقليل الاعتماديات","تحسين مسؤوليات الفئة والدالة لتحقيق تماسك أفضل"]},"limitations":{"en":["Requires access to codebase","Evaluates module quality at the function, class, or small module level only"],"zh":["需要访问代码库","仅在函数、类或小模块级别评估模块质量"],"ja":["コードベースへのアクセスが必要","モジュール品質を関数、クラス、または小さなモジュールのレベルでのみ評価する"],"ko":["코드베이스에 접근해야 한다","모듈 품질을 함수, 클래스 또는 작은 모듈 수준에서만 평가한다"],"es":["Requiere acceso a la base de código","Evalúa la calidad del módulo solo a nivel de función, clase o módulo pequeño"],"fr":["Nécessite un accès à la base de code","Évalue la qualité du module uniquement au niveau de la fonction, de la classe ou du petit module"],"de":["Benötigt Zugriff auf die Codebasis","Bewertet die Modulqualität nur auf Funktion-, Klassen- oder kleinem Modulniveau"],"pt":["Requer acesso à base de código","Avalia a qualidade do módulo apenas no nível de função, classe ou módulo pequeno"],"ru":["Требует доступа к кодовой базе","Оценивает качество модуля только на уровне функции, класса или небольшого модуля"],"ar":["يتطلب الوصول إلى قاعدة الكود","تقييم جودة الوحدة على مستوى الدالة أو الفئة أو الوحدة الصغيرة فقط"]},"version":4},"contentHash":"ab3fc780f2e7ef57138eaf75c6b02ddd4e92f7a1e22898c294a4177739a5cd87","qualityScore":38}');
