INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Peiiii/AgentVerse/project-os', 'project-os', 'Peiiii', 'AgentVerse', 'community', 'project-os Peiiii AgentVerse community project-os is a multi-agent collaboration platform that enables autonomous closed loops and automated workflows for development teams, covering demand, implementation, verification, release, and review. Project OS 是一个用于快速落地『开发规范 + 迭代日志 + 发布闭环』的通用体系，实现自治闭环、自动化编排和规则驱动执行 Project OSは、『開発規範 + イテレーションログ + リリースクローズ』のための汎用システムで、自治閉合、自動化オーケストレーション、ルール駆動実行を実現する Project OS는 『개발 규범 + 반복 로그 + 릴리스 폐쇄』를 위한 일반 시스템으로 자치 폐쇄, 자동화 오케스트레이션, 규칙 기반 실행을 구현합니다 Project OS es una plataforma de colaboración multi-agente que permite automatizar flujos de trabajo de desarrollo, desde la implementación hasta la publicación Project OS est une plateforme de collaboration multi-agent qui permet d''automatiser les flux de travail de développement, de la mise en œuvre à la publication Project OS ist eine Multi-Agenten-Kollaborationsplattform, die die Automatisierung von Entwicklungsworkflows ermöglicht, von der Implementierung bis zur Veröffentlichung O Project OS é uma plataforma de colaboração multi-agente que automatiza fluxos de trabalho e padroniza projetos Project OS — это многоагентная платформа, которая автоматизирует рабочие процессы и стандартизирует проекты Project OS هو منصة تعاون متعددة الوكلاء التي تتيح автомatisation تدفقات العمل وتوحيد المشاريع how to use project-os project-os setup guide project-os alternative project-os vs jira project-os install what is project-os project-os automated workflow project-os autonomous closed loop project-os multi-agent collaboration Project OS 多代理协作平台 自治闭环 自动化编排 规则驱动执行 AI 操作系统 开发规范 迭代日志 发布闭环 Enforces autonomous closed loops via demand-implementation-verification-release-smoke testing-review Supports automated workflow orchestration using commands, skills, and workflows Utilizes Rulebook for unified constraint and judgment, ensuring execution consistency and auditability Allows for rapid project setup using template replication and merging Facilitates team-unified validation, smoke testing, and release specifications project-os is a universal system for quickly establishing ''development specifications + iteration logs + release closed loops'' in new projects, evolving towards an autonomous, programmable, and automatically driven AI operating system.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kks0488/vibe-codex/vcf', 'community', 'kks0488', 'vibe-codex', 'kks0488/vibe-codex', 'vcf', 0, 0, 38, '2026-03-08T01:57:15.373Z', '2026-03-08T02:04:31.278Z', '9bb8e2781a097ac41920099b4d2bc7616e0d7bf6939cc66403f81b5721240d33', '{"id":"kks0488/vibe-codex/vcf","name":"vcf","description":{"en":"The vcf skill is a thin alias for vc-phase-loop, enabling fast loops and compatibility with Codex and OpenCode for AI agents and developers.","zh":"VCF 是一个薄的别名为 vc-phase-loop，用于实现快速循环和零设置的 Codex 与 OpenCode 兼容性","ja":"VCF は、vc-phase-loop の薄いエイリアスであり、高速ループとゼロセットアップの Codex および OpenCode との互換性を実現します","ko":"VCF는 vc-phase-loop의 얇은 별칭으로 빠른 루프와 제로 설정의 Codex 및 OpenCode와의 호환성을 실현합니다","es":"vcf es un alias de vc-phase-loop que permite loops rápidos y zero-setup para la codificación autónoma con Codex y OpenCode","fr":"vcf est un alias de vc-phase-loop qui permet des boucles rapides et zero-setup pour la codification autonome avec Codex et OpenCode","de":"vcf ist ein Alias von vc-phase-loop, der schnelle Loops und Zero-Setup für die autonome Codierung mit Codex und OpenCode ermöglicht","pt":"A habilidade VCF é um alias para vc-phase-loop, permitindo codificação autônoma com loops rápidos e zero configuração","ru":"Навык VCF является псевдонимом для vc-phase-loop, позволяющим автономное кодирование с быстрыми циклами и нулевой настройкой","ar":"المهارة VCF هي اسم مستعار ل vc-phase-loop، مما يسمح بالترميز الذاتي مع الحلقات السريعة وبدون إعداد"},"seo":{"title":{"en":"vcf: Thin Alias Setup Guide for AI Agents","zh":"VCF 技术指南：AI-first 自动编码的快速循环","ja":"VCF Setup Guide: AIエージェントによる高速ループ","ko":"VCF 설정 가이드: AI-first 자동 코딩의 빠른 루프","es":"Guía de configuración de vcf para codificación autónoma","fr":"Guide de mise en route de vcf pour la codification autonome","de":"Einrichtungsleitfaden für vcf zur autonomen Codierung","pt":"Guia de Configuraç