INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kks0488/vibe-codex/vcf', 'vcf', 'kks0488', 'vibe-codex', 'community', 'vcf kks0488 vibe-codex community The vcf skill is a thin alias for vc-phase-loop, enabling fast loops and compatibility with Codex and OpenCode for AI agents and developers. VCF 是一个薄的别名为 vc-phase-loop，用于实现快速循环和零设置的 Codex 与 OpenCode 兼容性 VCF は、vc-phase-loop の薄いエイリアスであり、高速ループとゼロセットアップの Codex および OpenCode との互換性を実現します VCF는 vc-phase-loop의 얇은 별칭으로 빠른 루프와 제로 설정의 Codex 및 OpenCode와의 호환성을 실현합니다 vcf es un alias de vc-phase-loop que permite loops rápidos y zero-setup para la codificación autónoma con Codex y OpenCode vcf est un alias de vc-phase-loop qui permet des boucles rapides et zero-setup pour la codification autonome avec Codex et OpenCode vcf ist ein Alias von vc-phase-loop, der schnelle Loops und Zero-Setup für die autonome Codierung mit Codex und OpenCode ermöglicht A habilidade VCF é um alias para vc-phase-loop, permitindo codificação autônoma com loops rápidos e zero configuração Навык VCF является псевдонимом для vc-phase-loop, позволяющим автономное кодирование с быстрыми циклами и нулевой настройкой المهارة VCF هي اسم مستعار ل vc-phase-loop، مما يسمح بالترميز الذاتي مع الحلقات السريعة وبدون إعداد how to use vcf vcf setup guide vcf vs vc-phase-loop what is vcf vcf install vcf alternative vcf and Codex compatibility autonomous coding with vcf vcf for AI agents VCF 技术 AI-first 自动编码 快速循环 零设置 Codex 兼容性 OpenCode 兼容性 vc-phase-loop 技术 Treats any invocation as a direct call to vc-phase-loop Reads and follows vc-phase-loop skill instructions exactly Does not deviate from vc-phase-loop defaults and execution rules Supports compatibility with Codex and OpenCode Enables fast loops for autonomous coding tasks Requires zero-setup for efficient development vcf is a thin alias for vc-phase-loop, providing a direct call to execute autonomous coding tasks with ease.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jihyukma123/codex-skills-test/log-debug', 'community', 'jihyukma123', 'codex-skills-test', 'jihyukma123/codex-skills-test', 'log-debug', 0, 0, 38, '2026-03-08T01:57:15.378Z', '2026-03-08T02:05:24.963Z', 'dfaaf0c6237a4e2bf2deacb1d2cc4caabed167141687345354c5b387c0362255', '{"id":"jihyukma123/codex-skills-test/log-debug","name":"log-debug","description":{"en":"The log-debug skill helps developers extract the most likely root cause from logs and provides concrete next steps to confirm and fix issues. It benefits developers working with complex systems and logs.","zh":"log-debug 是一个用于测试日志调试的技能，通过解析信号、识别范围和形成假设来提供具体的下一步","ja":"log-debug はエラーログを解析し、根本原因を特定するために設計されたスキルです","ko":"log-debug는 오류 로그를 분석하여根本 원인을 식별하고 구체적인 다음 단계를 제공하는 스킬입니다","es":"log-debug es una herramienta para identificar la causa raíz más probable de los errores y proporcionar pasos concretos para confirmar y solucionar","fr":"log-debug est un outil pour identifier la cause profonde la plus probable des erreurs et fournir des étapes concrètes pour confirmer et résoudre","de":"log-debug ist ein Tool, um die wahrscheinlichste Ursache von Fehlern zu identifizieren und konkrete Schritte zur Bestätigung und Lösung zu liefern","pt":"O log-debug é uma ferramenta de análise de logs que ajuda a identificar causas raiz de erros e fornecer passos concretos para confirmar e corrigir","ru":"Лог-дебаг - это инструмент анализа логов, который помогает выявить коренные причины ошибок и предоставить конкретные шаги для подтверждения и исправления с помощью ИИ Агентов","ar":"لوح-تحليل هو أداة تحليل السجلات التي تساعد في تحديد الأسباب الجذرية للأخطاء وتقديم خطوات ملموسة للتحقق والتصحيح"},"seo":{"title":{"en":"log-debug: Debugging Setup Guide for AI Agents","zh":"log-debug 故障排除指南","ja":"log-debug エラーログ解析ツール","ko":"log-debug 오류 로그 디버깅 가이드","es":"Guía de configuración de log-debug para identificar causa...","fr":"Mise en place de log-debug pour déterminer les causes pro...","de":"Einrichtungsleitfaden für log-debug zur Ermittlung der Ur...","pt":"Guia de Configuração do Log-Debug: Ferramenta de Análise ...","ru":"Настройка лог-дебага: инструмент для анализа логов ИИ Аге...","ar":"دليل إعداد لوح-تحليل: أداة تحليل السجلات للوكلاء الذكية"},"description":{"en":"Unlock efficient log analysis with log-debug. Discover how to extract root causes, link evidence, and fix issues with this AI agent skill. Get started now!","zh":"使用 log-debug 通过解析日志信号、识别范围和形成假设来排除故障","ja":"log-debug を使用してエラーログを解析し、根本原因を特定します","ko":"log-debug를 사용하여 오류 로그를 분석하고根本 원인을 식별하세요","es":"Aprende a utilizar log-debug para extraer la causa raíz más probable de los registros y obtener pasos concretos para confirmar y solucionar","fr":"Découvrez comment utiliser log-debug pour extraire la cause profonde la plus probable des journaux et obtenir des étapes concrètes pour confirmer et résoudre","de":"Erfahren Sie, wie Sie log-debug verwenden, um die wahrscheinlichste Ursache aus den Protokollen zu extrahieren und konkrete Schritte zur Bestätigung und Lösu...","pt":"Aprenda a configurar e utilizar o log-debug para identificar causas raiz de erros e melhorar a depuração de código","ru":"Узнайте, как настроить и использовать лог-дебаг для выявления коренных причин ошибок и улучшения отладки кода с помощью ИИ Агентов","ar":"تعلم كيفية تكوين واستخدام لوح-تحليل لتحديد الأسباب الجذرية للأخطاء وتحسين تصحيح الأخطاء في الكود"},"definition":{"en":"log-debug is a repository testing skill that works on Codex SDK to analyze logs, identify scope, and form hypotheses for efficient debugging.","zh":"log-debug 是一种用于日志调试的 AI 工具","ja":"log-debug はエラーログ解析用の AI エージェントです","ko":"log-debug는 오류 로그 디버깅을 위한 AI 도구입니다","es":"log-debug es una herramienta de depuración que analiza registros para identificar la causa raíz de los errores","fr":"log-debug est un outil de débogage qui analyse les journaux pour identifier la cause profonde des erreurs","de":"log-debug ist ein Debugging-Tool, das Protokolle analysiert, um die Ursache von Fehlern zu identifizieren","pt":"Log-debug é uma técnica de análise de logs que visa extrair a causa mais provável de erros e fornecer evidências","ru":"Лог-дебаг - это метод анализа логов, направленный на выявление наиболее вероятной причины ошибок и предоставление доказательств с помощью ИИ Агентов","ar":"لوح-تحليل هو طريقة لتحليل السجلات تهدف إلى استخراج السبب الأكثر احتمالا للأخطاء وتقديم الأدلة"},"features":{"en":["Parses signals including error type, first failure, and context lines","Identifies scope through service/module, request ID, and time window analysis","Forms and ranks hypotheses by likelihood for targeted debugging","Suggests targeted checks or repro steps for issue confirmation","Proposes a fix direction and validation step for efficient resolution"],"zh":["解析信号以提取错误类型和上下文","识别范围以确定服务/模块和请求 ID","形成假设并按可能性进行排名","建议有针对性的检查或复现步骤","提供具体的下一步以确认和修复"],"ja":["シグナルを解析してエラータイプとコンテキストを抽出","スコープを識別してサービス/モジュールとリクエスト ID を決定","仮説を形成して可能性順にランク付け","ターゲットを絞ったチェックや再現手順を提案","確認と修復のための具体的な次のステップを提供"],"ko":["오류 유형과 컨텍스트를 추출하기 위한 신호 분석","서비스/모듈과 요청 ID를 결정하기 위한 범위 식별","가능성에 따라 순위가 매겨진 가설 형성","타겟을 좁힌 체크 또는 재현 단계를 제안","확인 및 수정을 위한 구체적인 다음 단계 제공"],"es":["Análisis de señales de error para identificar la causa raíz","Identificación del alcance del error para proporcionar pasos concretos","Formulación de hipótesis y clasificación por probabilidad","Propuesta de pasos de comprobación y reproducción","Propuesta de dirección de solución y validación"],"fr":["Analyse des signaux d''erreur pour identifier la cause profonde","Identification de la portée de l''erreur pour fournir des étapes concrètes","Formulation d''hypothèses et classification par probabilité","Proposition d''étapes de vérification et de reproduction","Proposition de direction de solution et de validation"],"de":["Analyse von Fehlersignalen zur Identifizierung der Ursache","Identifizierung des Fehlerrahmens zur Bereitstellung konkreter Schritte","Formulierung von Hypothesen und Klassifizierung nach Wahrscheinlichkeit","Vorschlag von Überprüfungs- und Reproduktionsschritten","Vorschlag von Lösungsrichtung und Validierung"],"pt":["Extração da causa raiz de erros","Identificação do escopo de erros","Formação de hipóteses e classificação por probabilidade","Sugestão de verificações ou reprodução de erros","Proposta de direção de correção e validação"],"ru":["Выявление коренной причины ошибок","Определение объема ошибок","Формирование гипотез и ранжирование по вероятности","Предложение проверок или воспроизведения ошибок","Предложение направления исправления и проверки с помощью ИИ Агентов"],"ar":["استخراج السبب الجذري للأخطاء","تحديد نطاق الأخطاء","تشكيل فرضيات وتصنيفها حسب الاحتمالية","اقتراح فحص أو إعادة إنتاج الأخطاء","اقتراح اتجاه التصحيح والتأكيد"]},"keywords":{"en":["how to use log-debug","log-debug alternative","log-debug setup guide","what is log-debug","log-debug vs debugging tools","log-debug install for Codex SDK"],"zh":["log-debug","AI 工具","日志调试","错误分析","故障排除","日志信号解析","范围识别","假设形成","下一步"],"ja":["log-debug","AI エージェント","エラーログ解析","エラータイプ","コンテキスト","スコープ識別","仮説形成","次のステップ"],"ko":["log-debug","AI 도구","오류 로그 디버깅","오류 분석","故障 해결","로그 신호 분석","범위 식별","가설 형성","다음 단계"],"es":["log-debug","depuración de registros","identificación de causas raíz","análisis de señales de error","herramientas de depuración","solución de errores","Herramientas de IA para desarrolladores","Agentes de IA para la depuración"],"fr":["log-debug","débogage de journaux","identification de causes profondes","analyse de signaux d''erreur","outils de débogage","résolution d''erreurs","Outils d''IA pour les développeurs","Agents d''IA pour le débogage"],"de":["log-debug","Debugging von Protokollen","Identifizierung von Ursachen","Analyse von Fehlersignalen","Debugging-Tools","Fehlerlösung","IA-Tools für Entwickler","IA-Agents für das Debugging"],"pt":["log-debug","análise de logs","depuração de código","identificação de erros","correção de erros","ferramentas de desenvolvimento","tecnologias de desenvolvimento","desenvolvimento de software"],"ru":["лог-дебаг","анализ логов","отладка кода","выявление ошибок","исправление ошибок","инструменты разработки","технологии разработки","разработка программного обеспечения","ИИ Агенты"],"ar":["لوح-تحليل","تحليل السجلات","تصحيح الأخطاء في الكود","تحديد الأخطاء","تصحيح الأخطاء","أدوات تطوير","تقنيات تطوير","تطوير البرمجيات","الوكلاء الذكية"]}},"owner":"jihyukma123","repo":"codex-skills-test","repoPath":"jihyukma123/codex-skills-test","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.378Z","topics":[],"category":"community","skillMd":{"name":"log-debug","description":"Analyze logs, stack traces, and error output to diagnose issues. Use when asked to debug logs, analyze stack trace, or why is this error happening.","bodyPreview":"# Log Debug\n\n## Goals\n\n- Extract the most likely root cause from logs.\n- Link evidence to hypotheses.\n- Provide concrete next steps to confirm and fix.\n\n## Workflow\n\n1. Parse signal: error type, first failure, and context lines.\n2. Identify scope: service/module, request id, time window.\n3. Form hypotheses and rank by likelihood.\n4. Suggest targeted checks or repro steps.\n5. Propose a fix direction and validation step.\n\n## Output Format\n\n- **Likely cause**: 1–2 sentences.\n- **Evidence**: quoted","body":"# Log Debug\n\n## Goals\n\n- Extract the most likely root cause from logs.\n- Link evidence to hypotheses.\n- Provide concrete next steps to confirm and fix.\n\n## Workflow\n\n1. Parse signal: error type, first failure, and context lines.\n2. Identify scope: service/module, request id, time window.\n3. Form hypotheses and rank by likelihood.\n4. Suggest targeted checks or repro steps.\n5. Propose a fix direction and validation step.\n\n## Output Format\n\n- **Likely cause**: 1–2 sentences.\n- **Evidence**: quoted log lines or stack frames.\n- **Next steps**: numbered list of checks.\n- **Fix direction**: brief recommendation.\n"},"lastSynced":"2026-03-08T02:05:24.963Z","agentAnalysis":{"suitability":{"en":"Perfect for Technical Support Agents needing advanced log analysis capabilities to extract root causes and provide concrete next steps.","zh":"非常适合需要高级日志分析能力的技术支持代理，以提取根因并提供具体的下一步措施。","ja":"高度なログ分析機能を必要とするテクニカルサポートエージェントに最適で、根本原因を抽出し、具体的な次のステップを提供します。","ko":"고급 로그 분석 기능이 필요한 기술 지원 에이전트에게 적합하여 근본 원인을 추출하고 구체적인 다음 단계를 제공합니다.","es":"Perfecto para agentes de soporte técnico que necesitan capacidades de análisis de registros avanzadas para extraer causas raíz y proporcionar pasos concretos siguientes.","fr":"Parfait pour les agents de support technique ayant besoin de capacités d''analyse de journaux avancées pour extraire les causes profondes et fournir des étapes concrètes suivantes.","de":"Perfekt für technische Support-Agenten, die erweiterte Protokollanalysefunktionen benötigen, um Ursachen zu ermitteln und konkrete nächste Schritte bereitzustellen.","pt":"Perfeito para Agentes de Suporte Técnico que necessitam de capacidades avançadas de análise de log para extrair causas raiz e fornecer próximos passos concretos.","ru":"Идеально подходит для технических агентов поддержки, которым требуются продвинутые возможности анализа журналов для выявления коренных причин и предоставления конкретных следующих шагов.","ar":"مثالي لوكلاء الدعم الفني الذين يحتاجون إلى قدرات تحليل سجل متقدمة لاستخراج الأسباب الجذرية وتقديم الخطوات التالية المحددة."},"recommendation":{"en":"Empowers agents to parse error signals, identify scopes, and form hypotheses to confirm and fix issues, utilizing log data to provide targeted checks and repro steps, all while linking evidence to hypotheses and proposing fix directions with validation steps.","zh":"赋予代理分析错误信号、识别范围、形成假设以确认和修复问题的能力，利用日志数据提供有针对性的检查和重现步骤，同时将证据链接到假设并提出带有验证步骤的修复方向。","ja":"エージェントにエラーシグナルを分析し、スコープを特定し、問題を確認および修復するための仮説を形成する能力を提供し、ログデータを使用してターゲットとなるチェックと再現手順を提供し、証拠を仮説にリンクし、検証手順を伴う修復方向を提案します。","ko":"에이전트가 오류 신호를 분석하고 범위를 식별하고 문제를 확인 및 수정하기 위한 가설을 형성할 수 있는 능력을 제공하여 로그 데이터를 사용하여 타겟이 되는 확인 및 재현 단계를 제공하고 증거를 가설에 연결하여 검증 단계가 포함된 수정 方向을 제안합니다.","es":"Habilita a los agentes a parsear señales de error, identificar ámbitos y formar hipótesis para confirmar y solucionar problemas, utilizando datos de registros para proporcionar controles dirigidos y pasos de reproducción, todo mientras enlaza evidencia a hipótesis y propone direcciones de solución con pasos de validación.","fr":"Permet aux agents d''analyser les signaux d''erreur, d''identifier les étendues et de former des hypothèses pour confirmer et résoudre les problèmes, en utilisant les données de journal pour fournir des vérifications ciblées et des étapes de reproduction, tout en reliant les preuves aux hypothèses et en proposant des directions de correction avec des étapes de validation.","de":"Ermächtigt Agenten, Fehlermeldungen zu parsen, Bereiche zu identifizieren und Hypothesen zu bilden, um Probleme zu bestätigen und zu beheben, indem Protokoll-Daten verwendet werden, um gezielte Überprüfungen und Reproduktionsschritte bereitzustellen, während Beweise mit Hypothesen verknüpft und Korrekturrichtungen mit Validierungsschritten vorgeschlagen werden.","pt":"Habilita os agentes a analisar sinais de erro, identificar escopos e formular hipóteses para confirmar e corrigir problemas, utilizando dados de log para fornecer verificações direcionadas e etapas de reprodução, ligando evidências a hipóteses e propondo direções de correção com etapas de validação.","ru":"Наделяет агентов возможностью парсить сигналы ошибок, определять объемы и формулировать гипотезы для подтверждения и исправления проблем, используя лог-данные для предоставления целенаправленных проверок и шагов воспроизведения, связывая доказательства с гипотезами и предлагая направления исправления с шагами проверки.","ar":"يسمح للوكلاء بتحليل إشارات الخطأ وتحديد النطاقات وتكوين فرضيات لconfirmation وتصحيح المشكلات، باستخدام بيانات السجل لتوفير فحوصات موجهة وخطوات إعادة الإنتاج، وربط الأدلة بالفرضيات واقتراح اتجاهات الإصلاح مع خطوات التحقق."},"useCases":{"en":["Debugging complex system issues","Analyzing error logs to identify root causes","Generating targeted checks for issue reproduction"],"zh":["调试复杂系统问题","分析错误日志以识别根因","为问题再现生成有针对性的检查"],"ja":["複雑なシステムの問題をデバッグする","エラーログを分析して根本原因を特定する","問題の再現のためにターゲットとなるチェックを生成する"],"ko":["복잡한 시스템 문제를 디버깅하는 것","오류 로그를 분석하여 근본 원인을 식별하는 것","문제 재현을 위한 타겟이 되는 확인을 생성하는 것"],"es":["Depuración de problemas de sistema complejos","Análisis de registros de error para identificar causas raíz","Generación de controles dirigidos para la reproducción de problemas"],"fr":["Débogage de problèmes de système complexes","Analyse des journaux d''erreur pour identifier les causes profondes","Génération de vérifications ciblées pour la reproduction de problèmes"],"de":["Fehlersuche bei komplexen Systemproblemen","Analyse von Fehlerprotokollen zur Ermittlung von Ursachen","Erzeugung gezielter Überprüfungen für die Reproduktion von Problemen"],"pt":["Depuração de problemas complexos de sistema","Análise de logs de erro para identificar causas raiz","Geração de verificações direcionadas para reprodução de problemas"],"ru":["Отладка сложных системных проблем","Анализ логов ошибок для выявления коренных причин","Генерация целенаправленных проверок для воспроизведения проблем"],"ar":["تصحيح أخطاء مشكلات النظم المعقدة","تحليل سجلات الأخطاء لتحديد الأسباب الجذرية","توليد فحوصات موجهة لإعادة إنتاج المشكلات"]},"limitations":{"en":["Requires access to log data","Limited to text-based log analysis"],"zh":["需要访问日志数据","仅限基于文本的日志分析"],"ja":["ログデータへのアクセスが必要","テキストベースのログ分析のみ"],"ko":["로그 데이터에 대한 액세스가 필요","텍스트 기반 로그 분석만"],"es":["Requiere acceso a datos de registros","Limitado al análisis de registros basado en texto"],"fr":["Nécessite l''accès aux données de journal","Limité à l''analyse de journal basée sur le texte"],"de":["Erfordert Zugriff auf Protokoll-Daten","Begrenzt auf textbasierte Protokollanalyse"],"pt":["Requer acesso a dados de log","Limitado à análise de log baseada em texto"],"ru":["Требует доступа к лог-данным","Ограничен анализом логов на основе текста"],"ar":["يتطلب الوصول إلى بيانات السجل","محدود بالتحليل القائم على النص للسجل"]},"version":4},"contentHash":"dfaaf0c6237a4e2bf2deacb1d2cc4caabed167141687345354c5b387c0362255","qualityScore":38}');
