INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jihyukma123/codex-skills-test/log-debug', 'log-debug', 'jihyukma123', 'codex-skills-test', 'community', 'log-debug jihyukma123 codex-skills-test community The log-debug skill helps developers extract the most likely root cause from logs and provides concrete next steps to confirm and fix issues. It benefits developers working with complex systems and logs. log-debug 是一个用于测试日志调试的技能，通过解析信号、识别范围和形成假设来提供具体的下一步 log-debug はエラーログを解析し、根本原因を特定するために設計されたスキルです log-debug는 오류 로그를 분석하여根本 원인을 식별하고 구체적인 다음 단계를 제공하는 스킬입니다 log-debug es una herramienta para identificar la causa raíz más probable de los errores y proporcionar pasos concretos para confirmar y solucionar log-debug est un outil pour identifier la cause profonde la plus probable des erreurs et fournir des étapes concrètes pour confirmer et résoudre log-debug ist ein Tool, um die wahrscheinlichste Ursache von Fehlern zu identifizieren und konkrete Schritte zur Bestätigung und Lösung zu liefern O log-debug é uma ferramenta de análise de logs que ajuda a identificar causas raiz de erros e fornecer passos concretos para confirmar e corrigir Лог-дебаг - это инструмент анализа логов, который помогает выявить коренные причины ошибок и предоставить конкретные шаги для подтверждения и исправления с помощью ИИ Агентов لوح-تحليل هو أداة تحليل السجلات التي تساعد في تحديد الأسباب الجذرية للأخطاء وتقديم خطوات ملموسة للتحقق والتصحيح how to use log-debug log-debug alternative log-debug setup guide what is log-debug log-debug vs debugging tools log-debug install for Codex SDK log-debug AI 工具 日志调试 错误分析 故障排除 日志信号解析 范围识别 假设形成 下一步 Parses signals including error type, first failure, and context lines Identifies scope through service/module, request ID, and time window analysis Forms and ranks hypotheses by likelihood for targeted debugging Suggests targeted checks or repro steps for issue confirmation Proposes a fix direction and validation step for efficient resolution log-debug is a repository testing skill that works on Codex SDK to analyze logs, identify scope, and form hypotheses for efficient debugging.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('xx-suzuki/astro-sandbox/source-reviewer', 'community', 'xx-suzuki', 'astro-sandbox', 'xx-suzuki/astro-sandbox', 'source-reviewer', 0, 0, 38, '2026-03-08T01:57:15.379Z', '2026-03-08T02:05:30.007Z', 'e916b945e8d42320e7dd23fb9204b6121f0bca13e5e7dfdd4cca669e59bd05ea', '{"id":"xx-suzuki/astro-sandbox/source-reviewer","name":"source-reviewer","description":{"en":"The source-reviewer skill helps developers review code diffs, prioritize risk, and report findings. It benefits development teams by ensuring type safety, FLOCSS/BEM naming, and proper component placement.","zh":"Source Reviewer是一种AI代码审查工具，帮助开发者优化代码结构和性能，确保代码安全性和质量。","ja":"Source ReviewerはAIエージェントによるコードレビュー工具です。コードの品質と安全性を向上させ、性能を最適化します。","ko":"Source Reviewer는 AI 코드 리뷰 도구로서 개발자가 코드 구조와 성능을 최적화하고 코드의 안전성과 품질을 보장하는 데 도움을 줍니다.","es":"Source-reviewer es una herramienta para revisar diffs y priorizar riesgos en el código, enfocada en regresiones de comportamiento y seguridad de tipos","fr":"Source-reviewer est un outil pour examiner les diffs et prioriser les risques dans le code, axé sur les régressions de comportement et la sécurité des types","de":"Source-reviewer ist ein Tool zur Überprüfung von Diffs und Priorisierung von Risiken im Code, mit Fokus auf Verhaltensrückentwicklungen und Typsicherheit","pt":"O source-reviewer é uma ferramenta de revisão de código que ajuda a identificar problemas de segurança e melhorar a qualidade do código.","ru":"ИИ Агент source-reviewer - это инструмент код ревью, который помогает выявить проблемы безопасности и улучшить качество кода.","ar":"أداة الفحص المصدرية source-reviewer هي أداة لمراجعة الكود تساعد في تحديد مشاكل الأمان وتحسين جودة الكود."},"seo":{"title":{"en":"source-reviewer: Code Review Setup Guide | AI Agent Skill","zh":"Source Reviewer Setup Guide - AI代码审查工具","ja":"Source Reviewer ベストプラクティス - AIエージェントによるコードレビュー","ko":"Source Reviewer 사용법 - AI 코드 리뷰 도구","es":"Guía de configuración de source-reviewer para revisión de...","fr":"Configurer source-reviewer pour la revue de code","de":"Einrichtungsleitfaden für source-reviewer zur Code-Überpr...","pt":"Guia de Configuração do source-reviewer para Análise de C...","ru":"Настройка ИИ Агента source-reviewer для Код Ревью","ar":"دليل إعداد أداة الفحص المصدرية source-reviewer"},"description":{"en":"Unlock efficient code reviews with source-reviewer! Learn how to prioritize risk, report findings, and ensure type safety in your projects. Get started now!","zh":"了解Source Reviewer的功能和特点，提高代码质量和安全性。使用AI代码审查工具，优化代码结构和性能。","ja":"Source Reviewerの機能と特徴をご紹介します。AIエージェントを使用してコードの品質と安全性を向上させましょう。","ko":"Source Reviewer의 기능과 특징을 알아보세요. AI 코드 리뷰 도구를 사용하여 코드 품질과 성능을 개선하세요.","es":"Aprende a utilizar source-reviewer para revisar diffs y priorizar riesgos en tu código con nuestras mejores prácticas","fr":"Découvrez comment utiliser source-reviewer pour examiner les diffs et prioriser les risques dans votre code","de":"Erfahren Sie, wie Sie source-reviewer einsetzen, um Diffs zu überprüfen und Risiken in Ihrem Code zu priorisieren","pt":"Aprenda a configurar o source-reviewer para análise de código e melhore a qualidade do seu código com essa ferramenta de revisão de código","ru":"Узнайте, как настроить ИИ Агент source-reviewer для код ревью и улучшите качество вашего кода с помощью этого инструмента","ar":"تعرف على كيفية إعداد أداة الفحص المصدرية source-reviewer لتحسين جودة كودك مع هذه الأداة لمراجعة الكود"},"definition":{"en":"source-reviewer is a code review tool that analyzes diffs, identifies behavioral regressions, and checks for type safety, FLOCSS/BEM naming, and SCSS structure","zh":"Source Reviewer是一种AI代码审查工具，用于优化代码结构和性能，确保代码安全性和质量。","ja":"Source Reviewerは、コードの品質と安全性を向上させるために使用されるAIエージェントによるコードレビュー工具です。","ko":"Source Reviewer는 코드의 안전성과 품질을 보장하기 위해 사용되는 AI 코드 리뷰 도구입니다.","es":"Source-reviewer es una herramienta de revisión de código que ayuda a identificar riesgos y priorizar cambios","fr":"Source-reviewer est un outil de revue de code qui aide à identifier les risques et à prioriser les modifications","de":"Source-reviewer ist ein Code-Überprüfungstool, das hilft, Risiken zu identifizieren und Änderungen zu priorisieren","pt":"O source-reviewer é uma ferramenta de análise de código que realiza revisões de código para identificar problemas de segurança e melhorar a qualidade.","ru":"ИИ Агент source-reviewer - это инструмент, который выполняет код ревью для выявления проблем безопасности и улучшения качества кода.","ar":"أداة الفحص المصدرية source-reviewer هي أداة تحليل كود تقوم بمراجعة الكود لتحديد مشاكل الأمان وتحسين الجودة."},"features":{"en":["Reads diffs and prioritizes risk based on severity","Reports findings in a list format with file references","Checks for missing tests or checks, ensuring comprehensive code review","Analyzes type safety and usage of ''any'' type","Verifies FLOCSS/BEM naming and SCSS structure for consistency"],"zh":["支持Diff代码审查","优化代码结构和性能","确保代码安全性和质量","支持FLOCSS/BEM命名和SCSS结构","组件placement优化"],"ja":["Diffコードレビューのサポート","コード構造とパフォーマンスの最適化","コードの安全性と品質の確保","FLOCSS/BEM命名とSCSS構造のサポート","コンポーネント配置の最適化"],"ko":["Diff 코드 리뷰 지원","코드 구조와 성능의 최적화","코드의 안전성과 품질의 보장","FLOCSS/BEM命名과SCSS구조 지원","컴포넌트 배치의 최적화"],"es":["Revisión de diffs para identificar regresiones de comportamiento","Análisis de seguridad de tipos y uso de ''any''","Verificación de naming y estructura SCSS con FLOCSS/BEM","Análisis de flujo de estado y datos","Informes de hallazgos con referencias a archivos"],"fr":["Examen de diffs pour identifier les régressions de comportement","Analyse de la sécurité des types et de l''utilisation de ''any''","Vérification de la nomination et de la structure SCSS avec FLOCSS/BEM","Analyse du flux d''état et de données","Rapports de découverte avec des références à des fichiers"],"de":["Überprüfung von Diffs zur Identifizierung von Verhaltensrückentwicklungen","Analyse der Typsicherheit und der Verwendung von ''any''","Überprüfung der Benennung und der SCSS-Struktur mit FLOCSS/BEM","Analyse des Zustands- und Datenflusses","Berichte über Funde mit Dateireferenzen"],"pt":["Análise de diffs para priorizar riscos","Relatório de findings ordenados por gravidade","Verificação de regressões comportamentais","Análise de segurança de tipos e uso de ''any''","Verificação de naming e estrutura SCSS","Análise de fluxo de estado e dados"],"ru":["Анализ diffs для приоритизации рисков","Отчет о findings, упорядоченный по уровню опасности","Проверка поведенческих регрессий","Анализ безопасности типов и использования ''any''","Проверка именования и структуры SCSS","Анализ потока состояния и данных"],"ar":["تحليل الاختلافات لترتيب المخاطر","تقرير عن النتائج المترتبة على ترتيب الخطورة","فحص انحدارات السلوك","تحليل أمان الأنواع واستخدام ''any''","فحص التسمية وهيكل SCSS","تحليل تدفق الحالة والبيانات"]},"keywords":{"en":["how to use source-reviewer","source-reviewer setup guide","code review tools for AI agents","source-reviewer vs code reviewers","source-reviewer install","what is source-reviewer","source-reviewer alternative","code diff analysis with source-reviewer","type safety checking with source-reviewer"],"zh":["AI代码审查工具","代码优化","代码安全性","代码质量","Diff代码审查","FLOCSS/BEM命名","SCSS结构","组件placement"],"ja":["AIエージェント","コードレビュー","コード最適化","コードの安全性","コードの品質","Diffコードレビュー","FLOCSS/BEM命名","SCSS構造","コンポーネント配置"],"ko":["AI 코드 리뷰 도구","코드 최적화","코드 안전성","코드 품질","Diff 코드 리뷰","FLOCSS/BEM命名","SCSS구조","컴포넌트 배치"],"es":["herramientas de revisión de código","revisión de diffs","seguridad de tipos","FLOCSS","BEM","SCSS","flujo de estado y datos","informes de hallazgos"],"fr":["outils de revue de code","examen de diffs","sécurité des types","FLOCSS","BEM","SCSS","flux d''état et de données","rapports de découverte"],"de":["Code-Überprüfungstools","Diffs-Überprüfung","Typsicherheit","FLOCSS","BEM","SCSS","Zustands- und Datenfluss","Berichte über Funde"],"pt":["source-reviewer","análise de código","revisão de código","segurança de código","qualidade de código","ferramentas de desenvolvimento","desenvolvimento de software","codificação segura"],"ru":["ИИ Агент source-reviewer","код ревью","анализ кода","безопасность кода","качество кода","инструменты разработки","разработка программного обеспечения","безопасная кодировка"],"ar":["أداة الفحص المصدرية source-reviewer","مراجعة الكود","تحليل الكود","أمان الكود","جودة الكود","أدوات التطوير","تطوير البرمجيات","تدوين آمن"]}},"owner":"xx-suzuki","repo":"astro-sandbox","repoPath":"xx-suzuki/astro-sandbox","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.379Z","topics":[],"category":"community","skillMd":{"name":"source-reviewer","description":"修正差分レビューでバグ・回帰・設計逸脱・命名違反の指摘が必要な時に使う。Astro/TypeScript/SCSS(FLOCSS/BEM)の規約違反や影響範囲の確認が必要な場面で使う。","bodyPreview":"# Diff Reviewer\n\n## Quick use\n- Read diffs and prioritize risk\n- Report findings first, ordered by severity\n- Call out missing tests or checks\n\n## Focus areas\n- Behavioral regressions\n- Type safety and `any`\n- FLOCSS/BEM naming and SCSS structure\n- Component placement (component vs project)\n- State/data flow changes\n\n## Output format\n- Findings list with file references\n- Open questions or assumptions\n- Brief change summary (optional)\n\n## References\n- See `references/review-checklist.md`","body":"# Diff Reviewer\n\n## Quick use\n- Read diffs and prioritize risk\n- Report findings first, ordered by severity\n- Call out missing tests or checks\n\n## Focus areas\n- Behavioral regressions\n- Type safety and `any`\n- FLOCSS/BEM naming and SCSS structure\n- Component placement (component vs project)\n- State/data flow changes\n\n## Output format\n- Findings list with file references\n- Open questions or assumptions\n- Brief change summary (optional)\n\n## References\n- See `references/review-checklist.md`\n"},"lastSynced":"2026-03-08T02:05:30.007Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents requiring advanced diff analysis and risk prioritization capabilities.","zh":"适用于需要高级diff分析和风险优先级排序能力的代码审查代理。","ja":"コードレビューエージェントが高度なdiff分析とリスク優先順位付け機能を必要とする場合に適しています。","ko":"고급 diff 분석 및 위험 우선 순위 지정 기능이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Ideal para agentes de revisión de código que requieren un análisis de diferencias avanzado y capacidades de priorización de riesgos.","fr":"Idéal pour les agents de révision de code nécessitant une analyse de différences avancée et des capacités de priorisation des risques.","de":"Ideal für Code-Review-Agents, die eine erweiterte Differenzanalyse und Risikopriorisierungsfunktionen erfordern.","pt":"Ideal para Agentes de Revisão de Código que requerem análise de diff avançada e capacidades de priorização de risco.","ru":"Идеально для Агентов Кодового Обзора, требующих расширенного анализа diff и возможностей приоритизации риска.","ar":"مثالي للوكلاء المراجعة الكود الذين يحتاجون إلى تحليل متقدم وتحديد الأولويات لمخاطر"},"recommendation":{"en":"Empowers agents to ensure type safety, enforce FLOCSS/BEM naming conventions, and validate component placement using SCSS structure analysis, while also identifying behavioral regressions and state/data flow changes.","zh":"赋予代理确保类型安全、执行FLOCSS/BEM命名约定、使用SCSS结构分析验证组件放置，同时还可以识别行为回归和状态/数据流更改。","ja":"エージェントがタイプセーフティを確保し、FLOCSS/BEM命名規則を適用し、SCSS構造分析を使用してコンポーネントの配置を検証し、同時に動作の回帰と状態/データフローの変更を特定することを可能にします。","ko":"에이전트가 타입 안전성을 보장하고 FLOCSS/BEM命名 규칙을 적용하며 SCSS 구조 분석을 사용하여 컴포넌트 배치를 검증하는 동시에 동작 회귀 및 상태/데이터 흐름 변경을 식별할 수 있도록 합니다.","es":"Habilita a los agentes para garantizar la seguridad de los tipos, hacer cumplir las convenciones de nomenclatura FLOCSS/BEM y validar la colocación de componentes utilizando el análisis de estructura SCSS, además de identificar regresiones de comportamiento y cambios en el flujo de estado y datos.","fr":"Permet aux agents de garantir la sécurité des types, de faire respecter les conventions de nommage FLOCSS/BEM et de valider le placement de composants en utilisant l''analyse de structure SCSS, tout en identifiant les régressions de comportement et les modifications du flux d''état et de données.","de":"Ermächtigt die Agenten, die Typsicherheit zu gewährleisten, die FLOCSS/BEM-Benennungskonventionen durchzusetzen und die Komponentenplatzierung mithilfe der SCSS-Strukturanalyse zu validieren, während sie auch Verhaltensrückschritte und Änderungen im Zustands-/Datenfluss identifizieren.","pt":"Habilita agentes a garantir segurança de tipo, impor convenções de nomenclatura FLOCSS/BEM, e validar a colocação de componentes usando análise de estrutura SCSS, além de identificar regressões comportamentais e alterações de fluxo de estado/dados.","ru":"Наделяет агентов возможностью обеспечить безопасность типов, соблюдать соглашения об именах FLOCSS/BEM, и проверять размещение компонентов с помощью анализа структуры SCSS, а также выявлять регрессии поведения и изменения потока состояния/данных.","ar":"يمنح الوكلاء القدرة على ضمان سلامة النوع، وفرض اتفاقيات تسمية FLOCSS/BEM، والتحقق من وضع المكونات باستخدام تحليل هيكل SCSS، بالإضافة إلى تحديد الانحدارات السلوكية وتغييرات تدفق الحالة / البيانات"},"useCases":{"en":["Automating code diff reviews for risk prioritization","Generating findings reports with file references and severity ordering","Debugging type safety issues and ''any'' type usage"],"zh":["自动化代码diff审查以进行风险优先级排序","生成文件引用和严重性排序的查找报告","调试类型安全问题和''any''类型的使用"],"ja":["リスク優先順位付けのためにコードdiffレビューを自動化する","ファイル参照と重大度の順序付けを含む調査結果報告を生成する","タイプセーフティの問題と''any''タイプの使用をデバッグする"],"ko":["위험 우선 순위 지정 위해 코드 diff 리뷰를 자동화하는 것","파일 참조 및 심각도 순서를 포함한 조사 결과 보고서 생성","타입 안전성 문제 및 ''any'' 타입 사용을 디버깅하는 것"],"es":["Automatizar las revisiones de diferencias de código para la priorización de riesgos","Generar informes de hallazgos con referencias de archivo y orden de gravedad","Depurar problemas de seguridad de tipos y uso del tipo ''any''"],"fr":["Automatiser les examens de différences de code pour la priorisation des risques","Générer des rapports de constatations avec des références de fichiers et un ordre de gravité","Déboguer les problèmes de sécurité des types et l''utilisation du type ''any''"],"de":["Automatisieren von Code-Differenz-Überprüfungen für die Risikopriorisierung","Erstellen von Berichten über Feststellungen mit Dateireferenzen und Schweregradordnung","Beheben von Typsicherheitsproblemen und ''any''-Typ-Verwendung"],"pt":["Automatizar revisões de diff de código para priorização de risco","Gerar relatórios de descobertas com referências de arquivo e ordenação de gravidade","Depurar problemas de segurança de tipo e uso do tipo ''any''"],"ru":["Автоматизация обзоров diff-кода для приоритизации риска","Генерация отчетов о находках с ссылками на файлы и упорядочением по степени тяжести","Отладка проблем безопасности типов и использования типа ''any''"],"ar":["توفير مراجعات تلقائية لفرق الكود لتحديد الأولويات للمخاطر","توليد تقارير اكتشاف مع مراجع الملفات وترتيب الحدة","تصحيح مشاكل سلامة النوع واستخدام نوع ''أي''"]},"limitations":{"en":["Requires access to code diffs and repository structure","Limited to reviewing code written in languages supporting type safety and SCSS"],"zh":["需要访问代码diff和存储库结构","仅限于审查支持类型安全和SCSS的语言编写的代码"],"ja":["コードdiffとリポジトリ構造へのアクセスが必要","タイプセーフティとSCSSをサポートする言語で書かれたコードのレビューのみ"],"ko":["코드 diff 및 저장소 구조에 대한 액세스가 필요함","타입 안전성 및 SCSS를 지원하는 언어로 작성된 코드의 리뷰만 가능"],"es":["Requiere acceso a las diferencias de código y la estructura del repositorio","Limitado a la revisión de código escrito en lenguajes que admiten la seguridad de los tipos y SCSS"],"fr":["Nécessite un accès aux différences de code et à la structure du référentiel","Limité à la révision de code écrit dans des langages prenant en charge la sécurité des types et SCSS"],"de":["Benötigt Zugriff auf Code-Differenzen und Repository-Struktur","Begrenzt auf die Überprüfung von Code, der in Sprachen geschrieben ist, die die Typsicherheit und SCSS unterstützen"],"pt":["Requer acesso a diffs de código e estrutura de repositório","Limitado a revisar código escrito em linguagens que suportam segurança de tipo e SCSS"],"ru":["Требует доступа к diff-коду и структуре репозитория","Ограничен обзором кода, написанного на языках, поддерживающих безопасность типов и SCSS"],"ar":["يتطلب الوصول إلى فرق الكود وهيكل المستودع","محدود بالمراجعة الكود المكتوب بلغات تدعم سلامة النوع و SCSS"]},"version":4},"contentHash":"e916b945e8d42320e7dd23fb9204b6121f0bca13e5e7dfdd4cca669e59bd05ea","qualityScore":38}');
