INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('xx-suzuki/astro-sandbox/source-reviewer', 'source-reviewer', 'xx-suzuki', 'astro-sandbox', 'community', 'source-reviewer xx-suzuki astro-sandbox community The source-reviewer skill helps developers review code diffs, prioritize risk, and report findings. It benefits development teams by ensuring type safety, FLOCSS/BEM naming, and proper component placement. Source Reviewer是一种AI代码审查工具，帮助开发者优化代码结构和性能，确保代码安全性和质量。 Source ReviewerはAIエージェントによるコードレビュー工具です。コードの品質と安全性を向上させ、性能を最適化します。 Source Reviewer는 AI 코드 리뷰 도구로서 개발자가 코드 구조와 성능을 최적화하고 코드의 안전성과 품질을 보장하는 데 도움을 줍니다. Source-reviewer es una herramienta para revisar diffs y priorizar riesgos en el código, enfocada en regresiones de comportamiento y seguridad de tipos Source-reviewer est un outil pour examiner les diffs et prioriser les risques dans le code, axé sur les régressions de comportement et la sécurité des types Source-reviewer ist ein Tool zur Überprüfung von Diffs und Priorisierung von Risiken im Code, mit Fokus auf Verhaltensrückentwicklungen und Typsicherheit O source-reviewer é uma ferramenta de revisão de código que ajuda a identificar problemas de segurança e melhorar a qualidade do código. ИИ Агент source-reviewer - это инструмент код ревью, который помогает выявить проблемы безопасности и улучшить качество кода. أداة الفحص المصدرية source-reviewer هي أداة لمراجعة الكود تساعد في تحديد مشاكل الأمان وتحسين جودة الكود. how to use source-reviewer source-reviewer setup guide code review tools for AI agents source-reviewer vs code reviewers source-reviewer install what is source-reviewer source-reviewer alternative code diff analysis with source-reviewer type safety checking with source-reviewer AI代码审查工具 代码优化 代码安全性 代码质量 Diff代码审查 FLOCSS/BEM命名 SCSS结构 组件placement Reads diffs and prioritizes risk based on severity Reports findings in a list format with file references Checks for missing tests or checks, ensuring comprehensive code review Analyzes type safety and usage of ''any'' type Verifies FLOCSS/BEM naming and SCSS structure for consistency source-reviewer is a code review tool that analyzes diffs, identifies behavioral regressions, and checks for type safety, FLOCSS/BEM naming, and SCSS structure');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Enisa200467/EnisaHealingAndMassage/edit-page-content', 'community', 'Enisa200467', 'EnisaHealingAndMassage', 'Enisa200467/EnisaHealingAndMassage', 'edit-page-content', 0, 0, 38, '2026-03-08T01:57:15.379Z', '2026-03-08T02:05:32.618Z', '09dced2eabd0f7d6c3cdbd7d9f695a2dd921ef2b61955cebe44dea0d901b19b4', '{"id":"Enisa200467/EnisaHealingAndMassage/edit-page-content","name":"edit-page-content","description":{"en":"The edit-page-content skill allows developers to automatically correct Dutch grammar and flow in existing page content, modifying only textual content in .md and .vue files. This skill benefits developers working with Markdown and Vue.js files.","zh":"AI编辑页面内容技能，用于编辑现有页面内容，自动修复Dutch语法和流畅度","ja":"ページコンテンツを編集するAIエージェントのスキルです。Dutch語の文法と流暢性を自動的に修正します","ko":"페이지 콘텐츠를 편집하는 AI 스킬로 Dutch 문법 및 흐름을 자동으로 수정합니다","es":"Edite contenido de página existente con herramientas de AI, corrigiendo la gramática y el flujo en neerlandés de forma automática","fr":"Éditez du contenu de page existant avec des outils d''IA, en corrigeant la grammaire et le flux en néerlandais de manière automatique","de":"Bearbeiten Sie bestehende Seiteninhalte mit KI-Tools, indem Sie die Grammatik und den Fluss in Niederländisch automatisch korrigieren","pt":"O agente de edição de conteúdo de página é uma ferramenta que edita o conteúdo existente de páginas, corrigindo a gramática e o fluxo de texto em arquivos MD e Vue.","ru":"ИИ Агент для редактирования содержимого страницы - это инструмент, который редактирует существующее содержимое страниц, исправляя грамматику и поток текста в файлах MD и Vue.","ar":"وكيل تحرير محتوى الصفحة هو أداة لتحرير المحتوى الحالي للصفحات، وتصحيح القواعد والنص في الملفات MD و Vue."},"seo":{"title":{"en":"edit-page-content: Automated Dutch Grammar Correction for...","zh":"AI编辑页面内容设置指南","ja":"ページコンテンツ編集のベストプラクティス - AI