INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Enisa200467/EnisaHealingAndMassage/edit-page-content', 'edit-page-content', 'Enisa200467', 'EnisaHealingAndMassage', 'community', 'edit-page-content Enisa200467 EnisaHealingAndMassage community The edit-page-content skill allows developers to automatically correct Dutch grammar and flow in existing page content, modifying only textual content in .md and .vue files. This skill benefits developers working with Markdown and Vue.js files. AI编辑页面内容技能，用于编辑现有页面内容，自动修复Dutch语法和流畅度 ページコンテンツを編集するAIエージェントのスキルです。Dutch語の文法と流暢性を自動的に修正します 페이지 콘텐츠를 편집하는 AI 스킬로 Dutch 문법 및 흐름을 자동으로 수정합니다 Edite contenido de página existente con herramientas de AI, corrigiendo la gramática y el flujo en neerlandés de forma automática Éditez du contenu de page existant avec des outils d''IA, en corrigeant la grammaire et le flux en néerlandais de manière automatique Bearbeiten Sie bestehende Seiteninhalte mit KI-Tools, indem Sie die Grammatik und den Fluss in Niederländisch automatisch korrigieren O agente de edição de conteúdo de página é uma ferramenta que edita o conteúdo existente de páginas, corrigindo a gramática e o fluxo de texto em arquivos MD e Vue. ИИ Агент для редактирования содержимого страницы - это инструмент, который редактирует существующее содержимое страниц, исправляя грамматику и поток текста в файлах MD и Vue. وكيل تحرير محتوى الصفحة هو أداة لتحرير المحتوى الحالي للصفحات، وتصحيح القواعد والنص في الملفات MD و Vue. how to use edit-page-content edit-page-content alternative edit-page-content setup guide what is edit-page-content edit-page-content vs grammarly edit-page-content install for Vue.js automated Dutch grammar correction edit-page-content for developers edit-page-content Markdown support AI编辑页面内容 自动修复Dutch语法 页面内容编辑 AI工具 Vue编辑 MD文件编辑 Automatically corrects Dutch grammar and flow in .md files Modifies textual content in Vue.js components (.vue files) Preserves HTML structure, Vue component structure, and layout markup Works within content/behandelingen/ and app/features/ directories Supports editing of headings, paragraphs, labels, and button text edit-page-content is a specialized AI agent skill designed to edit existing page content, focusing on correcting Dutch grammar and flow in Markdown and Vue.js files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('StrayDragon/llman/openspec-archive-change', 'community', 'StrayDragon', 'llman', 'StrayDragon/llman', 'openspec-archive-change', 0, 0, 38, '2026-03-08T01:57:15.382Z', '2026-03-08T02:05:42.315Z', '7a25c7baa0427afe72dbfce72323d0600b6b7678b843476c0596d74373cb7710', '{"id":"StrayDragon/llman/openspec-archive-change","name":"openspec-archive-change","description":{"en":"The openspec-archive-change skill automates archive management for AI agents, allowing developers to efficiently manage changes and artifacts using CLI commands. It benefits developers working with experimental workflows.","zh":"openspec-archive-change 是一个用于归档已完成变更和管理配置的工具，支持 CLI 命令和工件完成状态检查","ja":"openspec-archive-change は、完了した変更をアーカイブ化し、設定を管理するためのツールです - CLI コマンドとアーティファクトの完了状態の確認をサポート","ko":"openspec-archive-change는 완료된 변경을 아카이브하고 설정을 관리하기 위한 도구입니다 - CLI 명령어와 아티팩트 완료 상태 확인을 지원","es":"Openspec-archive-change es una habilidad para gestionar cambios en flujos de trabajo de IA. Permite a los usuarios seleccionar y archivar cambios con CLI.","fr":"Openspec-archive-change est une compétence pour gérer les changements dans les flux de travail d''IA. Il permet aux utilisateurs de sélectionner et d''archiver des changements avec CLI.","de":"Openspec-archive-change ist eine Fähigkeit zur Verwaltung von Änderungen in KI-Arbeitsabläufen. Sie ermöglicht es Benutzern, Änderungen mit CLI auszuwählen und zu archivieren.","pt":"O openspec-archive-change é uma ferramenta de gerenciamento de arquivos que permite aos desenvolvedores gerenciar alterações de forma eficiente","ru":"openspec-archive-change - это инструмент управления файлами, который позволяет разработчикам эффективно управлять изменениями","ar":"openspec-archive-change هو أداة لإدارة الملفات تسمح للمطورين بإدارة التغييرات بفعالية"},"seo":{"title":{"en":"openspec-archive-change: Archive Management Se