INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('StrayDragon/llman/openspec-archive-change', 'openspec-archive-change', 'StrayDragon', 'llman', 'community', 'openspec-archive-change StrayDragon llman community The openspec-archive-change skill automates archive management for AI agents, allowing developers to efficiently manage changes and artifacts using CLI commands. It benefits developers working with experimental workflows. openspec-archive-change 是一个用于归档已完成变更和管理配置的工具，支持 CLI 命令和工件完成状态检查 openspec-archive-change は、完了した変更をアーカイブ化し、設定を管理するためのツールです - CLI コマンドとアーティファクトの完了状態の確認をサポート openspec-archive-change는 완료된 변경을 아카이브하고 설정을 관리하기 위한 도구입니다 - CLI 명령어와 아티팩트 완료 상태 확인을 지원 Openspec-archive-change es una habilidad para gestionar cambios en flujos de trabajo de IA. Permite a los usuarios seleccionar y archivar cambios con CLI. Openspec-archive-change est une compétence pour gérer les changements dans les flux de travail d''IA. Il permet aux utilisateurs de sélectionner et d''archiver des changements avec CLI. Openspec-archive-change ist eine Fähigkeit zur Verwaltung von Änderungen in KI-Arbeitsabläufen. Sie ermöglicht es Benutzern, Änderungen mit CLI auszuwählen und zu archivieren. O openspec-archive-change é uma ferramenta de gerenciamento de arquivos que permite aos desenvolvedores gerenciar alterações de forma eficiente openspec-archive-change - это инструмент управления файлами, который позволяет разработчикам эффективно управлять изменениями openspec-archive-change هو أداة لإدارة الملفات تسمح للمطورين بإدارة التغييرات بفعالية how to use openspec-archive-change openspec-archive-change setup guide openspec-archive-change vs manual archiving openspec-archive-change install what is openspec-archive-change openspec-archive-change alternative openspec-archive-change CLI commands openspec-archive-change for AI agents openspec-archive-change workflow automation openspec-archive-change 配置管理 变更归档 CLI 命令 工件完成状态检查 AI 工具 设置指南 Runs openspec list --json to retrieve available changes Uses AskUserQuestion tool to prompt user for change selection Checks artifact completion status with openspec status --change "<name>" --json Parses JSON to understand schemaName and artifact status Displays warnings and lists incomplete artifacts using AskUserQuestion tool openspec-archive-change is a skill that automates the archiving of completed changes in experimental workflows, using CLI commands like openspec list and openspec status to manage artifacts and schemas.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sanmak/kritarch-lite/security-env', 'community', 'sanmak', 'kritarch-lite', 'sanmak/kritarch-lite', 'security-env', 0, 0, 38, '2026-03-08T01:57:15.387Z', '2026-03-08T02:05:53.808Z', '142f3a8c5422c3e299830a4659635d6023bcfb45b072d2350874b277898ecee1', '{"id":"sanmak/kritarch-lite/security-env","name":"security-env","description":{"en":"The security-env skill helps developers keep secrets out of their repository by storing them in .env files. It provides a secure way to manage environment variables and prevent sensitive data exposure.","zh":"Security-Env 是一种 AI 工具，帮助开发者安全地配置环境变量，保护代码仓库中的机密信息","ja":"Security-Env は、開発者がセキュアに環境変数を設定し、コードリポジトリの機密情報を保護するための AI エージェントです","ko":"Security-Env 는 개발자가 보안 환경 변수를 설정하고 코드 저장소의 중요한 정보를 보호하는 데 도움을 주는 AI 도구입니다","es":"Security-env es una herramienta que ayuda a mantener los secretos fuera del repositorio y documentar la configuración requerida de manera segura.","fr":"Security-env est un outil qui aide à garder les secrets hors du référentiel et à documenter la configuration requise de manière sécurisée.","de":"Security-env ist ein Tool, das hilft, Geheimnisse aus dem Repository zu halten und die erforderliche Konfiguration sicher zu dokumentieren.","pt":"A habilidade security-env ajuda a manter segredos fora do repositório e documentar configurações necessárias com segurança","ru":"Навык security-env помогает сохранять секреты вне репозитория и документировать необходимые конфигурации безопасно","ar":"المهارة security-env تساعد على الحفاظ على السرية خارج المستودع وتوثيق التكوينات الضرورية بأمان"},"seo":{"title":{"en":"security-env: Secure Environment Setup Guide | AI Agent S...","zh":"Security-Env 安全环境配置设置指南","ja":"Security-Env セキュリティ環境設定ベストプラクティス","ko":"Security-Env 보안 환경 설정 가이드","es":"Configuración de seguridad-env: Guía para proteger secretos","fr":"Mise en place de security-env: Meilleures pratiques pour ...","de":"Sicherheitseinrichtung security-env: Leitfaden für sicher...","pt":"Guia de Configuração de Segurança com Ferramentas de Inte...","ru":"Настройка Среды Безопасности с ИИ Агентами","ar":"دليل إعداد بيئة الأمان باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how security-env helps keep secrets out of your repo. Learn to store secrets in .env files and sanitize logs to prevent token leaks. Get started now!","zh":"学习如何使用 Security-Env 保护代码仓库中的机密信息，避免敏感数据泄露","ja":"Security-Env を使用してコードリポジトリのセキュリティを強化し、機密情報を保護する方法を学びます","ko":"Security-Env 를 사용하여 코드 저장소의 보안을 강화하고 중요한 정보를 보호하는 방법을 알아보세요","es":"Aprende a proteger tus secretos con security-env. Descubre cómo almacenar claves de API y configuraciones de manera segura.","fr":"Découvrez comment protéger vos secrets avec security-env. Apprenez à stocker les clés API et les configurations de manière sécurisée.","de":"Erfahren Sie, wie Sie Ihre Geheimnisse mit security-env schützen. Entdecken Sie, wie Sie API-Schlüssel und Konfigurationen sicher speichern.","pt":"Aprenda a manter segredos fora do repositório e documentar configurações necessárias com segurança usando a habilidade security-env","ru":"Узнайте, как сохранять секреты вне репозитория и документировать необходимые конфигурации безопасно с помощью навыка security-env","ar":"تعلم كيفية الحفاظ على السرية خارج المستودع وتوثيق التكوينات الضرورية بأمان باستخدام مهارة security-env"},"definition":{"en":"security-env is a skill that enables secure environment setup by storing secrets in .env files and sanitizing logs to prevent token leaks.","zh":"Security-Env 是一种环境变量安全配置工具","ja":"Security-Env は環境変数のセキュリティ設定ツールです","ko":"Security-Env 는 환경 변수 보안 설정 도구입니다","es":"Security-env es un agente de seguridad que ayuda a proteger secretos y configuraciones en proyectos de desarrollo.","fr":"Security-env est un agent de sécurité qui aide à protéger les secrets et les configurations dans les projets de développement.","de":"Security-env ist ein Sicherheitsagent, der hilft, Geheimnisse und Konfigurationen in Entwicklungsprojekten zu schützen.","pt":"O security-env é uma habilidade que ajuda a manter segredos fora do repositório e documentar configurações necessárias com segurança","ru":"Security-env - это навык, который помогает сохранять секреты вне репозитория и документировать необходимые конфигурации безопасно","ar":"security-env هو مهارة تساعد على الحفاظ على السرية خارج المستودع وتوثيق التكوينات الضرورية بأمان"},"features":{"en":["Stores secrets in .env files to keep them out of the repository","Updates .env.example with new variable names and defaults","Prefer server-only env usage for secrets via API routes and server components","Sanitizes logs to avoid leaking tokens","Moves client-only env usage to server routes for enhanced security"],"zh":["将机密信息存储在 `.env` 文件中","更新 `.env.example` 文件以包含新变量名和默认值","在服务器端使用环境变量以保护机密信息","清理日志以避免泄露令牌","防止将机密信息提交到代码仓库"],"ja":["機密情報を `.env` ファイルに保存する","`.env.example` ファイルを更新して新しい変数名とデフォルト値を含める","サーバー側で環境変数を使用して機密情報を保護する","ログをクリーンアップしてトークンの漏洩を防ぐ","コードリポジトリに機密情報をコミットしない"],"ko":["기밀 정보를 `.env` 파일에 저장","`.env.example` 파일을 업데이트 하여 새로운 변수 이름과 기본 값을 포함","서버에서 환경 변수를 사용하여 기밀 정보를 보호","로그를 정리하여 토큰 유출을 방지","코드 저장소에 기밀 정보를 커밋하지 않음"],"es":["Almacenamiento de secretos en archivos .env","Actualización de .env.example con nuevos nombres de variables y valores predeterminados","Uso preferente de variables de entorno solo en el servidor para secretos","Limpieza de registros para evitar fugas de tokens","Protección de claves de API y configuraciones"],"fr":["Stockage de secrets dans des fichiers .env","Mise à jour de .env.example avec de nouveaux noms de variables et valeurs par défaut","Utilisation préférentielle de variables d''environnement uniquement sur le serveur pour les secrets","Nettoyage des journaux pour éviter les fuites de tokens","Protection des clés API et des configurations"],"de":["Speicherung von Geheimnissen in .env-Dateien","Aktualisierung von .env.example mit neuen Variablenamen und Standardwerten","Bevorzugte Verwendung von Server-Umgebungsvariablen für Geheimnisse","Säuberung von Protokollen, um Token-Lecks zu vermeiden","Schutz von API-Schlüsseln und Konfigurationen"],"pt":["Armazenamento de segredos em `.env`","Atualização de `.env.example` com novos nomes de variáveis e valores padrão","Preferência por uso de servidor apenas para segredos","Sanitização de logs para evitar vazamento de tokens"],"ru":["Хранение секретов в `.env`","Обновление `.env.example` с новыми именами переменных и значениями по умолчанию","Предпочтение использования сервера только для секретов","Очистка логов для предотвращения утечки токенов"],"ar":["تخزين السرية في `.env`","تحديث `.env.example` بأسماء متغيرات جديدة وقيم افتراضية","الأفضلية لاستخدام الخادم فقط للأسرار","تنقية السجلات لتجنب تسرب الرموز"]},"keywords":{"en":["how to use security-env","security-env setup guide","what is security-env","security-env alternative","security-env vs env vars","security-env install","secure environment variables","prevent token leaks","sanitize logs"],"zh":["Security-Env","环境变量安全","代码仓库安全","机密信息保护","AI 工具","环境变量配置","安全开发实践"],"ja":["Security-Env","環境変数のセキュリティ","コードリポジトリのセキュリティ","機密情報の保護","AI エージェント","環境変数の設定","セキュアな開発方法"],"ko":["Security-Env","환경 변수 보안","코드 저장소 보안","기밀 정보 보호","AI 도구","환경 변수 설정","보안 개발 실무"],"es":["seguridad-env","protección de secretos","almacenamiento de claves de API","configuración segura","agentes de seguridad","herramientas de seguridad para desarrolladores","seguridad en el desarrollo de software","mejores prácticas de seguridad"],"fr":["sécurité-env","protection des secrets","stockage de clés API","configuration sécurisée","agents de sécurité","outils de sécurité pour les développeurs","sécurité dans le développement de logiciels","meilleures pratiques de sécurité"],"de":["Sicherheitseinrichtung","Schutz von Geheimnissen","Speicherung von API-Schlüsseln","sichere Konfiguration","Sicherheitsagenten","Sicherheitstools für Entwickler","Sicherheit in der Softwareentwicklung","Sicherheitsbest Practices"],"pt":["segurança de desenvolvimento","ferramentas de inteligência artificial","configuração de segurança","armazenamento de segredos","sanitização de logs","desenvolvimento de software seguro"],"ru":["безопасность разработки","ИИ агенты","настройка безопасности","хранение секретов","очистка логов","безопасное разработка программного обеспечения"],"ar":["أمان التطوير","أدوات الذكاء الاصطناعي","تكوين الأمان","تخزين السرية","تنقية السجلات","تطوير البرمجيات الآمنة"]}},"owner":"sanmak","repo":"kritarch-lite","repoPath":"sanmak/kritarch-lite","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.387Z","topics":[],"category":"community","skillMd":{"name":"security-env","description":"Use when adding config, credentials, external services, or environment variables.","bodyPreview":"# Goal\nKeep secrets out of the repo and document required configuration safely.\n\n# Do\n- Store secrets in `.env` only; never commit real keys.\n- Update `.env.example` with new variable names and defaults.\n- Prefer server-only env usage for secrets (API routes, server components).\n- Sanitize logs to avoid leaking tokens.\n\n# Don''t\n- Commit secrets or embed keys in client code.\n\n# Examples\n- \"Add a new API key and update `.env.example`.\"\n- \"Move client-only env usage to a server route.\"","body":"# Goal\nKeep secrets out of the repo and document required configuration safely.\n\n# Do\n- Store secrets in `.env` only; never commit real keys.\n- Update `.env.example` with new variable names and defaults.\n- Prefer server-only env usage for secrets (API routes, server components).\n- Sanitize logs to avoid leaking tokens.\n\n# Don''t\n- Commit secrets or embed keys in client code.\n\n# Examples\n- \"Add a new API key and update `.env.example`.\"\n- \"Move client-only env usage to a server route.\"\n"},"lastSynced":"2026-03-08T02:05:53.808Z","agentAnalysis":{"suitability":{"en":"Perfect for Security-Conscious Agents needing environment variable management and secret protection in .env files.","zh":"适用于需要环境变量管理和密钥保护的安全意识强的Agent，支持.env文件中的环境变量管理和密钥保护。","ja":"セキュリティにこだわりのあるエージェントに適しています。環境変数の管理と.envファイルでのシークレット保護が可能です。","ko":"보안을 고려한 에이전트에게 적합합니다. 환경 변수 관리와 .env 파일에서의 시크릿 보호가 가능합니다.","es":"Perfecto para agentes conscientes de la seguridad que necesitan administración de variables de entorno y protección de secretos en archivos .env.","fr":"Parfait pour les agents conscients de la sécurité nécessitant une gestion de variables d''environnement et une protection de secrets dans les fichiers .env.","de":"Perfekt für sicherheitsbewusste Agenten, die eine Verwaltung von Umgebungsvariablen und einen Schutz von Geheimnissen in .env-Dateien benötigen.","pt":"Perfeito para Agentes Conscientes de Segurança que precisam de gerenciamento de variáveis de ambiente e proteção de segredos em arquivos .env.","ru":"Идеально для осведомлённых о безопасности агентов, которым требуется управление переменными среды и защита секретов в файлах .env.","ar":"مثالي للوكلاء المهتمين بأمان البيئة الذين يحتاجون إلى إدارة متغيرات البيئة وحماية الأسرار في ملفات .env."},"recommendation":{"en":"Empowers agents to securely manage environment variables, store secrets in .env files, and prevent sensitive data exposure through sanitized logs and server-only env usage for secrets, utilizing .env.example for configuration documentation.","zh":"赋予代理人安全管理环境变量、在.env文件中存储密钥并通过清理日志和服务器仅环境变量使用防止敏感数据暴露的能力，利用.env.example进行配置文档。","ja":"エージェントに、環境変数を安全に管理し、.envファイルにシークレットを保存し、ログのサニタイジングとサーバー専用の環境変数使用によって機密データの漏洩を防ぐ能力を付与します。.env.exampleを使用して設定ドキュメントを作成します。","ko":"에이전트에게 환경 변수를 안전하게 관리하고, .env 파일에 시크릿을 저장하며, 로그의 위생 처리와 서버 전용 환경 변수 사용을 통해 민감한 데이터 노출을 방지할 수 있는 능력을 부여합니다. .env.example를 사용하여 설정 문서를 작성합니다.","es":"Habilita a los agentes a gestionar de forma segura las variables de entorno, almacenar secretos en archivos .env y prevenir la exposición de datos sensibles a través de registros saneados y uso de variables de entorno solo en el servidor para secretos, utilizando .env.example para la documentación de configuración.","fr":"Permet aux agents de gérer de manière sécurisée les variables d''environnement, de stocker des secrets dans les fichiers .env et de prévenir l''exposition de données sensibles grâce à des journaux sanitaires et à l''utilisation de variables d''environnement uniquement sur le serveur pour les secrets, en utilisant .env.example pour la documentation de configuration.","de":"Ermächtigt Agenten, Umgebungsvariablen sicher zu verwalten, Geheimnisse in .env-Dateien zu speichern und die Offenlegung sensibler Daten durch gereinigte Protokolle und Server-Only-Umgebungsvariablen-Nutzung für Geheimnisse zu verhindern, wobei .env.example für die Konfigurationsdokumentation verwendet wird.","pt":"Habilita os agentes a gerenciar variáveis de ambiente de forma segura, armazenar segredos em arquivos .env e prevenir a exposição de dados sensíveis por meio de logs sanitizados e uso de variáveis de ambiente apenas no servidor para segredos, utilizando .env.example para documentação de configuração.","ru":"Наделяет агентов возможностью безопасно управлять переменными среды, хранить секреты в файлах .env и предотвращать утечку конфиденциальных данных благодаря санитизированным журналам и использованию переменных среды только на сервере для секретов, используя .env.example для документации конфигурации.","ar":"تمكّن الوكلاء من إدارة متغيرات البيئة بأمان، وتخزين الأسرار في ملفات .env، ومنع تعرض البيانات الحساسة من خلال سجلات منظفة واستخدام متغيرات البيئة فقط على الخادم للأسرار، باستخدام .env.example لتوثيق التكوين."},"useCases":{"en":["Securing API keys by storing them in .env files","Updating .env.example with new variable names and defaults for safe configuration","Sanitizing logs to prevent token leakage","Migrating client-only env usage to server routes for enhanced security"],"zh":["通过将API密钥存储在.env文件中来保护API密钥","更新.env.example以包含新变量名称和默认值以实现安全配置","清理日志以防止令牌泄漏","将客户端仅环境变量使用迁移到服务器路由以提高安全性"],"ja":["APIキーを.envファイルに保存して保護する",".env.exampleを更新して新しい変数名とデフォルト値を安全に設定する","ログをサニタイジングしてトークンの漏洩を防ぐ","クライアント専用の環境変数使用をサーバー側ルートに移行してセキュリティを強化する"],"ko":["API 키를 .env 파일에 저장하여 보호하는 것",".env.example을更新하여 새로운 변수 이름과 기본값을 안전하게 설정하는 것","로그를 위생 처리하여 토큰 누출을 방지하는 것","클라이언트 전용 환경 변수 사용을 서버 라우트로 마이그레이션하여 보안을 강화하는 것"],"es":["Proteger las claves de API almacenándolas en archivos .env","Actualizar .env.example con nuevos nombres de variables y valores predeterminados para una configuración segura","Sanear los registros para prevenir fugas de tokens","Migrar el uso de variables de entorno solo para clientes a rutas de servidor para una mayor seguridad"],"fr":["Sécuriser les clés d''API en les stockant dans les fichiers .env","Mettre à jour .env.example avec de nouveaux noms de variables et valeurs par défaut pour une configuration sécurisée","Sanitiser les journaux pour prévenir les fuites de jetons","Migrer l''utilisation de variables d''environnement uniquement pour les clients vers des itinéraires de serveur pour une sécurité renforcée"],"de":["API-Schlüssel durch Speicherung in .env-Dateien schützen",".env.example mit neuen Variablen-Namen und Standardwerten für eine sichere Konfiguration aktualisieren","Protokolle sanieren, um Token-Lecks zu verhindern","Client-Only-Umgebungsvariablen-Nutzung auf Server-Routen für erhöhte Sicherheit migrieren"],"pt":["Proteger chaves de API armazenando-as em arquivos .env","Atualizar .env.example com novos nomes de variáveis e valores padrão para configuração segura","Sanitizar logs para prevenir vazamento de tokens","Migrar o uso de variáveis de ambiente apenas para o cliente para rotas de servidor para segurança aprimorada"],"ru":["Защищать ключи API, храня их в файлах .env","Обновлять .env.example новыми именами переменных и значениями по умолчанию для безопасной конфигурации","Санитизировать журналы, чтобы предотвратить утечку токенов","Переносить использование переменных среды только для клиента на серверные маршруты для повышения безопасности"],"ar":["حماية مفاتيح API عن طريق تخزينها في ملفات .env","تحديث .env.example بأسماء متغيرات جديدة وقيم افتراضية لتكوين آمن","تنظيف السجلات لمنع تسرب الرموز","نقل استخدام متغيرات البيئة فقط للعميل إلى مسارات الخادم لتطوير الأمان"]},"limitations":{"en":["Requires .env file setup and management","Server-only env usage recommended for secrets","Manual sanitation of logs needed to avoid leaking tokens"],"zh":[".env文件设置和管理要求","服务器仅环境变量使用建议用于密钥","手动日志清理需要避免泄漏令牌"],"ja":[".envファイルの設定と管理が必要","サーバー専用の環境変数使用がシークレットに推奨","手動でのログサニタイジングがトークンの漏洩を避けるために必要"],"ko":[".env 파일 설정 및 관리가 필요","서버 전용 환경 변수 사용이 시크릿에 권장됨","수동 로그 위생 처리가 토큰 누출을 방지하기 위해 필요"],"es":["Requiere configuración y administración de archivos .env","Se recomienda el uso de variables de entorno solo en el servidor para secretos","Se requiere una desinfección manual de los registros para evitar la fuga de tokens"],"fr":["Nécessite une configuration et une gestion de fichiers .env","L''utilisation de variables d''environnement uniquement sur le serveur est recommandée pour les secrets","Une sanitation manuelle des journaux est nécessaire pour éviter les fuites de jetons"],"de":["Benötigt .env-Datei-Einrichtung und -Verwaltung","Server-Only-Umgebungsvariablen-Nutzung für Geheimnisse wird empfohlen","Eine manuelle Sanierung der Protokolle ist erforderlich, um Token-Lecks zu vermeiden"],"pt":["Requer configuração e gerenciamento de arquivos .env","Uso de variáveis de ambiente apenas no servidor recomendado para segredos","Sanitização manual de logs necessária para evitar vazamento de tokens"],"ru":["Требует настройки и управления файлами .env","Рекомендуется использование переменных среды только на сервере для секретов","Требуется ручная санитизация журналов, чтобы избежать утечки токенов"],"ar":["يتطلب إعداد ملفات .env وإدارتها","يوصى باستخدام متغيرات البيئة فقط على الخادم للأسرار","التحسين اليدوي للسجلات ضروري لتجنب تسرب الرموز"]},"version":4},"contentHash":"142f3a8c5422c3e299830a4659635d6023bcfb45b072d2350874b277898ecee1","qualityScore":38}');
