INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sanmak/kritarch-lite/security-env', 'security-env', 'sanmak', 'kritarch-lite', 'community', 'security-env sanmak kritarch-lite community The security-env skill helps developers keep secrets out of their repository by storing them in .env files. It provides a secure way to manage environment variables and prevent sensitive data exposure. Security-Env 是一种 AI 工具，帮助开发者安全地配置环境变量，保护代码仓库中的机密信息 Security-Env は、開発者がセキュアに環境変数を設定し、コードリポジトリの機密情報を保護するための AI エージェントです Security-Env 는 개발자가 보안 환경 변수를 설정하고 코드 저장소의 중요한 정보를 보호하는 데 도움을 주는 AI 도구입니다 Security-env es una herramienta que ayuda a mantener los secretos fuera del repositorio y documentar la configuración requerida de manera segura. Security-env est un outil qui aide à garder les secrets hors du référentiel et à documenter la configuration requise de manière sécurisée. Security-env ist ein Tool, das hilft, Geheimnisse aus dem Repository zu halten und die erforderliche Konfiguration sicher zu dokumentieren. A habilidade security-env ajuda a manter segredos fora do repositório e documentar configurações necessárias com segurança Навык security-env помогает сохранять секреты вне репозитория и документировать необходимые конфигурации безопасно المهارة security-env تساعد على الحفاظ على السرية خارج المستودع وتوثيق التكوينات الضرورية بأمان how to use security-env security-env setup guide what is security-env security-env alternative security-env vs env vars security-env install secure environment variables prevent token leaks sanitize logs Security-Env 环境变量安全 代码仓库安全 机密信息保护 AI 工具 环境变量配置 安全开发实践 Stores secrets in .env files to keep them out of the repository Updates .env.example with new variable names and defaults Prefer server-only env usage for secrets via API routes and server components Sanitizes logs to avoid leaking tokens Moves client-only env usage to server routes for enhanced security security-env is a skill that enables secure environment setup by storing secrets in .env files and sanitizing logs to prevent token leaks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pluginagentmarketplace/custom-plugin-android/ui', 'community', 'pluginagentmarketplace', 'custom-plugin-android', 'pluginagentmarketplace/custom-plugin-android', 'ui', 0, 0, 38, '2026-03-08T01:57:15.401Z', '2026-03-08T02:06:45.130Z', '965faff961af61aefa8b31560189f1e251f62cadd3fae8f29e9518e3856e8cb5', '{"id":"pluginagentmarketplace/custom-plugin-android/ui","name":"ui","description":{"en":"The ui skill is an Android development plugin for Claude Code, enabling developers to efficiently design and implement user interfaces. It benefits Android developers seeking to simplify their UI design process.","zh":"UI 设计插件是 Android 开发中的一个重要工具，能够帮助开发者创建出色的用户界面。该插件支持 ConstraintLayout 和 Jetpack Compose 等技术","ja":"UI デザインスキルは Android 開発における強力なツールであり、開発者が優れたユーザーインターフェースを作成するのに役立ちます。ConstraintLayout や Jetpack Compose などの技術が含まれます","ko":"안드로이드 개발 플러그인은 개발자가 優れた 사용자 인터페이스를 만들 수 있도록 도와주는 중요한 도구입니다. 이 플러그인은 ConstraintLayout 및 Jetpack Compose 등의 기술을 지원합니다","es":"El plugin de UI para Claude Code es una herramienta para desarrolladores de Android que permite crear interfaces de usuario personalizadas con ConstraintLayout y Jetpack Compose","fr":"Le plugin UI pour Claude Code est un outil pour les développeurs Android qui permet de créer des interfaces utilisateur personnalisées avec ConstraintLayout et Jetpack Compose","de":"Das UI-Plugin für Claude Code ist ein Tool für Android-Entwickler, das die Erstellung von benutzerdefinierten Benutzeroberflächen mit ConstraintLayout und Jetpack Compose ermöglicht","pt":"O plugin UI para Android é uma ferramenta poderosa para desenvolvedores, oferecendo funcionalidades de design de interface do usuário","ru":"Плагин UI для Android - это мощный инструмент для разработчиков, предлагающий функции проектирования пользовательского интерфейса","ar":"الواجهة البرمجية UI لاندرويد هي أداة قوية للمطورين، وتقدم ميزات تصميم واجهة المستخدم"},"seo":{"title":{"en":"ui: Android Development Plugin Setup Guide | AI Agent Skill","zh":"UI 设计插件安装指南 - Android 开发最佳实践","ja":"UI デザインスキルのセットアップガイド - AIエージェントとの連携","ko":"UI 설계를 위한 안드로이드 개발 플러그인 설정 가이드","es":"Guía de configuración de UI para desarrolladores de Android","fr":"Paramétrer l''UI pour les développeurs Android","de":"UI-Setup-Anleitung für Android-Entwickler","pt":"Guia de Configuração UI para Desenvolvimento Android","ru":"ИИ Агент UI: Руководство по Настройке для Android","ar":"دليل إعداد واجهة المستخدم UI لتنمية اندرويد"},"description":{"en":"Unlock efficient Android UI design with the ui skill, featuring ConstraintLayout and Jetpack Compose. Get started now and streamline your development workflow!","zh":"了解如何使用 UI 设计插件来提升 Android 应用的用户体验，包括 ConstraintLayout 和 Jetpack Compose 的使用","ja":"AIエージェントと連携する UI デザインスキルの使い方を学び、Android アプリの UI を強化する","ko":"안드로이드 개발 플러그인을 사용하여 UI 설계를 개선하고 ConstraintLayout, Jetpack Compose 등의 기술을 활용하는 방법","es":"Aprende a utilizar el plugin de UI para Claude Code en el desarrollo de Android con ConstraintLayout y Jetpack Compose","fr":"Découvrez comment utiliser le plugin UI pour Claude Code dans le développement Android avec ConstraintLayout et Jetpack Compose","de":"Erfahren Sie, wie Sie das UI-Plugin für Claude Code im Android-Entwicklung mit ConstraintLayout und Jetpack Compose verwenden","pt":"Aprenda a configurar o plugin UI para desenvolvimento Android com Claude Code e melhore sua produtividade","ru":"Узнайте, как настроить плагин UI для разработки Android с Claude Code и повысьте свою производительность","ar":"تعرف على كيفية تكوين واجهة المستخدم UI لتنمية اندرويد مع Claude Code و تحسين إنتاجيتك"},"definition":{"en":"ui is an Android development plugin providing a set of tools and features for designing and implementing user interfaces, including ConstraintLayout and Jetpack Compose.","zh":"UI 设计插件是一种 Android 开发工具，用于创建和设计应用程序的用户界面","ja":"UI デザインスキルは、Android アプリのユーザーインターフェースを作成および設計するためのツールです","ko":"안드로이드 개발 플러그인은 애플리케이션의 사용자 인터페이스를 만들고 설계하는 데 사용되는 도구입니다","es":"Un plugin de UI es una herramienta que permite a los desarrolladores de Android crear interfaces de usuario personalizadas","fr":"Un plugin UI est un outil qui permet aux développeurs Android de créer des interfaces utilisateur personnalisées","de":"Ein UI-Plugin ist ein Tool, das es Android-Entwicklern ermöglicht, benutzerdefinierte Benutzeroberflächen zu erstellen","pt":"O que é UI? É um plugin de desenvolvimento Android para Claude Code que facilita o design de interfaces do usuário","ru":"Что такое UI? Это плагин для разработки Android для Claude Code, который упрощает проектирование пользовательских интерфейсов","ar":"ما هي واجهة المستخدم UI؟ هي واجهة برمجية لتنمية اندرويد مع Claude Code التي تسهل تصميم واجهات المستخدم"},"features":{"en":["Utilizes ConstraintLayout for flexible and adaptive UI design","Supports Jetpack Compose for modern and efficient UI development","Enables the use of XML for layout definitions","Allows for the implementation of buttons and other UI elements using androidx.constraintlayout.widget.ConstraintLayout","Facilitates the creation of responsive and intuitive user interfaces"],"zh":["支持 ConstraintLayout 布局","集成 Jetpack Compose 技术","简化 Android 应用的 UI 设计","提高开发效率","兼容多种 Android 版本"],"ja":["ConstraintLayout をサポート","Jetpack Compose テクノロジーを統合","Android アプリの UI 設計を簡素化","開発効率を向上","複数の Android バージョンに対応"],"ko":["ConstraintLayout 레이아웃 지원","Jetpack Compose 기술 통합","안드로이드 애플리케이션의 UI 설계를 단순화","개발 효율성을 높임","다양한 안드로이드 버전에 대응"],"es":["Compatibilidad con ConstraintLayout","Soporte para Jetpack Compose","Creación de interfaces de usuario personalizadas","Integración con Claude Code","Diseño de UI adaptable para diferentes dispositivos"],"fr":["Compatibilité avec ConstraintLayout","Prise en charge de Jetpack Compose","Création d''interfaces utilisateur personnalisées","Intégration avec Claude Code","Conception d''UI adaptable pour différents appareils"],"de":["Kompatibilität mit ConstraintLayout","Unterstützung für Jetpack Compose","Erstellung von benutzerdefinierten Benutzeroberflächen","Integration mit Claude Code","Entwurf von UI für verschiedene Geräte"],"pt":["Suporte a ConstraintLayout","Integração com Jetpack Compose","Design de interface do usuário personalizado","Compatibilidade com Claude Code","Facilita a criação de layouts complexos"],"ru":["Поддержка ConstraintLayout","Интеграция с Jetpack Compose","Пользовательский дизайн интерфейса","Совместимость с Claude Code","Упрощает создание сложных макетов"],"ar":["دعم ConstraintLayout","التكامل مع Jetpack Compose","تصميم واجهة المستخدم المخصص","التوافق مع Claude Code","يُسهل إنشاء تخطيطات معقدة"]},"keywords":{"en":["how to use ui in Android development","ui vs other Android design tools","ui setup guide for Claude Code","what is ui in Android development","ui alternative for efficient UI design","ui install for Android studio"],"zh":["UI 设计插件","Android 开发工具","ConstraintLayout","Jetpack Compose","用户界面设计","安卓应用开发","UI 设计最佳实践"],"ja":["UI デザインスキル","Android 開発ツール","ConstraintLayout","Jetpack Compose","ユーザーインターフェース設計","Android アプリ開発","UI 設計ベストプラクティス","AIエージェント"],"ko":["안드로이드 개발 플러그인","UI 설계 도구","ConstraintLayout","Jetpack Compose","사용자 인터페이스 설계","안드로이드 애플리케이션 개발","UI 설계 가이드","AI 에이전트"],"es":["desarrollo de Android","plugin de UI","ConstraintLayout","Jetpack Compose","Claude Code","diseño de UI","interfaces de usuario personalizadas","herramientas de desarrollo de Android"],"fr":["développement Android","plugin UI","ConstraintLayout","Jetpack Compose","Claude Code","conception d''UI","interfaces utilisateur personnalisées","outils de développement Android"],"de":["Android-Entwicklung","UI-Plugin","ConstraintLayout","Jetpack Compose","Claude Code","Benutzeroberflächen-Design","benutzerdefinierte Benutzeroberflächen","Android-Entwicklungstools"],"pt":["plugin ui android","desenvolvimento android","design de interface do usuário","constraintlayout","jetpack compose","claude code","android development","ui design"],"ru":["плагин ui android","разработка android","проектирование пользовательского интерфейса","constraintlayout","jetpack compose","claude code","android разработка","ui дизайн"],"ar":["واجهة برمجية ui اندرويد","تنمية اندرويد","تصميم واجهة المستخدم","constraintlayout","jetpack compose","claude code","اندرويد تنمية","تصميم واجهة المستخدم ui"]}},"owner":"pluginagentmarketplace","repo":"custom-plugin-android","repoPath":"pluginagentmarketplace/custom-plugin-android","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.401Z","topics":[],"category":"community","skillMd":{"name":"ui","description":"XML layouts, ConstraintLayout, Jetpack Compose, Material Design 3.","version":"2.0.0","bodyPreview":"# UI Design Skill\n\n## Quick Start\n\n### ConstraintLayout\n```xml\n<androidx.constraintlayout.widget.ConstraintLayout>\n    <Button\n        android:id=\"@+id/btn\"\n        android:layout_width=\"wrap_content\"\n        android:layout_height=\"wrap_content\"\n        app:layout_constraintStart_toStartOf=\"parent\"\n        app:layout_constraintEnd_toEndOf=\"parent\"\n        app:layout_constraintTop_toTopOf=\"parent\" />\n</androidx.constraintlayout.widget.ConstraintLayout>\n```\n\n### Jetpack Compose\n```kotlin\nColumn(mo","body":"# UI Design Skill\n\n## Quick Start\n\n### ConstraintLayout\n```xml\n<androidx.constraintlayout.widget.ConstraintLayout>\n    <Button\n        android:id=\"@+id/btn\"\n        android:layout_width=\"wrap_content\"\n        android:layout_height=\"wrap_content\"\n        app:layout_constraintStart_toStartOf=\"parent\"\n        app:layout_constraintEnd_toEndOf=\"parent\"\n        app:layout_constraintTop_toTopOf=\"parent\" />\n</androidx.constraintlayout.widget.ConstraintLayout>\n```\n\n### Jetpack Compose\n```kotlin\nColumn(modifier = Modifier.fillMaxSize().padding(16.dp)) {\n    Text(\"Hello Compose\", fontSize = 20.sp)\n    Button(onClick = { }) { Text(\"Click Me\") }\n}\n```\n\n### Material Design 3\n```kotlin\nScaffold(\n    topBar = { TopAppBar(title = { Text(\"MyApp\") }) }\n) { padding ->\n    // Content\n}\n```\n\n## Key Concepts\n\n### Constraint Types\n- Start/End, Top/Bottom\n- Chains (spread, packed)\n- Guidelines\n- Barriers\n- Bias\n\n### Compose State\n```kotlin\nvar count by remember { mutableStateOf(0) }\nButton(onClick = { count++ }) { Text(\"Count: $count\") }\n```\n\n### Material Components\n- Buttons (filled, outlined, text)\n- Cards, FABs, Dialogs\n- Navigation patterns\n- Theme system\n\n## Best Practices\n\n✅ Use ConstraintLayout for efficiency\n✅ Implement Material Design\n✅ Test on multiple screen sizes\n✅ Optimize rendering performance\n✅ Support accessibility\n\n## Resources\n\n- [ConstraintLayout Guide](https://developer.android.com/training/constraint-layout)\n- [Compose Documentation](https://developer.android.com/develop/ui/compose)\n- [Material Design 3](https://m3.material.io/)\n"},"lastSynced":"2026-03-08T02:06:45.130Z","agentAnalysis":{"suitability":{"en":"Perfect for Android Development Agents needing streamlined UI design and implementation capabilities.","zh":"非常适合需要简化UI设计和实现能力的Android开发代理。","ja":"Android開発エージェントがストリームライン化されたUIデザインと実装機能を必要とする場合に最適です。","ko":"스트림 라인化 된 UI 디자인 및 구현 기능이 필요한 Android 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo de Android que necesitan capacidades de diseño e implementación de interfaz de usuario optimizadas.","fr":"Parfait pour les agents de développement Android nécessitant des capacités de conception et de mise en œuvre d''interface utilisateur rationalisées.","de":"Perfekt für Android-Entwicklungsagenten, die eine optimierte Benutzeroberflächengestaltung und -implementierung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Android que necessitam de capacidades de design e implementação de UI otimizadas.","ru":"Идеально подходит для агентов разработки Android, которым необходимы оптимизированные возможности проектирования и реализации интерфейса пользователя.","ar":"مثالي للوكلاء الذين يحتاجون إلى تسهيلات تصميم واجهة المستخدم وتنفيذها المُستخدمة في تطوير التطبيقات الأندرويد."},"recommendation":{"en":"Empowers agents to efficiently design and implement user interfaces using ConstraintLayout and Jetpack Compose, leveraging XML and Kotlin for seamless Android app development.","zh":"赋予代理高效设计和实现用户界面使用ConstraintLayout和Jetpack Compose的能力，利用XML和Kotlin进行无缝的Android应用开发。","ja":"ConstraintLayoutとJetpack Composeを使用して効率的にユーザーインターフェイスを設計し実装するエージェントを可能にし、XMLとKotlinを利用して無断のAndroidアプリ開発を行う。","ko":"ConstraintLayout 및 Jetpack Compose를 사용하여 효율적으로 사용자 인터페이스를 디자인하고 구현할 수 있는 에이전트를 가능하게 하며, XML 및 Kotlin을 사용하여 무중단의 Android 앱 개발을 수행합니다.","es":"Habilita a los agentes a diseñar e implementar interfaces de usuario de forma eficiente utilizando ConstraintLayout y Jetpack Compose, aprovechando XML y Kotlin para un desarrollo de aplicaciones Android sin problemas.","fr":"Permet aux agents de concevoir et de mettre en œuvre des interfaces utilisateur de manière efficace en utilisant ConstraintLayout et Jetpack Compose, en exploitant XML et Kotlin pour un développement d''applications Android sans heurts.","de":"Ermächtigt die Agenten, Benutzeroberflächen effizient zu entwerfen und zu implementieren, indem sie ConstraintLayout und Jetpack Compose verwenden und XML und Kotlin für eine reibungslose Android-App-Entwicklung nutzen.","pt":"Habilita os agentes a projetar e implementar de forma eficiente interfaces do usuário usando ConstraintLayout e Jetpack Compose, aproveitando XML e Kotlin para um desenvolvimento de aplicativos Android sem interrupções.","ru":"Наделяет агентов возможностью эффективно проектировать и реализовывать интерфейсы пользователя с помощью ConstraintLayout и Jetpack Compose, используя XML и Kotlin для бесшовного разработки приложений Android.","ar":"تمكّن الوكلاء من تصميم واجهات المستخدم بفعالية باستخدام ConstraintLayout و Jetpack Compose، واستخدام XML و Kotlin لتطوير تطبيقات الأندرويد بشكل متواصل."},"useCases":{"en":["Designing responsive layouts with ConstraintLayout","Building reusable UI components with Jetpack Compose","Implementing material design principles for Android apps"],"zh":["使用ConstraintLayout设计响应式布局","使用Jetpack Compose构建可重用UI组件","实现Android应用的Material Design原则"],"ja":["ConstraintLayoutを使用してレスポンシブレイアウトを設計する","Jetpack Composeを使用して再利用可能なUIコンポーネントを構築する","AndroidアプリのMaterial Design原則を実装する"],"ko":["ConstraintLayout를 사용하여 반응형 레이아웃을 설계한다","Jetpack Compose를 사용하여 재사용 가능한 UI 구성 요소를 구축한다","Android 앱의 Material Design 원칙을 구현한다"],"es":["Diseñar diseños responsivos con ConstraintLayout","Crear componentes de interfaz de usuario reutilizables con Jetpack Compose","Implementar principios de diseño de material para aplicaciones de Android"],"fr":["Concevoir des mises en page responsives avec ConstraintLayout","Créer des composants d''interface utilisateur réutilisables avec Jetpack Compose","Mettre en œuvre les principes de conception de matériel pour les applications Android"],"de":["Responsives Layouts mit ConstraintLayout entwerfen","Wiederverwendbare Benutzeroberflächenkomponenten mit Jetpack Compose erstellen","Material-Design-Prinzipien für Android-Apps implementieren"],"pt":["Projetar layouts responsivos com ConstraintLayout","Construir componentes de UI reutilizáveis com Jetpack Compose","Implementar princípios de design de material para aplicativos Android"],"ru":["Проектировать отзывчивые компоновки с помощью ConstraintLayout","Построить многократно используемые компоненты пользовательского интерфейса с помощью Jetpack Compose","Реализовать принципы материального дизайна для приложений Android"],"ar":["تصميم تخطيطات متجاوبة مع ConstraintLayout","بناء مكونات واجهة المستخدم قابلة لإعادة الاستخدام مع Jetpack Compose","تنفيذ مبادئ تصميم المواد للتطبيقات الأندرويد"]},"limitations":{"en":["Requires Android development environment","Limited to Android platform","Familiarity with XML and Kotlin necessary"],"zh":["需要Android开发环境","仅限Android平台","需要熟悉XML和Kotlin"],"ja":["Android開発環境が必要","Androidプラットフォームに限定されている","XMLとKotlinに精通している必要がある"],"ko":["Android 개발 환경이 필요하다","Android 플랫폼에만 محدود된다","XML 및 Kotlin에 익숙해져야 한다"],"es":["Requiere un entorno de desarrollo de Android","Limitado a la plataforma Android","Se requiere familiaridad con XML y Kotlin"],"fr":["Nécessite un environnement de développement Android","Limité à la plateforme Android","Familiarité avec XML et Kotlin nécessaire"],"de":["Benötigt eine Android-Entwicklungsumgebung","Begrenzt auf die Android-Plattform","Vertrautheit mit XML und Kotlin erforderlich"],"pt":["Requer ambiente de desenvolvimento Android","Limitado à plataforma Android","Familiaridade com XML e Kotlin necessária"],"ru":["Требуется среда разработки Android","Ограниченная платформа Android","Необходимо знание XML и Kotlin"],"ar":["يتطلب بيئة تطوير الأندرويد","محدود منصة الأندرويد","يجب امتلاك معرفة بـ XML و Kotlin"]},"version":4},"contentHash":"965faff961af61aefa8b31560189f1e251f62cadd3fae8f29e9518e3856e8cb5","qualityScore":38}');
