INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pluginagentmarketplace/custom-plugin-android/ui', 'ui', 'pluginagentmarketplace', 'custom-plugin-android', 'community', 'ui pluginagentmarketplace custom-plugin-android community The ui skill is an Android development plugin for Claude Code, enabling developers to efficiently design and implement user interfaces. It benefits Android developers seeking to simplify their UI design process. UI 设计插件是 Android 开发中的一个重要工具，能够帮助开发者创建出色的用户界面。该插件支持 ConstraintLayout 和 Jetpack Compose 等技术 UI デザインスキルは Android 開発における強力なツールであり、開発者が優れたユーザーインターフェースを作成するのに役立ちます。ConstraintLayout や Jetpack Compose などの技術が含まれます 안드로이드 개발 플러그인은 개발자가 優れた 사용자 인터페이스를 만들 수 있도록 도와주는 중요한 도구입니다. 이 플러그인은 ConstraintLayout 및 Jetpack Compose 등의 기술을 지원합니다 El plugin de UI para Claude Code es una herramienta para desarrolladores de Android que permite crear interfaces de usuario personalizadas con ConstraintLayout y Jetpack Compose Le plugin UI pour Claude Code est un outil pour les développeurs Android qui permet de créer des interfaces utilisateur personnalisées avec ConstraintLayout et Jetpack Compose Das UI-Plugin für Claude Code ist ein Tool für Android-Entwickler, das die Erstellung von benutzerdefinierten Benutzeroberflächen mit ConstraintLayout und Jetpack Compose ermöglicht O plugin UI para Android é uma ferramenta poderosa para desenvolvedores, oferecendo funcionalidades de design de interface do usuário Плагин UI для Android - это мощный инструмент для разработчиков, предлагающий функции проектирования пользовательского интерфейса الواجهة البرمجية UI لاندرويد هي أداة قوية للمطورين، وتقدم ميزات تصميم واجهة المستخدم how to use ui in Android development ui vs other Android design tools ui setup guide for Claude Code what is ui in Android development ui alternative for efficient UI design ui install for Android studio UI 设计插件 Android 开发工具 ConstraintLayout Jetpack Compose 用户界面设计 安卓应用开发 UI 设计最佳实践 Utilizes ConstraintLayout for flexible and adaptive UI design Supports Jetpack Compose for modern and efficient UI development Enables the use of XML for layout definitions Allows for the implementation of buttons and other UI elements using androidx.constraintlayout.widget.ConstraintLayout Facilitates the creation of responsive and intuitive user interfaces ui is an Android development plugin providing a set of tools and features for designing and implementing user interfaces, including ConstraintLayout and Jetpack Compose.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RTGS2017/NagaAgent/solve', 'community', 'RTGS2017', 'NagaAgent', 'RTGS2017/NagaAgent', 'solve', 0, 0, 38, '2026-03-08T01:57:15.401Z', '2026-03-08T02:06:45.326Z', '7d620eb304ee1d626980cf02f2c6bd7b6350a401ae8ccf62c9f55aa16a194a8c', '{"id":"RTGS2017/NagaAgent/solve","name":"solve","description":{"en":"The Solve skill provides structured solutions to users'' specific problems, leveraging multi-agent collaboration and seamless tool integration for efficient issue resolution, benefiting developers and users alike.","zh":"解决问题技能是一种简单却强大的框架，用于实现智能交互、多Agent协作和工具集成。它提供结构化的解决方案，包括问题分析、原因判断、方案提供和注意事项","ja":"問題解決スキルは、智能交互、多エージェント協力、ツール統合を実現するためのシンプルながら強力なフレームワークです。問題分析、原因判断、方案提供、注意事項などを提供します","ko":"문제 해결 스킬은 지능형 상호작용, 멀티 에이전트 협업, 툴 통합을 위한 간단하지만 강력한 프레임워크입니다. 문제 분석, 원인 판단, 方案 제공, 注意事項 등을 제공합니다","es":"El framework solve permite la interacción inteligente y la colaboración multiagente, con herramientas de búsqueda y análisis de problemas","fr":"Le framework solve permet l''interaction intelligente et la collaboration multi-agents, avec des outils de recherche et d''analyse de problèmes","de":"Das solve-Framework ermöglicht die intelligente Interaktion und die Multi-Agenten-Kollaboration, mit Tools zur Problemanalyse und -lösung","pt":"O skill Solve é um framework de agente simples e poderoso para assistentes pessoais, projetado para permitir interação inteligente e colaboração entre agentes","ru":"Навык Solve - простой и мощный фреймворк агента для персональных ассистентов, предназначенный для обеспечения умного взаимодействия и сотрудничества между агентами","ar":"مهارة الحل هي إطار عمل موكل بسيط وقوي للمساعدين الشخصيين، مصمم لتمكين التفاعل الذكي والتعاون بين الموكلين"},"seo":{"title":{"en":"Solve: Intelligent Problem Solving Framework for AI Agent...","zh":"解决问题技能设置指南 - 实现智能交互和多Agent协作","ja":"AIエージェントの問題解決スキル - Setup Guide for Intelligent Interaction","ko":"문제 해결 스킬 설정 가이드 - 지능형 상호작용 및 멀티 에이전트 협업","es":"Guía de Configuración para solve: Agentes de Inteligencia...","fr":"Guide de Mise en Place pour solve: Outils d''Intelligence ...","de":"Einrichtungsleitfaden für solve: KI-Agents und -Tools","pt":"Guia de Configuração do Skill Solve para Agentes de IA","ru":"Настройка навыка Solve для ИИ Агентов: лучшие практики","ar":"دليل إعداد مهارة حل للموكلين الإصطناعيين"},"description":{"en":"Unlock efficient issue resolution with Solve, an AI agent framework that integrates tool collaboration and real-time data search - get started now!","zh":"了解解决问题技能的技术细节，实现智能交互、多Agent协作和工具集成。查看设置指南和最佳实践","ja":"AIエージェントの問題解決スキルの技術的詳細を学び、智能交互、多エージェント協力、ツール統合を実現しましょう","ko":"문제 해결 스킬의 기술적 세부 사항을 확인하고 지능형 상호작용, 멀티 에이전트 협업, 툴 통합을 구현하세요","es":"Descubre cómo configurar solve para agentes de inteligencia artificial, con pasos para la resolución de problemas y colaboración multiagente","fr":"Découvrez comment configurer solve pour les outils d''intelligence artificielle, avec des étapes pour la résolution de problèmes et la collaboration multi-agents","de":"Erfahren Sie, wie Sie solve für KI-Agents und -Tools einrichten, mit Schritten zur Problemlösung und Multi-Agenten-Kollaboration","pt":"Aprenda a configurar o skill Solve para agentes de IA e melhore a interação inteligente com os usuários","ru":"Узнайте, как настроить навык Solve для ИИ Агентов и повысьте умную интеракцию с пользователями","ar":"تعرف على كيفية إعداد مهارة الحل للموكلين الإصطناعيين وتحسين التفاعل الذكي مع المستخدمين"},"definition":{"en":"Solve is a simple yet powerful agent framework designed for personal assistants, enabling intelligent interaction and problem-solving capabilities.","zh":"解决问题技能是一种AI框架，用于实现智能交互和多Agent协作","ja":"問題解決スキルは、智能交互と多エージェント協力を実現するためのAIフレームワークです","ko":"문제 해결 스킬은 지능형 상호작용과 멀티 에이전트 협력을 위한 AI 프레임워크입니다","es":"solve es un framework de agente para asistentes personales que permite la resolución de problemas y la colaboración multiagente","fr":"solve est un framework d''agent pour les assistants personnels qui permet la résolution de problèmes et la collaboration multi-agents","de":"solve ist ein Agenten-Framework für persönliche Assistenten, das die Problemlösung und die Multi-Agenten-Kollaboration ermöglicht","pt":"O skill Solve é um framework de agente que fornece soluções estruturadas para problemas do usuário","ru":"Навык Solve - это фреймворк агента, который предоставляет структурированные решения для проблем пользователя","ar":"مهارة الحل هي إطار عمل موكل يوفر حلولًا منظمة لمشكلات المستخدم"},"features":{"en":["Provides step-by-step solving methods using specific commands or code","Supports real-time information search via OpenClaw agentType","Analyzes causes of problems using a combination of knowledge and search results","Offers risk awareness and notice of potential pitfalls","Prioritizes simple and effective solution recommendations"],"zh":["结构化的解决方案","问题分析和原因判断","方案提供和注意事项","支持多Agent协作","实现智能交互和工具集成","使用openclaw工具搜索相关信息"],"ja":["構造化された解決策","問題分析と原因判断","方案提供と注意事項","多エージェント協力対応","智能交互とツール統合の実現","openclawツールを使用した関連情報の検索"],"ko":["구조화된 해결책","문제 분석과 원인 판단","방안 제공과注意事項","멀티 에이전트 협업 지원","지능형 상호작용과 툴 통합의 구현","openclaw 툴을 사용한 관련 정보 검색"],"es":["Resolución de problemas estructurada","Colaboración multiagente","Búsqueda y análisis de problemas con herramientas de búsqueda","Proporciona soluciones paso a paso","Soporte para problemas técnicos con comandos y código específicos"],"fr":["Résolution de problèmes structurée","Collaboration multi-agents","Recherche et analyse de problèmes avec des outils de recherche","Fournit des solutions étape par étape","Prise en charge des problèmes techniques avec des commandes et du code spécifiques"],"de":["Strukturierte Problemlösung","Multi-Agenten-Kollaboration","Suche und Analyse von Problemen mit Suchtools","Bietet schrittweise Lösungen","Unterstützung für technische Probleme mit spezifischen Befehlen und Code"],"pt":["Análise de problemas do usuário","Integração com ferramentas de busca","Fornecimento de soluções estruturadas","Recomendação de soluções baseadas em conhecimento","Suporte a colaboração entre agentes"],"ru":["Анализ проблем пользователя","Интеграция с инструментами поиска","Предоставление структурированных решений","Рекомендация решений на основе знаний","Поддержка сотрудничества между агентами"],"ar":["تحليل مشكلات المستخدم","دمج أدوات البحث","توفير حلول منظمة","توصية بحلول قائمة على المعرفة","دعم التعاون بين الموكلين"]},"keywords":{"en":["how to use solve","solve AI agent framework","solve alternative","solve vs other frameworks","solve install guide","solve setup tutorial","what is solve","solve problem solving skill","solve intelligent interaction"],"zh":["解决问题技能","AI框架","智能交互","多Agent协作","工具集成","问题分析","原因判断","方案提供","注意事项","openclaw工具"],"ja":["問題解決スキル","AIフレームワーク","智能交互","多エージェント協力","ツール統合","問題分析","原因判断","方案提供","注意事項","openclawツール"],"ko":["문제 해결 스킬","AI 프레임워크","지능형 상호작용","멀티 에이전트 협업","툴 통합","문제 분석","원인 판단","방안 제공","주의事項","openclaw 툴"],"es":["agentes de inteligencia artificial","herramientas de inteligencia artificial","resolución de problemas","colaboración multiagente","framework solve","asistentes personales","búsqueda y análisis de problemas","solución de problemas técnicos","desarrollo de agentes de inteligencia artificial"],"fr":["outils d''intelligence artificielle","agents d''intelligence artificielle","résolution de problèmes","collaboration multi-agents","framework solve","assistants personnels","recherche et analyse de problèmes","résolution de problèmes techniques","développement d''outils d''intelligence artificielle"],"de":["KI-Agents","KI-Tools","Problemlösung","Multi-Agenten-Kollaboration","solve-Framework","persönliche Assistenten","Suche und Analyse von Problemen","Lösung von technischen Problemen","Entwicklung von KI-Agents und -Tools"],"pt":["agentes de IA","skill solve","integração com ferramentas de busca","soluções estruturadas","collaboração entre agentes","desenvolvimento de agentes de IA","IA égium","ferramentas de desenvolvimento de IA"],"ru":["ИИ Агенты","навык solve","интеграция с инструментами поиска","структурированные решения","сотрудничество между агентами","разработка ИИ Агентов","ИИ инструменты","инструменты разработки ИИ"],"ar":["الموكلين الإصطناعيين","مهارة الحل","دمج أدوات البحث","حلول منظمة","التعاون بين الموكلين","تطوير الموكلين الإصطناعيين","أدوات الإصطناع","أدوات تطوير الإصطناع"]}},"owner":"RTGS2017","repo":"NagaAgent","repoPath":"RTGS2017/NagaAgent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.401Z","topics":[],"category":"community","skillMd":{"name":"solve","description":"问题解决技能。针对用户描述的具体问题，提供分步骤的解决方案。适用于技术问题、日常疑难、学习困惑等场景。","version":"1.0.0","tags":"","bodyPreview":"# 问题解决技能\n\n针对用户的具体问题，提供结构化的解决方案。\n\n## 解决流程\n\n1. 明确问题：确认用户遇到的具体问题\n2. 判断是否需要联网：如果问题涉及实时信息、最新数据、具体事实核查等，先使用工具搜索：\n```tool\n{\"agentType\": \"openclaw\", \"task_type\": \"message\", \"message\": \"搜索：问题相关的关键词\"}\n```\n3. 分析原因：结合自身知识和搜索结果（如有），列出可能的原因\n4. 提供方案：给出分步骤的解决方法\n5. 注意事项：提醒可能的风险或注意点\n\n## 规则\n\n1. 方案应该具体可执行，避免空泛建议\n2. 优先推荐最简单有效的方案\n3. 如果有多种方案，按推荐度排序\n4. 对于技术问题，提供具体的命令或代码\n5. 不需要联网的问题（纯逻辑推理、数学计算、代码问题等）直接分析即可，不要强行搜索","body":"# 问题解决技能\n\n针对用户的具体问题，提供结构化的解决方案。\n\n## 解决流程\n\n1. 明确问题：确认用户遇到的具体问题\n2. 判断是否需要联网：如果问题涉及实时信息、最新数据、具体事实核查等，先使用工具搜索：\n```tool\n{\"agentType\": \"openclaw\", \"task_type\": \"message\", \"message\": \"搜索：问题相关的关键词\"}\n```\n3. 分析原因：结合自身知识和搜索结果（如有），列出可能的原因\n4. 提供方案：给出分步骤的解决方法\n5. 注意事项：提醒可能的风险或注意点\n\n## 规则\n\n1. 方案应该具体可执行，避免空泛建议\n2. 优先推荐最简单有效的方案\n3. 如果有多种方案，按推荐度排序\n4. 对于技术问题，提供具体的命令或代码\n5. 不需要联网的问题（纯逻辑推理、数学计算、代码问题等）直接分析即可，不要强行搜索\n"},"lastSynced":"2026-03-08T02:06:45.326Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code requiring advanced problem-solving capabilities with multi-agent collaboration and tool integration.","zh":"适合像Cursor、Windsurf和Claude Code这样的AI代理，需要具有高级问题解决能力的多代理协作和工具集成。","ja":"Cursor、Windsurf、Claude CodeのようなAIエージェントに適しています。これらのエージェントは、多エージェントのコラボレーションとツールの統合を必要とする高度な問題解決能力を必要とします。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에게 적합합니다. 이러한 에이전트는 다중 에이전트 협업 및 툴 통합을 통한 고급 문제 해결 능력이 필요합니다.","es":"Ideal para Agentes de IA como Cursor, Windsurf y Claude Code que requieren capacidades de resolución de problemas avanzadas con colaboración entre agentes y integración de herramientas.","fr":"Idéal pour les agents d''IA comme Cursor, Windsurf et Claude Code nécessitant des capacités de résolution de problèmes avancées avec une collaboration entre agents et une intégration d''outils.","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die erweiterte Problemlösungsfähigkeiten mit Multiagenten-Kollaboration und Tool-Integration erfordern.","pt":"Ideal para Agentes de IA como Cursor, Windsurf e Claude Code que exigem capacidades avançadas de resolução de problemas com colaboração multi-agente e integração de ferramentas.","ru":"Идеально для агентов ИИ, таких как Cursor, Windsurf и Claude Code, требующих продвинутых возможностей решения проблем с многоагентным сотрудничеством и интеграцией инструментов.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code الذين يتطلبونقدرات متقدمة لحل المشكلات بالتعاون مع عدة وكلاء وتكامل الأدوات."},"recommendation":{"en":"Empowers agents to provide structured solutions to specific user problems, leveraging seamless tool integration for efficient issue resolution, utilizing protocols like openclaw for real-time information retrieval and analysis, and generating step-by-step executable plans.","zh":"赋予代理提供结构化的解决方案以解决特定用户问题，利用无缝的工具集成实现高效的问题解决，利用openclaw等协议进行实时信息检索和分析，并生成一步一步的可执行计划。","ja":"エージェントに、特定のユーザーの問題に対する構造化されたソリューションを提供する力を与え、ツールのシームレスな統合により効率的な問題解決を実現し、openclawなどのプロトコルを使用してリアルタイムの情報取得と分析を行い、ステップバイステップの実行可能なプランを生成します。","ko":"에이전트가 특정 사용자 문제에 대한 구조화된 솔루션을 제공할 수 있도록 하며, 무결점의 툴 통합을 통해 효율적인 문제 해결을 가능하게 하고, openclaw와 같은 프로토콜을 사용하여 실시간 정보 검색 및 분석을 수행하며, 단계별 실행 가능한 계획을 생성합니다.","es":"Habilita a los agentes a proporcionar soluciones estructuradas a problemas específicos de los usuarios, aprovechando una integración de herramientas sin problemas para una resolución eficiente de problemas, utilizando protocolos como openclaw para la recuperación y análisis de información en tiempo real y generando planes ejecutables paso a paso.","fr":"Permet aux agents de fournir des solutions structurées à des problèmes spécifiques des utilisateurs, en exploitant une intégration d''outils sans rupture pour une résolution efficace des problèmes, en utilisant des protocoles comme openclaw pour la récupération et l''analyse d''informations en temps réel et en générant des plans exécutables étape par étape.","de":"Ermächtigt die Agenten, strukturierte Lösungen für spezifische Benutzerprobleme bereitzustellen, indem sie eine nahtlose Tool-Integration für eine effiziente Problemlösung nutzen, Protokolle wie openclaw für die Echtzeitinformationenrückgewinnung und -analyse verwenden und schrittweise ausführbare Pläne generieren.","pt":"Habilita os agentes a fornecer soluções estruturadas para problemas específicos do usuário, aproveitando a integração de ferramentas sem interrupções para uma resolução eficiente de problemas, utilizando protocolos como openclaw para recuperação e análise de informações em tempo real e gerando planos executáveis passo a passo.","ru":"Наделяет агентов возможностью предоставлять структурированные решения для конкретных проблем пользователей, используя беспрепятственную интеграцию инструментов для эффективного решения проблем, используя протоколы, такие как openclaw, для извлечения и анализа информации в реальном времени и генерируя пошаговые выполнимые планы.","ar":"يمنح الوكلاء القدرة على تقديم حلول منظمة لمشكلات المستخدمين المحددة، مستفيداً من تكامل الأدوات دون انقطاع لتحقيق حلول فعالة للمشكلات، باستخدام بروتوكولات مثل openclaw لاسترجاع وتحليل المعلومات في الوقت الفعلي وتوليد خطط قابلة للتنفيذ خطوة بخطوة."},"useCases":{"en":["Analyzing user problems with real-time data","Generating executable solutions for technical issues","Debugging complex problems through multi-step analysis"],"zh":["使用实时数据分析用户问题","为技术问题生成可执行的解决方案","通过多步骤分析调试复杂问题"],"ja":["リアルタイムデータを使用してユーザーの問題を分析する","技術的な問題に対する実行可能なソリューションを生成する","マルチステップ分析を通じて複雑な問題をデバッグする"],"ko":["실시간 데이터를 사용하여 사용자 문제를 분석하는 것","기술적인 문제에 대한 실행 가능한 솔루션을 생성하는 것","다중 단계 분석을 통해 복잡한 문제를 디버깅하는 것"],"es":["Análisis de problemas de los usuarios con datos en tiempo real","Generación de soluciones ejecutables para problemas técnicos","Depuración de problemas complejos a través de un análisis multietapa"],"fr":["Analyse des problèmes des utilisateurs avec des données en temps réel","Génération de solutions exécutables pour des problèmes techniques","Débogage de problèmes complexes via une analyse multétape"],"de":["Analyse von Benutzerproblemen mit Echtzeitdaten","Generierung von ausführbaren Lösungen für technische Probleme","Fehlerbehebung komplexer Probleme durch eine mehrstufige Analyse"],"pt":["Analisar problemas do usuário com dados em tempo real","Gerar soluções executáveis para problemas técnicos","Depurar problemas complexos por meio de análise multi-etapas"],"ru":["Анализ проблем пользователей с данными в реальном времени","Генерация выполнимых решений для технических проблем","Отладка сложных проблем посредством многоступенчатого анализа"],"ar":["تحليل مشكلات المستخدم مع البيانات في الوقت الفعلي","توليد حلول قابلة للتنفيذ لمشكلات فنية","تصحيح مشكلات معقدة من خلال تحليل متعدد المراحل"]},"limitations":{"en":["Requires internet connection for real-time data retrieval","Limited to problems that can be solved through logical reasoning, mathematical computation, or code analysis"],"zh":["需要互联网连接以获取实时数据","仅限于可以通过逻辑推理、数学计算或代码分析解决的问题"],"ja":["リアルタイムデータの取得にはインターネット接続が必要","論理的推論、数学的計算、またはコード分析によって解決できる問題に限定される"],"ko":["실시간 데이터 조회를 위해 인터넷 연결이 필요함","논리적 추론, 수학적 계산 또는 코드 분석을 통해 해결できる 문제에 한정됨"],"es":["Requiere conexión a Internet para la recuperación de datos en tiempo real","Limitado a problemas que se pueden resolver mediante razonamiento lógico, cálculo matemático o análisis de código"],"fr":["Nécessite une connexion Internet pour la récupération de données en temps réel","Limité aux problèmes qui peuvent être résolus via un raisonnement logique, un calcul mathématique ou une analyse de code"],"de":["Benötigt Internetverbindung für die Echtzeitdatenrückgewinnung","Begrenzt auf Probleme, die durch logisches Denken, mathematische Berechnung oder Codeanalyse gelöst werden können"],"pt":["Exige conexão com a internet para recuperação de dados em tempo real","Limitado a problemas que podem ser resolvidos por meio de raciocínio lógico, computação matemática ou análise de código"],"ru":["Требует подключения к Интернету для извлечения данных в реальном времени","Ограничен проблемами, которые могут быть решены с помощью логических рассуждений, математических вычислений или анализа кода"],"ar":["يتطلب الاتصال بالإنترنت لاسترجاع البيانات في الوقت الفعلي","محدود بمشكلات يمكن حلها من خلال التفكير المنطقي أو الحسابات الرياضية أو تحليل الشفرة"]},"version":4},"contentHash":"7d620eb304ee1d626980cf02f2c6bd7b6350a401ae8ccf62c9f55aa16a194a8c","qualityScore":38}');
